UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'Anne için Şarj 🔋', 'Günün koşturmacası enerjinizi tüketti mi? Kendinizi unutarak çocuk büyütmek kahramanlık değildir. Onu güvenli bir yere bırakıp 10 dakikalık bir kahve molası verin.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'Hız sınırı aşılıyor 🏃‍♂️', 'Artık yürümüyor, neredeyse koşuyor! Ona yetişmek giderek zorlaşıyor. Bu yeni hız rekorunu gelişim takipçisine kaydedin ve evdeki engelleri ortadan kaldırın.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'Sözsüz anlaşma 🫂', 'Bugün çok yoruldunuz. Bebeğiniz uyuduktan sonra eşinizle hiçbir şey konuşmadan, sadece koltukta yan yana oturup sessizliğin tadını çıkarın.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'Vücudunuzun ihtiyacı 🥑', 'Kollarınız ve beliniz ağrıyor mu? Bebeğiniz artık ağırlaştı. Sağlıklı tarifler arasından kalsiyum ve protein açısından zengin, hafif bir öğle yemeği seçerek kaslarınızı destekleyin.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'Kitap sevgisi 📖', 'Kitabın sayfalarını kendi başına çeviriyor ve resimlere parmağıyla dokunuyor mu? Okuma alışkanlığı şimdiden oluşuyor. Resimdekileri onunla birlikte adlandırın.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'Aniden çığlık atarak mı uyandı?', 'Uyku terörü olabilir. Sesini Ağlama Analizi''ne dinleterek sorunun fiziksel mi yoksa psikolojik mi olduğunu öğrenin.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'Ev işleri bekleyebilir 🛑', 'Yerler silinmedi mi? Bırakın öyle kalsın. Kirli ev temizlenir, ancak tükenmiş bir annenin toparlanması uzun sürer. Kanepeye uzanın ve sadece huzuru dinleyin.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'Mantık oyunları 🧱', '3-4 küpü üst üste koyup kule mi yapıyor? Bu motor beceri zaferini Gelişim Takibi''ne kaydedin! Onun bu küçük mühendislik girişimlerini alkışlayın.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'Uykuya geçiş kolaylaşsın. 🌙', 'Odanın ışığını en düşük seviyeye indirin ve sessizce, fısıldayarak konuşun. Bu, sinir sistemine dinlenme zamanının geldiği sinyalini verecektir.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'Enerji toplama zamanı. 🍎', 'Çocuğunuz uyurken siz de 20 dakika gözlerinizi kapatın. Ev işleri bitmez ama sizin enerjiniz tükenebilir. Kendinizi koruyun.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'Yardımsever minik. 🧺', 'Oyuncakları kutuya toplarken o da birini getirip koyuyor mu? Bu küçük yardımlarını mutlaka alkışlayın ve ona teşekkür edin.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'Akıllı masalın büyüsü 🪄', 'Akıllı masallarda kahramanı kendi çocuğunuz olan özel bir hikâye oluşturun: Sihirli ormanda gezen cesur minik.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'Annenin kendine ayırdığı zaman 🎧', 'Çocuğunuz uyur uyumaz mutfağa koşmayın. Kulaklığınızı takın, sevdiğiniz bir şarkıyı açın ve 15 dakika boyunca sadece Siz olun.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'Kendi başına yemekte ısrar ediyor. 🥄', 'Kaşığı elinizden alıyorsa ona engel olmayın. Üstünü başını kirletse de kendi başına yemesi, bağımsızlığının en büyük göstergesidir.'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'Bana bak! ☝️', 'Dikkatinizi çekmek için ses çıkarıyor ve ilgisini çeken nesneyi parmağıyla gösteriyor. Keşiflerine ortak olun ve Evet, bu bir top diyerek onu onaylayın.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'Kaşık inadı 🥄', 'Kendi başına yemek istiyor ve yemeğin yarısını üstüne mi döküyor? Temizliğe odaklanmayın. Bu günler, kendi başına beslenme alışkanlığının temelini oluşturur.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'Günün değerlendirmesi 📝', 'Kendinizi yetersiz hissettiğinizde Ruh Hali Günlüğü''ne bugünkü küçük başarılarınızı yazın. (Örneğin: Onu güldürdüm, karnını doyurdum). Siz harikasınız.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'Sohbet giderek ciddileşiyor 🗣️', 'Anlaşılmaz kelimelerle size bir şeyler anlatıyor, hatta el hareketleri mi yapıyor? Onunla aynı ciddiyetle iletişim kurun; bu, konuşmaya başlaması için önemlidir.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'Temiz havanın gücü 🌙', 'Uyumayı mı reddediyor? Pencereyi açın ve odanın havasını tamamen değiştirin. Serin ve temiz hava, uykuya geçişi her zaman kolaylaştırır.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'Alerji şüphesi mi var? 🤖', 'Yeni bir meyve verdiniz ve kızarıklık mı oluştu? Paniğe kapılmadan önce Anacan AI''dan çocuklarda gıda alerjisi durumunda atılması gereken ilk adımları öğrenin.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'Hayali oyunlar başlıyor 🧸', 'Oyuncak ayısına yemek yedirmeye veya onu uyutmaya mı çalışıyor? Hayal gücü uyanıyor! Bu harika empati girişimlerini kenardan gururla izleyin.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'Babanın oyun saati 👨‍👧', 'Sabrınız tükenmek üzere mi? Bu akşam yerde yuvarlanma ve gıdıklama oyunlarını babaya bırakın.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'Mutfakta keşif. 🍎', 'Meyveleri yıkarken onun da size yardım etmesine izin verin. Suyun sesi ve meyvelerin renkleri merakını canlı tutacak.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'İki kelimeli cümle denemeleri. 🗣', '️ “Anne, ver” veya “Baba, bak” gibi iki kelimeyi birleştirmeye mi çalışıyor? Bu, dil gelişiminde harika bir sıçramadır!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'Büyülü gece fonu 🪄', 'Uykuya dalmakta zorlanıyor mu? Beyaz gürültü seçenekleri arasından yalnızca dere seslerinden oluşan sakinleştirici bir fon açın.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'Küçük ressam iş başında 🖍️', 'Eline kalem verdiğinizde kâğıdı (veya duvarı) karalıyor mu? İnce motor becerileri hızla gelişiyor. Yıkanabilir boyalar almanın zamanı geldi.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'Babanın hikâye saati. 👨‍🍼', 'Akşamın son enerjik oyunlarını babaya bırakın. Birlikte attıkları kahkahalar, sizin için en güzel dinlenme fonu olacak.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'Hava keşfi ⛅', 'Dışarıda rüzgâr mı var, yoksa hava sadece serin mi? Pencereden bakıp yanılmayın. Hava ve kıyafet aracı, en uygun kombini size saniyeler içinde söylesin.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'Deneyimlerinizi paylaşın 💬', '“Benim çocuğum da böyle mi?” düşüncesi zihninizi mi meşgul ediyor? Anacan Topluluğu''na katılın, 16 aylık bebeği olan diğer annelerin hikâyelerini okuyup derin bir nefes alın.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'Sakinleştirici banyo. 🛁', 'Yatmadan önce ılık suyla oynamak, günün tüm gerginliğini alıp götürecek. Suyun içine biraz uçucu yağ ekleyerek huzurlu bir ortam yaratın.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'Merdivenleri kendi başına çıkma denemesi. 🪜', 'Artık elinizden tutarak basamakları daha güvenle çıkıyor. Bacak kaslarını güçlendirmesi için ona engel olmayın; yalnızca güvenliğini sağlayın.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'Cebinizdeki liste 🛒', 'Günlük koşuşturma içinde şampuanın mı yoksa ıslak mendilin mi bittiğini hatırlamaya çalışmayın. Alışveriş listesine yazın ve eşinizle senkronize edin.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'Sorunuz mu var? 🤖', '“Gece uyanmaları neden arttı?” gibi soruları gecenin geç saatlerinde bile Anacan AI yardımcımıza sorarak anında yanıt alın.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'Seni buldum! 🙈', 'Gözlerini elleriyle kapatıp ce-ee mi oynuyor? Nesne sürekliliği kavrayışı gelişiyor.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'Biz bir takımız! 💖', 'Zorlu bir günün ardından eşinizle yüz yüze oturup dertleşin. Birbirinize destek olmak, fiziksel ve duygusal yükü tam anlamıyla yarıya indirir.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'Çocuk sağlığıyla ilgili endişeler 🤖', '16-18 aylık gelişim döneminde neler beklemelisiniz? İnternette korkutucu haberler okumak yerine Anacan AI''dan uzman bilgilerine dayalı, net bir özet isteyin.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'Rahatlatıcı rutin 🌙', 'Güzel bir günün sonu. Uyku zamanlayıcısını başlatın, Beyaz Sesler arasından bir ninni seçin ve günün sona erişinin keyfini huzurla çıkarın.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'Temiz hava arayışı 🌳', 'Evde sıkıldınız mı? Anne Dostu Mekanlar haritamızı açın ve bebeğinizle rahatça gezebileceğiniz yeni bir park keşfedin.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'Uyku vakti geldi ⏱️', 'Bebeğinizi uyutmaya mı hazırlanıyorsunuz? Uyku zamanlayıcısını başlatın, uyku düzenine ne kadar uyduğunuzu kaydedin ve uyku ihtiyacını analiz edin.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'Sabah iştahı nasıl? 🥣', 'Güne sağlıklı başlamak önemlidir! Beslenme takip aracıyla bugünkü vitamin ihtiyacını hesaplayın ve menüyü planlayın.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'Sabah rutini 💩', 'Günün ilk bezini değiştirdiniz mi? Dışkının rengi ve kıvamı bağırsak sağlığı hakkında bilgi verir. Hemen bez takip aracına kaydedin!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'Kadınlar için enerji 🥗', 'Günlük koşuşturma yorucudur. Kendinizi unutmayın! Kadınlara özel sağlıklı tariflerden, anında enerji veren lezzetli bir salata hazırlayın.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'Beyaz Seslerin büyüsü 🌧️', 'Çok hareketli bir gün müydü? Odada Beyaz Sesler arasından yağmur sesini açın; bebeğiniz kolayca uykuya dalsın, siz de rahat bir nefes alın.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'Günün en tatlı anı 📸', 'Bugün farklı ve komik bir hareket mi yaptı? Bebek fotoğraf çekimindeki eğlenceli çerçevelerle o anı yakalayın ve ömür boyu sürecek bir hatıraya dönüştürün.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'Kendi başına yemek istiyor! 🥦', 'Bağımsız olmak mı istiyor? Ek gıdaya başlayan bebekler için Tarifler arasından kolayca tutulabilen ve dökülmeyen lezzetli porsiyonlar seçin.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'İnatçılıkla başa çıkma 🤖', 'Her şeye hayır mı diyor? Bu dönemdeki krizleri nasıl yöneteceğinizi bilmiyorsanız hemen Anacan AI''a danışın.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'Kıyafetler dar mı geliyor? 📏', 'Çocuğunuzun birden boy attığını mı fark ettiniz? Kilo Takip Aracına yeni ölçümleri girin ve sağlıklı büyüme grafiğini inceleyin.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'Beslenme zamanlayıcısı ⏱️', 'Yemek yemesi ne kadar sürüyor? Beslenme zamanlayıcısını başlatın ve besinlerin tamamen sindirilebilmesi için öğün düzenini takip edin.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'Faydalı okumalar 📖', 'Çocuğunuz uyudu, peki siz ne yapıyorsunuz? Annelik deneyiminizi geliştirmek için Bloglar bölümümüzdeki en yeni makaleleri okuyun.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'İdeal suluk arayışı 🥤', 'Sızdırmayan ve kullanışlı bir suluk mu arıyorsunuz? Önerilen Ürünler bölümünde annelerin en çok deneyip onayladığı ürünlere göz atın.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'Kahve molası ☕', 'Bugün evden çıkmak mı istiyorsunuz? Anne Dostu Mekanlar arasından çocuk köşesi bulunan bir kafe seçin ve kendinize zaman ayırın.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'Duygusal rahatlama 📝', 'Bugün her şey planladığınız gibi gitmedi mi? Kendinizi suçlamayın. İçinizi sıkan düşünceleri Ruh Hali Günlüğüne yazarak zihninizi boşaltın.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'Tatlı rüyalar 🌙', 'Bugün çok yoruldunuz. Bebeğiniz uyurken Beyaz Sesler arasından okyanus dalgalarını açın; hem o rahat uyusun hem de siz dinlenin.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'Öğün zamanlayıcısı ⏱️', 'Öğün saatlerini takip etmek artık daha kolay! Beslenme zamanlayıcısını başlatın ve bebeğinizin günlük beslenme düzenini dikkatle takip edin.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'Koşturmaca başladı! 🏃‍♀️', '17 aylık kaşifiniz evde fırtınalar mı estiriyor? Enerjisini atabilmesi için Anne Dostu Mekanlar arasından yakınınızdaki yeni bir parkı keşfedin.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'Lezzetli ve farklı! 🥦', 'Bugün ona farklı ne pişireceğinizi mi düşünüyorsunuz? Ek gıdaya başlayan bebekler için Tarifler bölümünde birbirinden lezzetli fikirler var.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'Duygularınızı yazın 📝', 'Annelik bazen yorucudur ve bu çok normaldir. Bugün sizi en çok neyin yorduğunu Duygu Günlüğü''ne yazın ve rahatlayın.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'Sabah sürprizi 💩', 'Günün ilk bezini değiştirdiniz mi? Uygulamadaki bez takipçisine kaydetmeyi unutmayın; hijyen rutinini kolayca takip edelim!'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'Gündüz uykusu 😴', 'Uyku zamanlayıcısını başlatın! 17 aylık bebeğinizin gündüz uykusu süresini analiz ederek akşam uyku planınızı daha doğru şekilde oluşturun.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'Rahatlık arayışı 🍼', 'Bebeğinizin kendi başına kullanabilmesi için en iyi dökülmez suluk modelini mi arıyorsunuz? Önerilen Ürünler bölümünde annelerin en çok beğendiği seçeneklere göz atın.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'Kendinizi unutmayın! ☕', 'Enerjiniz, bebeğiniz için en önemli şeylerden biridir. Sağlıklı tariflerden yararlanarak kendinize lezzetli ve enerji veren bir smoothie hazırlayın.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'Blog ve kahve 📖', 'Bebeğiniz uyudu, şimdi sıra sizde! Yeni blog yazımızı okuyarak hareketli çocukların psikolojisi hakkında birbirinden ilginç bilgiler edinin.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'Rahat bir yürüyüş 👟', 'Parkta onun peşinden koşarken ikinize de rahat ayakkabılar mı gerekiyor? Önerilen Ürünler bölümündeki en iyi seçeneklere göz atın.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'Sorunuz mu var? 🤔', 'Bebeğinizin giderek artan inatçılığıyla nasıl başa çıkacağınızı mı düşünüyorsunuz? Anacan AI, uzman tavsiyeleriyle sorularınızı hemen yanıtlamaya hazır!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'Derin bir nefes alın ✨', 'Her şeyin mükemmel olması gerekmiyor. Siz zaten bebeğiniz için en iyi annesiniz! Duygu Günlüğü''nde günün stresini geride bırakın ve dinlenin.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'Boyu uzadı mı? 🦒', 'Kıyafetlerinin dar gelmeye başladığını mı fark ettiniz? Gelişim Takipçisi''ne yeni ölçümleri girin ve büyüme grafiğinin nasıl yükseldiğini görün.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'Beslenme ihtiyacı 🥣', 'Bugün yeterince protein aldı mı? Beslenme takip aracıyla bebeğinizin günlük menüsünü analiz edin ve eksiklerini tamamlayın.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'Sakinleştirici ses 🌧️', 'Günün heyecanından uyuyamıyor mu? Beyaz Sesler arasından yağmur sesini seçin ve sinir sisteminin doğal şekilde sakinleşmesine yardımcı olun.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'Bugün farklı olsun 🌟', 'Ev rutini sizi sıktı mı? Anne Dostu Mekanlar haritamızı açın ve bebeğinizle birlikte rahatça oturabileceğiniz yeni bir kafe keşfedin.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'Bebek yıldız! 📸', 'Onun tatlı gülümsemesi dünyalara bedel! Bebek fotoğraf çekimi özelliğindeki farklı çerçeveleri kullanarak bu günü ölümsüzleştirin.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'Sindirim sistemi kontrolü ⏱️', 'Günlük bez kullanımını takip etmek, beslenme durumuyla ilgili önemli ipuçları verir. Bugünkü bez değişimlerini uygulamamıza kaydettiniz mi?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'Aile sofrası 🍲', 'Akşam yemeğinde ona ne vereceksiniz? Ek gıda tariflerinde tüm ailenin severek yiyebileceği ortak ve sağlıklı yemek fikirleri var.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'Annelik hikayeniz 📝', 'Her annenin hikayesi eşsizdir. Bloglarımızda diğer annelerin gerçek deneyimlerini ve hikayelerini okuyarak ilham alın.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'Parkta koşu 👟', 'İlk adımların ardından koşuşturma başlar. İlk ayakkabı seçimi için Önerilen Ürünler bölümündeki sağlıklı modellere göz atın.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'Odada huzur 🌊', 'Bugün uykuya dalmak zor mu? Beyaz Sesler arasından okyanus dalgalarının sesini açın; sinir sistemini sakinleştirerek uykuya geçişi kolaylaştırın.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'Protein alımı yeterli mi? 🍗', 'Çocuğunuzun büyümesi için protein şarttır! Beslenme takip aracıyla günlük besin dengesini ölçün ve eksiklerini tamamlayın.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'Uyku zamanlayıcısı etkin mi? ⏳', 'Bebeğinizi uyutmaya mı başlıyorsunuz? Zamanlayıcıyı açın, uykuya geçiş süresini analiz edin ve bu rutini nasıl iyileştirebileceğinizi öğrenin.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'Akıllı yardımcınız 🤖', 'Çocuğunuzun iştahı neden aniden azaldı? Bu ve benzeri endişe verici sorularınızı Anacan AI''a yazın, hemen bilimsel temelli bir yanıt alın.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'Enerji depolayın 🔋', 'Günün koşturmacasına hazır mısınız? Kadınlara özel sağlıklı tarifler arasından kendinize lezzetli ve vitamin dolu bir kahvaltı seçin.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'Rahatlık arayışında 🍼', 'Bebeğinizin bağımsızca kullanabileceği en iyi akıtmaz suluk modelini mi arıyorsunuz? Önerilen Ürünler bölümünde annelerin en çok beğendiği seçeneklere göz atın.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'Siz başarabilirsiniz! 💪', 'Gününüz zor mu geçti? Duygu Günlüğü''nde iç sesinize kulak verin. Unutmayın, bu sadece zor bir gün; kötü bir hayat değil.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'Beslenme raporu 📊', 'Çocuğunuzun bugünkü öğünlerini Beslenme takip aracına kaydedin. Bakalım bugün gerekli vitaminleri yeterince almış mı?'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'Günün mucizesi 🖼️', '520. güne özel bir dokunuş! En değerli ve komik fotoğrafları Bebek Albümü''ne yükleyin, yıllar sonra gülümseyerek hatırlayın.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'Büyüme atağı mı? 📈', 'Çok mu ağlıyor veya uyku düzeni mi bozuldu? Anacan AI''a danışarak bunun 17. aya özgü bir büyüme atağı haftası olup olmadığını öğrenin.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'Uyku düzenine bakalım 😴', 'Gece nasıl uyudu? Uyku zamanlayıcısındaki kayıtları inceleyerek bebeğinizin günlük uyku ihtiyacını karşılayıp karşılamadığını analiz edin.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'Sizi ne endişelendiriyor? 🤖', 'Çocuğunuzun gelişimiyle ilgili şüpheleriniz mi var? Anacan AI uzman yardımcımıza yazarak bilimsel temelli yanıtlar alın ve içinizi rahatlatın.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'Her öğünde farklı bir lezzet 🍲', '“Bugün ne pişirsem?” derdi bitti. Ek gıdaya başlayan bebekler için Tarifler bölümünde rengârenk ve sağlıklı menüler sizi bekliyor.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'Günlük dışkılama raporu 💩', 'Sabah bezini değiştirirken kaydetmeyi unutmayın! Gün boyunca bez değişimlerini takip etmek, çocuğun yeterli sıvı alıp almadığını anlamaya yardımcı olur.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'Sizin de ihtiyaçlarınız var 🥗', 'Enerjiniz tükenmek üzere mi? Kadınlara özel sağlıklı tariflerden vitamin açısından zengin bir smoothie hazırlayın. Güçlü kalmalısınız!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'Unutulmaz anılar 🖼️', 'Gelecekte bugünkü tatlı hâllerine bakıp gülümsemek için en güzel fotoğraflarını Bebek Albümüne yükleyerek güvenli bir yerde saklayın.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'Bugün neler hissettiniz? 💖', 'Çok yorulsanız da onu kokladığınızda her şey geçiyor, değil mi? Bugünkü duygularınızı Duygu Günlüğüne kaydedin ve dinlenin.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'Zamanlayıcıyla yemek ⏱️', 'Yemek masasında çok mu uzun oturuyor? Beslenme zamanlayıcısını başlatın, uygun süreye bağlı kalarak iştahsızlığın önüne geçin.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'Sabah oyunları 🧩', 'Birlikte öğreniyoruz! 17.5 aylık çocukların zihinsel gelişimini destekleyen oyunlarla ilgili Bloglar bölümündeki yazımızı mutlaka okuyun.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', '“Seni Seviyorum” sarılması 🫂', 'Birden yanınıza gelip boynunuza sarılıyor veya yüzünüzü okşuyor mu? Artık sevgisini fiziksel olarak gösteriyor. Bu anın tadını çıkarın.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'Babadan gelen teselli 🫂', 'Gece uyanmalarında bir sefer siz, bir sefer eşiniz kalksın. Yükü bir ekip olarak tam ortadan ikiye bölün.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'Alerji şüphesi 🤖', 'Yeni bir gıda verdiniz ve yanaklarında kızarıklık mı gördünüz? Paniğe kapılmadan önce atmanız gereken ilk adımları Anacan AI''dan öğrenin.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'Evde bunaldınız mı?☕', 'Anne Dostu Mekânlar arasından hem sizin nefes alabileceğiniz hem de bebeğinizin eğlenebileceği en yakın kafeyi bulun.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'Ses tonunuzu anlıyor 🗣️', 'Ciddi bir ses tonuyla “hayır” dediğinizde durup size bakıyor mu? Artık duyguları ve yasakları tamamen kavrıyor. Sınırlarınızı koruyun.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'Işıkları azaltın 🌙', 'Uyku saatinden 1 saat önce evdeki tüm parlak ışıkları ve ekranları kapatın. Melatonin yalnızca sakin bir ortamda salgılanır.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'Uyku ihtiyacı ⏱️', 'Yatma vakti! Uyku zamanlayıcısını etkinleştirin. Günlük uyku ihtiyacını karşıladığından emin olmak için grafiği analiz edin.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'Kendinize iyi bakın 🥗', 'Çocuğunuzun peşinden koşmaktan yoruldunuz mu? Kadınlara özel sağlıklı tarifler arasından anında enerji veren lezzetli bir salata göz atın.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'Sabah temizliği 🧻', 'Günün ilk bez değişimi nasıl geçti? Dışkı bilgilerini uygulamaya kaydederek bebeğinizin sindirim sistemini kolayca takip edin.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'Vitamin deposu 🥦', 'Beslenme takip aracıyla bugünkü menüyü kontrol edin. Eksik vitaminleri tamamlamak için Bebek Tariflerinde rengârenk porsiyonlar sizi bekliyor!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'Çok mu inatçı? 🤖', 'Ağzından “hayır” kelimesi düşmüyor mu? 17.5 aylık çocuğunuzun krizlerini yönetmek için Anacan AI yardımcımızdan bilimsel temelli psikolojik öneriler alın.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'Huzur dolu bir akşam 🌊', 'Odada sakin bir ortam yaratma zamanı. Beyaz Seslerden okyanus dalgalarını açarak sinir sisteminin rahatlamasına ve derin uykuya geçmesine yardımcı olun.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'Yemek masası sınavı ⏱️', 'Yemek saati çok mu uzuyor? Beslenme zamanlayıcısını açarak hem uygun süreyi takip edin hem de iştahsızlığın nedenlerini analiz edin.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'Günlük terapi 📝', 'Annelik bazen duygusal bir hız treni gibidir. Duygu Günlüğünü açın, bugünkü yorgunluğunuzu satırlara dökerek rahatlayın.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'Kahve zamanı geldi ☕', 'Evin dört duvarı arasında kalmaktan sıkıldınız mı? Anne Dostu Mekanlardan çocuğunuzla rahatça gidebileceğiniz bir kafe bulun ve kendinizi şımartın.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'Tatlı anılar 📸', 'Bugün yaptığı en komik hareketi Bebek Albümüne ekleyin. Yıllar sonra bu karelere bakıp çok güleceksiniz.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'Dökülmeyen suluk 🥤', 'Koşarken su içmeyi seviyor ama üstünü mü ıslatıyor? Önerilen Ürünler bölümünde annelerin tercih ettiği en kullanışlı suluklara göz atın.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'Kıyafetler küçülüyor! 📏', 'Küçüğünüzün kıyafetlerinin kolları yine mi kısa gelmeye başladı? Kilo Takibine yeni ölçümleri girin, boy ve kilo artışını gelişim grafiğinden gururla takip edin.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'Bağımsız oyun zamanı 🧸', 'Artık 10-15 dakika boyunca oyuncaklarıyla tek başına oyalanabiliyor. Bu, dikkat süresinin uzadığını gösterir. Sessizliğin tadını çıkarın.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'Dışarıda hava pek belli değil mi? ⛅', 'Hava ve kıyafet aracı, pencereden fark edemediğiniz rüzgâr hızını ve doğru kombini size anında söylesin.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'Masaj zamanı 💆‍♂️', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birbirinize omuz masajı yapın. Siz bir takımsınız!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'Ses kontrolü 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamı kontrol edin ve ani gürültülere karşı dikkatli olun.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'Hızlı pediatrist 🤖', '18 aylık çocuğunuzun dil gelişimi hakkında endişeleriniz mi var? Anacan AI''a sorarak bu dönemde hangi kelimelerin normal olduğunu öğrenin.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'Basit komutları yerine getiriyor 🧸', '“Ayakkabını getir” dediğinizde gerçekten gidip getiriyor mu? Kelime dağarcığı ve anlama becerisi zirvede! Onu oyunlara daha fazla dahil edin.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'Kendinizi takdir edin 👏', 'Odanın dağınıklığına değil, bugün onun ne kadar mutlu olduğuna bakın. Siz, hiçbir kitabın öğretemeyeceği kadar harika bir annesiniz.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'Zamanlayıcıyla uyku analizi ⏱️', 'Gündüz uykusu kısalıyor mu? Uyku zamanlayıcısını başlatın, bu haftanın grafiğini analiz ederek gece uyku saatini yeniden ayarlayın.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'Birbirinize destek olun! 💖', 'Zor bir günün ardından eşinizle karşılıklı oturup dertleşin. Birbirinize destek olmak yükü yarıya indirir.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'Öğle iştahı 🥣', 'Bugün yeterince protein tüketti mi? Beslenme takip aracına yiyecekleri girerek günlük ihtiyacını karşıladığınızdan emin olun.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'Zekâ sıçraması 🧠', 'Bebeğinizin beyninde neler oluyor? Bloglar bölümünde 17-18 aylık çocukların bilişsel gelişimi hakkındaki en yeni makaleyi okuyun.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'Uyku programı ⏱️', 'Uyanma saatleri değişti mi? Uyku zamanlayıcısının istatistiklerine bakarak gündüz ve gece uykusu arasındaki dengeyi ayrıntılı şekilde analiz edin.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'Sabah raporu 💩', 'Sağlığın ilk göstergesi sindirim sistemidir. Bezini değiştirirken dışkı kayıtlarını uygulamaya ekleyerek gün içindeki değişiklikleri takip edin.'),
