  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'Annenin bel ağrıları 🧘‍♀️', 'Bebeğinizi kaldırmaktan beliniz mi ağrıyor? Sağlıklı tariflerden iltihap azaltıcı ve yenileyici zencefilli yeşil çay demleyerek bedeninize iyi bakın.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'Yanlış bardak krizi mi? 🥤', 'Suyu kırmızı değil de mavi bardakta verdiğiniz için kıyamet mi koptu? Mantıksız görünen bu krizleri soğukkanlılıkla nasıl çözeceğinizi hemen Anacan AI''a sorun.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'İçinizi dökün 📝', 'Bugün durmadan ağladı ve siz çok yoruldunuz. Kendinizi suçlamayın. Tüm yorgunluğunuzu Duygu Günlüğüne yazarak zihninizi boşaltın ve dinlenin.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'Masalı o anlatsın 📖', 'Kitaptaki resimlere bakıp kendi dilinde bir şeyler mi anlatıyor? Bu muhteşem hayal gücü anını hemen sesli video olarak Bebek Albümüne ekleyip geleceğe saklayın.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'Dört duvar arasından çıkın 🌳', 'Evde enerjisini atamıyor ve her şeyi dağıtıyor mu? Anne Dostu Mekanlar haritasını açın, güvenle koşabileceği bir park bulup temiz havaya çıkın.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'Paylaşmak istemiyor mu? 🧸', 'Parkta oyuncağını kimseye vermiyor mu? Bloglar bölümünde 22 aylık çocuklara sırayla oynama kavramını öğretmeye yönelik pratik makaleyi mutlaka okuyun.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'Kalsiyum kalkanı 🦴', 'Kemikler ve dişler için kalsiyum şarttır. Beslenme takip aracıyla bugün tüketmesi gereken yoğurt ve peynir miktarını karşılayıp karşılamadığınızı kontrol edin.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'Ayakkabısı sıkıyor mu? 📏', 'Son zamanlarda koşarken sık sık tökezliyor mu? Ayağı büyümüş olabilir! Güncel boyunu ve ölçülerini Kilo Takibine girerek fiziksel gelişimini izleyin.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'Yemeğini yere mi atıyor? 🥣', 'Kaşığı ve yemeği masadan aşağı atmaya başladıysa doymuş veya sıkılmış olabilir. Beslenme zamanlayıcısını durdurun, iştahının seyrini grafik üzerinden analiz ederek öğünü sonlandırın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182'::uuid, '5 dakikalık enerji ⚡', 'Sabah hemen ev işlerine koşmayın. Kadınlara özel sağlıklı tariflerden antioksidan deposu orman meyveli yulaf hazırlayarak bedeninizi yenileyin.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'Gece uyanmaları ⏱️', 'Uyku zamanlayıcısını başlatın! Gece terörü veya uyku gerilemesi olup olmadığını zamanlayıcının istatistik grafiğinden ayrıntılı şekilde analiz ederek düzenini ayarlayın.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'Zihinsel gelişim durmuyor 🧠', 'Her şeyi sınıflandırmayı seviyor! Renk ve şekil algısını geliştiren, beyni uyaran geometrik yapbozları (puzzle) Önerilen Ürünler''de hemen keşfedin.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni bir beceride sizin emeğiniz var. Duygu Günlüğü''nü açın ve bugün kendinizi ayakta alkışlayacağınız bir not yazın!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'Boyaya bulanmış küçük sanatçı! 📸', 'Kendisini ve duvarı mı boyadı? Sinirlenmek yerine bu eğlenceli karalama anını Bebek Fotoğraf Çekimi''ndeki neşeli çıkartmalarla süsleyip albüme unutulmaz bir anı olarak yükleyin.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'Kabızlık sorunu mu var? 💩', 'Sabah bezini değiştirirken dışkısını gözlemleyin. Kabızlık varsa uygulamaya kaydedin ve Beslenme Takibi aracıyla menüsüne mutlaka lifli gıdalar ekleyin.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'Güven duygusu 🌌', 'Odanın ışığını kapattığınızda korkuyor mu? Beyaz Sesler''den anne rahmindeki kalp atışı sesini açarak ona aşina olduğu o sıcak güven duygusunu verin ve uykuya hazırlayın.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'Sizin de sosyalleşmeye ihtiyacınız var ☕', 'Sadece çocuğunuzla konuşmaktan yoruldunuz mu? Anne Dostu Mekanlar''dan annelerin sıkça buluştuğu çocuk kafelerini bulup kendinize de yeni bir sosyal çevre oluşturun.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'Vurma veya itme 🛑', 'Öfkelendiğinde birden elini mi kaldırıyor? Bu yaşta yoğunlaşan saldırgan duyguları oyuna dönüştürerek nazikçe nasıl yönlendirebileceğinizi öğrenmek için Anacan AI''a danışın.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'Mantıksal sıçrama 🧩', 'Neden-sonuç ilişkisi kurmaya başladı. Bloglar bölümünde 22 aylık çocukların bilişsel gelişimini hızlandıran en iyi ev oyunlarını okuyup uygulayın.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'Düzenini analiz edelim ⏱️', 'Akşam uyanık kaldığı süre çok mu uzadı? Uyku zamanlayıcısını başlatın ve grafiği takip edin. Belki de gündüz uykusunu 15 dakika kısaltmanın tam zamanıdır.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'Demir deposu kontrolü 🥩', 'Kasların aktif çalışabilmesi için kansızlık olmamalı. Beslenme Takibi aracıyla bugünkü demir alımını kontrol edin ve eksikleri hemen tamamlayın.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'Şekersiz atıştırmalık 🍪', 'Hazır bisküvilere ihtiyacınız yok. Bebek tariflerinde evde 10 dakikada hazırlanan, hurmalı ve elmalı sağlıklı tatlıları keşfederek iştahını artırın.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'Boy sıçraması! 📏', 'Gömleklerinin kolları yine mi kısaldı? Fiziksel gelişimi hızlanıyor. Gelişim Takibi''ne güncel ölçülerini girin ve büyüme grafiğine gururla bakın.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'Yeni kelimeler geliyor! 🗣️', 'Çok fazla ses çıkarıyor ama henüz tam bir kelime söylemiyor mu? Pasif kelime dağarcığını etkinleştirmek için bu sevimli hece denemelerini sesli olarak Bebek Albümü''ne ekleyip takip edin.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'Temizlik yardımcısı 🧹', 'Artık ev işlerine katılmak istiyor. Bloglar bölümünde 22.5 aylık bir çocuğa sorumluluk duygusunu oyun yoluyla nasıl kazandırabileceğinizi okuyup uygulayın.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'Gece uyanmaları ⏱️', 'Uyku zamanlayıcısını başlatın! Gece terörü veya uyku gerilemesi yaşayıp yaşamadığını zamanlayıcının istatistik grafiğinden hemen analiz edin.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'Demir ihtiyacı 🥩', 'Hareketli kaslarını besleyin! Beslenme takip aracıyla bugün yeterince demir alıp almadığını kontrol edin ve menüsünü düzenleyin.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'Kahkaha sesleri 📸', 'Yüzünü mü buruşturuyor, yoksa size bakıp kahkaha mı atıyor? Bu tatlı anı Bebek Fotoğraf Çekimindeki çıkartmalarla süsleyin ve ölümsüz bir hatıra olarak albüme ekleyin.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'Tekdüzeliğin gücü 🎶', 'Gürültülü bir günün ardından aniden oluşan sessizlik onu korkutabilir. Beyaz Seslerden saç kurutma makinesi sesini açarak uyku ortamında kendini güvende hissetmesini sağlayın.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'Annenin pili 🔋', 'Enerjiniz mi tükendi? Tatlıya yönelmeyin! Kadınlara özel sağlıklı tariflerden anında enerji veren, proteinli bir fıstık ezmeli smoothie hazırlayın.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'Kıyafetler yine mi daralıyor? 📏', 'Fiziksel gelişim atağı başladı! Gelişim Takibine güncel boyunu ve ayakkabı numarasını girin, gelişim eğrisinin nasıl yükseldiğini gururla izleyin.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'Mantık arayışı 🧩', 'Aynı oyuncaklardan sıkıldı mı? Zihnini geliştirecek, yaşına uygun ve güvenli yapbozları Önerilen Ürünler bölümünde keşfedin.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'Aniden vurma ve ısırma 🦖', 'Öfkelendiğinde saldırganlaşıyor mu? Anacan AI ile bu davranışı oyuna dönüştürerek nasıl nazikçe değiştirebileceğinizi öğrenin.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'Sebzelerle saklambaç 🥕', 'Havuç ve ıspanağı reddediyor mu? Bebek tariflerinde bu vitaminleri lezzetli pankeklerin içine nasıl ustaca gizleyebileceğinizi keşfedin.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'Vicdan azabı çekmeyin 💖', 'Bugün sesinizi mi yükselttiniz? Kendinizi suçlamayın. Duygu Günlüğüne hislerinizi yazın; siz zaten onun için en iyi annesiniz.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'Sofrada bitmeyen gösteri ⏱️', 'Yemeğiyle oynuyor ama yemiyor mu? Beslenme zamanlayıcısını başlatın, süreci takip edin ve iştahının seyrini doğru şekilde analiz edin.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni bir beceride sizin emeğiniz var. Duygu Günlüğünü açın ve bugün kendinizi ayakta alkışlayacağınız bir not yazın!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'Birlikte ama ayrı 👶', 'Parkta diğer çocuklarla oynamıyor, yalnızca onları mı izliyor? Bu, paralel oyundur! Bloglar bölümünde bu sağlıklı sosyalleşme aşaması hakkında bilgi edinin.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'Şekersiz atıştırmalık 🍪', 'Market bisküvilerine gerek yok. Bebek tariflerinde evde 10 dakikada hazırlanan, hurmalı ve elmalı sağlıklı tatlıları keşfedin.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'Gece bezleri doluyor mu? 🧻', 'Sabah bezi çok ağırsa gece uykusu bölünebilir. Bez takibine idrar miktarını kaydedin ve akşam sıvı alımını düzenlemek için istatistikleri analiz edin.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'Minik kâşif mutfakta 🥦', 'O da sizinle yemek yapmak mı istiyor? Ek gıdaya başlayan bebekler için Tarifler bölümünden birlikte hazırlayabileceğiniz kolay, sebzeli ve lezzetli kek tariflerini keşfedin.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'Hayal gücü sınır tanımaz 🧸', 'Oyuncak ayısına yemek mi yediriyor, yoksa sizi mi tedavi ediyor? Empati gelişimini gösteren kısa bir videoyu Bebek Albümüne ekleyerek ömür boyu saklayacağınız bir anı yaratın.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'Güvenli keşifler ⚠️', 'Dolaplar, çekmeceler... Minik kaşifiniz için tehlikeli olabilir! Önerilen Ürünlerdeki mobilya koruyucularına ve güvenlik kilitlerine mutlaka göz atın.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'Günün yorgunluğunu atın 🛋️', 'Peşinden koşmaktan bitkin düştünüz. Çocuğunuz uyuduğuna göre şimdi tüm stresinizi Duygu Günlüğüne yazın ve kendinize bir fincan bitki çayı hazırlayın.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'Lazımlık sinyalleri? 🚽', 'Sabah bezi kupkuru mu? Eğitime başlamak için ideal zaman olabilir. Bez takip aracına kaydedin ve uygulamadaki hazırlık yazılarına göz atın.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'Et yemek istemiyor mu? 🥩', 'Proteine ihtiyacı var ama etten kaçıyor mu? Bebek tariflerindeki kolay çiğnenen, lezzetli tavuk köfteleriyle Beslenme Takibi aracındaki hedefi tamamlayın.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'Yataktan kaçış planı 🏃‍♂️', 'Uyku saati geldiğinde odadan kaçıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Seslerden orman uğultusunu açarak odayı sakin bir mağaraya dönüştürün.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'Sabah inatçılığı 🛑', '“Bunu giymeyeceğim, onu yemeyeceğim!” krizleri sabahlarınızı zorlaştırıyor mu? Hemen Anacan AI''a yazarak bu yaşta sınırları test etme davranışını nasıl yöneteceğinizi öğrenin.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'Duvardan kanepeye atlayış! 🧗‍♂️', 'O tam bir dublör! Evdeki enerjisini atabilmesi için Anne Dostu Mekanlarda geniş oyun salonları bulunan merkezleri bulup özgürce oynamasına izin verin.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'Duvardaki sanat eseri 🎨', 'Kalemi eline alıp duvarı mı boyadı? Sinirlenmeyin! Bu tatlı yaramazlığı Bebek fotoğraf çekimindeki eğlenceli çerçevelerle albüme ekleyin ve gülümseyin.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'Ani uyanmalar geri mi döndü? ⏱️', 'Gece yarısı ağlayarak mı uyanıyor? Uyku zamanlayıcısındaki grafiğe bakın. Gündüz uykusu çok geç biterse akşam derin uykuya geçmesi zorlaşabilir.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'Annenin kahve molası ☕', 'Kendinizi unutmayın! Kadınlara özel sağlıklı tariflerden enerjinizi artıracak yulaflı bir atıştırmalık hazırlayın ve kahvenizin tadını çıkarın.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'Doğru lazımlık seçimi 🚽', 'Tuvalet eğitimi için görsel hazırlık başlasın! Önerilen Ürünlerde annelerin deneyip onayladığı en rahat ve ilgi çekici lazımlık modellerine mutlaka göz atın.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'Omega-3 düzeyi nasıl? 🐟', 'Hızlı beyin gelişimi için balık veya ceviz şart! Beslenme Takibi aracıyla bu haftaki Omega-3 alımını kontrol edin ve menüyü hemen güncelleyin.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'Mükemmel olmak zorunda değilsiniz 💖', 'Bugün ev dağıldı, yemek gecikti mi? Hiç sorun değil! İç sesinizi Duygu Günlüğüne yazın ve çocuğunuzun sizi her halinizle sevdiğini hatırlayın.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'Bol su, kolay sindirim 💧', 'Aktif miniğinizin bağırsakları nasıl çalışıyor? Bezini değiştirirken gözlemlerinizi kaydedin. Kabızlık riski varsa uygulamadaki doğal lifli besin önerilerine göz atın.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'Yemek savaşı bitti ⏱️', 'Masada kaşığı bir kenara mı atıyor? Beslenme zamanlayıcısını durdurun; çocuğunuz doymuş olabilir. İştah grafiğini analiz ederek zorla yedirmekten kaçının.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'Giyinme savaşı! 👗', 'Sabahları giyinmek büyük bir krize mi dönüşüyor? Ona iki farklı tişört sunarak seçim özgürlüğü tanıyın.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'Gözlerini mi ovuşturuyor? 🥱', 'Uyku sinyalleri geliyor! Uyku zamanlayıcısını başlatın, Beyaz Sesler arasından orman hışırtısını açarak onu sakince uykuya hazırlayın ve programını takip edin.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'Annenin kahve saati ☕', 'Şimdi mola zamanı. Çocuğunuz kendi kendine oynarken Kadınlar için sağlıklı tariflerden antioksidan deposu yeşil çay veya hafif bir kahve seçerek enerjinizi tazeleyin.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'Evde duvarlara mı tırmanıyor? 🧗', 'Enerjisini atması şart! Anne Dostu Mekanlar haritasını açın, güvenli bir koşu alanı ve kaydırağı olan yeni bir park keşfederek özgürce hareket etmesini sağlayın.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'Masadan kaçış! 🏃‍♂️', 'Yemeğini yarıda bırakıp kaçıyor mu? Beslenme zamanlayıcısını durdurun. Zorla yedirmek yerine Bloglar bölümünde iştahı doğal yollarla artırmanın sırlarını okuyun.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'Ayakkabısı neden sıkıyor? 👟', 'Koşarken sık sık tökezliyor mu? Ayağı büyümüş olabilir! Güncel ölçülerini Gelişim Takipçisine girip gelişim sıçramasını hemen kontrol ederek büyümesini değerlendirin.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'Şekilleri doğru eşleştiriyor mu? 🧩', 'Mantıksal gelişimini desteklemek için yaşına uygun geometrik yapbozları (puzzle) ve eğitici ahşap oyuncakları hemen Önerilen Ürünlerde arayın.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'Protein alımı yeterli mi? 🥚', 'Hızla büyüyen kaslar için protein şarttır. Beslenme takip aracıyla bugünkü ihtiyacını hesaplayın ve eksiklik varsa menüyü düzenleyin.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'İlk ciddi sohbetler 🗣️', 'Sizinle kendi dilinde uzun uzun bir şeyler mi konuşuyor? Bu eğlenceli ve paha biçilmez anı sesli bir video olarak Bebek Albümüne kaydedin.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'Ani çığlıklar! 🛑', 'İstediği olmayınca kendini yere mi atıyor? 23. aya doğru artan bu duygusal krizleri oyuna dönüştürmenin yollarını Anacan AI uzman yardımcımıza sorun.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'Su içmeyi unutmasın 💧', 'Sürekli koşturan küçüğünüzün bağırsakları nasıl çalışıyor? Bezini değiştirirken dışkısını kaydedin. Kabızlık riski varsa uygulamadaki doğal lifli gıda önerilerine mutlaka göz atın.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'Karanlıktan mı korkuyor? 🌌', 'Odanın ışığını kapattığınızda ağlıyor mu? Beyaz Sesler arasından anne karnı sesini (kalp atışı) açarak ona eskiden tanıdığı o eşsiz güven duygusunu yaşatın.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'Sabah enerjinizi koruyun ⚡', 'Güne aç karnına başlamayın! Kadınlar için sağlıklı tariflerden 5 dakikada hazırlanan, tok tutan ve lezzetli bir yulaflı kek seçerek kendinize iyi bakın.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'Sizin de arkadaşlara ihtiyacınız var 👯‍♀️', 'Yalnızca çocuğunuzla konuşmaktan yoruldunuz mu? Anne Dostu Mekanlardan oyun grupları bulunan merkezleri keşfedin, diğer annelerle sosyalleşin ve deneyimlerinizi paylaşın.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'Gündüz uykusu kısalıyor mu? ⏱️', 'Gece uykuya dalması çok mu uzun sürdü? Uyku zamanlayıcısını başlatın ve programını takip edin. Belki de gündüz uykusunu 15-20 dakika kısaltmanın tam zamanıdır.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni beceri, attığı her öz güvenli adım sizin emeğinizin sonucudur. Duygu Günlüğünü açın ve bugün kendinizle gurur duymanızı sağlayacak bir not yazın!'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'Yeşillik görünce kaçıyor mu? 🥦', 'Renk seçiciliği başladı mı? Bebek tariflerinde ıspanak ve havucu lezzetli pankeklerin içine ustalıkla gizlemeyi keşfederek iştahını artırın.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'Küçük ressam iş başında 🎨', 'Üstü başı boya olsa bile sinirlenmeyin! Bu yaratıcı anı hemen Bebek fotoğraf çekimindeki neşeli çıkartmalarla süsleyip albüme ekleyin ve gülümseyin.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'Vurma veya itme 🦖', 'Sinirlendiğinde aniden vuruyor veya arkadaşlarını itiyor mu? Bu yaşta yoğunlaşan duyguları nazikçe nasıl yönlendirebileceğinizi Anacan AI''a sorun.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'Kemikler güçleniyor 🦴', 'Hızlı gelişim kalsiyum gerektirir. Beslenme takip aracıyla bugün tüketmesi gereken peynir ve yoğurt miktarını karşılayıp karşılamadığınızı kontrol edin, eksikleri tamamlayın.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'Doğal sakinleştirici 🍃', 'Çok gürültülü bir gün müydü? Zamanlayıcı durdu. Ev işlerini unutun, Beyaz Seslerden çay şırıltısını açıp dinlenmek için kanepeye uzanın.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'Kitapları yırtmak değil, okumak 📖', 'Akşam masalı sırasında sayfaları yırtıyor mu? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi hemen Bloglar bölümünden okuyun.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'Yatakta bitmeyen gösteri 🛌', 'Uyumak yerine yatakta zıplıyor mu? Uyku zamanlayıcısını başlatın ve düzenini takip edin. Enerjisini yeterince atamadığını mı, yoksa aşırı yorulduğunu mu analiz edin.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'Diş fırçalama kavgası 🪥', 'Fırçayı görür görmez ağzını sımsıkı kapatıyor mu? Önerilen Ürünlerdeki müzikli veya parmak fırçalarına göz atarak bu önemli rutini eğlenceli bir oyuna dönüştürmeyi keşfedin.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'Öfkeli ısırıklar 🦖', 'Sinirlendiğinde arkadaşlarını veya sizi ısırıyor mu? Bu zor davranışla sevgiyle nasıl başa çıkabileceğinizi uzman yardımcımız Anacan AI''a hemen sorun.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'Sadece ekmek mi yiyor? 🍞', 'Protein ve sebzeleri bir kenara itip yalnızca karbonhidrat mı istiyor? Beslenme takip aracıyla bugün ne kadar besleyici gıda tükettiğini hesaplayın ve miktarı buna göre ayarlayın.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'Sayfaları yırtma hevesi 📖', 'Akşam masalı sırasında kitabın sayfalarını yırtmak mı istiyor? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi Bloglar bölümünden okuyun.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'Duvardaki sanat eseri 🎨', 'Kalemi eline alıp duvarı mı boyadı? Sinirlenmeyin! Bu tatlı yaramazlığı Bebek fotoğraf çekimindeki komik çerçevelerle albüme ekleyin ve sadece gülümseyin.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'Beliniz mi ağrıyor? 🧘‍♀️', '12+ kq ağırlığındaki ufaklığı sürekli kaldırmak kolay değil. Sağlıklı tariflerden kasları rahatlatan, iltihap karşıtı zencefil çayını demleyip dinlenin.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'Yataktan kaçış planı 🏃‍♂️', 'Uyku vakti geldiğinde beşikten tırmanıp çıkıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Seslerden monoton tren sesini açarak onu sakince uykuya hazırlayın.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'Lazımlık sinyalleri? 🚽', 'Sabah bezi kupkuru mu? Tuvalet eğitimine başlamak için ideal zaman olabilir. Bez takip aracına kaydedin ve Önerilen Ürünlerdeki ergonomik lazımlık seçeneklerine göz atın.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'Tek başına mı oynamak istiyor? 👶', 'Parkta diğer çocuklara katılmayıp onları uzaktan mı izliyor? Bu sağlıklı paralel oyun dönemiyle ilgili en ilginç bilimsel bilgileri Bloglar bölümünde keşfedin.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'Hava tuhaf diye evde mi kaldınız?', 'Hava Durumu ve Giyim aracı size rüzgâr hızını ve doğru kombini anında söylesin, siz de gönül rahatlığıyla parka çıkın.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'Son azı dişleri mi? 🦷', 'Durup dururken her şeyi kemiriyor ve agresifleşiyor mu? En arkadaki azı dişleri çıkmak üzere olabilir. Diş Çıkarma Takibi''ne süreci kaydedip soğuk diş kaşıyıcılarını hazırlayın.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'Masalın kahramanı 🪄', 'Bu akşam Akıllı Masallar''da kahramanı kendi çocuğunuz olan özel bir hikâye oluşturun: Dişlerini fırçalamayı seven cesur minik.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'Kendinize zaman ayırın 🛋️', 'Peşinden koşmaktan yoruldunuz. Çocuğunuz uyudu; şimdi tüm stresinizi Duygu Günlüğü''ne yazıp kendinize bir fincan melisa çayı hazırlayın.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'Aç mı, susuz mu? 💧', 'Bazen susuzluk iştahsızlıkla karıştırılır. Bez Takibi''ndeki idrar ve dışkı kayıtlarını kontrol ederek yeterince sıvı aldığından hemen emin olun.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'Minik şarkıcı 🎤', 'Aynı şarkıyı durmadan mı söylüyor? Bu, ritim duygusunu ve dil gelişimini destekler.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'Hayal gücü sınır tanımıyor 🧸', 'Oyuncak ayısına yemek mi yediriyor, yoksa sizi mi muayene ediyor? Empati gelişimini harika şekilde destekleyen doktor veya mutfak setleri için Önerilen Ürünler''e göz atın.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'Ayrılık korkusu geri mi döndü? 🌌', 'Odadan çıkar çıkmaz arkanızdan ağlıyor mu? Beyaz Sesler''den kalp atışı sesini açarak ona güven duygusu verin ve uykuya hazırlayın.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'Pantolonlar yine kısaldı! 📏', 'Gömleklerin kolları dar mı geliyor? Fiziksel gelişim sıçraması yaşıyor olabilir. Güncel ölçülerini Gelişim Takibi''ne girip büyüme grafiğine gururla bakın.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'Annenin protein deposu ⚡', 'Hareketli bir miniğin peşinden koşmak kolay değil. Kadınlara özel sağlıklı tariflerden protein ve meyve açısından zengin bir enerji smoothie’si hazırlayıp enerjinizi yenileyin.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'Bunu ben yapacağım! 👕', 'Sabahları giyinmek büyük bir krize mi dönüşüyor? İnatçılıkla başa çıkmanın ve ona seçim hakkı vermenin püf noktalarını hemen Anacan AI''dan öğrenin.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'Doyduğunu nasıl anlarız? ⏱️', 'Yemeği atmaya veya tükürmeye başladıysa doyduğunu söylüyor olabilir. Beslenme zamanlayıcısını durdurun, yeterince yediğini kaydedip iştahını analiz edin.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'Kitap sevgisi 📖', 'En sevdiği masal kitabını getirip kucağınıza mı oturuyor? Dikkat süresi uzuyor. Onunla birlikte okuyun ve resimdekilerin adlarını söyleyin.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'Korkular mı başladı? 👻', 'Daha önce korkmadığı elektrikli süpürgeden şimdi korkuyor mu? Hayal gücü geliştikçe yersiz korkular ortaya çıkabilir. Ona sarılın ve güvende olduğunu söyleyin.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'Temiz hava ihtiyacı 🌳', 'Çocuğunuz çok huzursuz ve evde durmuyor mu? Hava Durumu ve Giyim''i kontrol edip hemen parka gidin. Doğa, onun için en hızlı sakinleştiricidir.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'Sizin de arkadaşlara ihtiyacınız var 👯‍♀️', 'Yalnızca çocuğunuzla konuşmaktan yoruldunuz mu? Anne Dostu Mekânlar''dan oyun grupları bulunan merkezleri keşfedin, diğer annelerle sosyalleşip deneyimlerinizi paylaşın.'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'Mükemmel anne arayışı 💖', 'Bugün sesiniz biraz yükseldi mi? Vicdan azabı çekmeyin. Duygu Günlüğüne hislerinizi yazın; siz zaten onun için en iyi annesiniz.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'Uyku düzenini analiz edelim ⏱️', 'Akşam uyanık kalma süresi fazla mı uzadı? Uyku zamanlayıcısını başlatın ve programı takip edin. Belki de gündüz uykusunu 15 dakika kısaltmanın tam zamanıdır.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'Kum ve çamur terapisi 🏖️', 'Kirlenmekten korkmayın! Duyusal gelişimi için Anne Dostu Mekanlar arasından kum havuzu bulunan güvenli bir park bulup onu doğayla baş başa bırakın.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'Demirin en iyi dostu 🥩', 'Demirin vücutta emilebilmesi için C vitamini şarttır! Beslenme takip aracıyla bugünkü menüyü kontrol edin ve etin yanına bol limonlu bir salata ekleyin.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'Sadece ekmek mi yiyor? 🍞', 'Protein ve sebzeleri bir kenara itip sadece karbonhidrat mı istiyor? Beslenme takip aracıyla bugün ne kadar faydalı besin tükettiğini hesaplayın ve miktarları dengeleyin.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'Sayfaları yırtma merakı 📖', 'Akşam masalı sırasında kitabın sayfalarını parçalamak mı istiyor? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi Bloglar bölümünden okuyun.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'Öfkeli ısırıklar 🦖', 'Sinirlendiğinde arkadaşlarını veya sizi mi ısırıyor? Bu zorlayıcı davranışı sevgiyle nasıl çözebileceğinizi hemen Anacan AI uzman yardımcımıza sorun.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'Beliniz ağrıyor mu? 🧘‍♀️', '12+ kq ağırlığındaki minik çocuğunuzu sürekli kaldırmak kolay değil. Kadınlara özel sağlıklı tariflerden kasları rahatlatan, iltihap karşıtı zencefil çayı hazırlayıp dinlenin.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'Duvardaki sanat eseri 🎨', 'Eline kalemi alıp duvarı mı boyadı? Sinirlenmeyin! Bu tatlı yaramazlığı Bebek Fotoğraf Çekimindeki eğlenceli çerçevelerle albüme ekleyin ve sadece gülümseyin.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'Yataktan kaçış planı 🏃‍♂️', 'Uyku saati geldiğinde beşikten tırmanarak çıkıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Seslerden tekdüze tren sesini açın ve onu sakince uykuya hazırlayın.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'İki ayakla zıplama 🦘', 'Olduğu yerde iki ayağıyla aynı anda zıplamaya mı çalışıyor? Çok komik görünüyor, değil mi? Bu anı mutlaka ölümsüzleştirin.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'Müzikli huzur 🎶', 'Akşamüstü başlayan huysuzlanmaları yatıştırmanın en kolay yolu, sevdiği bir melodiyi açıp ona sarılarak yavaşça dans etmektir.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'Uykuyu mu reddediyor? 🥱', 'Gündüz uykusuna yatmak istemiyor, direniyor mu? Anacan AI''dan 2 yaşa yaklaşırken uyku pencereleri hakkında net bilgiler ve bir uyku düzeni programı isteyin.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'Sağlıklı tatlı arayışı 🍎', 'Hazır bisküvilere son! Bebek Tariflerinde evde 10 dakikada hazırlanan, hurmalı ve elmalı sağlıklı tatlıları keşfederek iştahını artırın.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'Diş fırçalama mücadelesi 🪥', 'Fırçayı görür görmez ağzını sımsıkı kapatıyor mu? Bu önemli hijyen rutinini nasıl eğlenceli bir oyuna dönüştürebileceğinizi öğrenmek için Anacan AI''dan pratik öneriler alın.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'Komik telaffuzlar 🗣️', 'Bazı kelimeleri o kadar tatlı ve yanlış söylüyor ki! Bu değerli anları kaçırmayın. Bebek Albümüne sesli video olarak yükleyin ve gelecekte birlikte gülün.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'Temizlik yardımcısı 🧹', 'Artık ev işlerine katılmak istiyor. Bloglar bölümünde yaklaşık 2 yaşındaki bir çocuğa sorumluluk duygusunu oyunla nasıl kazandırabileceğinizi okuyup uygulayın.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'Kendinizle gurur duyun! 🌟', 'Her gün öğrendiği yeni beceri, attığı her özgüvenli adım sizin emeğinizin eseri. Duygu Günlüğünü açın ve bugün kendinizle gurur duymanızı sağlayacak bir not yazın!'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'Gizli sebze operasyonu 🥦', 'Brokoliyi görür görmez tabağı itiyor mu? Bebek tariflerinde bu vitaminleri lezzetli pankeklerin içine ustalıkla nasıl saklayabileceğinizi keşfedin ve iştahını artırın.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'Oyun bir türlü bitmiyor ⏱️', 'Yatağa gitmek yerine kaçıp saklanıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Seslerden okyanus dalgalarını açarak odayı sakin bir uyku mağarasına dönüştürün.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'Sabah çok mu erken uyanıyor? 🌅', 'Güneş doğmadan uyanıp enerjiyle doluyor mu? Bu uyku düzenini daha makul saatlere nasıl çekebileceğinizi öğrenmek için hemen Anacan AI uzman yardımcımızdan ipuçları alın.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'Mantık oyunları 🧩', 'Oyuncakları kutunun içine atıp sonra hepsini boşaltıyor mu? İçerisi ve dışarısı kavramları gelişiyor. Bu bilişsel beceriyi Gelişim Takibine kaydedin.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'Ayakkabı inadı 👟', 'Dışarı çıkarken yazın mutlaka o kışlık ayakkabıyı giymek mi istiyor? Bazen seçimlerine izin verin; bu, iradesini güçlendirir.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'Sorunuz mu var? 🤖', '2 yaş krizleri hakkında okuduklarınız sizi korkutuyor mu? İnternette kaybolmayın; doğrudan Anacan AI''a yazın ve bu dönemi nasıl daha kolay atlatabileceğinizi öğrenin.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'Koltuk dağcısı! 🧗', 'Mobilyaların üzerinde dolaşmak en büyük hobisi mi? Bu cesur ve komik motor beceri gösterisini Bebek fotoğraf çekimindeki eğlenceli çıkartmalarla süsleyip albüme yükleyin.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'Annenin enerjisi mi tükendi? 🔋', 'Öğle saatlerinde ayakta uyukluyor musunuz? Kadınlara özel sağlıklı tariflerden, kafeine ihtiyaç duymadan anında enerji veren proteinli fıstık ezmeli smoothie hazırlayın.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'Bugün her şey zor muydu? 💆‍♀️', 'Durmadan bağırma ve ağlama sesi mi duydunuz? Derin bir nefes alın, kendinizi yargılamayı bırakın; siz harikasınız!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'Mutfaktaki bütün tencereler yerde mi?', 'Zararsız eşyalarla oynamak, mantıksal düşünme becerisini geliştirir. Bırakın hazinesini özgürce keşfetsin.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'Sessizlik ihtiyacı 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamın desibel seviyesini kontrol edin ve ani gürültülerden kaçının.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'Mükemmellik yanılsaması 🛋️', 'Sosyal medyada sürekli neşeli görünen annelere bakıp kendinizi suçlamayın. Yorgunluğunuz da dağınık odanız da hayatın en doğal gerçekleridir.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'Kelimelerden cümlelere 🗣️', 'Artık 3 kelimelik komik cümleler kurmaya mı başladı? Bu muhteşem dil gelişimini ve sevimli telaffuzlarını sesli video olarak kaydedip geleceğe saklayın.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'Sayfalar canlanıyor 📖', 'Masal okurken kitaptaki hayvanların seslerini taklit ediyor mu? Bloglar bölümünde hayal gücünün gelişimini destekleyen interaktif okuma tekniklerini mutlaka okuyun.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'Enerji patlaması 💥', 'Evin dört duvarı bu koşuşturmalara dayanmıyor. Anne Dostu Mekanlar haritasını açın, yumuşak zeminli ve büyük kaydıraklı güvenli bir park bulup özgürce hareket etmesine izin verin.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'Kendim fırçalayacağım! 🪥', 'Diş fırçasını sizden alıp kendi fırçalamak istiyor ama aslında dişlerini fırçalamıyor mu? Bu süreci kolaylaştıracak müzikli ve ergonomik modelleri hemen Önerilen Ürünler''de arayın.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'Sıvı alımı ve kabızlık 💧', 'Çok koşuyor, az su mu içiyor? Bezini değiştirirken dışkısını takip edin. Kabızlık riski varsa uygulamaya kaydedin ve hemen Beslenme Takibi aracıyla lifli gıdalar ekleyin.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'Masada sabır sınavı 🥣', 'Yemeğiyle oynayıp her yeri kirletiyor mu? Beslenme zamanlayıcısını başlatın, iştahının seyrini grafik üzerinden analiz ederek sürecin ne kadar sürdüğünü tam olarak takip edin.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'Her şeyi yere atma hevesi 🛑', 'Sinirlendiğinde veya sıkıldığında elindekini savurup atıyor mu? Bu duygusal tepkileri nazikçe nasıl yönlendirebileceğinizi Anacan AI''a sorun.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'Kıyafetleri küçülüyor! 📏', 'Giydirirken kollarının dar geldiğini fark ettiniz mi? 2 yaşına yaklaşırken fiziksel bir büyüme atağı yaşanır! Güncel boy ölçüsünü Gelişim Takibi''ne girin ve gelişim eğrisine gururla bakın.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Ev işlerine koşmayın! Kadınlara özel sağlıklı tariflerden melisa çayı demleyin ve Ruh Hali Günlüğü''ne bugünkü küçük başarılarınızı kaydedin.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'Demirin gücü 🥩', 'Hareketli miniğinizin kansızlık yaşamaması ve enerjik kalması için Beslenme Takibi aracından bugünkü demir alımını kontrol edin; eksiklik varsa menüyü düzenleyin.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'Tekdüzeliğin büyüsü 🌬️', 'Televizyon kapandıktan sonraki ani sessizlik onu huzursuz eder. Odada Beyaz Sesler''den vantilatör veya saç kurutma makinesi sesini açın ve uyku ortamında nasıl güven hissi yarattığını görün.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'Boyalı eller sanatı 🎨', 'Renklerle oynarken yüzünü gözünü boyaya mı buladı? Sinirlenmek yerine bu eğlenceli ve yaratıcı anın hemen fotoğrafını çekip albüme en renkli anı olarak ekleyin.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'Gece ritüelleri 🧸', 'Her akşam aynı oyuncağa sarılıp mı uyuyor? Bu tatlı güven anını fotoğrafsız, yalnızca bir betimleme olarak Bebek Albümü''nün notlar bölümüne yazıp unutulmaz kılın.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'İlk arkadaşlık denemeleri 👶', 'Parkta başka bir çocuğun oyuncağına ilgi gösterip sesler mi çıkarıyor? Bu sosyalleşme dönemini nasıl destekleyebileceğinizi Anne Dostu Mekanlar''da diğer annelerle sohbet ederek keşfedin.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'Küçük doktor iş başında 🩺', 'Oyuncak ayısına iğne yapıyor ya da karnını mı dinliyor? Hayal gücüne dayalı oyunlar zirvede! Bloglar bölümünde rol yapma oyunlarının zeka gelişimi üzerindeki inanılmaz etkisini okuyun.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'Bezi tamamen kuru mu uyandı? 🩲', 'Sabah bezini değiştirirken kuru olduğunu fark ettiniz mi? Bu, fiziksel olarak lazımlık eğitimine hazır olduğunun başlıca göstergelerinden biridir! Bez Takibi''ne kaydedip istatistikleri dikkatle izleyin.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'Şekersiz ama tatlı 🍪', 'Öğleden sonra atıştırmalık mı istiyor? Market bisküvilerine gerek yok. Bebek tariflerinde 10 dakikada hazırlanan hurmalı ve yulaflı sağlıklı tatlıları keşfedin.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'Düzenini ayrıntılı inceleyelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu 20 dakika kısaltmanın ve akşam yatış saatini erkene çekmenin tam zamanıdır.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'Mantıksal sıçrama 🧩', 'Neden-sonuç ilişkisi kurmaya başladı. Bloglar bölümünde yaklaşık 2 yaşındaki çocukların bilişsel gelişimini hızlandıran en iyi ev oyunlarını okuyup uygulayın.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'Kalsiyum kalkanı 🦴', 'Dişler ve kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tüketilmesi gereken yoğurt ve peynir miktarına uyup uymadığınızı kontrol edin.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'Pankek canavarı 🥞', 'Kahvaltı yapmak istemiyor mu? Bebek tariflerindeki şekersiz muzlu pankek tarifine göz atın. Hem eline alıp kendi yiyecek hem de iştahı açılacak.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'Sofrada sabır sınavı 🥣', 'Yemekle oynuyor ve her yeri kirletiyor mu? Beslenme zamanlayıcısını başlatın, iştahının seyrini grafik üzerinden analiz ederek sürecin ne kadar sürdüğünü tam olarak takip edin.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'Kum ve çamur terapisi 🏖️', 'Kirlenmekten korkmayın! Kinetik kum veya duyusal oyunlar için en iyi ürünleri hemen Önerilen Ürünler bölümünde keşfedin.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'Enerji atma sanatı 🧗', 'Evin duvarları artık ona yetmiyor. Anne Dostu Mekânlar haritasını açın; zıplayıp koşabileceği, yumuşak zeminli ve güvenli bir oyun alanı bulunan mekânı keşfedin.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'Seçici iştah 🥦', 'Yalnızca makarna veya ekmek mi istiyor? Beslenme takip aracıyla menüsünü analiz edin ve eksik vitaminleri Bebek tariflerindeki ilgi çekici porsiyonlarla tamamlayın.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'Işıkları azaltın 🌙', 'Uyku saatinden 1 saat önce evdeki tüm parlak ışıkları ve ekranları kapatın. Melatonin yalnızca sakin ve loş bir ortamda salgılanır.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'Akıllı oyuncaklar 🧩', '2 yaşındaki bir zihnin yalnızca ses çıkaran değil, öğreten oyuncaklara ihtiyacı vardır. Önerilen Ürünler bölümünde mantıksal gelişimi destekleyen ahşap yapbozları keşfedin.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'Şekersiz pasta hazırlığı 🎂', 'Yarınki özel gün için sağlıklı bir pasta lazım! Bebek tariflerinde rafine şeker içermeyen, meyveli ve tamamen çocuk dostu pasta tariflerini keşfedin.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'Annenin güç merkezi 🥗', 'Kendi enerjinizi yenilemeyi unutmayın! Sağlıklı tariflerden anında enerji veren, fıstık ezmeli ve proteinli bir smoothie hazırlayın.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'Resmen 2 yaşında! 🎈', 'Kesintisiz emek, sevgi ve uykusuzlukla geçen 2 yıl. Tüm bu 730 günün gururunu Duygu Günlüğü''ne yazın. Siz gerçekten harika bir annesiniz!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'Siz başardınız 🥂', 'İki yıllık özveri! Çocuğunuz uyuduysa ev işlerini bırakın. Duygu Günlüğü''nü açın, kendinize bir teşekkür notu yazın ve sadece dinlenin.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', '2 yaş sendromu mu? 🌪️', '“Hayır”lar ve bağırmalar arttı mı? Bu meşhur dönemi daha rahat geçirmek için hemen Anacan AI''dan duygusal krizleri yönetme taktikleri alın.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'Masada oturmak istemiyor 🥣', 'Yemekten çabuk sıkılıp kaçıyor mu? Beslenme zamanlayıcısını başlatın, sürecin ne kadar sürdüğünü kaydedin ve zorla yedirmekten kesinlikle kaçının.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'Sessizlik ihtiyacı 🤫', 'Dünkü gürültünün ardından odanın sessizliğini Ses Ölçer ile koruyun. Gece bölünen uyku hem onun hem de sizin ruh hâlinizi olumsuz etkiler.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'Sabah krizleri 👗', '“Bu ayakkabıyı istemiyorum!” inadı sabahlarınızı zorlaştırıyor mu? Ona alternatifler sunarak seçim özgürlüğü tanımanın en etkili psikolojik yollarını Anacan AI''dan öğrenin.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'Annenin protein deposu ⚡', 'Hareketli miniğin peşinden koşmak kolay değil. Kendinizi tüketmeyin! Sağlıklı tariflerden protein ve meyve açısından zengin bir enerji smoothie’si hazırlayarak enerjinizi geri kazanın.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'Doğal sakinleştirici 🍃', 'Çok gürültülü ve koşturmacalı bir gün müydü? Zamanlayıcı sona erdi. Odayı karartın, Beyaz Sesler''den dere şırıltısını açarak hem onun hem de kendinizin zihnini dinlendirin.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'Bağımsızlık savaşı! 👕', 'Kendi başına giyinmek istiyor ve yardımınızı reddediyor mu? Bu inadı nasıl sağlıklı bir gelişim fırsatına dönüştürebileceğinizi hemen Anacan AI uzman yardımcımıza sorun.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'Demir deposu kontrolü 🥩', 'Hareketli miniğinizin kansızlık yaşamaması için Beslenme Takibi aracından bugünkü demir alımını (et, baklagiller) kontrol edin ve menüyü güncelleyin.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'Gece yavaşlama zamanı 🎶', 'Koşmaktan yorulmuyor ve yatağa gitmiyor mu? Uyku zamanlayıcısını başlatın, Beyaz Sesler''den okyanus dalgalarının sesini açarak odada sakin ve uykuya uygun bir ortam oluşturun.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'Masalı o anlatsın 📖', 'Kitaptaki resimlere bakıp kendi dilinde bir şeyler mi anlatıyor? Bu harika hayal gücü anını hemen sesli video olarak Bebek Albümü''ne ekleyin ve gelecek için saklayın.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'Güvenli koşu alanı 🏃‍♀️', 'Evde enerjisini atamıyor ve her yeri dağıtıyor mu? Anne Dostu Mekanlar haritasını açın, güvenle koşabileceği bir park bulup temiz havaya çıkın.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'Yanlış bardak kavgası mı? 🥤', 'Suyu kırmızı değil de mavi bardakta verdiğiniz için kıyamet mi koptu? Mantıksız görünen bu krizleri soğukkanlılıkla nasıl yönetebileceğinizi Anacan AI''dan öğrenin.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'Gece uyanmaları ⏱️', 'Uyku zamanlayıcısını başlatın! Gece terörü veya uyku gerilemesi olup olmadığını zamanlayıcının istatistik grafiğinden ayrıntılı olarak analiz edin ve uyku düzenini buna göre ayarlayın.'),
