  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'Kabızlık sorunu mu var? 🚽', 'Sabah bezini değiştirirken dışkısını gözlemleyin. Kabızlık varsa uygulamaya kaydedin, ardından Beslenme Takibi aracıyla hemen lifli gıdalar ekleyerek dengeyi koruyun.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'Ekran karşısında kriz 📱', 'Telefonu elinden aldığınızda kendini yere mi atıyor? Ekran süresini strese yol açmadan nasıl sınırlayacağınızı ve sağlıklı sınırlar koymayı Anacan AI''dan öğrenin.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni bir beceride sizin emeğiniz var. Duygu Günlüğü''nü açın ve bugün kendinizi ayakta alkışlamanızı sağlayacak bir not yazın!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'Diş fırçalama kavgası 🪥', 'Diş fırçasını görür görmez kaçıyor mu? Önerilen Ürünler''deki müzikli veya döner başlıklı çocuk diş fırçalarına göz atarak bu önemli hijyen sürecini eğlenceli bir oyuna dönüştürün.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'Doğal sakinleştirici 🍃', 'Çok gürültülü ve koşturmacalı bir gün müydü? Zamanlayıcı sona erdi. Odayı karartın, Beyaz Sesler''den dere şırıltısını açarak hem onun hem de kendinizin zihnini dinlendirin.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'Doğum günü sonrası kaos 🌪️', 'Dünkü partinin ardından ev darmadağın mı? Hemen temizliğe girişmeyin. 2 yaşına yeni giren miniğinizle bugünü sadece dinlenmeye ayırın.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'Doğanın sanatçısı 🍂', 'Evden çıkın! Parktaki yapraklar ve taşlar en iyi duyusal materyallerdir. Anne Dostu Mekanlar arasından geniş yeşil alanı olan bir yer bulun.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'Bol su, kolay sindirim 💧', 'Koşup oynamaktan su içmeyi mi unutuyor? Bez takipçisine sabah kaydını girin ve kabızlık riskine karşı sıvı/lif dengesini hemen analiz edin.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'Akşam masalı alışkanlığı 📖', 'Okuduğunuz masalı kendi diliyle tekrar mı anlatıyor? Bu muhteşem dil gelişimi sıçramasını hemen sesli video olarak Bebek Albümüne ekleyip geleceğe saklayın.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', 'Benim! dönemi 🧸', 'Parkta oyuncağını paylaşmayıp bağırıyor mu? 2 yaş benmerkezciliğini saldırganlığa dönüşmeden sağlıklı biçimde nasıl yönetebileceğinizi Anacan AI''dan öğrenin.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'İltihap karşıtı güç 🍵', 'Çocuğunuzu kucağınıza almaktan beliniz ve kollarınız mı ağrıyor? Kadınlara özel sağlıklı tariflerden zencefilli limonlu çay demleyerek bedeninizin toparlanmasına destek olun.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'Düzeni analiz edelim ⏱️', 'Akşam uyanık kalma süresi çok mu uzadı? Uyku zamanlayıcısını başlatın ve çizelgeyi takip edin. Belki de gündüz uykusunu 20 dakika kısaltmanın zamanı gelmiştir!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'Taklitlere devam ediyor 🦜', 'Siz telefonla konuşurken o da kumandayı eline alıp kulağına mı götürüyor? Sizi 100% taklit ediyor! Ona iyi örnek olmaya çalışın.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', 'Hayır kelimesinin gücü 🛑', 'Bir şey önerdiğinizde başını sallayarak hayır mı diyor? Bu inatçılık değil, kendi fikrini ifade etme biçimidir. Ona seçenekler sunarak sakinleşmesine yardımcı olun.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'Babanın eğlenceli halleri 🤡', 'Bebeği güldürmenin en iyi yolu, babanın tuhaf sesler çıkarmasıdır. Bu akşamki neşeli anların çocuğunuzla birlikte tadını çıkarın.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'Şekersiz ama lezzetli 🥞', 'Tatlı mı arıyor? Markete gitmeyin. Bebek tariflerindeki sadece 10 dakikada hazırlanan muzlu ve elmalı pankekleri deneyerek iştahını açın.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'Diş fırçası savaşı 🪥', 'Dişlerini fırçalamak büyük bir mücadeleye mi dönüşüyor? Önerilen Ürünlerdeki müzikli veya sevdiği çizgi film kahramanının yer aldığı fırçalara göz atarak bunu hemen oyuna dönüştürün.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'Doğal sakinleştirici 🍃', 'Çok gürültülü ve koşturmacalı bir gün müydü? Zamanlayıcı durdu. Odayı karartın, Beyaz Seslerden dere şırıltısını açıp kendi zihninizi de dinlendirin.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'Demir kalkanı 🥩', 'Enerjisi mi düştü, yoksa sadece yoruldu mu? Beslenme takip aracıyla bugünkü demir alımını (et, baklagiller) kontrol edip eksikleri hemen tamamlayın.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'Doktorculuk oyunu başladı 🩺', 'Oyuncak ayısına iğne mi yapıyor? Hayal gücüne dayalı oyunlar zirvede. Bu tatlı anı Bebek fotoğraf çekimiyle yakalayıp unutulmaz bir hatıra olarak saklayın.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'Sizin de molaya ihtiyacınız var ☕', 'Çocuğunuzdan kısa bir süreliğine ayrılıp nefes alın! Anne Dostu Mekanlar arasından çocuk köşesi bulunan bir kafe seçin ve sıcak kahvenizin tadını çıkarın.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'Yataktan kaçış planı 🏃‍♂️', 'Uyku saati geldiğinde kaçıp saklanıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Sesler arasından orman uğultusunu açarak odayı sakin bir mağaraya dönüştürün.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'Paralel oyundan birlikte oyuna 👶', 'Diğer çocuklarla aynı ortamda oynamaya ilgisi artıyor. Bloglar bölümünde 2 yaşındaki çocukların sosyalleşme sırlarını ve oyun parkı psikolojisini keşfedin.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'İnatçı giyinme krizi 👗', 'Bu pantolonu istemiyorum! diyerek ağlıyor mu? Sabahları yaşanan giyinme krizlerini azaltmanın ve ona özgürce seçim yapma hakkı tanımanın yollarını Anacan AI''dan öğrenin.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'Küçük aşçı iş başında 👨‍🍳', 'Mutfakta size yardım ediyor, hamur mu yoğuruyor? Üstü başı una bulanmışken yaşadığınız bu eğlenceli anı sesli video olarak kaydedip ömürlük bir anıya dönüştürün.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'Markette çığlık krizi 🛒', 'Halka açık bir yerde istediği alınmadığı için kendini yere mi attı? Çevrenizdekilerin bakışlarını unutun ve bu 2 yaş krizlerini soğukkanlılıkla yönetmek için Anacan AI ile dertleşin.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'Gece uykusuz mu kaldınız? ☕', 'Gece uyanmaları enerjinizi tüketti mi? Kadınlara özel sağlıklı tariflerden, kafeine ihtiyaç duymadan anında enerji veren proteinli fıstık ezmeli smoothie hazırlayarak canlanın.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'Ani uyanmalar 🌌', 'Gece yarısı ağlayarak uyanıyor ve sakinleşmiyor mu? Gece terörü ile kâbus arasındaki farkı anlamak ve doğru şekilde müdahale etmek için Anacan AI uzmanına yazın.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'Diş fırçalama kavgası sona eriyor 🪥', 'Diş fırçasını görür görmez ağzını sımsıkı kapatıyor mu? Bu süreci kolaylaştıracak müzikli ve ergonomik modelleri hemen Önerilen Ürünler''de arayın, rutini oyuna dönüştürün.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'Demir kalkanı 🥩', 'Aktif miniğinizin kansızlık yaşamaması ve enerjik kalması için Bebek tariflerinde kolay çiğnenen, lezzetli sebzeli köfteleri keşfederek iştahını artırın.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'Sayfaları yırtma hevesi 📖', 'Okumak yerine kitabın sayfalarını mı yırtıyor? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi hemen Anacan AI''a sorun.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', '5 dakikalık enerji ⚡', 'Öğle saatlerinde ayakta uyukluyor musunuz? Kadınlara özel sağlıklı tariflerden, anında enerji veren ve antioksidan deposu olan meyveli yulaf hazırlayarak bedeninizi yenileyin.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'Sözcüklerden cümlelere 🗣️', 'Artık 3-4 sözcüklü komik cümleler kurmaya mı başladı? Bu harika dil gelişimini destekleyen en iyi ev oyunlarını ve hece çalışmalarını Bloglar bölümünden okuyun.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'Masaj zamanı 💆‍♂️', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birbirinize omuz masajı yapın. Siz bir takımsınız!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'Hayali araba sürme 🚗', 'Boş bir kutuyu veya oyuncağı direksiyon gibi çevirip ses mi çıkarıyor? Sembolik oyun becerileri (mış gibi oyun) tam olarak gelişiyor!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'Annelerin dertleşmesi 💬', 'Benim çocuğum bunu neden yapıyor? düşüncesi zihninizi mi kurcalıyor? Anacan Topluluğu''na katılın, diğer annelerin benzer hikâyelerini okuyun.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'Kalsiyum deposu 🦴', 'Dişler ve kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tüketmeniz gereken yoğurt ve peynir miktarını karşılayıp karşılamadığınızı kontrol edin, eksiklerinizi tamamlayın.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', 'Kendim yiyeceğim inadı 🥦', 'Kaşığı elinizden almak istiyor. Bırakın alsın. Üstü kirlenecek ama bu bağımsızlık hissi onun için çok önemli.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni bir beceride, kendi başına attığı her adımda sizin emeğiniz var.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'Zeka geliştirici oyuncaklar 🧩', '2 yaşındaki bir zihnin yalnızca ses çıkaran değil, öğreten oyuncaklara ihtiyacı vardır. Önerilen Ürünler bölümünde mantıksal gelişimi destekleyen ahşap yapbozları ve şekilleri keşfedin.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'Kabızlık sorunu mu var? 🚽', 'Koşup oynamaktan su içmeyi mi unutuyor? Bezini değiştirirken dışkısını takip edin. Kabızlık riski varsa bunu uygulamaya kaydedin ve hemen Beslenme Takibi aracıyla lifli gıdalar ekleyin.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'Düzenini analiz edelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu 20 dakika kısaltıp akşam uyku saatini erkene çekmenin tam zamanıdır.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'Şekersiz ama tatlı 🍪', 'Öğleden sonra atıştırmalık mı istiyor? Market bisküvilerine gerek yok. Bebek tarifleri arasından 10 dakikada hazırlanan, hurmalı ve yulaflı sağlıklı atıştırmalıkları pişirin.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'Komik yüz ifadeleri 🤪', 'Aynanın karşısında yüzünü şekilden şekle mi sokuyor? Bu eğlenceli anı kaçırmayın! Hemen Bebek Fotoğraf Çekimi bölümündeki komik çerçevelerle süsleyip albüme ekleyin.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'Sizin de molaya ihtiyacınız var ☕', 'Evden çıkıp biraz nefes alın! Anne Dostu Mekanlar arasından yakınınızdaki çocuk köşesi bulunan bir kafeyi bulun, sıcak kahvenizin tadını çıkarın ve diğer annelerle tanışın.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'Yanlış renk tabak! 🎨', 'Yemeğini yeşil değil de kırmızı tabakta verdiğiniz için kriz mi çıktı? Bu yaşa özgü mantık dışı inatlaşmaları yönetmek için Bloglar bölümündeki önerileri okuyun.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'Annenin bel ağrıları 🧘‍♀️', '13+ kq ağırlığındaki küçük çocuğunuzu kaldırmaktan beliniz mi ağrıyor? Kadınlar için sağlıklı tarifler arasından kasları rahatlatan zencefil çayı demleyerek kendinize iyi bakın.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'Gizli taklitçi 📸', 'Sizin gibi telefonla mı konuşuyor veya aynı hareketleri mi yapıyor? Bu komik anı Bebek Fotoğraf Çekimi bölümündeki eğlenceli çıkartmalarla süsleyip albüme ekleyin.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'Her şeyi yere atma hevesi 🛑', 'Sinirlendiğinde veya sıkıldığında elindekini savurup atıyor mu? Bu duygusal tepkileri nazikçe nasıl yönlendirebileceğinizi Bloglar bölümündeki yazılardan öğrenin.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'Boyalı eller sanatı 🎨', 'Renklerle oynarken yüzünü gözünü tamamen boyaya mı buladı? Sinirlenmek yerine bu eğlenceli ve yaratıcı anın hemen fotoğrafını çekip en renkli anı olarak Bebek Albümüne ekleyin.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'Doğal sakinleştirici 🍃', 'Zamanlayıcı durdu. Çocuk uyudu. Kendinizi ödüllendirin! Kadınlar için sağlıklı tarifler arasından melisa çayı demleyin, kanepeye uzanın ve bu yorucu günün ardından sessizliğin tadını çıkarın.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'Kendim yıkayacağım! 🧽', 'Banyoda fırçayı veya lifi elinizden mi alıyor? Bu bağımsızlık arayışını destekleyen, çocuk dostu banyo ürünlerini Önerilen Ürünler bölümünde arayın.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', '5 dakikalık enerji ⚡', 'Peşinden koşmaktan bitkin mi düştünüz? Kadınlar için sağlıklı tarifler arasından anında enerji veren, proteinli fıstık ezmeli bir smoothie hazırlayıp tazelenin.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'Uyku düzeni analizi ⏱️', 'Akşamları yatakta çok mu dönüp duruyor? Uyku zamanlayıcısının grafiğine göz atın. Belki de gündüz uykusunu 20 dakika kısaltmanın ve akşam uykusunu erkene çekmenin tam zamanıdır.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'Sessizliğin büyülü fonu 🌊', 'Krizlerle ve gürültüyle dolu bir gün müydü? Beyaz Sesler''den okyanus dalgalarını açarak hem onun hem de kendinizin sinir sistemini sakinleştirin.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'Sebzelerle oyun 🥦', 'Ispanağı reddediyor mu? Bebek tariflerinde bu vitaminleri lezzetli kreplerin içine ustalıkla nasıl saklayabileceğinizi keşfedin ve iştahını artırın.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'Boy atma zamanı! 📏', 'Pantolonları yine mi kısaldı? 25. aya doğru fiziksel gelişim hızlanır. Güncel ölçülerini Gelişim Takibi''ne girin ve gelişim grafiğini gururla inceleyin.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'Temiz hava keşfi 🌳', 'Evin duvarları ona dar geliyor. Anne Dostu Mekanlar''dan geniş ve güvenli bir park bulun; bırakın özgürce koşup tüm enerjisini atsın.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'Sofrada sabır sınavı ⏱️', 'Yemekle oynuyor ama yemiyor mu? Beslenme zamanlayıcısını açın, süreci ne kadar sürdüğünü takip edin ve iştahının seyrini uygulamadaki grafik üzerinden analiz edin.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'Neden aniden vuruyor? 🛑', 'Sinirlendiğinde vuruyor mu? Bu yaşta görülen saldırgan davranışları oyuna dönüştürerek nasıl nazikçe değiştirebileceğinizi Anacan AI uzmanından öğrenin.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'Kahve molası ☕', 'Ev işleri ve çocuk bakımı... Şimdi mola zamanı! Anne Dostu Mekanlar''dan çocuk köşesi olan bir kafe bulun ve sıcak kahvenizin tadını çıkarın.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'Günün kahramanı sizsiniz 🌟', 'Her gün öğrendiği yeni beceride sizin emeğiniz var.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'C vitamini dengesi 🍊', 'Bağışıklığının güçlü olması gerekir. Beslenme takip aracıyla bugün yeterince C vitamini alıp almadığını hesaplayın ve menüyü güncelleyin.'),
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45', 'Bitmek bilmeyen neden? dönemi 🤔', 'O ne?, Neden böyle?... Artık dünyayı sorguluyor! Sabırla cevap verin; çünkü bunlar, beynindeki nöronların bayram ettiği anlardır.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'Mükemmellik zincirini kırın 🛑', 'Çocuğunuz bugün öğle uykusuna yatmadı ve ev darmadağın mı? Hiç sorun değil! Derin bir nefes alın; her şeyi aynı anda kontrol edemezsiniz. Akışına bırakın.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'Sabrınız mı tükeniyor?', 'Odanın kapısını kapatın ve çocuğu babasıyla baş başa bırakın. Bırakın bu akşam evdeki oyun alanının sorumlusu o olsun.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'Evin duvarları üzerinize mi geliyor?', 'Anne Dostu Mekanlar''dan çocuk oyun köşesi olan bir kafe keşfedin. O oynarken siz de kahvenizin tadını çıkarın.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'Kendim giyineceğim 👕', 'Pantolonunu başına geçirmeye çalışsa bile giyinme çabalarına engel olmayın. Bağımsızlık arzusu zirvede! Bu küçük zaferi Gelişim Takibi''ne kaydedin.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'Müzikli huzur 🎶', 'Akşamüstü başlayan huysuzlanmaları yatıştırmanın en kolay yolu, sevdiği bir melodiyi açıp ona sarılarak yavaşça dans etmektir.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'Mide-bağırsak sinyalleri 💩', 'Bez değiştirirken notlarınızı girin. Kabızlık riski varsa uygulamadaki doğal lifli besin önerilerine ve meyveli su tariflerine mutlaka göz atın.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'Ayrılık korkusu? 🌌', 'Odadan çıkar çıkmaz arkanızdan ağlıyor mu? Beyaz Sesler bölümünden anne karnı sesini açarak ona geçmişten tanıdığı o sıcak güven duygusunu yaşatın ve uykuya geçmesini kolaylaştırın.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'Şekersiz ama tatlı 🍪', 'Market bisküvilerine son! Bebek tariflerinde evde 10 dakikada hazırlanan hurmalı ve yulaflı sağlıklı tatlıları keşfedin.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', 'Hayır deme sanatı! 🛑', 'Her şeye hayır mı diyor? Bu, size karşı gelmesi değil, kendi bireyselliğini keşfetmesidir. Ona kapalı uçlu sorular sormak yerine iki seçenek sunarak inatlaşmayı azaltın.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'Hafızanız yine mi unuttu?', 'Evde tükenen her küçük şeyi aklınızda tutmaya çalışmayın; hemen Alışveriş listesine ekleyin, eşiniz halletsin.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'Gecenin bir yarısı çığlık atarak uyanıp susmuyor mu?', '2 yaş krizleri uykuyu da etkiler. Sesini Ağlama analizine dinleterek sorunun ne olduğunu netleştirin.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'Mağara huzuru 🌌', 'Koşmaktan yorulmuyor ve yatağa gitmiyor mu? Uyku zamanlayıcısını başlatın, Beyaz Sesler bölümünden orman uğultusunu açarak odayı huzurlu bir uyku mağarasına dönüştürün.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'Zıplama zamanı 🦘', 'Evde koltukların üzerinde mi zıplıyor? Anne Dostu Mekanlar arasından trambolini ve yumuşak zemini olan bir eğlence merkezi bulun; enerjisini güvenle atsın.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'Çok erken uyanıyor! 🌅', 'Güneş doğmadan ayakta mı? Bu uyku ritmini nasıl düzenleyebileceğinizi öğrenmek için hemen Anacan AI uzman yardımcımızdan pratik ipuçları alın.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'Yeni kelime keşifleri 🗣️', 'Bugün hangi komik kelimeyi uydurdu? Bu harika dil gelişimini sesli bir video olarak Bebek Albümüne kaydedin; yıllar sonra izleyip çok güleceksiniz.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40'::uuid, 'Öğle vakti ayakta mı uyukluyorsunuz?', 'Sağlıklı tariflerden, kafeine ihtiyaç duymadan anında enerji veren fıstık ezmeli bir smoothie hazırlayın.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'Yatakta bitmeyen gösteri 🛌', 'Uyumak yerine yatakta mı zıplıyor? Uyku zamanlayıcısının grafiğini takip edin. Enerjisini yeterince atamadığını mı, yoksa aşırı yorulduğunu mu hemen analiz edin.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Ev işlerine koşmayın! Melisa çayı demleyin ve yalnızca sessizliğin tadını çıkarın.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'Kalsiyum kalkanı 🦴', 'Dişler ve kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tüketilmesi gereken yoğurt ve peynir miktarını karşılayıp karşılamadığınızı kontrol edin, eksikleri tamamlayın.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'Küçük doktor iş başında 🩺', 'Oyuncak ayısına iğne mi yapıyor, yoksa karnını mı dinliyor? Hayal gücüne dayalı oyunlar zirvede! Bu tatlı anı hemen Bebek fotoğraf çekimiyle yakalayın ve unutulmaz bir anıya dönüştürün.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'Sessizlik ihtiyacı 🤫', 'Odanın sessizliğini Ses ölçer ile koruyun. Gece bölünen uyku hem onun gelişimini hem de sizin sabahki ruh halinizi olumsuz etkiler.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'Son azı dişleri mi? 🦷', 'Durup dururken her şeyi kemiriyor ve ellerini ağzından çıkarmıyor mu? En arkadaki azı dişleri (ikinci azılar) geliyor olabilir. Diş çıkarma takipçisini mutlaka kontrol edin.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'Ev işleri bekleyebilir 🛑', 'Yerler silinmedi mi? Bırakın öyle kalsın. Kirli ev temizlenir, ancak tükenmiş bir annenin toparlanması uzun sürer. Kanepeye uzanın ve yalnızca huzuru dinleyin.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'Meyve düşmanlığı 🍎', 'Dün sevdiği meyveyi bugün yere mi atıyor? Yemek seçme bu yaşın klasik sorunlarından biridir. Sağlıklı tariflerdeki eğlenceli ve farklı sunumlara göz atın.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'Hayali oyunlar derinleşiyor 🧸', 'Oyuncaklarına yemek yediriyor, onları uyutuyor mu? Hayal gücü gelişiminin zirve noktası! Bu empati girişimlerini gelişim takipçisine kaydedin.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'Güç birlikten doğar🥂', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birer çay doldurun ve “Biz harika bir takımız” diyerek birbirinizi takdir edin.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'Rutini analiz edelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu 20 dakika kısaltmanın ve akşam rutinini erkene çekmenin tam zamanıdır.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'Toplum içinde kriz 🛒', 'Markette istediği alınmadığı için kendini yere mi attı? Çevrenizdekilerin bakışlarını unutun ve bu krizleri soğukkanlılıkla yönetmek için Anacan AI ile dertleşin.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'Kirlenmekten korkmayın!', 'Kinetik kum veya duyusal oyunlar için en iyi araçları hemen Önerilen Ürünler bölümünde keşfedin ve evinize sipariş verin.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'Annenin enerji bombası ⚡', 'Koşturmaktan gözleriniz mi kapanıyor? Tatlıya değil, proteine yönelin! Kadınlara özel sağlıklı tariflerdeki 5 dakikada hazırlanan fıstık ezmeli smoothie ile enerjinizi yenileyin.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'Gölgelerden korkuyor mu? 🌌', 'Odayı kararttığınızda duvardaki gölgeler onu rahatsız mı ediyor? Gelişen hayal gücü korkulara yol açabilir. Beyaz Sesler bölümünden anne karnı sesini açarak odada güvenli bir atmosfer oluşturun.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'Tuvalete ilk adım mı? 🧻', 'Sabah bezi tamamen kuru kalıyor ve bu durumdan rahatsız mı oluyor? Bu harika bir işarettir. Bez takipçisine kaydedin ve Bloglar bölümünden lazımlık eğitimine hazırlık aşamalarını okumaya başlayın.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', 'Hayır! fırtınası 🛑', 'Her önerinize bağırarak karşı mı çıkıyor? 2 yaş sendromunun bu zorlu anlarında soğukkanlı kalmak ve krizleri oyuna dönüştürmek için hemen Anacan AI uzmanımızdan ipuçları alın.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'Mantık arayışı 🧩', 'Artık basit oyuncaklardan çabucak sıkılıyor. Zihnini geliştirecek ve dikkatini toplamasına yardımcı olacak ahşap yapbozları ve geometrik oyunları Önerilen Ürünler bölümünde keşfedin.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'Bitmeyen koşturmaca 🏃‍♂️', 'Yatağa gitmek yerine kanepelerin üzerinde mi zıplıyor? Uyku zamanlayıcısını başlatın, sürecin ne kadar sürdüğünü kaydedin ve grafiğe göre akşam rutinini erkene çekmeyi değerlendirin.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'Komik cümleler 🗣️', 'Tatlı hatalarla kurduğu o 3-4 kelimelik cümleler altın değerinde! Bu harika gelişimi kaçırmayın; hemen sesli video olarak Bebek Albümüne ekleyip ölümsüzleştirin.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'Enerjisini atamadığı için her şeyi dağıtıyor mu?', 'Anne Dostu Mekânlar haritasını açın, yumuşak zeminli ve kaydıraklı güvenli bir park bulup özgürce oynamasına izin verin.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'Protein deposu kontrolü 🥚', 'Hızla büyüyen kaslar için protein şarttır. Beslenme takip aracıyla bugünkü ihtiyacını (yumurta, et, baklagiller) hesaplayın; eksik varsa menüyü düzenleyin.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'Parmak boyası sanatı! 🎨', 'Renklerle oynarken her yerini boyaya mı buladı? Sinirlenmek yerine bu eğlenceli ve yaratıcı anı hemen Bebek fotoğraf çekimindeki neşeli çıkartmalarla süsleyip albüme yükleyin.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'Gece uyanmaları geri mi döndü? ⏱️', 'Gece yarısı ağlayarak uyanıyor ve tekrar uykuya dalmakta zorlanıyor mu? Uyku zamanlayıcısındaki istatistikleri inceleyin. Belki gündüz uykusu fazla uzadığı için akşam düzeni bozuluyordur?'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'Okumak değil, anlatmak 📖', 'Akşam masalında resimleri size o mu anlatıyor? Bu harika hayal gücü anını sesli olarak kaydedin.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'Kemikler güçleniyor 🦴', 'Hızlı gelişim için kalsiyum gereklidir. Beslenme takip aracıyla bugün yeterli miktarda peynir ve yoğurt tüketip tüketmediğini kontrol edin, eksiklerini tamamlayın.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'Paylaşmak istemiyor mu? 🧸', 'Parkta diğer çocukların oyuncaklarına doğru koşuyor ama kendi oyuncağını vermiyor mu? Bloglar bölümünden 2 yaşındaki çocuklara sırayla oynama kavramını nasıl öğretebileceğinizi öğrenin.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'Uyku düzenini ayrıntılı inceleyelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısındaki grafiğe bakın. Belki gündüz uykusunu 20 dakika kısaltmanın ve akşam uykusunu erkene almanın tam zamanıdır.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'Sizin küçük kopyanız 📸', 'Siz odayı süpürürken o da bezle siliyor veya sizin gibi mi yürüyor? Taklit dönemi zirvede!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'Şekersiz ama tatlı 🍪', 'Market bisküvilerine son! Bebek tariflerinde evde 10 dakikada hazırlanan, hurmalı ve elmalı sağlıklı tatlıları keşfederek onu sevindirin.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'Ani saldırganlık 🛑', 'Sinirlendiğinde arkadaşlarını itiyor veya size vurmaya mı çalışıyor? Bu yaşta yoğunlaşan saldırgan duyguları nasıl nazikçe yönlendirebileceğinizi hemen Anacan AI''a sorun.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'Beliniz ağrıyor mu? 🧘‍♀️', '13+ kq ağırlığındaki ufaklığı kaldırmaktan beliniz mi sızlıyor? Sağlıklı tariflerden kasları rahatlatan, iltihap karşıtı zencefil çayı demleyerek kendinize iyi bakın.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'Sessizlik onu korkutuyor mu?', 'Odada Beyaz Sesler bölümünden vantilatör veya saç kurutma makinesi sesini açın ve uyku ortamında nasıl kusursuz bir güven hissi yarattığını görün.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'Beyin sisi 🌫️', 'Çok yorgun olduğunuz için her şeyi unutuyor musunuz? Kadınlara özel sağlıklı tariflerden Omega-3 bakımından zengin, cevizli bir atıştırmalık hazırlayın ve Duygu Günlüğü''ne yazarak zihninizi boşaltın.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'Lazımlığa itiraz mı ediyor? 🚽', 'Tuvalete gitmek istemiyor ve ağlıyor mu? Eğitime ara vermeniz mi, yoksa farklı bir yöntem denemeniz mi gerektiğini hemen Anacan AI uzman yardımcımıza sorun.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'Yalnızca meyve mi yiyor? 🍎', 'Proteini veya sebzeleri reddediyor mu? Beslenme takip aracıyla bugün ne kadar sağlıklı besin tükettiğini hesaplayın ve meyveli yoğurt gibi lezzetli kombinasyonlar hazırlayın.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'Annenin su dengesi 💧', 'Bebeğinizin peşinden koşarken su içmeyi unuttunuz mu? Baş ağrınızın nedeni bu olabilir. Kadınlara özel sağlıklı tariflerden naneli ve limonlu detoks suyu hazırlayıp canlanın.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'Sabah sindirim kontrolü 💩', 'Bezini değiştirirken dışkısını gözlemleyin. Katı gıdalar arttıkça kabızlık riski yükselir. Durumu uygulamaya kaydedin ve Beslenme Takibi aracını kullanarak lifli gıdaları (armut, yulaf) hemen beslenmesine ekleyin.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'Ani seslerden korkma 🌪️', 'Elektrikli süpürge veya blender sesinden korkuyor mu? Odada Beyaz Gürültüler arasından saç kurutma makinesi sesini açarak hem korkusunu azaltın hem de onu yavaş yavaş uykuya hazırlayın.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'Renkleri ayırma 🔴🔵', 'Mantıksal gelişimini desteklemek için yaşına uygun geometrik yapbozları (puzzle) ve renkli ahşap oyuncakları hemen Önerilen Ürünler''de arayın, zekâsını geliştirin.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'Isırma ve vurma 🦖', 'Öfkelendiğinde aniden elini kaldırıyor veya ısırıyor mu? Bu yaşta yoğunlaşan duygularını nasıl nazikçe yönlendirebileceğinizi Bloglar bölümündeki psikoloji yazılarından okuyun.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'Ayakkabısı birden dar mı geldi? 👟', 'Koşarken sık sık tökezliyor mu? Ayağı büyümüş olabilir! Kilo Takibi''ne güncel boyunu ve ayakkabı numarasını girerek fiziksel gelişimini takip edin.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'Kemikleri güçleniyor 🦴', 'Hızlı gelişim kalsiyum gerektirir. Beslenme Takibi aracıyla bugün yeterli miktarda peynir ve yoğurt tüketip tüketmediğini kontrol edin, eksikleri hemen tamamlayın.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'Siz zaten harikasınız 🌟', 'Bugün durmadan onun peşinden koştunuz ve yoruldunuz. Duygu Günlüğü''nü açın, bugün onun için yaptığınız en küçük iyiliği bile yazın ve kendinizi ayakta alkışlayın!'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'Kendi kendine yeme ısrarı 🥄', 'Kaşığı elinizden alıp her yeri batırıyor mu? Beslenme zamanlayıcısını başlatın ve bu bağımsızlık denemesinin ne kadar sürdüğünü analiz edin. Dökülen yemeklere ise sadece gülümseyin.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'Bu pantolonu istemiyorum! 👗', '“Kendim giyineceğim!” ısrarı başladı mı? Sabahları yaşanan giyinme krizlerini azaltmanın ve ona özgürce seçim yapma hakkı tanımanın yollarını Anacan AI''dan öğrenin.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'Sizin de arkadaşlara ihtiyacınız var 👯‍♀️', 'Yalnızca bebeğinizle konuşmaktan yoruldunuz mu? Anne Dostu Mekânlar''dan oyun grupları bulunan merkezleri keşfedin, diğer annelerle sosyalleşip deneyimlerinizi paylaşın.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'Kitapları yırtmak değil, okumak 📖', 'Akşam masalı sırasında sayfaları yırtıyor veya okumanıza izin vermiyor mu? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi hemen Anacan AI''a sorun.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'Düzenini ayrıntılı inceleyelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu 20 dakika kısaltmanın ve akşam uykusunu erkene çekmenin tam zamanıdır.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'Bitmek bilmeyen “Neden?” soruları 🤔', 'Soru sormaktan hiç yorulmuyor mu? “Bu ne?”, “Neden?” dönemi resmen başladı! Bebeğinizin bu keşfetme merakına sabırla nasıl karşılık verebileceğinizi Bloglardan öğrenin.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'Şekersiz ama tatlı 🍪', 'Market bisküvilerine son! Bebek tariflerinde evde 10 dakikada hazırlayabileceğiniz sağlıklı tatlıları keşfedin ve onu sevindirin.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'Sıcak kahve ve sessizlik 🍵', 'Zamanlayıcı durdu, bebeğiniz uyudu. Hemen ev işlerine koşmayın! Sağlıklı tariflerden kendinize özel bir kahve hazırlayın, kanepeye uzanın ve yalnızca sessizliğin tadını çıkarın.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'Ayaküstü atıştırmayın 🍎', 'Kendinize değer verin! Sağlıklı tariflerden antioksidan deposu olan bir orman meyveleri salatası hazırlayın.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'Tuvalet kağıdı sevgisi 🧻', 'Banyoda tuvalet kağıtlarını rulodan açıp oynuyor mu? Bu ilgisini fırsata çevirin; Bloglar bölümündeki oyunla lazımlık eğitimine geçiş yazısını hemen okumaya başlayın.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'Bir, iki, üç... 🔢', 'Merdivenleri çıkarken bir şeyleri saymaya mı çalışıyor? Bunlar matematiksel gelişimin ilk kıvılcımlarıdır.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'Dişleri tamamlandı mı? 🦷', 'Son azı dişleri mi çıkıyor? Kalsiyum ihtiyacını karşılamak için Beslenme Takibi aracıyla bugünkü yoğurt ve peynir tüketimini mutlaka kontrol edin.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'Yatak odası çok mu sıcak? 🌡️', 'Yatakta çok dönüyor ve terliyor mu? Odanın sıcaklığını kontrol edin, uyku zamanlayıcısını başlatın ve Beyaz Sesler arasından vantilatör sesini açarak odada psikolojik olarak serinlik hissi yaratın.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'Arkanızdan ağlıyor mu? 🚪', 'Odadan çıktığınızda bile arkanızdan bağırıyor mu? Ayrılık kaygısının bu yeni dalgasını nazikçe yönetmenin yollarını Anacan AI''a sorun.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'Mantık iş başında 🧩', 'Geometrik şekilleri eşleştirmede ustalaşıyor mu? Zekâsını daha da zorlayacak daha karmaşık oyunlar için Önerilen Ürünler bölümünü keşfedin.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'Diş macunu seçimi 🪥', 'Suyu tükürmeyi öğrenmeye başladı mı? Florürlü veya florürsüz diş macunu seçimiyle ilgili Bloglar bölümündeki bilimsel yazımızı mutlaka okuyun.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'Çamur pastaları! 🧁', 'Bahçede toprakla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen bu harika anları Bebek fotoğraf çekimiyle ölümsüzleştirin.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'Zihninizi yeniden başlatın 🧘‍♀️', 'Her şey üstünüze üstünüze mi geliyor? Duygu Günlüğünü açın ve 3 dakika boyunca durmadan neler hissettiğinizi yazın. Yazmak stresi hemen azaltır.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'Yer çekimi testi! 🍎', 'Yiyecekleri veya oyuncakları yukarıdan aşağıya atmaya bayılıyor mu? Bu fizik keşiflerini durdurmak yerine farklı bir yöne kanalize etmeyi Anacan AI''dan öğrenin.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'Lif eksikliği mi? 💩', 'Dışkısı sertleşti ve kabızlık onu rahatsız mı ediyor? Bez Takibine kaydedin ve Beslenme Takibi aracıyla menüsüne hemen kuru erik veya yulaf ekleyin.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'İlk oyun arkadaşı 👯‍♂️', 'Parkta başka bir çocukla sürekli oynamaya mı çalışıyor? Anne Dostu Mekânlar bölümünde bu yeni sosyalleşme dönemini destekleyen çocuk kafelerine göz atın.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'Uyku zamanlayıcısı analizi ⏱️', 'Akşamları çok mu geç uyuyor? Uyku zamanlayıcısının grafiğine bakın. Gündüz uykusunu iyice kısaltmanın ve gece uyku saatini erkene çekmenin zamanı yaklaşıyor.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'Ayakkabısı birden dar mı geldi? 👟', 'Koşarken sık sık tökezliyor mu? Ayağı büyümüş olabilir! Gelişim Takibine güncel boyunu ve ayakkabı numarasını girerek fiziksel gelişimini takip edin.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'Kahve mi, su mu? 💧', 'Yorgunluğu kafeinle bastırmaya çalışmayın! Kadınlara özel sağlıklı tarifler arasından enerji veren, proteinli ve meyveli detoks içeceklerini keşfedin.'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'Minik temizlik yardımcısı 🧹', 'Odayı süpürürken o da bezle siliyor ya da elektrikli süpürgeye saldırıyor mu? Bu komik taklit anını hemen Bebek fotoğraf çekimindeki çıkartmalarla süsleyip albüme yükleyin.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'Demir deposu kontrolü 🥩', 'Hareketli miniğinizin kansızlık yaşamaması için Beslenme takip aracında bugünkü demir alımını (et, baklagiller) kontrol edin ve menüsünü güncelleyin.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'Zıplama sanatı 🦘', 'Koltuklar artık ona yetmiyor! Trambolini olan güvenli bir kapalı eğlence merkezi bulup enerjisini atmasına yardımcı olun.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'Minik ressam iş başında 🎨', 'Renklerle oynarken yüzünü gözünü boyaya mı buladı? Sinirlenmek yerine bu eğlenceli ve yaratıcı anın tadını çıkarın.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'Gece uyanmaları geri mi döndü? ⏱️', 'Gece yarısı ağlayarak uyanıyor ve yeniden uykuya dalmakta zorlanıyor mu? Uyku zamanlayıcısındaki istatistikleri inceleyin. Bunun nedeni 2 yaş uyku gerilemesi veya diş çıkarma olabilir.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'Doğal sakinleştirici 🍃', 'Çok gürültülü ve koşturmacalı bir gün mü geçirdiniz? Odayı karartın, Beyaz Seslerden dere şırıltısını açın; hem onun hem de kendinizin zihnini dinlendirin.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'Protein alımı nasıl? 🍗', 'Hareketli kaslar için protein şarttır. Beslenme takip aracıyla günlük besin dengesini ölçün ve menüsünü zenginleştirin.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'En sevdiği şarkılar 🎤', 'Aynı şarkıyı durmadan söylüyor veya mırıldanıyor mu? Bu ritim duygusu ve dil gelişimi anını, Bebek fotoğraf çekimindeki müzik çıkartmalarıyla albüme ekleyerek kaydedin.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'Gündüz uykusuna isyan! 🛌', 'Öğle uykusuna yatmak istemeyip kaçıyor mu? Anacan AI''a 2 yaşındaki çocukların uyku ihtiyaçlarını ve sakin zaman (quiet time) oluşturmanın inceliklerini sorun.'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'Soyunma uzmanı! 🧦', 'Çoraplarını veya pantolonunu kendi başına çıkarmaya mı çalışıyor? Bu, motor becerilerinin geliştiğini gösteren harika bir adımdır.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'Zencefilin gücü 🫖', 'Bütün gün koşturmaktan beliniz ve bacaklarınız mı ağrıyor? Sağlıklı tariflerden kasları rahatlatan bir çay demleyip dinlenin.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'Kuşları gözlemliyoruz 🕊️', 'Evde çok mu sıkıldı? Yemyeşil bir park bulun ve kuşlara yem vererek doğaya karşı empati duygusunu güçlendirin.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'Hikâye uydurma zamanı 📖', 'Kitap okumaktan sıkıldınız mı? Işıkları kapatın, Beyaz Seslerden yağmur sesini açın ve karanlıkta birlikte hayalî masallar uydurarak uykuya dalın.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'Püreye geri dönüş mü? 🥣', 'Katı yiyecekleri çiğnemeye üşenip yeniden püre mi istiyor? Bebek tariflerindeki kolay çiğnenen, ancak püre olmayan ilgi çekici köfte tariflerine göz atın.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'Kendim dolduracağım! 🥛', 'Suyu bardağa kendisi doldurmak istiyor ve her yeri ıslatıyor mu? Bu pratik yaşam becerilerini desteklemek için Önerilen Ürünlerdeki dökülmeyen akıllı bardaklara göz atın.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'Kapıları mı çarpıyor? 🚪', 'Öfkelendiğinde kapıları çarpıp ağlıyor mu? Bu yoğun duygusal patlamaları yönetmek için hemen Anacan AI uzmanımızla iletişime geçerek uygun stratejileri öğrenin.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'Minik şef mutfakta 👩‍🍳', 'Bebek tariflerindeki şekersiz kurabiye hamurunu birlikte yoğurun. Böylece hem motor becerileri gelişsin hem de kendi emeğini afiyetle yesin.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'Küçük Dağcı 🧗', 'Mobilyaların üzerine tırmanmak artık hobiye mi dönüştü? Evin güvenliğini en üst düzeye çıkarmak için Önerilen Ürünler bölümündeki özel koruyuculara göz atın.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'Şırıl şırıl sular 🌊', 'Çok hareketli ve koşturmacalı bir gün mü oldu? Işıkları kısın, Beyaz Sesler bölümünden nehir şırıltısını açın ve ikiniz de kendinizi sakinliğe bırakın.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'Kendinizi alkışlayın 🌟', 'Günü kriz yaşamadan tamamlayabildiniz mi? Siz olmasaydınız bu gelişim de olmazdı. Duygu Günlüğünü açın ve gösterdiğiniz özveri için kendinize kocaman bir teşekkür yazın!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'Oyuncaklara şefkat 🧸', 'Ayısına ninni söylüyor veya üzerini mi örtüyor? Bu, güçlü bir empati gelişiminin göstergesidir. Sesli video olarak Bebek Albümüne ekleyip şefkatini kaydedin.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'Kelime patlaması 🗣️', 'Kelime dağarcığı nasıl? Bloglar bölümünde bu aya ait konuşma gelişimi standartlarını ve gelişimi destekleyen ev oyunlarını keşfedin.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'Yemekler şekilleniyor ⭐️', 'Sıradan şekilde doğranmış meyveleri yemiyor mu? Bebek tariflerindeki yıldız veya hayvan biçimli eğlenceli tabak sunumlarına göz atarak beslenmeyi görsel bir oyuna dönüştürün.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'Saklanıp kaka mı yapıyor? 🙈', 'Perdenin arkasına veya bir köşeye çekilip kaka mı yapıyor? Bu, lazımlık eğitimine hazır olduğunun en önemli psikolojik işaretlerinden biridir! Bez takipçisine kaydedip Bloglardaki eğitim yazılarını okuyun.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'Beliniz mi sızlıyor? 🧘‍♀️', 'Ağırlaşan miniğinizi kaldırmaktan kaslarınız gerildi. Kadınlara özel sağlıklı tariflerden iltihap karşıtı zencefil çayı demleyin, uzanıp kendinize biraz zaman ayırın.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', 'Kendim giyineceğim sanatı 👕', 'Pantolonu başına, tişörtü ayağına giymeye mi çalışıyor? Bu komik bağımsızlık girişimini sakın kaçırmayın! Hemen Bebek fotoğraf çekimindeki eğlenceli çıkartmalarla süsleyip albüme yükleyin.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'Su birikintisi keşfi 🌧️', 'Yağmurdan sonra evde oturmak olmaz! Anne Dostu Mekanlardan yakındaki bir parkı bulun, yağmur çizmelerini giydirip çamurda zıplamasına izin verin.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'Uyku aralığı kayıyor ⏱️', 'Gündüz uykusunu reddetti mi? Akşam aşırı yorulup kriz yaşamaması için uyku zamanlayıcısını başlatın ve akşam rutinini 30 dakika erkene alın.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'Parmak motor becerileri gelişiyor 🧩', 'Artık basit yapbozları ezberledi. Zihnini daha fazla zorlayacak, daha karmaşık ve çok parçalı ahşap yapbozları Önerilen Ürünler bölümünde keşfedin.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'Yerde ağlama krizi 🛑', 'Halka açık bir yerde kendini yere atıp bağırıyor mu? Çevrenin bakışlarına aldırmayın! Bu şiddetli duygusal patlamaları soğukkanlılıkla yönetmek için Anacan AI ile dertleşip taktikler öğrenin.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'Kitabı yırtmak değil, okumak 📖', 'Akşam masalı sırasında sayfaları mı yırtıyor? Okuma alışkanlığına zarar vermeden dikkatini masala nasıl çekebileceğinizi Bloglar bölümünden okuyun.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'Kalsiyum yalnızca sütte bulunmaz 🧀', 'Süt içmeyi reddediyor mu? Kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tükettiği peynir, yoğurt veya brokoli miktarını hesaplayıp eksikleri tamamlayın.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'Çamaşır katlama oyunu 🧺', 'Siz çamaşırları toplarken o da yardım etmek mi istiyor? Çorapları eşleştirme görevini ona verin! Sorumluluk duygusunu oyunla kazandırmanın sırlarını Bloglarda okuyun.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'Karanlık oda korkusu 🌌', 'Işığı kapattığınızda ağlıyor mu? Hayal gücü geliştikçe korkuları artabilir. Beyaz Seslerden anne rahmi sesini açarak ona eskiden hissettiği güven duygusunu yaşatın.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'Kitaplara ilgi nasıl oluşur? 📖', 'Okumak yerine sayfaları yırtmak mı istiyor? Okuma alışkanlığına zarar vermeden dikkatini masala nasıl çekebileceğinize dair Anacan AI''a pratik yöntemler sorun.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'Demirin sırrı: C vitamini 🍋', 'Demirin vücutta iyi emilmesi için Beslenme Takibi aracındaki bugünkü menüye göz atın. Et yemeğinin yanına mutlaka bol limonlu veya domatesli bir salata ekleyin.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'Annenin kahve saati ☕', 'Ev işlerini bir kenara bırakıp nefes alın! Anne Dostu Mekanlar arasından çocuk oyun köşesi bulunan bir kafe seçin, sıcak kahvenizi yudumlayın ve başka annelerle tanışın.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'Gecenin sesi: Tren 🚂', 'Günün gürültüsünden sonra aniden oluşan sessizlik onu huzursuz mu ediyor? Evdeki diğer sesleri bastırmak için Beyaz Seslerden monoton tren sesini açarak uykuya geçmesine yardımcı olun.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'Ayakkabısı birden dar mı geldi? 👟', 'Koşarken tökezliyor veya ayakkabısını çıkarmak mı istiyor? Ayağı büyümüş olabilir! Güncel ölçülerini Gelişim Takibine girerek fiziksel gelişimini hemen takip edin.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'Şekersiz enerji topları 🍪', 'Market tatlılarına son! Bebek tariflerinde yalnızca 10 dakikada hazırlanan, hurmalı ve yulaflı sağlıklı, lezzetli atıştırmalıkları keşfederek onu sevindirin.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'Ani saldırganlık 🦖', 'Sinirlendiğinde arkadaşlarını itiyor veya size vurmaya mı çalışıyor? Bu yaşta yoğunlaşan öfke duygusunu nazikçe nasıl yönlendirebileceğinizi hemen Anacan AI''a sorun.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'Kendinizi unutmayın ⚡', 'Öğleden sonra enerjiniz mi tükeniyor? Tatlıya yönelmeyin! Kadınlara özel sağlıklı tariflerden anında enerji veren, proteinli ve fıstık ezmeli bir smoothie hazırlayarak enerjinizi yenileyin.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'Zamanlayıcıyla uyku analizi ⏱️', 'Akşam uykuya dalması çok mu uzun sürdü? Uyku zamanlayıcısını başlatın ve grafiği takip edin. Enerjisini yeterince atamadığını mı, yoksa aşırı yorulduğunu mu analiz edin.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Şimdi ev işlerine dokunmayın! Kadınlara özel sağlıklı tariflerden melisa çayı demleyin ve günün yorgunluğunu sıcak buharla üzerinizden atın.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'Protein alımı yeterli mi? 🍗', 'Durmadan koşup zıplayan kaslar için protein şarttır. Beslenme Takibi aracıyla günlük besin dengesini ölçün ve menüsünü zenginleştirin.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'Bitmek bilmeyen Neden? soruları 🤔', 'Bu ne? Neden böyle? dönemi resmen başladı! Çocuğunuzun bitmek bilmeyen keşfetme merakına sabırla ve gelişimini destekleyecek şekilde nasıl yanıt vereceğinizi Bloglardan öğrenin.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'Eski ses kayıtları 🎤', 'Çocuğunuz uyuduktan sonra Bebek Albümünü açın ve aylar önce çıkardığı o tatlı sesleri dinleyin. Ne kadar hızlı büyüdüğünü görüp gururlanın!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', 'Benim! dönemi 🧸', 'Parkta oyuncaklarını kimseyle paylaşmıyor mu? 2.5 yaşına yaklaşan çocuklara sırayla oynama kavramını nasıl kazandırabileceğinizi Anacan AI''a sorarak öğrenin.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'Makarna sevgisi 🍝', 'Çocuğunuz günlerdir aynı yemeği mi istiyor? Yemek seçiciliği zirvede. Sağlıklı tarifler arasından sebzeleri gizleyebileceğiniz eğlenceli soslar arayın.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'Sessizliğin tadı 🤫', 'Odaya sonunda sessizlik çöktü. İşleri boş verin, karanlıkta oturun. Ses ölçeri etkinleştirip bu sessizliğin seviyesini ölçün ve zihninizi dinlendirin.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', '800''ü tamamladık!🚀', 'Şimdi daha fazla soru, daha fazla hareket ve daha fazla bireysellik zamanı. Bu yeni ve heyecan verici döneme derin bir nefes alarak başlayın.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'Mükemmel anne efsaneleri 🛑', 'Bugün ekran süresi fazla oldu diye kendinizi mi suçluyorsunuz? İnternetteki ideal anneleri unutun. Siz kendi gerçekliğinizle mükemmelsiniz.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'Babanın oyun alanı 👨‍👧', 'Sabrınız mı tükeniyor? Odanın kapısını kapatın ve çocuğu babasıyla yalnız bırakın. Bu akşam evdeki oyunları o yönetsin.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', 'Neden? dönemi 🤔', 'Her şey için “Bu neden böyle?” diye mi soruyor? Beyni bir sünger gibi bilgiyi emiyor. Sabrınızı toplayın ve ona kısa, mantıklı cevaplar verin.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'Zor bir gün müydü? 📝', 'Bugünkü stresinizi duygu günlüğüne yazarak içinizi dökün. Bütün anneler bu krizleri yaşıyor, siz yalnız değilsiniz.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'Hayali oyunlar 🧸', 'Arabaları konuşturuyor, oyuncak ayısını besliyor mu? Hayal gücü şahlanıyor. Bu bilişsel sıçramayı gelişim takipçisine kaydedip oyuna katılın.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'Evde sıkıldınız mı?', 'Anne Dostu Mekanlar arasından çocuk oyun köşesi olan bir kafe keşfedin. O oynasın, siz kahvenizi sıcakken için.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'Müzikli huzur 🎶', 'Akşamüstü başlayan huysuzlanmaları çözmenin en kolay yolu, sevdiği bir melodiyi açıp ona sarılarak yavaşça dans etmektir.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'Hava tuhaf diye evde mi kaldınız?', 'Hava durumu ve giyim aracı, pencereden anlayamadığınız sıcaklığı size anında söylesin; parka çıkın.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'Kendim giyineceğim 👕', 'Pantolonunu başına geçirse bile giyinme çabalarına engel olmayın. Bağımsızlık arzusu zirvede! Ona zaman tanıyın, denemesine izin verin.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'Kendim dolduracağım! 🥛', 'Suyu bardağa kendisi doldurmak istiyor ve her yeri ıslatıyor mu? Pratik yaşam becerilerini geliştiren, ancak dökülmeyen akıllı çocuk bardaklarını Önerilen Ürünler''de arayarak işinizi kolaylaştırın.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'Şef mutfakta 👩‍🍳', 'Bebek tariflerinden şekersiz, muzlu kurabiye hamurunu birlikte yoğurun. Hem motor becerileri gelişsin hem de eğlenerek hazırladığı yiyeceği iştahla yesin.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Ev işlerine koşmayın! Sağlıklı tariflerden melisa veya papatya çayı demleyin, kanepeye uzanın ve yalnızca sessizliğin tadını çıkarın.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'Seninki de benim! 🧸', 'Parkta başkasının oyuncağını geri vermek istemiyor mu? Benmerkezcilik döneminde. Paylaşmayı zorla değil, sırayla oynamayı öğreterek kazandırın.'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'Masalın kahramanı 🪄', 'Bu akşam Akıllı Masallar''da kahramanı kendi çocuğunuz olan özel bir hikâye oluşturun: Geceyi seven cesur minik.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', 'Seni Seviyorum sarılması 🫂', 'Birden yanınıza gelip boynunuza sarılıyor veya yüzünüzü okşuyor mu? Artık sevgisini fiziksel olarak gösteriyor. Bu anın tadını çıkarın.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'Eşyaları yerine koyma 🧸', 'Oyuncağı kutuya atıp tekrar çıkarıyor mu? İçerisi ve dışarısı kavramları gelişiyor. Bu bilişsel beceriyi Gelişim Takibi''ne mutlaka kaydedin.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'Sorunuz mu var? 🤖', '2 yaşından sonra çocuğun konuşması nasıl olmalı? İnternette kaybolmayın; doğrudan Anacan AI''a yazın ve bilimsel temellere dayanan bir yanıt alın.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'Uzun cümleler geliyor! 🗣️', 'Artık 4-5 kelimeyi birleştirerek komik bir hikâye anlatıyor mu? Kelime dağarcığında büyük bir sıçrama yaşanıyor! Bu değerli anı kaçırmayın; hemen sesli olarak Bebek Albümü''ne kaydedin ve gelişimini not edin.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'Mantık arayışı 🧩', 'Artık iki-üç parçalı basit yapbozları ezberledi. Zihnini daha fazla zorlayacak ve neden-sonuç ilişkisi kurmasını sağlayacak karmaşık ahşap oyuncakları Önerilen Ürünler bölümünde bulabilirsiniz.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'Banyoda fırtına 🛁', 'Sudan çıkmak istemiyor ve ağlıyor mu? Banyo rutinini stressiz tamamlamak için dikkat dağıtıcı oyuncakları ve pratik geçiş yöntemlerini hemen Anacan AI''a sorun.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'Kaydırakta sıra kavgası 🛑', 'Parkta diğer çocukları beklemek istemiyor mu? 2.5 yaşına yaklaşırken sıra bekleme ve paylaşma kavramlarını nasıl kazandırabileceğinizi Bloglar bölümündeki sosyalleşme yazılarından mutlaka okuyun.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'Sayfalar canlanıyor 📖', 'Masal okurken hikâyenin sonunu o mu uyduruyor? Bu harika hayal gücü anını destekleyen etkileşimli okuma tekniklerini Anacan AI aracılığıyla keşfedin.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'Sıvı tüketimi ve kabızlık 💩', 'Çok koşuyor, az su mu içiyor? Bezini değiştirirken (veya lazımlıktayken) dışkısını takip edin. Kabızlık riski varsa uygulamaya kaydedin ve Beslenme Takibi aracıyla menüsüne hemen kuru erik veya yulaf ekleyin.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'Yemeğiyle oynuyor 🥦', 'Makarnayı yemek yerine ezip etrafa mı saçıyor? Bu yaşta yiyecekler aynı zamanda birer oyuncaktır. Ne kadar yediğini Beslenme Planı''na kaydederek haftalık dengeyi takip edin.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'Sabah filozofu 🧦', 'Bu sabah çorabını eline giymek mi istedi? İnatçılığın eşlik ettiği bu keşif anlarına öfkelenmeyin. Biraz böyle dolaşmasına izin verin; bu, onun bağımsızlık denemesidir.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'Suyun sihirli gücü 🛀', 'Bütün gün koşturmaktan hem o hem de siz yoruldunuz. Ilık bir banyo yalnızca temizlik değildir; onun sinir sistemini sakinleştiren en iyi terapilerden biridir.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'Parktaki bencillik 🧸', 'Kumda oynarken kovasını kimseye vermiyor mu? 27 aya yaklaşırken paylaşma kavramı hâlâ çok zayıftır. Onu bencillikle suçlamayın, yalnızca sırayla oynama kuralını anlatın.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'Babanın ses tonu 📖', 'Bu akşam odada farklı bir atmosfer yaratalım. Kitap okuma veya masal anlatma görevini babanın tok, güven veren sesine bırakın; siz de bir köşede dinlenin.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'Mükemmel hafıza 🧠', 'Dün sakladığınız oyuncağın yerini bu sabah tam olarak buldu mu? Uzun süreli hafızası inanılmaz ölçüde gelişmiş.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'Ayna karşısında şov 🤪', 'Yüzünü şekilden şekle sokup kendine bakarak kahkahalar mı atıyor? Bu komik kendini keşfetme anını hemen video olarak Bebek Albümüne ekleyin ve günün stresini üzerinizden atın.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'Sizin de molaya ihtiyacınız var ☕', 'Evden çıkıp biraz nefes alın! Anne Dostu Mekanlardan yakınınızdaki çocuk köşesi bulunan bir kafeyi keşfedin, sıcak kahvenizi yudumlayın ve diğer annelerle tanışın.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'Kendinizle gurur duyun 🌟', 'Her gün öğrendiği yeni beceri ve attığı her öz güvenli adım, sizin özverinizin bir sonucudur. Ruh Hali Günlüğünü açın ve bugün kendinizi ayakta alkışlamanızı sağlayacak bir not yazın!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'Yemeği savurup atıyor mu? 🥣', 'Masada oturmaktan sıkılıp kaşığı mı atıyor? Beslenme zamanlayıcısını başlatın, süreci grafik üzerinden analiz edin ve zorla yedirmekten tamamen kaçının.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'Tek renkli beslenme mi? 🟡', 'Yalnızca sarı renkli yiyecekler (patates, makarna, muz) mi istiyor? Beslenme takip aracıyla menüsünü analiz edin, Bebek tariflerinde rengarenk ve gizli sebzeler içeren alternatifler keşfedin.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'Ben ve Sen farkı 🗣️', 'Artık kendisinden 3. şahıs olarak değil, Ben diyerek mi bahsediyor? Bu büyük bilişsel sıçramayı desteklemek için Anacan AI''a doğru iletişim kurmanın püf noktalarını hemen sorun.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'Bir masal daha! 📚', 'Yatağa gitmemek için durmadan yeni bahaneler mi uyduruyor? Uyku zamanlayıcısını başlatın, sınırları koruyun ve Beyaz Seslerden okyanus dalgalarını açarak odayı sakinlik moduna geçirin.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'Zıplama sanatı 🦘', 'Merdivenden veya koltuktan atlamaya mı çalışıyor? Motor gelişimi için güvenli bir alana ihtiyacı var. Anne Dostu Mekanlardan trambolinli bir kapalı eğlence merkezi bulun ve enerjisini doğru yere yönlendirin.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'Sizin de bir piliniz var 🔋', 'Bütün gün Hayır demekten ve peşinden koşmaktan yoruldunuz mu? İçinizde biriken sıkıntıları Ruh Hali Günlüğüne dökün. Unutmayın, kendinize zaman ayırmak lüks değil, ihtiyaçtır.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'Ayakkabılar ters! 👟', 'Sağ ayakkabıyı sol ayağına, sol ayakkabıyı sağ ayağına giyip çıkarmak istemiyor mu? Bu komik bağımsızlık girişimini Bebek fotoğraf çekimindeki eğlenceli çıkartmalarla süsleyin ve albümün en komik karesine dönüştürün.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'Muz mu, telefon mu? 🍌', 'Muzu veya kumandayı kulağına tutup hayali konuşmalar mı yapıyor? Hayal gücü oyunlarının zirvesi! Bu değerli anı sesli video olarak hemen Bebek Albümüne ekleyin ve hafızalara kazıyın.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'Karanlık oda korkusu 🌌', 'Işığı kapattığınızda odadaki eşyaları canavarlara mı benzetiyor? Hayal gücü geliştikçe korkular da ortaya çıkar. Beyaz Seslerden anne rahmi sesini açarak ona eskiden aşina olduğu o kusursuz güven hissini yaşatın.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'Demir ve enerjinin sırrı 🥩', 'Hareketli miniğinizin kansızlık yaşamaması için Beslenme takip aracından bugünkü demir alımını (et, mercimek, ıspanak) kontrol edin ve menüsünü C vitaminiyle zenginleştirin.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'Sıvı tüketimi ve kabızlık 💧', 'Çok koşuyor ama az su mu içiyor? Bezini değiştirirken dışkısını takip edin. Kabızlık riski varsa uygulamaya kaydedin ve Beslenme takip aracıyla hemen lifli gıdalar (armut, yulaf) ekleyin.'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'Renk ve şekil ustası 🔴🟩', 'Nesneleri, düğmeleri veya oyuncakları renklerine göre mi gruplandırıyor? Zihnini daha fazla zorlayacak ve mantıksal gelişimini destekleyecek ahşap yapbozları hemen Önerilen Ürünler bölümünde keşfedin.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'Gece terörü mü, kabus mu? 🤖', 'Gece yarısı ağlayarak uyanıyor ve sakinleşmiyor mu? İkisi arasındaki farkı anlamak ve doğru psikolojik yaklaşımı uygulamak için Bloglar bölümündeki bilimsel makalelerimize göz atın.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'Kitap Kurdu 📖', 'En sevdiği masal kitabını getirip aynı sayfayı defalarca okutuyor mu? Tekrar etmek onun öğrenme yöntemidir. Sabırla yeniden okuyun.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'Ev işleri bekleyebilir 🛑', 'Yerler silinmedi mi? Bırakın öyle kalsın. Kirli ev temizlenir, ancak tükenmiş bir annenin toparlanması uzun sürer. Kanepeye uzanın ve huzurun tadını çıkarın.'),
  ('04312503-34be-494a-8896-38312d406a86', 'Hayali çay takımı 🫖', 'Sizi veya oyuncaklarını hayali bardaklardan çay içmeye mi zorluyor? Rol oyunları, zeka gelişiminin zirve noktasıdır!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'Annenin boyun ağrıları 🧘‍♀️', 'Yerde oynamaktan ve çocuğunuzu kaldırmaktan boynunuz, beliniz mi tutuldu? Sağlıklı Tarifler''den kasları rahatlatan, iltihap karşıtı zencefilli yeşil çay demleyerek dinlenin.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'Yatağın altındaki canavar mı? 👾', 'Hayal gücü geliştikçe korkular da gerçekmiş gibi hissedilir. Gölgelerden korkuyorsa ışıkları kısın ve Beyaz Sesler''den anne rahmi sesini (kalp atışı) açarak ona o eski, kusursuz güven hissini yaşatın.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'Kaydırakta sıra kavgası 🛑', 'Parkta diğer çocukları beklemek istemiyor mu? 2.5 yaş civarında sıra bekleme ve sabır kavramlarını nasıl kazandırabileceğinizi Bloglar bölümündeki sosyalleşme yazılarından mutlaka okuyun.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'Vicdan azabı çekmeyin 💖', 'Bugünkü inatlaşmalar sabrınızı taşırdı ve sesinizi mi yükselttiniz? İçinizdeki sıkıntıları Ruh Hali Günlüğü''ne dökün. Siz robot değilsiniz, mükemmel olmak zorunda da değilsiniz!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'Ters giyinme modası! 👕', 'Pantolonunu ters, ayakkabılarını yanlış ayağına giydi ve çıkarmak istemiyor mu? Bu komik bağımsızlık girişimine müdahale etmeyin!'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'Gündüz uykusuna isyan! ⏱️', 'Öğle uykusunu reddetti ve şimdi aşırı mı yorgun? Uyku zamanlayıcısındaki programa bakın, akşam rutinini en az 40 dakika erkene alarak gece terörlerini önleyin.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'Kakasını tutuyor mu? 💩', 'Tuvalet eğitimi döneminde ayakta durup kakasını mı tutuyor? Bu durum psikolojik kabızlığa yol açabilir. Bunu Bez Takipçisi''ne kaydedip menüsüne hemen kayısı veya yulaf ekleyin.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'Dört duvar onu bunaltıyor 🌳', 'Evde enerjisini atamıyor ve her şeyi etrafa mı fırlatıyor? Anne Dostu Mekanlar haritasını açın, yumuşak zeminli ve kaydıraklı güvenli bir park bulup açık havada özgürce oynamasına izin verin.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'Boy ve kilo sıçraması! 📏', 'Giydirirken gömleklerinin daraldığını veya ayakkabılarının sıktığını fark ettiniz mi? Kilo Takipçisi''ne güncel boyunu ve ölçülerini girip gelişim eğrisinin nasıl yükseldiğine gururla bakın.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'Demir deposunu kontrol edin 🥩', 'Benzinin soluk olduğunu veya çabuk yorulduğunu mu fark ettiniz? Beslenme Takibi aracında bugünkü demir alımını kontrol edin ve emilimi artırmak için etin yanında mutlaka C vitamini (limon, domates) verin.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'Sizin de arkadaşa ihtiyacınız var 👯‍♀️', 'Bütün gün yalnızca çocuk diliyle konuşmaktan yoruldunuz mu? Anne Dostu Mekanlar''dan annelerin sıkça buluştuğu çocuk kafelerini bulup kendinize de sosyalleşebileceğiniz bir ortam yaratın.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'Acil ihtiyaçlar 🛒', 'Şampuan, bebek bezi veya yulaf mı bitti? Aklınızda tutmaya çalışmayın, Alışveriş Listesi''ne yazın ve eşinizle senkronize edin.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'İstediği olmayınca kendini yere atıp bağırıyor mu?', 'Küçük çocuklarda öfke nöbetleri devam edebilir. Yakınında sakince bekleyin, sakinleştiğinde ona sarılın.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'Uykuya direnme 🥱', 'Öğle uykusuna yatmak istemiyor ve direniyor mu? Bazı çocuklar bu yaşlarda gündüz uykusunu bırakır. Tartışmak yerine, Sakinlik Saati ilan edip yatağında kitapları karıştırmasına izin verin.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'Odanın akustiği 🤫', 'Uykuya dalar dalmaz en ufak bir tıkırtıda irkiliyor mu? Ses ölçerle odanın akustiğini kontrol edin ve pencereden gelen sesleri bastırmak için beyaz gürültü açın.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'Küçük yardımcı 🧹', 'Siz çamaşırları katlarken veya yerleri silerken yaptığınız işi elinizden almaya mı çalışıyor? Kendini büyümüş hissediyor. Ona küçük bir bez verip size yardım etmesine izin verin.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'Yastık kalesi 🏰', 'Bu akşam odayı oyun alanına çevirin. Koltuk minderlerinden küçük bir kale yapıp içine girin. Biraz dağınıklık olacak ama bu kahkahalara kesinlikle değer.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'Dikkat testi 🧩', 'Tek bir oyuncakla oynama süresi artık 10-15 dakikaya ulaştı mı? Dikkat süresi uzuyor.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'Babayla uyku rutini 👨‍🍼', 'Bu gece çocuğu uykuya hazırlama, dişlerini fırçalatma ve pijamalarını giydirme işini babaya bırakıp sessizce çayınızı için.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'Menü derdi 🍲', 'Bugün ne pişireceğiniz hakkında hiçbir fikriniz yok mu? İnternette kaybolmayın; Uygulamanın Bloglar bölümündeki çocuk beslenmesi yazılarından yeni ve kolay tarifler bulun.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'Neden-sonuç arayışı 🤔', 'Bunu atarsam ne olur?, Bu düğme ne işe yarar? Sürekli fiziksel denemeler yapıyor. Evin güvenliğini bir kez daha gözden geçirin.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'İnatçı öfke nöbetleri 🛑', 'Mağazada veya parkta yaşanan öfke nöbetleri sizi utandırıyor mu? Unutmayın, önemli olan çevredekilerin ne düşündüğü değil, çocuğunuzun o anki duygusudur. Göz teması kurup onu sakinleştirin.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'Zıplama denemeleri 🤸‍♂️', 'Kanepeden yere veya durduğu yerde havaya zıplamaya mı çalışıyor? Kaba motor becerileri gelişiyor! Onu cesaretlendirin.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'Düzeni ayrıntılı inceleyelim ⏱️', 'Akşam uykuya dalması 40 dakika mı sürdü? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu iyice kısaltmanın ve akşam yatış saatini erkene çekmenin zamanı gelmiştir.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'Doğayı keşfetme ⛅', 'Dört duvar arasında bunaldınız. Hava durumu ve giyim aracını açın, onu hava koşullarına uygun giydirip hemen parka çıkarın. Yaprakları ve taşları keşfetsin.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'Sessizliğin tadını çıkarın 🤫', 'Sonunda uykuya daldı. Şimdi evdeki en küçük ses bile sizi geriyor. Kulaklığınızı takın ve hiçbir şey dinlemeden sadece sessizliğin kıymetini bilin.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'Renkleri keşfetme 🎨', 'Kırmızı topu istediğinizde gerçekten kırmızı olanı mı gösteriyor? Artık renkleri ayırt etmeye başladı. Bu yeni algı aşamasını gelişim takipçisine kaydedin.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', 'Tokum bahanesi 🥣', 'İki kaşık yiyip doyduğunu söylüyor ve kaçıyor mu? Onu zorlamayın. Küçük porsiyonları daha sık aralıklarla vermeyi deneyin.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'Vücut bölümlerini tanıma 👀', 'Omuzların nerede? diye sorduğunuzda parmağıyla dokunup gösteriyor mu? Zihinsel algısı zirvede! Oyunu daha karmaşık vücut bölümleriyle sürdürün.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'Koşu maratonu 🏃‍♂️', 'Yürümek artık ona sıkıcı geliyor, sadece koşuyor! Odanın ortasındaki küçük engelleri kaldırın ve bu bitmek bilmeyen enerjiyi gülümseyerek izleyin.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'Karanlık oyunları 🐰', 'Uyumak istemiyor ve karanlıktan korkuyor mu? Odayı tamamen karartın ve ellerinizle duvarda bir gölge tiyatrosu oluşturun. Korkuyu eğlenceye dönüştürün.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'Annenin çevrimdışı saati ☕', 'Çocuğunuz kendi dünyasına dalıp oyuncak bebekleriyle konuşurken hemen bulaşık makinesine koşmayın. Kendinize bir kahve koyun, telefonunuzu da bir kenara bırakın ve 15 dakika boyunca tamamen çevrimdışı olun.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'İlk uzun cümleler 🗣️', 'Anne, araba oraya gitti! Artık kelimeleri peş peşe sıralayıp anlamlı cümleler kuruyor. Bu tarihi anları dinleyin ve mutlaka bir anı olarak Gelişim takipçisine yazın.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'Blog molası 📱', 'Tuvalet eğitimine başlamak için doğru zaman mı? Kararsızsanız Anacan uygulamasının blog bölümüne girin ve uzmanların yazdığı, çocuk doktorları tarafından onaylanmış makaleleri okuyun.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'Günün değerlendirmesi 📝', 'Zor bir gün müydü? Bugün yaşadığınız tüm stresi duygu günlüğüne yazarak içinizi dökün. Tüm anneler bu zorlu krizleri yaşıyor, yalnız değilsiniz.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'Suyu reddetme 💧', 'Su yerine sürekli tatlı meyve suları mı istiyor? Günlük su ihtiyacını hesaplayın ve suyu renkli, ilgi çekici bardaklarda sunun.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'Hayalî hikâyeler 🎭', 'Elindeki oyuncak ayıyı konuşturup ona hayalî hikâyeler mi anlatıyor? Hayal gücü dorukta! Onu uzaktan izleyin ve hiç müdahale etmeyin.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'Masalsız uyumuyoruz 🪄', 'Klasik masallar artık ilgisini çekmiyor mu? Akıllı masallarda, kahramanı kendisi olan özel bir masal oluşturun.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'Dağınıklık güzeldir 🌪️', 'Her gün aynı oyuncakları kutuya toplamaktan yoruldunuz mu? Bugün toplamayın! Evin dağınık olması dünyanın sonu değil, psikolojik rahatlığınız daha önemli.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', 'Tek başınıza 10 dakika 🛀', 'Odaya sessizlik çöktü. Eşinizden evdeki her şeyle ilgilenmesini rica edin. Siz de sıcak bir duş alarak 10 dakika boyunca yalnızca kendinizle baş başa kalın.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'Kalsiyum sadece sütte bulunmaz 🧀', 'Süt içmeyi reddediyor mu? Kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tükettiği peynir, yoğurt veya brokoli miktarını hesaplayıp eksiklerini tamamlayın.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'Dayanışma kulübü 💬', 'Çok yoruldunuz ve kimsenin sizi anlamadığını mı düşünüyorsunuz? Hemen Anacan Topluluğuna yazın. Orada aynı uykusuzluğu yaşayan binlerce anne size destek olacak.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'Mantıksız inatlaşmalar 🛑', 'Bu sabah suyu mavi değil, kırmızı bardakta verdiğiniz için kıyamet mi koptu? Bu şımarıklık değil; sadece dünyayı kontrol edip edemediğini keşfediyor. Sabırlı olun.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'Vitamin deposu 🥗', 'Onu doyurmak için her şeyi yapıyorsunuz. Peki ya kendiniz? Sağlıklı tarifler arasından 10 dakikada hazırlanan, demir ve kalsiyum açısından zengin bir öğle yemeği seçerek enerjinizi yenileyin.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'Ayna karşısında 👀', 'Aynanın karşısında durup farklı yüz ifadeleri yapıyor, kendi kendine gülüyor mu? Benlik farkındalığı harika. Onu gizlice izleyin ve bu komik anların tadını çıkarın.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'Pijama savaşı 👕', 'Akşamları giyinmek büyük bir savaşa mı dönüşüyor? Seçimi ona bırakın: Beyaz pijamayı mı istersin, yoksa maviyi mi? Bu yöntem çoğu zaman işe yarar.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'Başkasının oyuncağı 🧸', 'Evinize gelen misafir çocuğa kendi oyuncağını vermiyor mu? Bu bencillik değil, kişisel sınırlarını koruma çabasıdır. Paylaşmayı zorlayarak değil, örnek olarak öğretin.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'Kelimelerin telaffuzu 🗣️', 'Bazı kelimeleri eksik veya çok komik mi telaffuz ediyor? Gülmeyin; beyninin doğru telaffuzu kodlaması için kelimeyi doğru vurguyla ona tekrar edin.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'Gece terörü şüphesi 😭', 'Gecenin bir yarısı gözleri kapalıyken ağlıyor ve sakinleşmiyor mu? Sesini hemen Ağlama Analizi''ne dinletin. Bazen bunun nedeni yalnızca gaz değil, gece terörü olabilir.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'Sabah huysuzluğu ☁️', 'Gözünü açar açmaz her şeye ağlıyor ve hiçbir şeyden memnun olmuyor mu? Belki de tam bir büyüme atağının ortasındadır. Ona bol bol sarılın ve güven verin.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'Kirlenmesine izin verin 🏖️', 'Parkta çamurla veya kumla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen bu etkinlik için en iyi Anne Dostu Mekanları uygulamada bulabilirsiniz.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'Takım ruhu 🥂', 'Zor bir günü geride bıraktınız. Çocuk uyuduktan sonra partnerinizle birer çay içip “Biz gerçekten bu işin üstesinden geliyoruz” diyerek birbirinizi takdir edin.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'Kendinizi nasıl hissediyorsunuz? 🩸', 'Enerjiniz aniden mi düştü, yoksa ruh haliniz değişken mi? Uygulamadaki Regl Takibi''ne göz atın. Döngünüzü takip ederek bedeninizin ihtiyaçlarına karşı daha anlayışlı olun.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'Hayali masallar 📖', 'Kitap okumaktan sıkıldınız mı? Işıkları kapatın, Beyaz Sesler arasından yağmur sesini açın ve karanlıkta birlikte hayali masallar uydurarak uykuya dalın.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'Meyveli keşifler 🍏', 'Proteinli gıdaları veya sebzeleri reddediyor mu? Beslenme Takibi aracıyla bugünkü ihtiyacını hesaplayın ve Bebek tariflerinde meyveli yoğurt gibi lezzetli kombinasyonlar hazırlayın.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'Parmak hesabı 🔢', 'Merdivenleri çıkarken veya oyuncak arabaları dizerken bir, iki, üç demeye mi çalışıyor? Matematiksel düşünmenin temelleri atılıyor. Onunla birlikte her şeyi sesli olarak sayın.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'Derin bir nefes 🧘‍♀️', 'Bütün gün sorulara cevap vermekten boğazınız kurudu. Odada sessizlik oluşur oluşmaz hiçbir ekrana bakmadan yalnızca derin nefes alıp vererek dinlenin.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Hemen ev işlerine koşmayın! Sağlıklı tariflerden melisa veya papatya çayı demleyin, koltuğa uzanın ve yalnızca sessizliğin tadını çıkarın.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'Paylaşmak zordur 🧸', 'Kardeşine veya parktaki bir çocuğa karşı sert mi davranıyor? Paylaşmak onun için henüz soyut bir kavramdır. Onu cezalandırmayın, duygularını anladığınızı gösterin.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'Hayali çay partisi 🍵', 'Sizi de hayali oyunlarına katıyor ve boş bir fincandan çay içmenizi mi istiyor? Hayal gücünün bir parçası olun. Bu oyunlar onun sosyal zekasını geliştirir.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'Babanın hikayesi 📖', 'Bu akşam sesinizi dinlendirin. Çocuğun en sevdiği kitapları farklı ses tonlarıyla ve komik bir şekilde okuma görevini babaya bırakın.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'Düştüğünde ağlamamak 🧗‍♂️', 'Hafifçe düştüğünde hemen ağlamayıp sizin tepkinize bakarak sonra mı karar veriyor? Telaşlanmayın; gülümseyerek “Bir şey yok, sen güçlüsün.” deyin.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'Karanlıktan korkuyor mu?  🌙', 'Yatağının kenarına küçük, sıcak renkli bir gece lambası koyun. Odanın geri kalanını ise melatonin salgılanması için tamamen karanlık tutun.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'Sebze düşmanlığı 🥦', 'Çorbadaki bütün sebzeleri kenara mı ayırıyor? Beslenme planında ona farklı alternatifler arayın. Sebzeleri köftenin içine gizlemek en eski anne hilelerinden biridir.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'Mükemmel anne yoktur 💬', 'Her şeyi aynı anda yapamadığınız için kendinizi kötü mü hissediyorsunuz? Hemen Anacan Topluluğuna katılın. Oradaki annelerin samimi itirafları size güç verecek.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'Karalama hevesi 🖍️', 'Kalemi tutuş şekli değişiyor ve kâğıda bilinçli çizgiler çiziyor. İnce motor becerilerindeki bu harika ilerlemeyi Gelişim Takipçisinde mutlaka işaretleyin.'),
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf', 'Kahve molası ☕', 'Günün koşturmacası sizi tüketti. Onu 15 dakikalığına güvenli bir etkinlikle (örneğin boyama) baş başa bırakın ve siz de mutlaka kahvenizle enerji toplayın.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'İsabetli atışlar ⚾', 'Ona attığınız büyük topu artık kollarıyla tutmaya, hatta geri atmaya mı çalışıyor? El-göz koordinasyonu hızla gelişiyor. Koridorda birlikte top oynayın.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'Müzikli geçiş 🛀', 'Akşam rutini zorlaşmaya mı başladı? Ilık bir banyo sırasında arka planda sakinleştirici klasik müzik açın. Su ve müziğin uyumu en inatçı çocuğu bile rahatlatır.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'Gündüz uykusunu reddetme 🥱', 'Yine uykuya dalmadı mı? Mücadele ederek hem onu hem de kendinizi yormayın. Odada sessizce kitap sayfalarını çevirmek de beyin için bir dinlenme biçimidir.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'Duyguları ifade etmek 📝', 'Bugün çok mu yoruldunuz, yoksa o çok tatlı bir söz mü söyledi? Her iki durumda da Ruh Hali Günlüğünü açın ve bu anı geleceğe bir hatıra olarak kaydedin.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'Diş fırçalama savaşı 🦷', 'Fırçayı ağzına yaklaştırmanıza izin vermiyor mu? Bunu zorunluluk olmaktan çıkarıp oyuna dönüştürün. Sizin dişlerinizi fırçalamasına izin verin, sonra sıra sizde olsun.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'Serbest oyun 🧸', 'Onu her dakika eğlendirmek zorunda değilsiniz. Çocuklar için sıkılmak, yaratıcılığın başlangıcıdır. Bırakın odada kendi başına bir şeyler keşfetsin.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'Sadece sarılın 🫂', 'Hiçbir araca, kitaba veya masala ihtiyacınız yok. Bu akşam onu sadece göğsünüze bastırın, kokusunu içinize çekin ve karanlıkta ona sevginizi fısıldayın.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', 'Kararlı Hayırlar 🛑', 'Biri onu öpmek istediğinde uzaklaşıp hayır mı diyor? Onun bedensel sınırlarına saygı gösterin ve başkalarının da buna uymasını sağlayın. Öz güven burada başlar.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'Bloglara göz atın 📱', '2 yaş öfke nöbetleriyle başa çıkamıyor musunuz? Anacan uygulamasındaki psikoloji bloglarını okuyun. O kriz anında çocuğun beyninde neler yaşandığını anlamak işinizi kolaylaştıracak.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'Akıllı masal zamanı 🪄', 'Akıllı masallarda bu akşam ona özel bir macera oluşturun: Korkusuz ve cesur tavşanın hikâyesi. Masallar aracılığıyla korkularını aşmasına yardımcı olun.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'Kriz anı 🛒', 'Markette istediği oyuncağı almadığınız için bağırıyor. Çevredeki mükemmel ebeveynlerin bakışlarını önemsemeyin. Sakince göz teması kurup açıklayın.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'Ev işleri beklesin 🛑', 'Yerler silinmedi, çamaşırlar katlanmadı mı? Bırakın beklesin. Kirli ev temizlenir ama psikolojik olarak tükenmiş bir annenin toparlanması çok uzun sürer. Kanepeye uzanın.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'Uykusuzluğu kabullenin 😭', 'Gecenin bir yarısı uyandı ve uyumak istemiyor. Ona kızmayın. Sesini Ağlama analizine dinleterek nedenini (ağrı, gaz, korku) belirleyin ve sabırla ona sarılın.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'Yeni arkadaş arayışı 👫', 'Parkta yaşıtlarıyla koşmaya, onlara yaklaşmaya mı çalışıyor? Sosyalleşme resmen başladı! Güvenliğini uzaktan gözeterek bu anı gururla izleyin.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'Bloglardan öğrenin 📱', 'Çocuğunuzun her şeye hayır demesi sizi bezdirdi mi? Bu, 2 yaş sendromunun klasik bir belirtisidir. Uygulamadaki psikoloji bloglarını okuyarak onun zihninde neler olup bittiğini anlayın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('19cce24b-ae51-482e-8dc7-6812a220483b'::uuid, 'Kendinizi suçlamayın 📝', 'Bugün sabrınız tükendi ve sesinizi mi yükselttiniz? Çocuğunuz uyuduğunda Duygu günlüğüne hislerinizi yazın ve kendinizi affedin. Siz sadece yoruldunuz, siz de insansınız.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'Merdivenleri kendi başına çıkmak 🧗‍♂️', 'Elinizden tutarak merdivenleri çıkmaya, hatta kendi başına tırmanmaya mı hevesleniyor? Bedeninin sınırlarını keşfediyor. Güvenliğini gözeterek ona mutlaka bu özgürlüğü tanıyın.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'Ayrılık korkusu 🥺', 'Tuvalete gittiğinizde bile kapının arkasında sizi bekleyip ağlıyor. Ayrılık kaygısı zaman zaman şiddetlenebilir. Her seferinde ona seslenerek burada olduğunuzu ve geri döneceğinizi söyleyin.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'Odanın karanlığı 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm gereksiz ışıkları, özellikle de tablet ekranlarını kapatın. Melatonin yalnızca karanlık ortamda salgılanır.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'Yemek konusunda inatlaşma 🥣', 'İki kaşık yiyip doyduğunu mu söylüyor? Onu zorlamayın. Besinlerle sağlıklı bir ilişki kurması, zorla yedirmenizden daha önemlidir. Öğün sayısını artırın, miktarı azaltın.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'Alkışlama sevinci 👏', 'Bir şeyi başardığında (örneğin kule yaptığında) kendi kendine alkışlayıp gururlanıyor mu? Takdir edilmek istiyor! Siz de onun bu küçük başarısını büyük bir sevinçle alkışlayın.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'Sakinlik saati ☕', 'Gündüz uykusu uyumuyorsa en az 1 saatlik Sakinlik saati (quiet time) belirleyin. O kendi yatağında kitapları karıştırsın, siz de çayınızı içip telefonunuza bakın.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'Çift molası 🥂', 'Çocuğunuz uyudu. Şimdi telefonları ve ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuğunuz dışında herhangi bir konu hakkında sohbet edin. Siz aynı zamanda bir çiftsiniz.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'Masalın sonu 🪄', 'Klasik masallar yorucudur. Akıllı masallarda bu kez hikâyenin sonunu çocuğunuza seçtirin. Sizce ayıcığa kim yardım etti? diye sorarak hayal gücünü harekete geçirin.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'Sınırları test etmek ⚠️', 'Bunu yapma dediğiniz hâlde gözlerinizin içine bakarak o hareketi mi yapıyor? Amacı sizi öfkelendirmek değil, sınırlarınızın ne kadar tutarlı olduğunu test etmektir. Kararlı olun.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'Resimlere tepki 📖', 'Kitaptaki hayvanları veya çocukları gördüğünde onlara dokunup ses çıkarıyor mu? Görsel algısı hayranlık uyandırıcı. Gelişim takipçisinde bu ayrıntıyı işaretleyin.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'Sabah dansı 🎶', 'Gözünü açar açmaz enerji dolu mu? Sabahın karmaşasını yatıştırmak için neşeli bir çocuk şarkısı açın ve odada birkaç dakika dans ederek güne gülümsemeyle başlayın.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'İhtiyaç listesi 🛒', 'Bebek bezi, şampuan veya meyve püresi mi bitti? Zihninizi yormayın; her şeyi hemen Alışveriş listesine yazın ve eşinizle tek tıkla senkronize edin.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'Derin sessizlik 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamın desibel seviyesini kontrol edin, televizyonun sesini kısın ve eve hâkim olan bu derin sessizliğin tadını çıkarın.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'Demirin sırrı: C vitamini 🍋', 'Solgun mu görünüyor veya iştahsız mı? Beslenme takip aracında bugünkü demir alımını kontrol edin ve emilimi artırmak için etin yanında mutlaka bol limonlu salata verin.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'Gece uyanmaları 🌌', 'Gece yarısı ağlayarak uyanıyor ve sakinleşmiyor mu? Gece terörü ile kâbus arasındaki farkı anlamak ve doğru psikolojik yaklaşımı uygulamak için Bloglar bölümüne göz atın.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'Daire çizme sanatı! 🎨', 'Kalemle kâğıda (veya duvara!) kapalı daireler çizmeye mi çalışıyor? Bu, motor becerilerinde muhteşem bir gelişim sıçramasıdır.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'Yeşillik detoksu 🌿', 'Kendinizi şişkin mi hissediyorsunuz? Regl Takibinde döngünüzü kontrol edin ve Kadınlara özel sağlıklı tariflerden yeşil smoothie hazırlayarak vücudunuzu arındırıp enerjinizi yenileyin.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'Sıvı tüketimi ve kabızlık 💩', 'Çok koşuyor ama az mı su içiyor? Bezini değiştirirken (veya lazımlıkta) dışkısını takip edin. Kabızlık riski varsa menüsüne yulaf ekleyin.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'Canavar avı! 👾', 'Yatağın altında canavar mı arıyor? Hayal gücüne bağlı korkular artabilir. Beyaz Seslerden vantilatör sesini açarak odada güvenli ve tekdüze bir ortam oluşturup onu sakinleştirin.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'Yataktan kaçış planı 🛌', 'Beşiğinden tırmanarak çıkmaya mı çalışıyor? Çocuk yatağına geçme zamanı yaklaşıyor. Odanın güvenliğini yer seviyesinden yeniden kontrol edin.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'Anne için mola ☕', 'Çocuğunuz kendi kendine oynarken hemen ev işlerine koşmayın. Odanın dağınıklığı hiçbir yere kaçmaz ama sizin enerjiniz tükenebilir. Oturun ve sıcak kahvenizi için.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', 'Neden? döneminin zirvesi 🤔', 'O neden orada?, Neden uyuyorum?... Beyni bir sünger gibidir! Bitmek bilmeyen sorularına kısa ama mantıklı cevaplar verin. O, dünyayı sizin dilinizle keşfediyor.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'Parkta sosyalleşme 🌳', 'Diğer çocuklarla oynamak yerine onların yanında kendi oyununu mu oynuyor? Paralel oyun bu yaş için tamamen doğaldır. Hava durumunu ve kıyafetlerini göz önünde bulundurarak onu sık sık yaşıtlarıyla aynı ortama götürün.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'Hayalî arkadaşlar 🧸', 'Oyuncak ayısına masal mı anlatıyor ya da boş bir bardaktan çay mı içiyor? Sembolik oyunlar gelişimin başyapıtıdır. Bu bilişsel sıçramayı Gelişim takibine gururla kaydedin.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'Sessizlik ihtiyacı 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamın desibel seviyesini kontrol edin ve yan odadaki televizyonun sesini buna göre ayarlayın.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'Her şeye sahip olmak mı istiyor? 🛑', 'Paylaşma kavramı henüz oluşmadı. Onu zorlamayın; bunun yerine Sırayla oynayalım kuralını yavaş yavaş uygulayın.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'Evdeki kaos 🌪️', 'Her gün temizlediğiniz oda 5 dakika içinde yine mi dağılıyor? Boş verin! Ev bir müze değil, yaşamın kaynadığı bir yerdir. Dağınıklığa değil, çocuğunuzun sevincine odaklanın.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'Korkuların uyanışı 👻', 'Daha önce hiç korkmadığı gürültülü elektrikli süpürgeden şimdi korkup arkanıza mı saklanıyor? Hayal gücü geliştikçe yersiz korkular ortaya çıkabilir. Onu okşayıp güven verin.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'Uykulu gözler 🥱', 'Uykusu gelse de yatağa gitmek istemiyor. Bu akşam rutinini biraz değiştirin. Kitap okumak yerine yatağa uzanıp ona bugün yaşanan güzel şeyleri hatırlatın.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'Enerji patlaması ⛅', 'Çocuğunuz evde duvarlara mı tırmanıyor? Enerjisini atması şart. Onu hava koşullarına uygun giydirin, parka çıkarın ve yorulana kadar koşmasına izin verin.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'Sesinizi taklit ediyor 🗣️', 'Oyuncaklarına tamamen sizin ses tonunuzla ve sizin cümlelerinizle mi öğüt veriyor? O, sizin en iyi aynanızdır. Kendinizi dışarıdan izlemek eğlenceli olacak.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'Boy ve kilo sıçraması! 📏', 'Giydirirken tişörtlerinin daraldığını veya ayakkabılarının sıktığını fark ettiniz mi? Gelişim Takipçisi''ne güncel boyunu ve ölçülerini girip gelişim eğrisinin nasıl yükseldiğine gururla bakın.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'Anne yorulduğunda 🛑', 'Siz robot değilsiniz. Bugün yemek pişirecek gücünüz yoksa dışarıdan sipariş verin. Mükemmel anne olmak, her şeyi tek başınıza yapmak demek değildir.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'Zafer tostu 🥂', 'Zorlu ve inatlaşmalarla dolu bir günü sağ salim tamamladınız. Eşinizle karşılıklı oturup çay bardaklarınızı tokuşturun. Bu büyük sorumluluğun üstesinden geliyorsunuz.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'Az su içtiğini mi düşünüyorsunuz?💧', 'Ona renkli ve farklı şekillerde bardaklar alarak su içmeyi eğlenceli bir alışkanlığa dönüştürün.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'Fısıltılı sohbetler 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlamanın en iyi yöntemlerinden biridir.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'Seçim özgürlüğü 👗', 'Kıyafetini kendisi seçmek istiyor ama renkler hiç uyuşmuyor mu? Zararı yok. İradesini kırmamak için ona yalnızca 2 seçenek sunun: Bu mu, yoksa diğeri mi?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'Babanın tuhaf sesleri 🤡', 'Bebeği güldürmenin en hızlı yolu, babanın tuhaf sesler çıkarıp komik mimikler yapmasıdır. Bu akşam neşeli kahkahalarını dinlerken siz de arka planda gülümseyin.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'Dertleşme zamanı 💬', 'Bugün her şeye ağladı ve siz tükendiniz. Hemen Anacan Topluluğu''na girip Bugün çok zordu yazın. Yüzlerce kadının aynı anları yaşadığını göreceksiniz.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'Yapı ustası 🧱', 'Büyük Legoları birleştirip bir şeyler yapmaya mı çalışıyor? O, geometriyi keşfediyor. Gelişim Takipçisi''ne onun bu küçük mühendislik denemelerini ekleyin.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'Kelimelerin tekrarı 🗣️', 'Ağzınızdan çıkan her yeni kelimeyi hemen papağan gibi tekrarlıyor mu? Kelime dağarcığı zenginleşiyor. Yanında kullandığınız kelimelere ve yansıttığınız duygulara özellikle dikkat edin.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'Gecenin melodisi 🛀', 'Bütün gün koşuşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo ve arka planda çalan hafif, huzurlu bir melodi onun sinir sistemini tamamen sakinleştirecek.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'Küçük mühendis 🏗️', 'Kuleler yapıp yıkmaya bayılıyor mu? Zekâsını ve motor becerilerini daha da geliştirecek mıknatıslı veya ahşap blokları hemen Önerilen Ürünler''de keşfedin.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'Derin bir nefes alın 🌬️', 'Bugün onun peşinden koşmaktan yoruldunuz mu? Ruh Hali Günlüğünü açın ve yorgunluğunuzu yazın. Mükemmel bir anne olmaya çalışmayın; sizin duygularınız da önemli!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'Zor bir gün müydü?', 'Bugünkü stresinizi Ruh Hali Günlüğüne yazarak içinizi dökün. Tüm anneler bu krizleri yaşıyor, yalnız değilsiniz.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'Anneye ziyafet 🥑', 'Onu doyurmak için elinizden geleni yapıyorsunuz. Peki ya siz? Sağlıklı tarifler arasından size güç verecek, demir açısından zengin bir öğle yemeği seçin; sakince oturup afiyetle yiyin.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'İki kelimelik cümleler 🗣️', '“Anne gel”, “Topu at” derken kelime dağarcığı her geçen gün zenginleşiyor. Yarım söylediği kelimeleri doğru telaffuzla tekrarlayarak konuşma gelişimini destekleyin.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'Market krizleri 🛒', 'Mağazada istediğini almadığınız için kendini yere mi attı? Çevredekilerin bakışlarına aldırmayın. Göz hizasına eğilin ve duygularını anladığınızı söyleyin.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'Ters giyilen kıyafetler 👗', 'Ayakkabısını yanlış ayağına, tişörtünü ters giyiyor ve kesinlikle çıkarmak istemiyor mu? Bırakın öyle kalsın! Bu, kendi bireyselliğini ortaya koymasının en masum yoludur.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'Müzikli huzur 🎶', 'Akşamüstü başlayan huysuzlukları yatıştırmanın en kolay yolu, sevdiği bir melodiyi açıp ona sarılarak yavaşça dans etmektir.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'Kendinizle gurur duyun 🌟', 'Her gün öğrendiği yeni bir beceri ve attığı her kendinden emin adım, sizin ve partnerinizin emeğinin bir sonucudur.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'Bağımsızlık bildirgesi 📜', 'Her şeye “Kendim yapacağım!” diyor ve işleri yavaşlatıyor mu? Sınır tanımayan bu inadı gelişim fırsatına dönüştürmenin yollarını hemen Anacan AI''a sorun.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'Kitaplardaki ayrıntılar 📖', 'Kitabın sayfalarını çevirip resimdeki en küçük ayrıntıyı parmağıyla mı gösteriyor? Görsel hafızası harika çalışıyor. Onunla resimdekiler hakkında sohbet edin.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'Karalama ustası 🖍️', 'Eline kalem geçer geçmez duvarları veya kâğıdı karalıyor. İnce motor becerileri renklerle gelişiyor.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'Gecenin Sessizliği 🛀', 'Ilık bir banyo, hafif bir masaj ve karanlık bir oda. Uyku rutinini asla bozmayın; çünkü bu rutin, beynine uyku vaktinin geldiğini bildiren en güçlü sinyaldir.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'Annelerin Dertleşmesi 💬', '“Benim çocuğum neden bu kadar inatçı?” düşüncesi sizi yoruyor mu? Anacan Topluluğuna katılın; her çocuğun farklı kriz dönemlerinden geçtiğini göreceksiniz.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'Akşamın kahramanı: Baba 🦸‍♂️', 'Bu akşam uyku rutinini Partner özelliğiyle eşinize devredin. Masalı o okusun, siz de kendinize ılık bir banyo hazırlayıp günün stresini atın.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'Yemek seçiciliği 🥦', 'Dün iştahla yediği yemeği bugün reddediyor mu? Beslenme takip aracıyla menüyü analiz edin ve Bebek tariflerinde farklı, eğlenceli sunumlar bulun.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'Ağrısız günler 🩸', 'Regliniz yaklaşıyor ve kramplarınız başladı mı? İlaçlara yönelmeden önce Kadınlar için sağlıklı tariflerden magnezyum açısından zengin hurmalı-cevizli bir atıştırmalık hazırlayarak kendinize iyi bakın.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'Kıyafetler küçülüyor! 📏', 'Gömleklerinin kolları yine mi kısaldı? 29. aya doğru gerçekleşen gelişim sıçramasını net bir şekilde görmek için güncel ölçülerini Kilo Takibi''ne girip yükselen grafiğe göz atın.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'Kitap kahramanı 📖', 'Aynı masalı 100. kez okumanızı mı istiyor? Sıkıcı görünen bu tekrarın zihinsel gelişimdeki inanılmaz rolünü Bloglardan okuyarak sabrınızı tazeleyin.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'İlk mantıksal çıkarımlar 🤔', 'Bunu yaparsam şöyle olur gibi cümleler mi kuruyor? Bu muhteşem bilişsel sıçramayı kaçırmadan sesli video olarak Bebek Albümü''ne ekleyin ve gurur duyun.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'Takım toplantısı 🥂', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birer çay doldurun ve harika bir takımız diyerek birbirinizi takdir edin.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'Anne için mekân keşfi ☕', 'Evde sürekli aynı duvarlara bakmak sizi tüketti. Anne Dostu Mekânlardan çocuk oyun köşesi olan bir kafe keşfedin. O oynarken siz de kahvenizin tadını çıkarın.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'Hayvan sesleri 🐶', 'Kedi görünce miyav, köpek görünce hav hav demeye mi çalışıyor? Kelime dağarcığı hayvan sesleriyle harika şekilde gelişir. Onunla bu oyunu oynayın.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'Hızlı çocuk doktoru 🤖', '2.5 yaşına yaklaşırken porsiyon miktarı ne kadar olmalı? Kararsızsanız hemen Anacan AI''dan doğru ve bilimsel temellere dayalı bir tablo isteyin.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'Masalın kahramanı 🪄', 'Bu akşam Akıllı masallarda kahramanı kendi çocuğunuz olan özel bir hikâye oluşturun: Dişlerini fırçalamayı seven cesur minik.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', 'Seni Seviyorum sarılması 🫂', 'Birden yanınıza gelip boynunuza mı sarılıyor ya da yüzünüzü mü okşuyor? Artık sevgisini fiziksel olarak gösteriyor. Bu anın getirdiği eşsiz huzurun tadını çıkarın.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'Uykuya itiraz 🥱', 'Öğle uykusuna yatmak istemiyor ve ağlıyor mu? Mücadele etmeyin. Bunun yerine odasında sessizce kitaplara bakacağı 30 dakikalık bir Sakinlik saati ilan edin.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'Nöbet değişimi 👨‍👧', 'Bütün gün Neden? sorularına cevap vermekten zihniniz yoruldu. Bu akşam pijamalarını giydirme ve uyutma görevini partnerinize devredin, siz dinlenin.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'Sıra dışı moda 👗', 'Kışın ortasında yazlık şortunu, pantolonunu ise başına giymek mi istiyor? Zevkine karışmayın. Bu komik denemeler, bireyselliğini ortaya koymasının bir yoludur.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'Tabakta keşif 🥦', 'Dün sevdiği yemeği bugün yere mi atıyor? Beslenme planı aracına girerek 2.5 yaş için uzmanların hazırladığı farklı ve rengârenk menü fikirlerinden yararlanın.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'Beklenmedik korkular 👻', 'Odanın karanlığından veya hayalî gölgelerden korkmaya mı başladı? Hayal gücü geliştikçe yersiz korkular ortaya çıkabilir. Ona güven verin ve yanında olduğunuzu hissettirin.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'Bitmeyen pil 🔋', 'Siz daha gözlerinizi açamamışken o çoktan halının üzerinde koşu maratonuna başladı. Kendinize büyük bir kahve doldurun, bugün çok hareketli geçecek.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'Sanatçının izinde 🖍️', 'Kağıt bitti, şimdi sıra duvarlarda ve kapılarda mı? İnce motor becerileri renklerle gelişiyor. Odaya büyük bir karton serin ve resmini yalnızca buraya çizebileceğini söyleyin.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'Mantıksız inatlar 🛑', 'Suyu mavi değil de kırmızı bardakta verdiğiniz için kıyamet mi koptu? Bu şımarıklık değil; yalnızca sınırlarınızı ve dünyayı kontrol edip edemediğini test ediyor. Sabırlı olun.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'Suyun terapötik gücü 🛀', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo yalnızca temizlik değildir; gerilen sinir sistemini sakinleştiren en iyi doğal yöntemlerden biridir.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'Dağınıklıkla barışmak 🌪️', 'Her gün aynı oyuncakları toplamaktan yoruldunuz mu? Bugün toplamayın! Evin dağınık olması dünyanın sonu değil; psikolojik rahatlığınız her şeyden daha önemlidir.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'Vicdan azabını susturun 💬', 'Bugün ekran karşısında çok kaldığı için kendinizi mi suçluyorsunuz? Anacan Topluluğuna katılın; diğer annelerin de bazen aynı duyguları yaşadığını okuyup rahatlayın. Yalnız değilsiniz.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'Aynadaki kişilik 👀', 'Aynanın karşısında farklı mimikler yapıyor, kendi kendine konuşup gülüyor mu? Benlik farkındalığı harika bir şekilde gelişiyor. Onu gizlice izleyin ve bu komik anların keyfini gururla çıkarın.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'Parktaki bencillik 🧸', 'Kumda oynarken kabını kimseye vermiyor mu? Bu bencillik değil, sınırlarını korumaktır. Onu zorlamayın; bunun yerine sırayla oynama kuralını yumuşak bir dille öğretin.'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'Hayali oyunlar 🧸', 'Oyuncak ayısına veya bebeğine su içirmeye çalışıyor, onlarla konuşuyor mu? Sembolik oyunlar gelişimin başyapıtıdır. Bu sevimli yönetmeni kenardan ilgiyle izleyin.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'Yeni kelimeler 🧠', 'Bugün farklı, bir yetişkininki gibi karmaşık bir cümle mi kurdu? Hemen Gelişim takipçisini açın ve bu bilişsel sıçramayı gelecekte okumak üzere bir anı olarak kaydedin.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'Çift molası 🥂', 'Çocuğunuz uyudu. Şimdi ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuğunuz dışında herhangi bir konuda sohbet edin. Siz aynı zamanda bir çiftsiniz.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'Amaçlı emekleme 🐢', 'Artık yürümenin yanı sıra bazen eğlenmek için hızla emekleyip sizden kaçıyor mu? Odadaki tehlikeli engelleri kaldırın ve siz de bu kovalamaca oyununa katılın.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'Anne için çevrimdışı saat ☕', 'Çocuğunuz kendi dünyasına dalıp oynarken hemen bulaşık makinesine koşmayın. Kendinize sıcak bir çay doldurun, telefonu bir kenara bırakın ve 15 dakika boyunca hiçbir şey düşünmeden çevrimdışı kalın.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'Fısıltılı sohbetler 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlamanın en sakinleştirici yollarından biridir.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'Ağrısız günler 🩸', 'Regliniz yaklaşıyor ve kramplar mı başladı? Hemen ilaçlara yönelmeden önce Sağlıklı tariflerden magnezyum açısından zengin, hurmalı-cevizli bir atıştırmalık hazırlayarak kendinize iyi bakın.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'Parmaklarla sayma 🔢', 'Merdivenleri çıkarken veya oyuncaklarını dizerken bir, iki, üç demeye mi çalışıyor? Matematiksel düşünme becerisi uyanıyor. Onunla birlikte odadaki eşyaları yüksek sesle sayın.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'Enerjinizi yenileyin 🍲', 'Koşturmaca sizi yorgun düşürdü. Ayaküstü atıştırmak yerine kendinize doyurucu, kalsiyum açısından zengin özel bir tabak hazırlayın ve keyifle yiyin.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'Babanın komik yüzü 🤡', 'Bebeği güldürmenin en hızlı yolu, babanın tuhaf sesler çıkarması ve komik mimikler yapmasıdır. Bu akşam neşeli kahkahalarını dinlerken siz de arka planda gülümseyin.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'Annenin sabah enerjisi ⚡', 'Sabah yorgun mu uyandınız? Hemen şekere yönelmeyin. Sağlıklı tarifler arasından 5 dakikada hazırlanan proteinli ve meyveli yulaf tarifini keşfederek güne güçlü başlayın.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'Babanın desteği gerekiyor 🫂', 'Regl Takipçisi''ne göre PMS dönemindesiniz ve kendinizi hassas mı hissediyorsunuz? Partner özelliğiyle bugün biraz daha fazla desteğe ihtiyacınız olduğunu ona bildirin.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'Yastık kalesi 🏰', 'Bu akşam odayı oyun alanına dönüştürün. Koltuk minderlerinden küçük bir kale yapıp içine girin. Biraz dağınıklık olacak ama bu neşeli kahkahalara kesinlikle değecek.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'Avukat gibi pazarlık 🗣️', '“Biraz daha oynayayım, sonra giyinirim.” mi diyor? Artık sizinle profesyonelce pazarlık yapmaya çalışıyor. Dil gelişimi harika, ancak sınırlarınızı sevgiyle korumayı unutmayın.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'Doğayı keşfetme zamanı 🌳', 'Dört duvar arasında bunaldınız. Hava serin olsa bile onu sıkıca giydirip 20 dakikalığına parka çıkarın. Yaprakları ve taşları keşfetsin; temiz hava ikinize de iyi gelecek.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', 'Seni buldum! heyecanı 🙈', 'Saklambaç artık en sevdiği oyun. Perdenin arkasına saklanıp onu bulmanızı bekliyor. Bu oyunu günlük rutininizin en eğlenceli parçasına dönüştürün.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'Karanlığa alışmak 🌙', 'Daha çabuk uykuya dalması için odadaki tüm ekranları kapatın. Televizyonun yaydığı mavi ışık, uyku hormonunun salgılanmasını geciktirir.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'Cesur adımlar 🧗‍♂️', 'Koltuk veya sandalyeye tutunup yukarı tırmanmaya mı çalışıyor? Dengesi gelişiyor, kas gücü artıyor. Onu koruyun ancak bu küçük dağcının tırmanma girişimlerine kesinlikle engel olmayın.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'Yemek inadı 🥣', 'İki kaşık yiyip doyduğunu söylüyor ve kaçıyor mu? Onu zorlamayın. Yiyeceklerle sağlıklı bir ilişki kurması, zorla yemek yedirmekten daha önemlidir.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'Günün değerlendirmesi 📝', 'Bugün çok mu yoruldunuz, yoksa o çok tatlı bir söz mü söyledi? Her iki durumda da Duygu Günlüğü''nü açın, bu anı geleceğe not ederek içinizi rahatlatın.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'Dikkat testi 🧩', 'Örneğin bir yapbozla oynama süresi artık 10-15 dakikaya ulaştı mı? Bu, dikkat süresinin uzadığını gösterir. Sessizce odanın bir köşesinde durup onu izleyin.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'Neden-sonuç arayışı 🤔', '“Bunu atarsam ne olur?”, “Bu düğme ne işe yarar?” Sürekli fiziksel denemeler yapıyor. Evin güvenliğini onun göz hizasından bir kez daha gözden geçirin.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'Masalsız uyumuyoruz 🪄', 'Klasik masallar artık ilgisini çekmiyor mu? Başkahramanı kendisi olan ve arka planda doğa sesleriyle zenginleştirilen özel bir hikâye uydurarak onun hayal dünyasına girin.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'Müzikle dans 🎶', 'Neşeli bir müzik çaldığında hemen ritme uygun şekilde sallanıyor mu? İşitme ve motor becerileri arasındaki bağlantı harika gelişiyor! Neşeli bir şarkı açıp onunla birlikte odada dans edin.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'Babanın hikâyesi 📖', 'Bu akşam ses tellerinizi dinlendirin. Bırakın çocuğun en sevdiği kitapları farklı ses tonları ve komik anlatımlarla okuma görevini baba üstlensin.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', 'Neden? bitti, Nasıl? başladı 🤔', 'Hayal gücü ve mantık sıçraması! Artık eşyaların nasıl çalıştığını da soruyor. Anacan AI uzmanımızdan bu sorulara yaşına uygun ve sıkıcı olmayan yanıtlar verme tekniklerini öğrenin.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'Uykusuzlukla barışın 😭', 'Gecenin bir yarısı uyandı ve uyumak istemiyor. Ona kızmayın. Nedenini (ağrı, gaz, korku) anlamaya çalışın; sabırla sarılıp güven verin.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'İnatçı lekeler 👗', 'Giysilerin sürekli lekelenmesi sizi yoruyor mu? Buna kızmayın. O, yiyecekleri keşfediyor. Silikon önlükler kullanın ve bu rengârenk, dağınık anların tadını çıkarın.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'Sana yardım edeyim! 🧹', 'Siz yerleri silerken veya toz alırken elinizdekini almaya mı çalışıyor? O artık kendini büyümüş hissediyor. Ona küçük bir bez verin ve ekibinize katılmasına izin verin.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'Bedeninizi dinleyin 🩸', 'Aniden gelen tatlı krizleri veya yorgunluk mu yaşıyorsunuz? Regl Takibi''ndeki takvime bakın. Regl döneminizdeyseniz Sağlıklı Tarifler arasından magnezyum içeren bir atıştırmalık seçin.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'Odadaki gölgeler 🌌', 'Karanlıktan ve hayalî canavarlardan mı korkuyor? Odayı tamamen karartmayın ve Beyaz Sesler''den anne karnı sesini açarak ona eskiden hissettiği o kusursuz güven duygusunu yaşatın.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'Ayrılık kaygısı 🥺', 'Siz odadan çıktığınızda, hatta tuvalete gittiğinizde bile arkanızdan ağlıyor mu? Geri dönmeyeceğinizi sanıyor. Her zaman "Ben buradayım, sesimi duyuyor musun?" diyerek ona güven verin.'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'Konuşkan minik 🗣️', 'Artık 4-5 kelimeyi birleştirip komik hikâyeler mi anlatıyor? Kelime hazinesi hızla büyüyor! Bu altın değerindeki anı kaçırmayın.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'Sesleri filtreleyin 🤫', 'Uykuya daldığı anlarda hassasiyeti artar. Pencereden gelen sesleri etkisizleştirmek için odada hafif bir beyaz gürültü (white noise) cihazı çalıştırın veya müzik açın.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'Mutfakta birlikte 🧑‍🍳', 'Mutfakta sizinle birlikte bir şeyler yapmak mı istiyor? Un veya su eklerken size yardım etmesine izin verin. Her yer kirlense de onun mutluluğu ve öğrenme hevesi buna değer.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'Liste şart değil, olmazsa olmaz 🛒', 'Uykusuzluk hafızanızı zayıflattığı için marketten alacaklarınızı mı unutuyorsunuz? Zihninizi yormayın. Her şeyi uygulamadaki Alışveriş Listesi''ne yazın.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'Sadece sarılın 🫂', 'Hiçbir oyuna veya kitaba gerek yok. Bu akşam onu sadece göğsünüze bastırın, kokusunu içinize çekin ve karanlıkta ona ne kadar değerli olduğunu fısıldayın.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'Yapı ustası 🧱', 'Büyük Legoları birleştirip bir şeyler yapmaya mı çalışıyor? Mekânı ve geometriyi keşfediyor. Gelişim Takibi''nde bu özel mühendislik girişimini işaretleyin.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', 'Tek başınıza 10 dakika 🛀', 'Odaya sessizlik çöktü. Eşinizden evdeki her şeyle ilgilenmesini rica edin. Siz de sıcak bir duş alarak yalnızca kendinizle baş başa kalın.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', '2 Yaş sendromu 📱', 'Çocuğunuzun her şeye hayır demesi sizi bıktırdı mı? Bloglar bölümündeki yazıları okuyarak beyninde yaşanan bu gelişim fırtınasının nedenlerini anlayın.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'Gizli sebze operasyonu 🥦', 'Yeşillikleri veya brokoliyi tabağından mı atıyor? Bebek Tarifleri''nde rengârenk, sebzeli ev yapımı keki keşfedin ve Beslenme Takibi aracında vitamin hedefinizi kolayca tamamlayın.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'Derin nefes 🧘‍♀️', 'Bütün gün soruları yanıtlamaktan boğazınız kurudu. Oda sessizliğe büründüğünde hiçbir ekrana bakmadan, sadece derin nefes alıp vererek dinlenin.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'Kelimelerin telaffuzu 🗣️', 'Bazı kelimeleri yarım veya çok komik mi telaffuz ediyor? Gülmeyin; beyninin doğru biçimini kodlaması için kelimeyi doğru vurguyla ona tekrar edin.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'Serbest oyun 🧸', 'Onu her dakika eğlendirmek zorunda değilsiniz. Sıkılmak, çocuklar için yaratıcılığın başlangıcıdır. Bırakın odada kendi başına bir şeyler keşfetsin.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'Zamanı durduran an 📸', 'Çocuğunuz uyuduğunda o masum yüzüne bakın. Bütün gün sizi çileden çıkarsa da uyur uyumaz onu özlüyorsunuz, öyle değil mi? Annelik tam da böyle bir paradokstur.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'Su içme alışkanlığı 💧', 'Su yerine sürekli tatlı meyve suları mı istiyor? Beslenme planındaki sıvı düzenini kontrol edin. Suyu renkli, özel pipetli bardaklarda sunarak onu teşvik edin.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'Alkış ekibi 👏', 'Bir şeyi başardığında kendi kendine alkışlayarak sevincini mi gösteriyor? Bu harika anı görür görmez evde küçük bir zafer dansı yapın ve onun sevincine ortak olun!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'Anne yorulduğunda 🛑', 'Siz robot değilsiniz. Bugün yemek pişirecek gücünüz yoksa dışarıdan sipariş verin. Mükemmel anne olmak, her şeyi tek başınıza yapmak demek değildir.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'Kararlı hayırlar 🛑', 'Biri onu öpmek istediğinde uzaklaşıp kararlı bir şekilde hayır mı diyor? Onun bedensel sınırlarına saygı gösterin. İzinsiz dokunulmaya itiraz etmesi çok önemlidir.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'Sırları paylaşmak 💬', 'Çok mu yoruldunuz? Anacan Topluluğuna katılın. Binlerce annenin gerçek hikâyelerini okuyun ve yalnız olmadığınızı hissederek güç toplayın.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'Sebzeleri gizleyin 🥦', 'Çorbadaki bütün sebzeleri kenara mı ayırıyor? Mücadele etmeyin. Sebzeleri püre hâline getirip sosların veya köftenin içine gizlemek, annelerin en eski yöntemlerinden biridir.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'Resimlere tepki 📖', 'Kitaptaki hayvanları veya farklı nesneleri gördüğünde onlara dokunuyor, ses çıkarıyor mu? Görsel algısı hayranlık uyandırıyor. Onunla kitaptaki karakterler hakkında konuşun.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'Uyku kovalamacası 🏃‍♂️', 'Yatağa gitmemek için durmadan bahaneler mi uyduruyor? Uyku zamanlayıcısını çalıştırın, sınırları koruyun ve Beyaz Seslerden yağmur sesini açarak odayı sakinleştirin.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'Sıvı alımı ve kabızlık 💩', 'Çok koşuyor ama az mı su içiyor? Lazımlıktaki veya bezdeki dışkısını takip edin. Kabızlık riski varsa uygulamaya kaydedin ve hemen Beslenme takip aracıyla menüsüne yulaf veya armut ekleyin.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'Yeni arkadaş arayışı 👫', 'Parkta yaşıtlarıyla koşmaya, onlara yaklaşmaya mı çalışıyor? Sosyalleşme resmen başladı! Güvenliğini uzaktan gözeterek bu girişimlerini gururla izleyin.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'Gecenin melodisi 🛀', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo ve arka planda çalan hafif, huzurlu bir melodi onun sinir sistemini tamamen sakinleştirecektir.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'Gündüz uykusunu reddetme 🥱', 'Yine uyumadı mı? Mücadele ederek hem onu hem de kendinizi yormayın. Odada sessizce oyuncaklarla oynamak da beyin için bir dinlenme biçimidir.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'Sessizlik ve kahve 🤫', 'Uyudu! Şimdi bulaşık makinesini boşaltmak yerine odanın karanlığında oturun. 15 dakikalık sessizliğin değerini bilin ve dinlenin.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'Aşağıya bakın! 👣', 'Artık ayak parmaklarını tutup inceliyor, hatta çıplak ayakla yürümekten keyif mi alıyor? Ayak tabanındaki sinirleri keşfetmesi, denge gelişimi için çok önemlidir.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'Hava sürprizi ⛅', 'Yürüyüşe çıktığınızda havaya aldanıp üşümesine neden olmayın. Yalnızca pencereden bakarak karar vermeyin; dışarıdaki rüzgâr hızını ve hissedilen sıcaklığı önceden kontrol edin.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'Benliğini keşfediyor 👑', 'Ben!, Benim! sözleri dilinden düşmüyor. Benmerkezcilik döneminin en belirgin zamanında. Bu bireyselliğini saygıyla karşılayın; bu, gelişiminin doğal bir aşamasıdır.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'Babanın sorumluluğu 👨‍🍼', 'Gündüzün yorgunluğu size yeter. Akşam çocuğu uykuya hazırlama ve pijamalarını giydirme işini babaya bırakıp sadece uzaktan izleyin.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'Enerji deposu lazım 🍲', 'Yorgunluğu iliklerinize kadar mı hissediyorsunuz? 10 dakikada hazırlanan, hem tok tutacak hem de enerji verecek özel bir salata hazırlayarak kendinizi ödüllendirin.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'Diş fırçası savaşı bitiyor 🪥', 'Diş fırçasını görür görmez ağzını sımsıkı kapatıyor mu? Bu süreci kolaylaştıracak müzikli veya dönen çocuk diş fırçalarını Önerilen Ürünler''de arayın ve hijyeni eğlenceye dönüştürün.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'Gece fırtınası 😭', 'Gecenin bir yarısı sebepsiz yere ağlayarak mı uyandı? Gaz sancısı mı, yoksa yalnızca uyku terörü mü? Sakince kucağınıza alın ve sesinizi yükseltmeden ona huzur verin.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'Dört duvarın dışına ☕', 'Evdeki rutin sizi bunaltmaya başladı. Bugün bir değişiklik yapın. Yakınlardaki sakin bir kafeye giderek hem onun ortamını değiştirin hem de kahvenizin tadını çıkarın.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'Uyku hassasiyeti 🤫', 'Uykuya dalar dalmaz en küçük tıkırtıyla irkiliyor mu? Odanın akustiğini kontrol edin ve pencereden gelen sesleri bastırmak için beyaz gürültü açın.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'Mobilyalara tırmanmak 🧗‍♂️', 'Kanepeye veya sandalyeye tutunup yukarı tırmanmaya mı çalışıyor? Bacak kasları farklı yükseklikleri test ediyor. Onu koruyun ancak bu küçük dağcının denemelerine engel olmayın.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'Tabakta sanat eseri 🥦', 'Yemeğini yemiyor mu? Bazen sorun tatta değil, görünüştedir. Rengârenk sebzelerle komik yüzler yaparak iştahını açmayı deneyin.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'Gece ninnisi 🎶', 'Hiçbir uygulama veya ses, anne ninnisinin yerini tutamaz. Bu akşam onu sadece göğsünüze yaslayın ve en sevdiği, ona güven veren ninniyi usulca söyleyin.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'Tuvalette ilk zafer! 🚽', 'Lazımlığa kendi başına gitmek mi istiyor? Bu, 2.5 yaşın en büyük zaferidir! Bez/Lazımlık takipçisinde bu başarıyı kaydedin ve Bloglarda bu geçişi nasıl daha da kolaylaştırabileceğinizi okuyun.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'Hafıza iflası 🛒', 'Uykusuzluk hafızanızı zayıflattığı için marketten alacaklarınızı mı unutuyorsunuz? Zihninizi yormayın. Her şeyi listeye yazın, eşiniz gelirken alıversin.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'Diplomatik görüşmeler 🤝', 'Parkta oyuncağını vermiyor mu? 2.5 yaşından sonra paylaşmayı değil, sırayla oynamayı nasıl öğretebileceğinizi mutlaka Bloglar bölümünden okuyun.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'Gece uyanmaları 🌌', 'Gece yarısı ağlayarak uyanıyor ve sakinleşmiyor mu? Uyku zamanlayıcısındaki grafiğe bakın. Gece terörü ile kâbus arasındaki farkı anlamak için hemen Bloglar bölümüne göz atın.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'İnat krizleri 🛑', 'Her “hayır” deyişinize çığlıkla mı karşılık veriyor? Kontrol edilemeyen bu duygusal patlamaları soğukkanlılıkla yönetmeyi ve dikkat dağıtma taktiklerini öğrenmek için Anacan AI ile dertleşin.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'Babanın masal saati 📚', 'Bu akşam uykuya geçiş rutinini partnerinize bırakın! Uygulamadaki Partner modunu kullanarak masalı o okusun, siz de çayınızı huzurla için.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'Deneyim paylaşımı 💬', 'Çocuğunuzun yeni bir davranışı sizi korkuttu mu? İnternette korkutucu yazılar aramayın. Anacan Topluluğundaki deneyimli annelerin tavsiyelerinden yararlanın.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'Demirin sırrı: C vitamini 🍋', 'Rengi soluk veya iştahsız mı? Beslenme takip aracından bugünkü demir alımını kontrol edin ve etin yanında bol limonlu salata vererek demir emilimini artırın.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'Yalnızca kuru gıdalar mı? 🍞', 'Püreleri ve sulu yemekleri reddedip yalnızca ekmek ve bisküvi mi istiyor? Bu, doku seçiciliğidir. Beslenme takip aracıyla menüsünü analiz edin ve Bebek tariflerinde sağlıklı alternatifler bulun.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'Bedeninizi dinleyin 🩸', 'Ani tatlı krizleri ve sinirlilik mi yaşıyorsunuz? Regl Takipçisindeki takvime bakın. Regl dönemindeyseniz Kadınlar için sağlıklı tariflerden magnezyum açısından zengin, hurmalı ve cevizli bir atıştırmalık hazırlayın.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'Doğa dedektifi 🔍', 'Evde her yeri dağıtıyor mu? Büyütecinizi alıp dışarı çıkın! Anne Dostu Mekanlardan yeşillikler içinde bir park bulun; böcekleri ve yaprakları birlikte keşfederek enerjisini doğaya yönlendirin.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'Akşam rutini zorlaştı mı?🛀', 'Ilık bir banyo sırasında arka planda sakinleştirici bir müzik açın. Suyun ve melodinin uyumu, en inatçı çocuğu bile yumuşatır.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'Evin kaosu 🌪️', 'Odanın her yanı oyuncakla mı dolu? Temizlikten çok, onunla gülümseyerek geçireceğiniz 10 dakika önemlidir. Oyuncaklar yarın da orada olacak, kendinizi yormayın.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'Mutlak sessizlik arayışı 🛋️', 'Çocuğunuz uyur uyumaz bulaşık makinesini boşaltmaya koşmayın! Kanepeye uzanın, gözlerinizi kapatın ve 15 dakika boyunca evdeki o nadir, mutlak sessizliğin içinde kaybolun.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'Karanlığa alışmak 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm ek ışıkları ve ekranları kapatın. Melatonin hormonunun salgılanması yalnızca sessiz ve karanlık bir ortamda hızlanır.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'Sizi duyuyorum 🗣️', 'Sizi dikkatle dinleyip benzer cümleler kurmaya mı çalışıyor? O, sizinle konuşuyor! Ona bol bol gülümseyerek karşılık verin ve bu iletişimi teşvik edin.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'Kahve zamanınız ☕', 'Sürekli evde oturmaktan yoruldunuz mu? Anne Dostu Mekanlar arasından annelerin sıkça buluştuğu çocuk kafelerini bulun ve kendinize sosyalleşebileceğiniz yeni bir ortam yaratın.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'Sıra bekleme sanatı 🧸', 'Parkta başka bir çocuğun kaydıraktan inmesini beklemek istemiyor mu? 2.5 yaşından sonra sabır ve sırayla oynama kavramlarını nasıl öğretebileceğinizi Bloglar bölümünden mutlaka okuyun.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'Demir deposu kontrolü 🥩', 'Rengi soluk veya iştahsız mı? Beslenme Takibi aracından bugünkü demir alımını kontrol edin; emilimi artırmak için etin yanında mutlaka bol limonlu salata verin.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'Babadan masaj 💆‍♀️', 'Bütün gün çocuğun peşinden koşmaktan beliniz mi tutuldu? Partner özelliğiyle ona, bu akşam çocuğu uyuttuktan sonra size kısa bir omuz masajı yapma zamanının geldiğini bildirin.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'Su içmeyi oyuna dönüştürün 💧', 'Çok koşuyor ama az mı su içiyor? Kabızlık riski artar. Uygulamaya dışkılamasını kaydedin, ardından Beslenme Takibi aracıyla menüsüne hemen yulaf ekleyin ve Önerilen Ürünler arasından renkli çocuk mataraları sipariş edin.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'Seçici iştah 🍝', 'Yalnızca makarna mı istiyor? Beslenme Takibi aracıyla haftalık dengeyi kontrol edin. Tek bir günün stresiyle kendinizi yıpratmayın.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'Yorgunluk gözyaşları 💧', 'Siz de ağlamak mı istiyorsunuz? Bu tamamen normal. Duygu Günlüğüne hislerinizi yazın, suçluluk duygusunu bir kenara bırakın.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'Sayıları tanıyor mu? 🔢', 'Merdivenleri çıkarken veya oyuncakları toplarken bir şeyleri saymaya çalışıyor mu? Matematiksel gelişimin ilk kıvılcımlarını hemen sesli video olarak Bebek Albümüne ekleyin ve ömür boyu saklanacak bir anıya dönüştürün.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'Sebzeleri gizleyin 🥦', 'Yeşillikleri veya brokoliyi tabağından atıyor mu? Bebek tarifleri arasında rengarenk, sebzeli ev kekini keşfedin ve Beslenme Takibi aracındaki günlük vitamin hedefini kolayca tamamlayın.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'Siz mükemmel bir takımsınız 🌟', 'Her gün öğrendiği yeni beceri, attığı her güvenli adım sizin ve partnerinizin emeğidir. Duygu Günlüğünü açın ve bugün takım olarak kendinizi ayakta alkışlayın!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'Boy ve kilo sıçraması! 📏', 'Giydirirken kıyafetlerinin daraldığını veya ayakkabısının sıktığını fark ettiniz mi? Kilo Takibine güncel boyunu ve ölçülerini girin, gelişim eğrisinin nasıl yükseldiğini gururla izleyin.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'Babadan masal saati 📚', 'Bu akşam uykuya geçiş partnerinizin sorumluluğunda. Masalı o okusun, siz de size armağan edilen bu kısa molanın tadını çıkarın.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', '“Neden?” soruları 🤔', 'Dünyayı anlamak istiyor. Bitmek bilmeyen sorularına nasıl sabırla yanıt verebileceğinizi Bloglardan öğrenin. Sabrınız, onun gelişimine katkıdır.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'Dört duvar üzerinize geliyor 🌳', 'Evde her şey havada mı uçuşuyor? Anne Dostu Mekanlardan yakındaki bir parkı bulun. Temiz hava hem ona hem de size en iyi ilaçtır.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'Demir ve güç 🥩', 'Rengi soluk mu? Beslenme Takibi aracından demir alımını kontrol edin. Emilimi artırmak için etin yanında limonlu salata verin.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'Diş fırçası savaşı 🪥', 'Fırçayı görünce kaçıyor mu? Önerilen Ürünler arasındaki müzikli fırçalara göz atın. Hijyeni zorunluluk olmaktan çıkarıp oyuna dönüştürün.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'Dışarı çıkma zamanı 🌳', 'Dört duvar arasında bunaldınız. Onu bebek arabasına koyun ve 20 dakikalığına da olsa temiz havaya çıkın. Doğanın huzuru hem bebeğe hem de sizin psikolojinize çok iyi gelecek.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'Aşağıya bakın! 👣', 'Artık çıplak ayakla yürümekten ve farklı dokuları ayaklarıyla keşfetmekten keyif alıyor mu? Ayak tabanındaki sinirlerin uyarılması, denge gelişimi açısından çok önemlidir.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'Masalların büyülü dünyası 🪄', 'Bu akşam bambaşka bir şey deneyin: Gökyüzünü keşfeden küçük bulutun hikâyesi. Ses tonunuzu masalın ritmine göre ayarlayın.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'Akşam rutininde sakinlik 🌬️', 'Bütün gün koşturdu ve şimdi yavaşlayamıyor mu? Uyku zamanlayıcısını başlatın, Beyaz Seslerden okyanus dalgalarını açarak odayı sakin bir uyku mağarasına dönüştürün ve enerjisini sıfırlayın.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'Babanın mutfak günü 👨‍🍳', 'Partner modunu etkinleştirin. Bugün öğle yemeğini hazırlamak ve bebeği yedirmek babanın görevi! Siz de bu zamanı kitap okuyarak veya dinlenerek kendinize ayırın.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'Amaçlı emekleme 🐢', 'Artık yürümenin yanı sıra bazen eğlenmek için hızla emekleyerek sizden kaçıyor mu? Odadaki tehlikeli engelleri kaldırın ve bu kovalamaca oyununa siz de katılın.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'Kemikler için D vitamini ☀️', 'Kalsiyumun emilimi için D vitamini şarttır! Beslenme takip aracıyla bugünkü beslenmesini kontrol edin ve Önerilen Ürünlerde doktorların tavsiye ettiği damlalara göz atın.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'Gecikme krizi 🛑', 'Evden çıkmanız gerekiyor ama o her şeyi yavaş yapıyor ve hiç acele etmiyor mu? Bu yaşta zaman kavramı henüz gelişmemiştir! Onu acele ettirmek yerine geçişleri nasıl kolaylaştırabileceğinizi Anacan AI uzmanımızdan öğrenin.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'Mükemmel anne arayışı 💖', 'Bugün sabrınız taştı ve sesinizi yükselttiniz mi? Vicdan azabı çekmeyin. Çocuğunuz uyuduktan sonra iç sıkıntılarınızı Duygu Günlüğüne yazarak yükünüzü hafifletin.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'Gündüz uykusu tarih mi oluyor? ⏱️', 'Öğle uykusunu kesinlikle reddediyor, akşamları ise aşırı yoruluyor mu? Uyku zamanlayıcısındaki istatistikleri analiz ederek tamamen sakin zaman (quiet time) düzenine geçmeyi deneyin.'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'Annenin PMS krizleri 🍫', 'Regliniz yaklaşırken enerjiniz düştü mü? Hemen ilaçlara başvurmadan önce Kadınlar için sağlıklı tariflerden hızla enerji veren, doğal şeker içeren orman meyveli bir smoothie hazırlayarak vücudunuzu toparlayın.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'Kendim keseceğim! ✂️', 'Mutfakta muzu veya oyun hamurunu kendisi kesmek mi istiyor? Bu, ince motor becerileri gerektiren harika bir istektir! Önerilen Ürünlerde çocuklar için güvenli, keskin olmayan bıçak ve makaslara hemen göz atın.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'Neden ağladığını bilmiyor 😭', 'Bardağı mavi değil de kırmızı olduğu için büyük bir kriz mi yaşanıyor? Asıl neden yorgunluk veya duyusal yüklenme olabilir. Kontrol edilemeyen bu duygusal patlamaları soğukkanlılıkla yönetmek için Anacan AI ile dertleşin.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'Odadaki yabancı sesler 🌌', 'Odadaki tam sessizlik veya komşudan gelen hafif tıkırtılar onu uyandırıyor mu? Beyaz Seslerden vantilatör sesini açın ve uyku ortamında nasıl kusursuz bir ses yalıtımı oluşturduğunu görün.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'Birlikte ev temizliği 🧹', 'Evin temizlenmesi mi gerekiyor? Partner modunu etkinleştirin! Siz, babası ve minik bebeğinizle (eline küçük bir bez vererek) temizliği nasıl eğlenceli bir aile oyununa dönüştürebileceğinizi keşfedin.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'Ekran yerine oyun 📱', 'Akşamüstü çizgi film izlemek istiyor ve ağlıyor mu? Ekran süresini stres yaşamadan nasıl sınırlandırabileceğinizi ve dikkatini hemen başka bir oyuna nasıl yönlendirebileceğinizi Anacan AI''dan öğrenin.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'Ekran krizleri 📱', 'Telefonu elinden aldığınızda kıyamet mi kopuyor? Ekran süresine stres yaşamadan sınır koymanın gerçekten işe yarayan psikolojik sırlarını Anacan AI''a sorun.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'Gece terörü 🤖', 'Gece yarısı çığlık atarak uyanıyor ve sizi tanımıyor mu? Bu durumda ne yapmanız gerektiğini ve gece terörü ile kâbus arasındaki farkı hemen Bloglar bölümündeki yazılardan öğrenin.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'Sizin de bir arkadaşınız var ☕', 'Yalnızca çocukla konuşmak yorucu olabilir. Anne Dostu Mekanlar''dan çocuk kafelerini bulun, bir kahve içip diğer annelerle sosyalleşin.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'Sabah krizleri 🛑', 'Her “hayır” dediğinizde ağlıyor mu? Duygusal patlamaları soğukkanlılıkla yönetmek ve dikkatini başka yöne çekmek için Anacan AI ile dertleşin.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'Kirlenmesine izin verin 🏖️', 'Çamurla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen en iyi malzemeleri Önerilen Ürünler''de bulun.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'Boy atma dönemi 📏', 'Gömlekleri mi kısaldı? Büyüyor! Güncel ölçülerini Kilo Takibi''ne girin ve gelişim eğrisinin nasıl yükseldiğini gururla izleyin.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Ev işlerini unutun! Sağlıklı tariflerden melisa çayı demleyin ve yalnızca sessizliğin tadını çıkarın.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'Uyku düzeni analizi ⏱️', 'Akşamları uykuya dalması çok mu uzun sürüyor? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu belirgin şekilde kısaltmanın zamanı gelmiştir.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'Kalsiyum kalkanı 🦴', 'Süt içmiyor mu? Güçlü kemikler için kalsiyum şarttır. Beslenme takip aracıyla yoğurt veya brokoli tüketimini hesaplayın ve eksikleri tamamlayın.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'Uzun cümleler 🗣️', 'Artık komik hikâyeler mi anlatıyor? Kelime dağarcığı hızla gelişiyor! Bu altın anı kaçırmadan Bebek Albümü''ne sesli bir anı kaydedin.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'Erken uyanmalar 🌅', 'Güneş doğmadan uyanıyor ve enerji dolu mu? Siz ise tükenmiş hissediyorsunuz. Bu düzeni nasıl ayarlayabileceğinizi Anacan AI''a sorun. Uykusuzluk sonsuza dek sürmez.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'Babanın hikâyesi 📚', 'Partner modunu açın. Bu akşam masalın kahramanı baba! O okusun, siz de kahvenizi doldurup odanın dışında sessizliğin tadını çıkarın.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'Paylaşma sıkıntısı 🧸', 'Oyuncağını kimseye vermiyor mu? Bu bencillik değil, yaşına özgü bir gelişim aşamasıdır. Bloglardan sırayla oynama alışkanlığını nasıl kazandıracağınızı öğrenin.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'Gözyaşları normaldir 💧', 'Yoruldunuz ve sadece ağlamak mı istiyorsunuz? Güçlü bir anne olmak, bazen kırılganlığınızı kabul edebilmektir.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'Enerji düşüşü ⚡', 'Öğle saatlerinde ayakta uyukluyor musunuz? Kafeine değil, proteine yönelin! Sağlıklı tariflerdeki anında enerji veren fıstık ezmeli smoothie ile tazelenin.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'Ani çığlıklar 🛑', 'Hiçbir neden yokken kendini yere mi atıyor? Bu krizleri soğukkanlılıkla yönetmek ve çevrenizdekilerin bakışlarını önemsememek için Anacan AI ile dertleşin.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'Birlikte çözüyoruz 🥂', 'Bebek uyuduktan sonra eşinizle karşılıklı oturun. Bebekten konuşmak yerine, “Bugün de hayatta kaldık” diyerek birbirinize gülümseyin ve takım ruhunu hissedin.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'Dışarı çıkma zorunluluğu ⛅', 'Dört duvar üzerinize geliyor. Hava ve kıyafet aracından hissedilen sıcaklığı kontrol edin ve hiç düşünmeden parka koşun. Temiz hava, en şiddetli krizleri bile anında yatıştırır.'),
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498', '20 dakikalık ayakkabı 👟', 'Ayakkabısını kendisi giymek istiyor ve evden çıkmanız gecikiyor mu? Sabrınız taşmasın.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'Cümleler uzuyor 🗣️', 'Artık kelimeleri bir araya getirerek ilginç ve tamamen kendi mantığına uygun cümleler kuruyor. Bu anları kaçırmayın; Bebek fotoğraf çekimi ile bu tatlı diyaloglarını videoya kaydedin.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'Karanlık oyunları 🐰', 'Işıklar söndüğünde korkuyor mu? Odayı tamamen karartın ve el feneriyle duvarda gölge oyunları yapın. Korkusunu eğlenceye dönüştürerek karanlıkla barışmasına yardımcı olun.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'Boy ve kilo sıçraması 📏', 'Pantolonları yine mi kısa gelmeye başladı? Hızla büyüyor! Güncel ölçülerini Gelişim Takibi''ne girin ve uykusuz gecelerinizin meyvesi olan o yükselen gelişim eğrisine gururla bakın.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'Nedensiz uyanmalar 😭', 'Gecenin bir yarısı çığlık atarak uyandı. Panik yapmayın. Ağlama analizi aracıyla bunun büyüme ağrısı mı yoksa uyku terörü mü olduğunu kontrol edin ve ona sabırla sarılın.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'Buz gibi kahve ☕', 'Kahveyi hazırlayıp 3 saat sonra içmek, anneliğin yazılı olmayan resmi kuralıdır. Bugün bir değişiklik yapın. Onu oyuncaklarıyla baş başa bırakın ve kahvenizi 10 dakika içinde sıcakken için!'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'Sayıları keşfediyor 🔢', 'Merdivenleri çıkarken veya oyuncakları dizerken bir, iki, üç diye saymaya çalışıyor. Bilişsel gelişimin bu matematiksel aşamasını onunla birlikte sayarak destekleyin.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'Babanın gizli silahı 🤡', 'Sizin yaptıklarınız artık işe yaramadığında, babanın çıkardığı tuhaf sesler ve yaptığı komik yüzler durumu anında kurtarır. Akşam krizlerinde topu hemen ona atın.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'Gündüz uykusu inatlaşmaları 🥱', 'Yatağa gitmeyi kesinlikle istemiyor mu? 2.5 yaşında bazı çocuklar gündüz uykusunu reddetmeye başlar. Uykuyu zorlamak yerine, 30 dakikalık Sessiz kitap saati uygulayın.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'Aşağı bakın, orada ne var? 👣', 'Çıplak ayakla yürümekten ve farklı yüzeylere (kum, halı, taş) dokunmaktan büyük keyif alır. Ayak tabanındaki sinirlerin uyarılması, nörolojik gelişimi için çok değerlidir.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'Işıkları azaltın 🌙', 'Uykuya 1 saat kala evdeki tüm parlak ışıkları ve mavi ekranları kapatın. Melatonin hormonunun devreye girmesi için evde loş bir akşam ortamı oluşturun.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'Doktor telaşı 🤖', '2.5 yaş için gerekli aşılar veya vitaminler konusunda şüpheleriniz mi var? İnternetteki korkutucu forumlarda kaybolmayın, hemen Anacan AI''dan net bir yanıt alın.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'Mini tartışmalar 🗣️', 'Hayır, ben büyüdüm, kendim bilirim! Artık gerekçeler öne sürerek sizinle aynı fikirde olmadığını göstermeye çalışıyor. Sesinizi yükseltmeden, onunla aynı seviyeye inerek fakat kararlı bir şekilde yanıt verin.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'Kendinize zaman ayırmak suç değil 💆‍♀️', '“Çocuğumla az zaman geçiriyorum” hissi her anneyi etkiler. Ancak tükenmiş bir annenin çocuğuna verecek hiçbir şeyi kalmayacağını unutuyorsunuz. Öğleden sonra kendiniz için 20 dakikalık bir nefes molası yaratın.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'Kırık kurabiye faciası 🍪', 'Kurabiyesi ikiye bölündü diye dünyanın sonu mu geldi? 2.5 yaşın klasik krizlerine hoş geldiniz. Mantık aramayın; ona sadece bu büyük derdini anladığınızı söyleyin.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'Filtresiz gerçeklik 🛑', 'Sosyal medyadaki sakin ve tertemiz çocuk videolarını izleyip kendinizi suçluyor musunuz? Onlar yalnızca 15 saniyelik illüzyonlar. Sizin dağınık ve gürültülü gerçekliğiniz en güzelidir.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'Pijama itirazı 👕', 'Giyinmek istemiyor ve evin içinde koşturuyor mu? Mücadeleyi oyuna dönüştürün. Bakalım kim daha hızlı giyinecek? Rekabet, çoğu zaman inatçılığı kıran en iyi silahtır.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'Küçük ses kayıt cihazı devrede 🎙️', 'Ağzınızdan çıkan en rastgele sözü bile hemen tekrarlıyor mu? O sizin canlı aynanızdır. Bu yaşta kelime dağarcığı hızla gelişir; bu yeni kelimeleri Gelişim Takibi''ne kaydedin.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'Hızlı tedarik 🛒', 'Uykusuzluk dikkatinizi mi dağıttı? Ne alacağınızı sürekli unutuyorsunuz. Her şeyi anında Alışveriş listesine ekleyin ve market sorumluluğunu tamamen eşinize bırakın.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'Babanın masal tiyatrosu 📖', 'Ses telleriniz bütün gün hayır demekten yoruldu. Bu akşam masal saatini babaya devredin. Bırakın sesini değiştirerek komik hikâyeler anlatsın, siz de dinlenin.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'Sanatçının yeni tuvali 🖍️', 'Kâğıtlar bitti, şimdi duvara veya kapıya mı resim yapmak istiyor? O yalnızca karalama yapmıyor, ince motor becerileriyle dünyayı keşfediyor. Ona büyük bir karton vererek sınırını belirleyin.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'Sessizliğe dokunmak 🤫', 'Evdeki kaos sonunda bitti ve o uyudu. Ses ölçeri açın, odanın ne kadar sessiz olduğunu görün ve 15 dakika boyunca hiçbir ekrana bakmadan bu sessizliğin içinde eriyin.'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'Sebze kamuflajı 🥦', 'Tabağındaki yeşil olan her şeyi kenara mı itiyor? Yemek seçiciliği zirvede. Beslenme planı bölümünde sebzeleri püre hâline getirip köftenin içine gizleyebileceğiniz kurnaz tarifler bulun.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'Parktaki sınırlar 🧸', 'Kum havuzunda kovasını kimseye vermiyor mu? Bu bencillik değil, mülkiyet anlayışıdır. Paylaşmayı zorlayarak değil, sırayla öğretin: Şimdi sıra onda.'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'Hayalî misafirler geldi ☕', 'Odada tek başına görünmez arkadaşlarıyla konuşup onlara çay mı dolduruyor? Hayal gücü gelişiminin zirve noktası! Bu muhteşem senaristi uzaktan gururla izleyin.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'Sihir artık çocuğun elinde 🪄', 'Klasik masallardan sıkıldı mı? Akıllı masallarda bu kez kahramanı onun seçmesine izin verin. Uçan köpek veya Konuşan ağaç – hayal gücünü özgür bırakın.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'Kendi kurallarını yazıyor 🛑', 'Her şeye kendim yapacağım! diyor. Ayakkabılarını ters, tişörtünü yanlış giyiyor ama yine de ısrar ediyor. Zararı yok; bağımsız olma arzusu estetikten daha önemlidir, izin verin.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'Su terapisi 🛀', 'Bütün gün koşturmaktan hem onun hem de sizin sinirleriniz gerildi. Ilık bir banyo yalnızca hijyen için değildir; suyun gerginliği gideren mistik gücünden yararlanmak içindir.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'Tükenmişlik hissi 🔋', 'Her şeye bağırmak mı istiyorsunuz? Bu, tükenmişliktir. Hemen Anacan Topluluğu''na katılın; sizinle aynı dönemden geçen annelerin paylaşımlarını okuyarak destek alın.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'Mutfak sabotajı 🧑‍🍳', 'Siz yemek yaparken o tencerelerle konser mi veriyor? O da ekibin bir parçası olmak istiyor. Eline küçük bir hamur parçası verin, bırakın o da yemek yapsın.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'En güzel yük 🫂', 'Gün boyu sizi çıldırttı, her şeye ağladı. Ama akşam uykuya dalarken göğsünüze sokulan o sıcacık, minik bedenin kokusu... İşte bu, dünyanın en güzel hissidir.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'Annelere uygun bir mekân ☕', 'Her gün aynı parka gitmekten sıkıldınız mı? Anne Dostu Mekânlar arasından çocukların da rahatça oynayabileceği, sakin ve farklı bir kafe keşfedin; bugün kendinizi şımartın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80'::uuid, 'Şekil ve mekân algısı 🧩', 'Yapboz parçalarını ve farklı şekilleri uygun deliklere yerleştirmekte ısrarcıdır. Hata yapsa da müdahale etmeyin. Problem çözme becerisini tam da deneme yanılma yoluyla öğrenir.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'Doğal beyaz gürültü 🤫', 'Uykuya daldığı ilk yarım saat, beynin en aktif olduğu zamandır. Odanın ses düzeyini bir ses ölçerle ayarlayın. Bazen yalnızca hafifçe yağan yağmurun sesi onu derin bir uykuya taşıyabilir.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'Kendinize teşekkür edin 🎈', 'Geceleri uykusuzluk, gündüzleri koşuşturmaca... Ama siz bunu başardınız. Bugün onu sesinizi yükseltmeden büyüttüğünüz için kendinize “Aferin!” deyin!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'Listesiz markete gitmek mi? Asla! 🛒', 'Hafızanıza güvenip markete gidiyor ve eve en gerekli şeyi almadan dönüyorsunuz. Bu alışkanlığı bırakın. Evde eksilen her şeyi anında Alışveriş listesine yazmayı alışkanlık hâline getirin.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'Duygularınızı serbest bırakın 📝', 'Kimse sizi anlamıyor mu? Yorgunluğunuzu görmüyor mu? Duygu günlüğü en iyi sırdaştır. Tüm stresinizi, acınızı ve yalnızlığınızı oraya yazın; içinizin nasıl ferahladığını göreceksiniz.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'Sebze düşmanlığı devam ediyor 🥦', 'Yine çorbadaki o küçük havuç parçasını görüp yemek yemeyi mi reddetti? Porsiyonları küçültün, şekilleri değiştirin. Yaratıcılık, bir annenin en büyük silahıdır.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', '“Seni buldum!” sürprizi 🙈', 'Saklambaç oyununun kuralları değişti. Artık o saklanıyor ve “Ben buradayım!” diye bağırarak ortaya çıkıyor. Oyunun kurallarını onun belirlemesine izin verin ve birlikte kahkahalar atın.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'Gecenin huzuru 🛀', 'Çok inatçı ve huysuz olduğu bir akşamsa onu ılık suyla buluşturun. Küvette yalnızca suyla oynaması ve suyun rahatlatıcı gücü, tüm olumsuz enerjisini alıp götürecektir.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'Şarkı mırıldanmaları 🎶', 'Oyun oynarken kendi kendine anlaşılmaz sözlerle şarkılar söylüyor. Bu, hem konuşma hem de işitme gelişiminin bir işaretidir. Bu yeni aşamayı gelişim takipçisine mutlaka ekleyin.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'Babanın kitap saati 📖', 'Bu akşam odada farklı bir atmosfer yaratalım. Kitap okuma görevini babanın tok ve güven veren sesine bırakın; siz de bir köşede mutlak sessizliğin tadını çıkarın.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'Annelerin destek grubu 💬', 'Zor bir karar mı vermeniz gerekiyor? (Kreş, lazımlık, uyku). Anacan Topluluğundaki deneyimli annelerin tavsiyeleri, hiçbir kitapta yazmayan en gerçekçi çözüm yollarıdır.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'Ev dağınık kalsın 🌪️', 'Her akşam aynı oyuncakları kutuya toplamaktan yoruldunuz mu? Bugün toplamayın! Ev bir müze değil; içinde hayatın aktığı ve küçük bir kâşifin büyüdüğü bir yerdir.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'Hedefli atışlar ve yakalama ⚾', 'Ona attığınız büyük topun artık sadece yanından geçmesine izin vermiyor, onu yakalamaya çalışıyor. Göz-el koordinasyonu hızla gelişiyor. Koridorda birlikte küçük spor oyunları oynayın.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'Masalsız uyumuyoruz 🪄', 'Odanın ışıklarını tamamen kapatın. Akıllı masallarda arka planda yalnızca doğa seslerinin (rüzgâr, orman) bulunduğu, sözsüz ve sakinleştirici bir ortam oluşturarak uykuya geçişi hızlandırın.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'Takım gururu 🥂', 'Zor bir günü geride bıraktınız. Çocuğunuz uyuduktan sonra partnerinizle birer çay koyup “Biz gerçekten bu işin üstesinden harika geliyoruz.” diyerek birbirinizi motive edin.'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'Hava değişken ⛅', 'Yürüyüşe çıktığınızda havaya aldanıp üşümesine neden olmayın. Pencereden bakarak karar vermeyin; Hava ve kıyafet yardımcısıyla dışarıdaki koşullara en uygun kombini belirleyin.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'Cesur atlayışlar 🧗‍♂️', 'Kanepeden yastıkların üzerine atlıyor. Yer çekimini ve cesaretini test ediyor. Yasaklamak yerine odada güvenli bir atlama alanı oluşturun.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'Uykusuzlukla barışın 😭', 'Gecenin bir yarısı uyandı ve uyumak istemiyor. Ona kızmayın. Nedenini anlamaya çalışın ve yanında olduğunuzu hissettirerek onu okşayın.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'Kriz anında sabır 🛒', 'Markette istediği oyuncağı almadığınız için bağırıyor. Etraftaki kusursuz ebeveynlerin bakışlarını önemsemeyin. Sakince göz teması kurup açıklayın ve tutumunuzdan vazgeçmeyin.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', '31. aya geçiş!  🎉', 'Artık çocukluk döneminin en zihinsel açıdan gelişmiş, aynı zamanda en çalkantılı evresinde. Her cümlesi, her sorusu sizin için büyük bir keşif.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'Yemek krizleri 🥣', 'İki kaşık yiyip “Doydum.” diyerek kaçıyor mu? Onu zorlamayın. Yiyeceklerle sağlıklı bir ilişki kurması, tabağını bitirmesinden daha önemlidir.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'Zamanı durduran kare 📸', 'Odada tatlı tatlı oynarken hemen Bebek fotoğraf çekimini açın; değişen ve büyüyen yüzünü, o ışıl ışıl gözlerini hiçbir filtre kullanmadan geleceğe bir anı olarak kaydedin.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'Yine mi ayrılık kaygısı? 🥺', 'Tuvalete gittiğinizde bile kapının arkasında sizi bekleyip ağlıyor. Ayrılık kaygısı bazen geri dönebilir. Başka bir odada olsanız bile her seferinde ona seslenerek burada olduğunuzu ve geri döneceğinizi söyleyin.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'Enerjisini atması şart 🌳', 'Dört duvar arasında kalmak onu hırçınlaştırıyor. Onu bebek arabasına koyun veya elinden tutup temiz havaya çıkın. Doğanın huzuru hem bebeğe hem de sizin ruh sağlığınıza çok iyi gelecektir.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'Karanlığa alışmak 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin, sakin ve karanlık bir ortamda daha hızlı salgılanır.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', '“Bu ne?” yağmuru ☝️', 'Her şeyi parmağıyla gösterip adını mı soruyor? Sizden dünyadaki şeyleri adlandırmanızı istiyor. Bu, iletişimde büyük bir sıçrama! Gösterdiği her nesnenin adını sabırla tekrarlayın.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'Alkışlamanın sevinci 👏', 'Bir şeyi başardığında kendi kendine alkışlayıp gururlanıyor mu? Onaylanmak istiyor! Siz de bu küçük başarısını büyük bir sevinçle alkışlayarak onu motive edin.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'Sorunuz mu var? 🤖', '2.5 yaşından sonra çocuğunuzun boy ve kilo grafiği sizi endişelendiriyor mu? İnternette korkutucu yazılar okumak yerine Anacan AI''dan doğru ve bilimsel temelli bilgi alın.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'Babanın tuhaf sesleri 🤡', 'Sizin yaptıklarınız işe yaramadığında babanın çıkardığı tuhaf sesler durumu kurtarır. Akşam krizlerinde pası hemen ona atın ve kenardan gülümseyin.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'Gecenin melodisi 🛀', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo ve arka planda çalan hafif, huzurlu bir melodi onun sinir sistemini tamamen sakinleştirecektir.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'Anne yorulduğunda 🛑', 'Siz demirden değilsiniz. Bugün yemek pişirecek gücünüz yoksa makarna haşlayın veya dışarıdan sipariş verin. Mükemmel anne olmak, her şeyi tek başına yapmak demek değildir.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'Kabızlık sinyali 💩', 'Çok koşuyor ama su içmeyi unutuyor mu? Lazımlıktaki dışkısını takip edin. Menüsüne mutlaka lifli yulaf ve kuru erik ekleyin.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'Yatakta bitmeyen gösteri 🛌', 'Uyumak yerine yatakta zıplayıp koşturuyor mu? Uyku zamanlayıcısını başlatın, sınırları sevgiyle koruyun. Beyaz Sesler arasındaki orman uğultusuyla odasını sakin bir uyku alanına dönüştürün.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'Kalsiyum kalkanı 🦴', 'Süt içmiyor mu? Kemikler için kalsiyum şarttır. Beslenme takip aracıyla bugün tükettiği peynir, yoğurt veya brokoli miktarını hesaplayıp eksiklerini tamamlayın.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'Yastık kalesi 🏰', 'Bu akşam odayı oyun alanına dönüştürün. Koltuk minderlerinden küçük bir kale yapıp içine girin. Biraz dağınıklık olacak ama bu neşeli kahkahalara kesinlikle değecek.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'Kendi yeme ısrarı 🥄', 'Kaşığı alıp her yeri batırıyor mu? Beslenme zamanlayıcısını başlatın. Etrafa saçılan yemeklere değil, kazandığı bağımsızlığa ve öz güvene odaklanıp gurur duyun.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'Sabah huysuzluğu ☁️', 'Gözünü açar açmaz her şeye ağlıyor ve hiçbir şeyden memnun olmuyor mu? Belki de tam bir büyüme atağının ortasındadır. Ona bol bol sarılıp güven vererek günü kurtarın.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'Babanın gece nöbeti 👨‍🍼', 'Gündüzün yorgunluğu size yeter. Akşam bebeği uykuya hazırlama ve pijamalarını giydirme görevini babaya bırakıp sadece uzaktan izleyin.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'Kelimeleri tekrar etme 🗣️', 'Sizin ağzınızdan çıkan her yeni kelimeyi hemen papağan gibi tekrarlıyor mu? Kelime dağarcığı zenginleşiyor. Yanında kullandığınız kelimelere ve gösterdiğiniz duygulara özellikle dikkat edin; o her şeyi taklit ediyor.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'Sebzeleri saklayın 🥦', 'Yine çorbadaki o küçük havuç parçasını görüp yemeyi reddetti mi? Beslenme planı yardımıyla sebzeleri püre hâline getirip köftenin içine saklamak, en eski ve faydalı anne hilelerinden biridir.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'Hava sürprizi ⛅', 'Gezintiye çıkarken havaya aldanıp üşümesine neden olmayın. Yalnızca pencereden bakarak karar vermeyin; Hava ve kıyafet yardımcısıyla dışarıdaki koşullara en uygun kombini belirleyip evden çıkın.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'Gece fırtınası 😭', 'Gecenin bir yarısı görünürde hiçbir sebep yokken ağlayarak uyandı mı? Gaz mı, yoksa yalnızca uyku terörü mü? Sakin bir şekilde kucağınıza alın ve sesinizi yükseltmeden huzur vererek yeniden uyutun.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'Ayrılık korkusu 🥺', 'Tuvalete gittiğinizde bile kapının arkasında sizi bekleyip ağlıyor. Ayrılık kaygısı bazen yoğunlaşabilir. Her seferinde ona seslenerek burada olduğunuzu ve hemen döneceğinizi söyleyin.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'Yeni arkadaş arayışı 👫', 'Parkta yaşıtlarıyla koşmaya ve onlara yaklaşmaya mı çalışıyor? Sosyalleşme resmen başladı! Güvenliğini uzaktan gözeterek bu ilk girişimleri gururla izleyin.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'Pijama güreşi 👕', 'Akşamları giyinmek büyük bir savaşa mı dönüşüyor? Seçimi ona bırakın: Kırmızı pijamayı mı istersin, yoksa maviyi mi? Bu küçük hile, kararı kendisinin verdiğini hissettirecek.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'Sakinlik saati ☕', 'Gündüz uykusu uyumuyorsa en az 1 saatlik bir Sakinlik saati (quiet time) belirleyin. O kendi yatağında kitapları karıştırsın, siz de çayınızı içip zihninizi dinlendirin.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'Resimlere anlam yüklüyor 📖', 'Kitaptaki hayvanları veya çocukları gördüğünde onlara dokunup “Bu ne yapıyor?” diye soruyor. Görsel algısı hayranlık uyandırıcı. Onunla karakterler hakkında ayrıntılı hikâyeler anlatın.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'Anneye özel zaman 🥑', 'Günlük koşuşturmada öğle yemeğinizi ayaküstü geçiştirmeyin. Sağlıklı tariflerden enerji veren bir atıştırmalık seçin ve en az 10 dakika kanepede uzanarak kendi beslenmenizi ön planda tutun.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'Fısıltılı sohbetler 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlayan en iyi yöntemlerden biridir.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'Demir ve güç 🥩', 'Rengi soluk mu veya çabuk mu yoruluyor? Etin yanında limonlu veya domatesli salata vererek demir emilimini artırın.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'Listelerin gücü 🛒', 'Markete gittiğinizde mutlaka bir şeyleri unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya kaydedin, eşiniz de işten dönerken eksiksiz şekilde alsın.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'Duygularınızı yazın 📝', 'Kimse sizi anlamıyor mu? Yorgunluğunuzu görmüyor mu? Duygu günlüğü en iyi sırdaştır. Tüm stresinizi, acınızı ve yalnızlığınızı oraya yazın; içinizin ne kadar hızlı rahatladığını göreceksiniz.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'Benim 🧸', 'Eve gelen misafir çocuğuna oyuncağını vermiyor mu? Bu bencillik değil, kişisel sınırlarını korumaktır. Paylaşmayı zorlayarak değil, örnek olarak öğretin.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'Serbest oyun 🧸', 'Her dakika onu eğlendirmek veya onun için oyunlar bulmak zorunda değilsiniz. Sıkılmak, çocuklar için yaratıcılığın başlangıcıdır. Bırakın odada kendi başına bir şeyler keşfetsin.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'Kirlenmeye tam izin 🏖️', 'Çamurla veya suyla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen bu etkinlikler için kolay temizlenen malzemeleri Önerilen Ürünler bölümünde bulabilirsiniz.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'Sesleri filtreleyin 🤫', 'Uykuya daldığı anlarda hassasiyeti artar. Pencereden gelen sesleri bastırmak için odada hafif bir beyaz gürültü (white noise) cihazı çalıştırın veya doğa sesleri açın.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'Aşağı bakın, ne keşfediyor? 👣', 'Artık çıplak ayakla yürümekten, halıya veya odadaki taşlara dokunmaktan keyif alıyor. Ayak tabanındaki sinirlerin uyarılması, dengesi ve motor gelişimi açısından çok önemlidir.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'Sadece sarılın 🫂', 'Hiçbir oyuna, kitaba veya masala gerek yok. Bu akşam onu sadece göğsünüze bastırın, kokusunu içinize çekin ve karanlıkta ona ne kadar değerli olduğunu fısıldayın.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'Deneyim paylaşımı 💬', 'Çocuğunuzun her şeye inat etmesi sizi korkuttu mu? İnternette korkutucu yazılar aramayın. Anacan Topluluğu''ndaki deneyimli annelerin gerçek yaşam tecrübelerinden yararlanın.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'Hedefli koşular 🐢', 'Artık yürümekle yetinmiyor; hızla koşup sizden saklanıyor. Odadaki tehlikeli engelleri kaldırın ve bu kovalamaca oyununa siz de büyük bir enerjiyle katılın.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'Babanın hikâyesi 📖', 'Bu akşam sesinizi dinlendirin. Bırakın çocuğunuzun en sevdiği kitapları farklı ses tonlarıyla, komik bir şekilde okuma görevini baba üstlensin.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'Kararlı “Hayır”lar başlıyor 🛑', 'Biri onu öpmek istediğinde uzaklaşıp kararlı bir şekilde “Hayır” mı diyor? Bedensel sınırlarına saygı gösterin. İzinsiz dokunuşlara itiraz edebilmesi, gelecekteki özgüveni için çok önemlidir.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'Karanlıktaki canavar 🌌', 'Işıkları kapattığınızda gölgelerden korkuyor mu? Hayal gücü geliştikçe korkular da gerçekmiş gibi hissedilir. Beyaz Sesler''den anne karnı sesini açarak ona ihtiyaç duyduğu o tanıdık güven duygusunu verin.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'Ani gözyaşları 😭', 'Gözünü açar açmaz sebepsiz yere ağlıyor mu? Duygusal olarak aşırı yüklenen bebeğinizi sakinliğinizi koruyarak nasıl rahatlatabileceğinizi Anacan AI uzmanımızla dertleşerek keşfedin.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'Temiz hava ihtiyacı 🌳', 'Evin dört duvarı hem onu hem de sizi bunaltıyor mu? Her şey altüst olmadan Anne Dostu Mekanlar''dan yakınınızdaki bir parkı bulun. Temiz hava ikinize de en iyi ilaçtır.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'Size yardım edeyim! 🧹', 'Siz yerleri silerken veya toz alırken elinizdekini almaya mı çalışıyor? Artık kendini büyümüş hissediyor. Ona küçük bir bez verip ekibinize katılmasına izin verin; böylece gelişimini destekleyin.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'Enerjisini atması şart 🌳', 'Dört duvar arasında kalmak onu hırçınlaştırıyor. Onu bebek arabasına koyun veya elinden tutup temiz havaya çıkın. Doğanın huzuru hem bebeğe hem de sizin ruh halinize çok iyi gelecektir.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'Karanlığa alışmak 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm gereksiz ışıkları, özellikle de tablet ekranlarını kapatın. Melatonin yalnızca karanlık ortamda salgılanır.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'Uykusuzlukla barışın 😭', 'Gecenin bir yarısı uyandı ve uyumak istemiyor. Ona kızmayın. Nedenini (ağrı, gaz, korku) belirleyin ve sabırla sarılarak yeniden uykuya dalmasını bekleyin.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'İnatçı lekeler 👗', 'Kıyafetlerin sürekli lekelenmesi sizi yoruyor mu? Buna kızmayın. O, yiyecekleri keşfediyor. Silikon önlükler kullanın ve bu renkli, dağınık anların tadını çıkarın.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'Aynadaki arkadaşı 👀', 'Onu aynanın karşısına götürün. Kendi yansımasına nasıl hayranlıkla baktığını ve farklı mimikler yaptığını izleyin. Bu, öz farkındalığının gelişmesi için harika bir etkinliktir.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'Müzikle uykuya geçiş 🛀', 'Akşam rutini zorlaştı mı? Ilık bir banyo sırasında arka planda sakinleştirici müzik açın. Suyun ve melodinin uyumu en inatçı çocuğu bile yumuşatır.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'Diş fırçalama savaşı 🦷', 'Fırçayı ağzına yaklaştırmanıza izin vermiyor mu? Bunu bir zorunluluk olmaktan çıkarıp oyuna dönüştürün. Önce sizin dişlerinizi fırçalamasına izin verin, sonra sıra sizde olsun.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'Yemek inadı 🥣', 'İki kaşık yedikten sonra doyduğunu söyleyip kaçıyor mu? Onu zorlamayın. Yiyeceklerle sağlıklı bir ilişki kurması, zorla yedirmekten daha önemlidir. Öğün sayısını artırın, porsiyonları küçültün.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'Hormon fırtınası 🩸', 'Aniden tatlı yeme isteği ve sinirlilik mi başladı? Regl Takipçisi''ne bakın. Belki de PMS''dir. Kendinizi suçlamayın; Sağlıklı Tarifler''den magnezyum ve hurma içeren bir atıştırmalıkla vücudunuzu destekleyin.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'Sebepsiz sabah krizleri 🛑', 'Gözünü açar açmaz her şeye bağırıp ağlıyor mu? Duygusal olarak aşırı yüklenen bebeğinizi sakinliğinizi koruyarak nasıl rahatlatabileceğinizi hemen Anacan AI uzmanımızla dertleşerek öğrenin.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'Masalın sonunu o söylesin 📖', 'Bu akşam masal okurken cümleleri yarım bırakın, bırakın o tamamlasın! Dil gelişimini harika bir şekilde destekleyen bu diyalog yöntemlerini Anacan AI''a sorun.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'Kirlenmesine tam izin 🏖️', 'Çamurla veya suyla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen bu etkinlikler için kolay temizlenen malzemeleri Önerilen Ürünler''de bulabilirsiniz.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'Uyku düzeni analizi ⏱️', 'Akşamları uykuya dalması 1 saat mi sürüyor? Uyku zamanlayıcısının grafiğine göz atın. Belki de gündüz uykusunu iyice kısaltmanın ve gece uykusunu daha erkene çekmenin zamanı çoktan gelmiştir.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'Birlikte temizlik 🧹', 'Evi toplamanız mı gerekiyor? Siz odayı süpürürken onun da bir bezle silerek size yardım etmesine izin verin. Temizliği birlikte nasıl eğlenceli bir oyuna dönüştürebileceğinizi Bloglardan okuyun.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'Gece yarısı çığlığı 🤖', 'Gece yarısı çığlık atarak uyanıyor ve sizi tanımıyor mu? Bu bir gece terörü olabilir. Böyle bir durumda ona nasıl doğru yaklaşacağınızı ve neden uyandırmamanız gerektiğini hemen Anacan AI''a sorun.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', '“Neden?”ler bitmiyor 🤔', 'Dünyayı anlamak ve her şeyi mantıklı bir yere oturtmak istiyor. Bitmek bilmeyen sorularına sıkılmadan ve sabırla nasıl yanıt verebileceğinizi Anacan AI''dan öğrenin. Sabrınız, onun geleceğidir.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'Kahveyi sıcak içme hakkı ☕', 'Oda dağınık mı? Bırakın öyle kalsın. Kendinize 10 dakika ayırın ve o kahveyi nihayet sıcak için. Kusursuz olmak zorunda değilsiniz.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'Gizlice yenen çikolata 🍫', 'Mutfağa geçip ondan gizlice ayaküstü tatlı bir şeyler mi atıştırdınız? Kendinizi suçlamayın. Günün gürültüsüne dayanabilmek için bir annenin kan şekerini yükseltmeye kesinlikle hakkı var.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'Sahne babanın 🎭', 'Sizin “Yemeğini bitir” sözünüz artık işe yaramıyor. Topu babaya atın. O, kaşığı uçan bir uçağa dönüştürdüğünde inatçılık nedense mucizevi bir şekilde ortadan kalkar. Dinlenin ve izleyin.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'Yanlış renk kaşık krizi 🥄', 'Yemeği yeşil değil de sarı kaşıkla verdiğiniz için kıyamet mi koptu? Derin bir nefes alın. Mantık aramayın; o sadece dünyayı kontrol edip edemediğini test ediyor. Kaşığı değiştirin ve gülümseyin.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'Size yardım edeyim 🧽', 'Siz toz alırken bezi elinizden mi çekiyor? Kendini büyük hissetmek istiyor. Ona küçük, nemli bir bez verin. Temizlemekten çok etrafı batıracak ama kendini önemli hissedecek.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'Evin akustiği 🤫', 'Öğle uykusuna zar zor daldı. Şimdi evdeki en ufak bir tıkırtı bile sizi çıldırtabilir. Hemen Ses ölçeri etkinleştirin, pencereleri kapatın ve bu mutlak sessizliğin tadını çıkarın.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'Ayakkabı giyme savaşı 👟', 'Sağ ayakkabısını sol ayağına giydi ve kesinlikle çıkarmak istemiyor mu? Bırakın öyle kalsın. Estetik ya da doğruluk şu anda onun özgürlük hissinden daha önemli değil.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'Karanlıkla barışmak 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanın ve gün içinde yaşananları çok alçak sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlayan en doğal yöntemlerden biridir.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'Küçük ressam 🎨', 'Kalemle duvara ya da kâğıda daireler mi çiziyor? Bu, kaba motor gelişiminde büyük bir sıçramadır.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'Anaokulu arayışı başlıyor mu? 🏫', '3 yaşına yaklaşırken anaokulu düşüncesi aklınızda dönüp duruyor mu? Tek başınıza düşünmekten yorulduysanız Anacan Topluluğuna katılarak diğer annelerin deneyim ve tavsiyelerini sorun.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'Hayali çay saati ☕', 'Boş fincanı size uzatıp “Çay iç” mi diyor? Sembolik oyunlar, gelişimin başyapıtıdır. O fincandaki oda sıcaklığındaki hayali çayı büyük bir keyifle için.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'Giysiler leke içinde 🎨', 'Pijaması yemek, üstü başı boya lekesi içinde mi? Çocuklar tertemiz büyümemeli; keşfederken kirlenmelidir. Silikon önlükler kullanın, gerisini çamaşır makinesine bırakın.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15 dakikalık kaçamak 🛀', 'Tuvalete girip kapıyı kapattınız ve sadece telefonunuza mı bakıyorsunuz? Evet, bu annelerin en meşhur kaçış ve dinlenme yöntemidir. Kimseye hesap vermeden o sessizliğin tadını çıkarın.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', '“Beni öpme!” kararlılığı 🛑', 'Akrabalardan biri onu öpmek istediğinde yüzünü çevirip itiyor mu? Beden sınırlarına müdahale etmeyin! İzinsiz dokunuşlara karşı çıkması, sağlıklı bir gelecek için gereklidir.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'Gece terörü gerçeği 😭', 'Gecenin bir yarısı gözleri kapalı şekilde ağlayarak uyanıyor ve kimseyi duymuyor mu? Bu, gece terörüdür. Onu sarsmayın, uyandırmaya çalışmayın. Sadece yanında olun ve ona güven verin.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'Doğa detoksu şart 🌳', 'Evdeki karmaşa bugün dayanılmaz bir hâl mi aldı? Hemen Hava Durumu ve Kıyafet aracına göz atıp uygun şekilde hazırlanın ve en yakın parka gidin. Temiz hava, çocuğun en iyi sakinleştiricisidir.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'Kelimelerin yeni versiyonu 🗣️', 'Su yerine “çu”, büyük yerine “böcük” mü diyor? O kadar sevimli geliyor ki gülmemek zor. Ancak beyninin doğru hâlini kodlaması için siz her seferinde kelimenin doğrusunu nazikçe tekrarlayın.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'Masalın sonunu o yazsın 🪄', 'Klasik kitaplardan ikiniz de yoruldunuz. Bu kez Akıllı Masallar''da hikâyenin sonunu çocuğunuzun seçmesine izin verin. “Sence o kahramana kim yardım etti?” diye sorarak hayal gücünü harekete geçirin.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'Enerjiniz tükendiğinde 🔋', 'Bugün hiçbir şeye gücünüz yok mu? Sağlıklı tariflerden 5 dakikada hazırlanan, blenderdan geçirilmiş, demir ve vitamin deposu bir smoothie hazırlayıp ayaküstü için. Kendinize iyi bakın.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'Market listesi hayat kurtarır 🛒', 'Hafızanıza güvenip markete gittiniz ve bebek bezini unutarak mı döndünüz? Böyle şeyler olur. Tüm ihtiyaçlarınızı Alışveriş Listesi''ne yazmayı alışkanlık hâline getirin; bırakın uygulama sizin yerinize hatırlasın.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'Sürpriz çift saati 🥂', 'Çocuğunuz beklenmedik şekilde erkenden uyudu! Bu nadir anı ev temizliğine harcamayın. Eşinizle karşılıklı oturun, televizyonu kapatın ve sadece birbirinize gününüzün nasıl geçtiğini sorun.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'Yapboz mühendisliği 🧩', 'Şekilleri uygun deliklere yerleştirmekte ısrarcı mı? Hata yapsa veya sinirlense bile hemen yardım etmeyin. Problem çözme becerisini tam da bu deneme yanılmalarla öğrenir.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'Babanın park keşfi 👨‍👧', 'Annelik 24/7 süren bir nöbet değildir! Bugünkü açık hava gezisini babaya devredin. Bırakın birlikte çamura bulansınlar; siz de kanepeye uzanıp sessizliğin tadını çıkarın.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'Boy ve kilo sıçraması 📏', 'Pantolonların paçaları yine mi kısaldı? O, her gün gözünüzün önünde büyüyor! Güncel ölçülerini Gelişim Takipçisi''ne girin ve uykusuz gecelerinizin meyvesi olan gelişim eğrisine gururla bakın.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'Klasik müzik mucizesi 🎶', 'Akşamüstü sebepsiz bir huzursuzluk mu başladı? Televizyonu kapatın, ışıkları azaltın ve odada çok hafif bir klasik müzik açın. Suyun ve müziğin uyumu ortamın havasını değiştirecek.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'Çorbadaki gizli ajanlar 🥦', 'Yeşil olan her şeyi boykot mu ediyor? Endişelenmeyin. Beslenme Planı''ndan yararlanarak sebzeleri püre hâline getirip köftelerin veya sosların içine gizlemek, annelerin en eski ve faydalı yöntemlerinden biridir.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'Uydurma şarkılar 🎤', 'Oyuncaklarını dizerken kendi kendine hiçbir dilde bulunmayan kelimelerle şarkı mı söylüyor? Kelime dağarcığı ve ritim duygusu aynı anda gelişiyor. Bu yeni müzik evresini mutlaka Gelişim Takipçisi''ne ekleyin.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'İnatçı pijama 👕', 'Giyinmek büyük bir savaşa mı dönüştü? Seçimi ona bırakın: “Kırmızı pijamayı mı istersin, yoksa maviyi mi?” Bu küçük yöntem, kararın kendisine ait olduğunu hissettirecek ve mücadeleyi sona erdirecektir.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'Beslenme sinyalleri 🥣', 'İki kaşık yiyip doyduğunu söylüyor ve sandalyeden kaçıyor mu? Onu zorlamayın. Yiyeceklerle sağlıklı bir ilişki kurması, tabağını mutlaka bitirmesinden çok daha önemlidir. Acıktığında kendisi isteyecektir.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'Resimli hikâyeler 📖', 'Kitaptaki hayvanları veya çocukları gördüğünde onlara dokunup “Bu ne yapıyor?” diye soruyor. Görsel algısı hayranlık uyandırıyor. Onunla birlikte karakterler hakkında detaylı ve eğlenceli hikâyeler uydurun.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'Uyku Düzeni Değişiyor mu? 😭', 'Gecenin bir yarısı uyanıyor ve uyumak istemiyor. Ona kızmayın. Nedenini anlamaya çalışın; yanında olduğunuzu hissettirerek onu okşayın ve yeniden uykuya dalmasını bekleyin.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'Hava Sürprizi ⛅', 'Gezmeye çıkarken havaya aldanıp üşümesine neden olmayın. Yalnızca pencereden bakarak karar vermeyin; Hava ve giyim yardımcısıyla dışarıdaki rüzgâra en uygun kombini belirleyip evden gönül rahatlığıyla çıkın.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'Serbest oyunun faydası 🧸', 'Onu her dakika eğlendirmek veya ona oyunlar bulmak zorunda değilsiniz. Sıkılmak, çocuklar için yaratıcılığın ilk basamağıdır. Bırakın odada kendi başına bir şeyler keşfetsin.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'Market listesinde unutulanlar 🛒', 'Markete gittiğinizde mutlaka en önemli şeyi unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya kaydedin, eşiniz de işten dönerken eksiksiz bir şekilde alsın.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'Beden diliyle iletişim 🗣️', '“Gidelim mi?” dediğinizde kollarını kaldırıyor veya istemediği bir şey olduğunda başını kararlı bir şekilde sallıyor. Anlama becerisi inanılmaz ölçüde gelişti! Ona bol bol onaylayıcı cümlelerle karşılık verin.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'Müzikle Uykuya Geçiş 🎶', 'Akşamüstü kopan sebepsiz fırtınaları hafif klasik müzikle dindirmeyi deneyin. Bu basit ama etkili yöntem çoğu zaman evde mucizeler yaratır ve odaya huzur getirir.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'Ev işlerini kim yapacak? 🌪️', 'İşler birikiyor mu? Bırakın biriksin. Bugün ev işlerini üstlenmesini eşinizden isteyin. Siz dinlenin; bu evin en önemli ve enerjiye en çok ihtiyaç duyan kişisi sizsiniz.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'Ekip desteği 🥂', 'Zor bir günü geride bıraktınız. Çocuk uyuduktan sonra eşinizle birer çay doldurun ve “Biz gerçekten bu işin üstesinden harika geliyoruz.” diyerek birbirinizi motive edin.'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'Resimlere anlam yüklüyor 📖', 'Kitaptaki karakterleri gördüğünde onlara dokunup “Bu ne yapıyor?” diye soruyor. Görsel algısı hayranlık uyandırıyor. Birlikte okuduğunuz kitaba yeni ve tamamen hayal ürünü bir son yazın.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'Temizlik sendromu 🌪️', 'Evi silip süpürdünüz ama 10 dakika sonra her yer yeniden patlama bölgesine mi döndü? Bugün dağınıklığa teslim olun. Kanepeye oturun ve kahveniz bitene kadar yerinizden kalkmayın.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'Babanın diplomatik çözümü 👨‍👧', '“Yemeğini bitir.” cümleniz artık işe yaramıyor mu? Topu babaya atın. O, kaşığı uçan bir uzay gemisine dönüştürdüğünde inatçılık bir şekilde mucizevi biçimde ortadan kaybolur. Siz dinlenin ve sahneyi izleyin.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'Sabahın avukatı iş başında 💼', '“Bu gömleği değil, diğerini giyeceğim!” Artık odada bir çocuk değil, sizinle profesyonelce müzakere eden küçük bir avukat var. Tartışmayın; ona yalnızca 2 seçenek sunarak kararı kendisinin verdiğini hissettirin.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'Lazımlık zaferi 🚽', 'Tuvalet ihtiyacını fark edip kendi kendine lazımlığa mı koşuyor? Bu büyük bir zafer!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'Masalı o uydursun 📖', 'Bu akşam kitabı bir kenara bırakın. Hikâyeyi o anlatsın! Bu harika hayal gücü gelişimini destekleyen diyalog yöntemlerini Anacan AI''a sorun.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'Ayrılık kaygısı 🥺', 'Odadan bir saniyeliğine çıktığınızda bile arkanızdan ağlıyor. Ayrılık kaygısı zaman zaman yeniden ortaya çıkabilir. Her seferinde ona seslenerek burada olduğunuzu, “Mutfaktayım, geliyorum” diyerek uzaktan da olsa güvende olduğunu hissettirin.'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'Mükemmellik baskısı 🛑', 'Diğer çocuklar artık renkleri sayıyor ama sizin çocuğunuz bunu yapmak istemiyor mu? Karşılaştırmayı hemen bırakın! Her çocuğun gelişim süreci farklıdır. Çocuğunuz kendi hızında ilerliyor ve bu tamamen normal.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'Babanın gizli taktiği 👨‍🍼', 'Gün boyu yorulmanız zaten yeter. Akşam çocuğu uykuya hazırlama ve dişlerini fırçalatma sürecini babanın eğlenceli oyunlarına bırakın; siz de bir köşede sessizce çayınızı için.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'Çocuk sağlığıyla ilgili şüpheler 🤖', '32 aylık çocuğunuzun boy ve kilo grafiği sizi birden endişelendirdi mi? İnternet forumlarında korkutucu hastalıklar aramayın; doğru ve bilimsel gerçekleri Anacan AI''dan öğrenin.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'Doğal uyku ortamı 🤫', 'Uykuya daldığı ilk yarım saat, beynin en hassas olduğu zamandır. Pencereden gelen sesleri bastırmak için odada hafif bir beyaz gürültü cihazını (örneğin yağmur sesi) açın.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'Sana anlatayım! ☝️', 'Her şeyi parmağıyla gösterip art arda sorular soruyor. Sizden dünyadaki şeylerin adını söylemenizi istiyor. Bu, iletişim becerilerinde büyük bir sıçrama! Yorulsanız bile o nesnelerin adlarını sabırla tekrarlayın.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'Sadece sarılın 🫂', 'Hiçbir oyuna, kitaba veya masala gerek yok. Bu akşam onu sadece göğsünüze bastırın, o güzel kokusunu içinize çekin ve karanlıkta kulağına ne kadar değerli olduğunu fısıldayın.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'Birlikte temizlik 🧹', 'Evi toplamanız mı gerekiyor? Siz odayı süpürürken onun da bir bezle silerek size yardım etmesine izin verin. Temizliği ekip çalışmasına ve eğlenceye dönüştürmenin yollarını Bloglardan okuyun.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'Çok yoruldum 🔋', 'Herkes sizden enerji bekliyor ama piliniz tükendi. Bugün hiçbir şey pişirmeyin, sipariş verin. Mükemmel bir anne olmak, her şeyi tek başınıza yapmak zorunda olduğunuz anlamına gelmez. Kendinize izin verin.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'Daireden şekle 🎨', 'Kalemle duvara veya kâğıda daireler mi çiziyor? Bu yaramazlık aslında motor becerilerinde büyük bir sıçrama.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'Suyun uyumu 🛀', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo sırasında arka planda sakinleştirici doğa sesleri açın. Suyun uyumu, en inatçı çocuğu bile uykuya hazırlayacaktır.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'Markette öfke nöbeti 🛒', 'Kasanın önünde şekerleme için bağırıyor mu? Çevrenizdekilerin onu yaramaz bir çocuk gibi gören bakışlarını kesinlikle önemsemeyin. Sakin bir şekilde göz teması kurup kuralı açıklayın ve kararlılığınızı bozmayın.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'Düzeni mi kayıyor? ⏱️', 'Akşam uykuya dalması 1 saatten uzun mu sürüyor? Uyku zamanlayıcısının grafiğine bakın. Belki de gündüz uykusunu iyice kısaltmanın ve gece uykusunu daha erkene almanın zamanı çoktan gelmiştir.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'Hayvan taklitleri 🐶', 'Yalnızca ses çıkarmıyor, aynı zamanda köpek gibi emekliyor ve kedi gibi sürtünüyor mu? Beden dili ile hayal gücü birleşiyor. Siz de onunla birlikte halının üzerinde bu oyuna büyük bir enerjiyle katılın.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'Öğle uykusu krizi 🥱', 'Yatağa gitmek istemiyor ve ağlıyor mu? 3 yaşına yaklaşırken bazı çocuklar gündüz uykusunu bırakmaya başlar. Mücadele etmek yerine “Sakinlik saati” ilan edin ve yatağında oyuncaklarıyla sessizce oynamasını önerin.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'Uyumak istemiyor ve karanlıktan korkuyor mu?', 'Odayı tamamen karartın ve ellerinizle duvarda kuş, köpek gölgeleri oluşturun. Korkuyu eğlenceye dönüştürerek karanlıkla arkadaş olmasına yardımcı olun.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'Yeşil renge itiraz 🥦', 'Yeşillikleri tabağından atıyor mu? Sofrayı savaş alanına çevirmeyin. Sağlıklı tariflerdeki sebzelerin gizlendiği ev yapımı kekleri keşfederek vitamin ihtiyacını fark ettirmeden karşılayın.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'Fısıltının büyüsü 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlayan en doğal ve sakinleştirici yöntemlerden biridir.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'Brokoli dedektifi 🥦', 'Tabağındaki yeşil sebzeleri keşfedip kenara mı itiyor? Kamuflaj sanatına başvurun. Sağlıklı tarifler bölümünde sebzeleri püre hâline getirip lezzetli köftelerin içine gizleyebileceğiniz kurnaz tarifler keşfedin.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'Bestecinin ilk konseri 🎤', 'Oyuncaklarını dizerken hiçbir sözlükte bulunmayan kelimelerle ama kendine özgü bir ritimle şarkı mı söylüyor? Bu zihinsel sıçramayı bölmeyin; Gelişim takipçisine onun ilk bestesi olarak kaydedin.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'Doğaya kaçış planı ⛅', 'Dört duvar hem onu hem de sizi gerginleştirdi. Hava durumu ve kıyafet aracını kontrol edin, hemen hazırlanıp parka kaçın. Oksijen, en şiddetli çocuk krizlerini bile hızla yatıştırır.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'Altın sessizlik 🤫', 'Evdeki kaos sonunda bitti ve o derin bir uykuya daldı. Ses ölçeri açın, odadaki sessizlik seviyesini (desibelini) görün ve 15 dakika boyunca hiçbir ekrana bakmadan bu altın sessizliğin içinde eriyin.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'Avangart moda 👗', 'Pantolonunu başına geçirip odada gururla mı dolaşıyor? Müdahale etmeyin. Bu komik denemeler, onun özgürlük ve bireysellik arayışının bir parçasıdır. Evet, uyumsuz görünüyor ama bu anların tadına doyulmaz.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'Markette hafıza kaybı 🛒', 'Hafızanıza güvenerek markete gittiniz ve en önemli şeyi unutarak mı döndünüz? Tüm ihtiyaçlarınızı uygulamadaki Alışveriş listesine yazmayı alışkanlık hâline getirin; bırakın dijital hafızanız sizi kurtarsın.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'Görünmez misafirler 👻', 'Kanepede boş bir noktaya bakıp bir şeyler anlatıyor, hatta görünmez arkadaşına çay mı dolduruyor? Hayali arkadaşlar dönemi zirvede! Artık kendi dünyasının senaristi. Bu gösteriyi gülümseyerek izleyin.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'Suyun hafızayı temizleyen gücü 🛀', 'Bütün gün koşturmaktan hem onun hem de sizin sinirleriniz gerildi. Ilık bir banyo yalnızca hijyen için değildir; suyun gerginliği azaltan ve günün olumsuz enerjisini yıkayıp götüren mistik gücünden yararlanmak içindir.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'Babanın mutfak sırası 👨‍🍳', 'Annelik, tek başına koşulan bir maraton değildir. Hafta sonu öğle yemeğini baba hazırlayıp yedirsin, siz de kanepeye uzanarak değerli bir molanın tadını çıkarın.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'Bir tek ben mi böyleyim? 💬', 'Çok yoruldunuz ve kimsenin sizi anlamadığını mı düşünüyorsunuz? Hemen Anacan Topluluğuna yazın. Orada aynı uykusuzluğu yaşayan binlerce annenin “Ben de sizin gibiyim” mesajları size güç verecek.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'Senaryoyu o yazsın 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masallarda bu kez hikâyenin sonunu çocuğunuza seçtirin. “Sence o kahramana kim yardım etti?” diye sorarak uyku öncesinde hayal gücünü harekete geçirin.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'Annenin besin deposu 🥗', 'Onu doyurmak için 3 farklı menü düşündünüz; peki siz ayaküstü bir şeyler mi atıştırdınız? Sağlıklı tariflerden 10 dakikada hazırlanan, vitamin deposu bir salata seçin ve kendinize değer verdiğinizi hissedin.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'Babanın mimik tiyatrosu 🤡', 'Sizin yaptıklarınız artık işe yaramadığında, babanın çıkardığı tuhaf sesler durumu hemen kurtarır. Akşam krizlerinde topu ona atın ve neşeli kahkahaları kenardan izleyin.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'Küçük temizlikçi 🧽', 'Siz toz alırken bezi elinizden mi çekiyor? Kendini büyük ve ekibin bir parçası gibi hissetmek istiyor. Ona nemli bir bez verin. Temizlemekten çok etrafı kirletecek ama gururu okşanacak.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'Annenin enerji barı 🥑', 'Günlük koşuşturma içinde öğle yemeğini ayaküstü geçiştirmeyin. Sağlıklı tarifler arasından enerji veren bir atıştırmalık seçin ve en az 10 dakika koltuğa uzanarak kendi beslenmenizi ön planda tutun.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'Yakalamaca maratonu 🏃‍♂️', 'Artık yürümekle yetinmiyor, siz onu çağırdığınızda hızla koşup saklanıyor. Odadaki tehlikeli engelleri kaldırın ve bu eğlenceli yakalamaca oyununa siz de katılın.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'Psikolojiyi keşfedin 📱', 'Çocuğunuzun her şeye hayır demesi sizi bıktırdı mı? Uygulamadaki psikoloji bloglarını okuyarak onun beyninde yaşanan bu gelişim fırtınasının altında yatan nedenleri anlayın.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'Karanlığın gücü 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin, yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'Sadece sarılın 🫂', 'Hiçbir oyuna, kitaba veya masala gerek yok. Bu akşam sadece onu göğsünüze bastırın, o güzel kokusunu içinize çekin ve karanlıkta ona ne kadar değerli olduğunu fısıldayın.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', '“Bu ne?” makinesi ☝️', 'Her şeyi parmağıyla gösterip adını mı soruyor? Sizden dünyayı adlandırmanızı istiyor. Bu, iletişimde büyük bir sıçrama! Yorulsanız da o nesnelerin adlarını sabırla tekrarlayın.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'Siz de insansınız 🛑', 'Bugün hiçbir şey planladığınız gibi gitmedi mi? Kendinizi suçlamayın. Siz gerçek bir annesiniz, sosyal medyadaki filtrelenmiş bir illüzyon değilsiniz. Çocuğunuzun sadece size ihtiyacı var.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'Yönetmen iş başında 🎭', 'Resimli kitaptaki karakterlere bakarak tamamen kendi uydurduğu olayları mı anlatıyor? Hayal gücü gelişimi zirvede! Bu sıra dışı hikâyelerini bölmeden, gururla dinleyin.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'Sıcak çay ve huzur 🍵', 'Ev işlerini unutun, her şey bekleyebilir. Sağlıklı tariflerden melisa çayı demleyin ve yalnızca kendinizle kalmanın tadını çıkarın.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'Park terapisi 🌳', 'Dört duvar arasında bunaldınız. Hava serin olsa bile onu sıkıca giydirip 20 dakikalığına parka çıkarın. Yaprakları ve taşları keşfetsin; temiz hava beynine oksijen taşıyacaktır.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'Tabakta sanat 🥦', 'Yemeğini yemiyor mu? Bazen sorun lezzette değil, görüntüdedir. Rengârenk sebzelerle komik yüzler hazırlayarak iştahını açmaya ve yemeği oyuna dönüştürmeye çalışın.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'Neşeli kahkahalar 🤡', 'Sizin çabalarınız işe yaramadığında babanın çıkardığı tuhaf sesler durumu kurtarıyor. Akşam krizlerinde topu hemen ona atın ve kenardan gülümseyin.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'Vahşi doğa evde 🐶', 'Yalnızca ses çıkarmıyor, aynı zamanda köpek gibi emekleyip kedi gibi sürtünüyor mu? Beden dili ve hayal gücü büyüleyici bir şekilde birleşiyor. Siz de onunla birlikte halının üzerinde bu oyuna katılın.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'Dağınıklık izni 🌪️', 'Her gün aynı oyuncakları kutuya toplamaktan yoruldunuz mu? Bugün toplamayın! Ev bir müze değil, içinde hayatın aktığı bir yerdir. Dağınıklığa değil, çocuğunuzun keşfetme sevincine odaklanın.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'Sıra babada 👨‍🍼', 'Gündüzün yorgunluğu size yeter. Akşam çocuğu uykuya hazırlama, dişlerini fırçalatma ve pijamalarını giydirme sürecini babaya bırakın; siz de bir köşede sessizce çayınızı için.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'Anne, bana bak! 👀', 'Siz telefonunuza veya başka bir işe bakarken gelip yüzünüzü kendisine doğru çeviriyor mu? Tüm dikkatinizi istiyor. Göz teması kurarak onu dinlediğinizi ve önemli olduğunu hissettirin.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'Cümleler masala dönüşüyor 🗣️', 'Artık kelimeleri birleştirip komik, hayal ürünü hikâyeler anlatıyor mu? Kelime dağarcığı hızla gelişiyor!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'Odanın akustiği 🤫', 'Uykuya daldığı anlarda seslere karşı hassasiyeti artar. Pencereden gelen sesleri etkisiz hâle getirmek için Ses ölçeri kontrol edin ve odada hafif bir beyaz gürültü (white noise) cihazı çalıştırın.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'Küçük mühendis 🤔', 'Bunu atarsam ne olur? Bu düğme ne işe yarar? Sürekli fiziksel deneyler yapıyor. O, öğreniyor! Evin güvenliğini onun göz hizasından bir kez daha gözden geçirin.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'Annelerin gizli grubu 💬', 'Zor bir karar mı vermeniz gerekiyor? (Örneğin, kreş seçimi). Anacan Topluluğu''ndaki deneyimli annelerin önerileri, hiçbir kitapta yazmayan, denenmiş en gerçekçi çözüm yollarıdır.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'Pencereye güvenmeyin ⛅', 'Gezintiye çıkarken pencereden bakıp yanılmayın. Hava ve kıyafet asistanıyla dışarıdaki gerçek rüzgâr ve sıcaklığa en uygun kombini belirleyip evden rahatça çıkın.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'Market kurtarıcısı 🛒', 'Markete gittiğinizde en önemli ürünü mutlaka unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya kaydedin, eşiniz de işten dönerken eksiksiz şekilde alsın.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'Suyun terapisi 🛀', 'Bütün gün koşturmaktan hem çocuğunuz hem de siz tükendiniz. Ilık bir banyo sırasında arka planda sakinleştirici doğa sesleri açın. Suyun uyumu, en inatçı çocuğu bile uykuya hazırlayacaktır.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'Kararlı bir Hayır! 🛑', 'Biri onu öpmek istediğinde uzaklaşıp sert bir şekilde hayır mı diyor? Onun bedensel sınırlarına saygı gösterin. İzinsiz dokunuşlara itiraz edebilmesi, sağlıklı bir psikolojik gelişim için gereklidir.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'Babanın ses tonu 📖', 'Bu akşam ses tellerinizi dinlendirin. Bırakın, çocuğunuzun en sevdiği kitapları farklı ses tonlarıyla, doğaçlama ve komik bir şekilde okuma görevini baba üstlensin.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'Özel mülkiyet 🧸', 'Eve gelen misafir çocuğuna kendi oyuncağını vermiyor mu? Bu bencillik değil, kişisel sınırlarını korumaktır. Paylaşmayı zorlayarak değil, yalnızca örnek olarak öğretin.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'Uykusuzluk ilanı 🥱', 'Yatağa gitmek istemiyor ve direniyor mu? Bazı çocuklar bu dönemde gündüz uykusunu bırakır. Mücadele etmek yerine, Sakinlik Saati ilan edin ve yatağında oyuncaklarıyla sessizce oynamasını önerin.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'Gece terörünün şifresi 😭', 'Gecenin bir yarısı gözleri kapalı hâlde ağlayarak uyanıyor ve kimseyi duymuyor mu? Sesini Ağlama Analizi''ne dinletin; eğer bu bir uyku terörüyse onu uyandırmaya çalışmayın. Sadece yanında olun ve ona güven verin.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'Seçici yeme krizleri 🍝', 'Dün sevdiği yemeği bugün reddediyor mu? Sofrayı savaş alanına çevirmeyin. Beslenme Takibi aracıyla haftalık dengeyi kontrol edin, Sağlıklı Tarifler''de farklı ve eğlenceli sunumlar bulun.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'Yaralı ayıcığın doktoru 🩺', 'Oyuncağı düşünce onu okşayıp “Ağlama” mı diyor? İçinde harika bir empati duygusu gelişiyor! Kişiliğinin bu altın dönemini hemen Gelişim Takibi''ne kaydedin.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'Melatonine davet 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm gereksiz ışıkları ve mavi ışık yayan ekranları kapatın. Uyku hormonu (melatonin), karanlık ve teknolojiden uzak bir ortamda daha hızlı salgılanır.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'Kum havuzu diplomasisi 🧸', 'Parkta kovasını kimseye vermiyor mu? Bu bencillik değil, yalnızca kişisel mülkiyet duygusunu keşfetmesidir. Onu utandırmadan sırayla oynama sistemini önerin ve diplomatik krizi çözün.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'Göz teması şarttır 🥂', 'Çocuğunuz beklenmedik şekilde erkenden uyudu! Bu nadir anı ev temizliğine harcamayın. Eşinizle yüz yüze oturun, televizyonu kapatın ve yalnızca birbirinizin gözlerine bakarak gününüzün nasıl geçtiğini sorun.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'Canlı ses kayıt cihazı 🎙️', 'Ağzınızdan çıkan en beklenmedik sözü bile hemen papağan gibi tekrarlıyor mu? O sizin canlı aynanızdır. Yanında kullandığınız sözcüklere ve yansıttığınız duygulara iki kat dikkat edin; çünkü her şeyi kopyalıyor.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'Soğuk kahve gerçeği ☕', 'Kahveyi hazırlayıp 3 saat sonra buz gibi içmek anneliğin yazılı olmayan kuralıdır. Bugün bir değişiklik yapın! Onu oyuncaklarıyla kendi başına oynamaya bırakın ve kahvenizi 10 dakika içinde sıcakken için. Siz bunu hak ediyorsunuz.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'Annenin gizli fırtınası 🩸', 'Aniden yoruluyor, sebepsiz yere ağlamak mı istiyorsunuz? Regl Takibi''ni açın. Belki de PMS dönemindesiniz. Kendinizi suçlamayın; Sağlıklı Tarifler''den magnezyum içeren bir atıştırmalık hazırlayın ve bedeninizi dinleyin.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'Dijital çocuk doktoru 🤖', '33 aylık çocuğunuzun boy ve kilo grafiği sizi birden endişelendirdi mi? İnternet forumlarında korkutucu hastalıklar aramayın; doğru, hızlı ve bilimsel gerçekleri Anacan AI''dan öğrenin.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'Mozart etkisi 🎶', 'Akşamüstü sebepsiz bir agresiflik mi başladı? Televizyonu kapatın, ışıkları azaltın ve odada çok hafif bir klasik müzik çalın. Suyun ve müziğin uyumu ortamı sihirli bir şekilde değiştirecek.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'Uçuş denemeleri 🧗‍♂️', 'Kendisini kanepeden yastıkların üzerine mi atıyor? Yer çekimini ve cesaretini test ediyor. Yasaklamak yerine odada güvenli bir atlama alanı oluşturun, enerjisini atmasına izin verin.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'Gece feryadının şifresi 😭', 'Nedenini bulamadığınız ağlama krizleri insanı tüketir. Tahmin yürütmeyi bırakın; Ağlama Analizi aracıyla sesin ardındaki gizli mesajı (ağrı, yorgunluk) anlamaya çalışın ve onu sakinleştirin.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'Kamuflaj ustası 🥦', 'Çorbadaki sebzeleri mikroskopla arıyormuş gibi kenara mı ayırıyor? Sağlıklı Tarifler''de sebzeleri görünmez kılacak sos tariflerini bulun. Yaratıcılık, bir annenin en güçlü gizli silahıdır.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'Diş fırçası savaşı 🦷', 'Diş fırçasını ağzına yaklaştırmanıza izin vermiyor ve kendi başına yapmak mı istiyor? Bunu zorunluluk olmaktan çıkarıp oyuna dönüştürün. Önce sizin dişlerinizi fırçalamasına izin verin, ardından sıra sizde olsun.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'Çıplak ayaklar 👣', 'Çıplak ayakla yürümekten ve farklı yüzeylere dokunmaktan büyük keyif alır. Ayak tabanındaki sinirlerin uyarılması nörolojik gelişimi için çok değerlidir; çorapsız yürümesine izin verin.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'Dijital hafıza 🛒', 'Markete gittiğinizde mutlaka bir şeyleri unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya not edin, eşiniz de işten dönerken eksiksiz alsın.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'Sesli hayal gücü 🪄', 'Akıllı masallarda bu akşam ona özel bir macera oluşturun: Elektrikli süpürgeden korkmayan cesur tavşanın hikâyesi. Masalların yardımıyla korkuların üstesinden gelmek çok daha kolaydır.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'İncinmemiş ego 🛑', 'Ben kendim yapacağım! diyerek her türlü yardımı reddediyor. Ayakkabılarını ters giyse bile müdahale etmeyin. Yanlış giyilmiş bir ayakkabıdan çok, incinmemiş bir ego daha önemlidir.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'Şüphelere son 🤖', 'Çocuğunuzun davranışlarındaki ani değişiklikler sizi endişelendirdi mi? İnternet forumlarında korkutucu hastalıklar aramayın; Anacan AI''dan doğru, anında ve bilimsel temellere dayanan bilgiler edinin.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'Uyku bekçisi 🤫', 'Uykuya daldığı ilk yarım saat, beynin en aktif olduğu zamandır. Ses ölçer ile odadaki ses düzeyini ayarlayın. Bazen yalnızca hafif bir yağmur sesi bile onu derin bir uykuya götürebilir.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', '1000 güne sadece 5 gün! 🎈', 'Geri sayım bitmek üzere! Tam 1000 günlük büyük ve unutulmaz bir yolculuğu tamamlamak üzeresiniz. Gülümseyin, yıl dönümü hazırlıklarına ve eğlenceli konseptlere şimdiden başlayın!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'Sessiz kitap saati 🥱', 'Yatağa gitmek istemiyor ve direniyor mu? Bazı çocuklar bu dönemde gündüz uykusunu bırakır. Mücadele etmek yerine Sessizlik saati ilan edin ve yatakta yalnızca kitaplara göz atmasını önerin.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'Gurur sayfası 📝', 'Bu uzun, inişli çıkışlı yolculuktaki en büyük gücünüz ona duyduğunuz sevgidir. Duygu günlüğünü açın ve ona gelecekte okuyacağı, gurur dolu küçük bir mektup yazın.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'Küçük yardımcı 🧸', 'Ayakkabını getir dediğinizde gerçekten gidip getiriyor mu? Kelime dağarcığı ve anlama becerisi zirvede! Onu evdeki küçük işlere dâhil ederek öz güvenini artırın.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'Asıl takım sizsiniz 🌟', 'Attığı her güvenli adım, sizin ve eşinizin ortak emeğinin sonucudur.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'Dağınık ev, neşeli anne 🌪', 'Çamaşırlar dağ gibi birikmiş, bulaşık makinesi dolu mu? Bırakın, kalsın. Eşinizden bugün ev işlerini üstlenmesini isteyin. Siz dinlenin; bu evin temel direği sizsiniz.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'Anatomi dersi 👀', 'Omuzların nerede? diye sorduğunuzda parmağıyla dokunup gösteriyor mu? Zihinsel kavrayışı zirvede! Oyuna daha karmaşık vücut bölümleriyle devam ederek kelime dağarcığını zenginleştirin.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'Suyun gücü 🛀', 'Bütün gün koşturmaktan hem o hem de siz yoruldunuz. Ilık bir banyo sırasında arka planda sakinleştirici doğa sesleri açın. Suyun uyumu, en inatçı çocuğu bile uykuya hazırlayacaktır.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'Annenin tabağındaki lezzet 🥣', 'Kendi tabağını kenara itip sizin yediklerinize mi uzanıyor? Çocuklar ebeveynlerinin seçimlerine her zaman daha çok güvenir. Sağlıklı tarifler arasından ikinizin de aynı yemeği yiyebileceği seçenekleri tercih edin.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'Gezinti taktiği ⛅', 'Gezintiye çıkarken havaya aldanıp üşümesine neden olmayın. Yalnızca pencereden bakarak karar vermeyin; Hava ve giyim yardımcısı ile dışarıdaki rüzgâra en uygun kombini belirleyip evden gönül rahatlığıyla çıkın.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'Melatonin fabrikası 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'Nezaket kuralları 👋', 'Biri kapıdan çıkarken kendiliğinden el sallayıp vedalaşıyor! Sosyal zekâsı ve empati becerisi gelişiyor. Bu nazik davranışlarını bol bol teşvik edin.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'Birlikte temizlik 🧹', 'Evi toplamanız mı gerekiyor? Odayı süpürürken bırakın, o da bezle silerek size yardım etsin. Temizliği ekip çalışmasına ve eğlenceye dönüştürmenin yollarını Bloglardan okuyun.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'Düzeni mi kayıyor? ⏱️', 'Akşamları uykuya dalması çok mu uzun sürüyor? Uyku zamanlayıcısındaki programa göz atın. Belki de gündüz uykusunu iyice kısaltmanın ve akşam uykusunu erkene çekmenin zamanı çoktan gelmiştir.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', 'Ben büyüdüm! inadı 🛑', 'Her şeye karışmak istiyor ve işleri yavaşlatıyor mu? Bu komik bağımsızlık mücadelesinde ona küçük seçenekler sunun.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', '1000 günlük mucize! 👑', 'TEBRİKLER! Tam 1000 gündür bu fırtınalı, yorucu ama dünyanın en değerli yolunda ilerliyorsunuz! Bu özel zafer gününü hemen kutlayın ve Anacan Topluluğunda gururla paylaşın!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'Ekibin zafer dansı 🥂', '1000 günün yorgunluğunu, gözyaşını ve sevincini bu akşam eşinizle birlikte kutlayın. Masaya bir mum koyun ve sarsılmaz ekibinizin zaferini büyük bir sevinçle alkışlayın!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'Siz bunu başardınız! 📈', 'Çocuğunuz ne kadar uzun bir yol katetti! İlk günlerdeki o kırılgan korkunun yerini şimdi muazzam bir güven aldı. Bu 1000 günü büyük bir gururla tamamladınız! Siz gerçekten harikasınız!'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'Günlüğe not düşün 📝', 'Çocuğunuz uyuduktan sonra Duygu günlüğünü açın. Bugün sizi en çok ne yordu, ne güldürdü? Duygularınızı tamamen özgür bırakın ve içinizi dökün.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'Zaferden sonraki gerçeklik 🚀', 'Dünkü kutlamadan sonra bu sabah yine etrafa saçılmış oyuncaklara ve Ben istemiyorum!lara uyandık! Hayat devam ediyor. Derin bir nefes alın; siz bu kaosun en güzel yöneticisisiniz.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'Gündüz uykusu krizi 🥱', 'Yatağa gitmek istemiyor ve ağlıyor mu? 3 yaşına yaklaşırken bazı çocuklar gündüz uykusunu bırakmaya başlar. Mücadele etmek yerine Sakinlik saati ilan edin ve yatakta yalnızca kitaplara göz atmayı önerin.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'Yataktan kaçış planı 🛌', 'Beşiğinden tırmanarak çıkmaya mı çalışıyor? Güvenliği sağlamak için odayı yeniden gözden geçirin. Çocuk yatağına geçme zamanı yaklaşıyor.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', 'Nasıl? soruları başlıyor 🤔', 'Neden? sorularının yerini Bu nasıl çalışıyor? sorusu alıyor. Mekanizmaları anlamaya çalışıyor. Sabırlı olun ve ona kısa, mantıklı açıklamalar yapın.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'Anne için mola ☕', 'Çocuğunuz kendi kendine oynarken hemen ev işlerine koşmayın. Odadaki dağınıklık bir yere kaçmaz ama sizin enerjiniz tükenebilir. Oturun ve sıcak kahvenizi için.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'Hayali senaryolar 🧸', 'Oyuncak ayısına masal mı anlatıyor ya da boş bardaktan çay mı içiyor? Sembolik oyunlar, gelişimin başyapıtıdır. Ona müdahale etmeyin; bu küçük yönetmeni uzaktan izleyin.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'Sessizlik ihtiyacı 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamın desibel düzeyini kontrol edin ve yan odadaki televizyonun sesini buna göre ayarlayın.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'Parkta sosyalleşme 🌳', 'Diğer çocuklarla oynamak yerine onların yanında kendi oyununu mu oynuyor? Paralel oyun bu yaş için tamamen doğaldır. Hava durumuna uygun kıyafetleri seçip onu parka çıkarın.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'Hızlı çocuk doktoru 🤖', 'Tuvalet eğitiminde (potty training) gerileme mi yaşıyorsunuz? Kendinizi yıpratmayın, bu psikolojik süreci nasıl yönetebileceğinizi Anacan AI''a sorun.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', 'Benim! inadı 🛑', 'Her şeye sahip olmak mı istiyor? Paylaşma kavramı henüz tam olarak gelişmedi. Onu zorlamayın; bunun yerine Sırayla oynayalım kuralını yavaş yavaş uygulayın.'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'Büyülü gece atmosferi 🪄', 'Uykuya dalmakta zorlanıyor mu? Akıllı masallarda ona özel bir masal oluşturarak yeni alışkanlıkları hikâyeye dönüştürün.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'Görsel yemek krizi 🥦', 'Ekmeğin kenarını veya salatalık dilimini çirkin göründüğü için yemiyor mu? Yemek seçiciliği bazen ilginç biçimler alabilir. Beslenme planında sebzeleri püre hâline getirip gizlemenin en yaratıcı yollarını keşfedin.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'Sabah konseri başladı 🎤', 'Uyanır uyanmaz sesini en yüksek desibele çıkarıp bir şeyler mi söylüyor? Onun enerjisi sabah 7''de tamamen dolu. Gözlerinizi ovuşturun ve bu küçük pop yıldızının gösterisini gülümseyerek izleyin.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'Banyo baskını 🛀', 'Suyla oynamak, temizlikten çok banyoyu su parkına çevirmek içindir. Bırakın sular sıçrasın. Ilık su ve eğlence, gün boyunca biriken tüm inatçılığını alıp götürecektir.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', 'Bir tane daha tuzağı 📖', 'Yatağa gitmek istemiyor, bir masal daha diyerek süreyi uzatıyor. Klasik kitaplardan uzaklaşın. Akıllı masallarda onun uydurduğu karakterlerle kısa bir uyku hikâyesi oluşturup süreci tamamlayın.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'Gizli çikolata molası 🍫', 'Mutfak dolabının arkasına saklanıp ayaküstü tatlı bir şeyler atıştıran anne, sizi görüyoruz! Kendinizi suçlamayın. Gürültüye dayanabilmek için o glikoz yükselişine sonuna kadar hakkınız var.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'Evin küçük diktatörü 👑', 'Oraya değil, buraya otur!, Bunu sen değil, ben yapacağım! Evi o yönetmek istiyor. İradesini sertçe kırmadan, Sen buraya otur, ben de oraya diyerek dengeyi sağlayın.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'Babadan masaj seansı 💆‍♂️', 'Bugün uzun süre ayakta kaldınız, peşinden koşmaktan beliniz kopacak gibi. Çocuk uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin direğisiniz, direklerin de dinlenmesi gerekir.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'Müdahale etmeyin 🧦', 'Çorabının topuk kısmı ayağının üstünde ama kendi giydiği için dünyanın en gururlu insanı gibi dolaşıyor. Sakın müdahale etmeyin. Özgürlük hissi, doğru giyinmekten daha önemlidir.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'Toplulukta nefes almak 💬', 'Çok yoruldunuz ve kendinizi dünyanın en sabırsız annesi gibi mi hissediyorsunuz? Hemen Anacan Topluluğunu açın. Başka annelerin de aynı krizleri yaşadığını okumak en büyük psikolojik destektir.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'Bulutların bilmecesi ⛅', 'Dört duvar üstünüze mi geliyor? Hava durumuna uygun kıyafetleri seçip parka çıkın. Sadece oturun ve gökyüzündeki bulutların neye benzediğini bulmaya çalışın. Bu sakin oyun beyni hem dinlendirir hem de geliştirir.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'Evdeki kaos sonunda bitti.', 'Pencereden gelen sesleri engellemek için lofi müzik açıp ruhunuzu dinlendirin.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'İlk sevimli yalanlar? 🤥', 'Suyu ben dökmedim, ayıcığım döktü. Dikkat! Hayal gücü o kadar gelişti ki olayları kendi yararına göre kurgulayabiliyor. Onu yalan söylemekle suçlamayın; Ayıcığına söyle, bir daha dökmesin deyip gülümseyin.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'Sabah egzersizi 🤸‍♂️', 'Siz daha uyanmadınız ama o yatağın üzerinde zıplıyor. Dünyanın en gürültülü ama en sevimli alarmı! Güne onun bitmek bilmeyen enerjisiyle gülerek başlayın.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'Listesiz market sıkıntısı 🛒', 'Markete gidip en önemli şeyi almadan mı döndünüz? Annelik hafızası böyledir. Hafızanıza güvenmeyin; en küçük ihtiyacı bile hemen Alışveriş listesine yazmayı alışkanlık hâline getirin.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939'::uuid, 'Mum ışığında çay 🕯️', 'Çocuğunuz uyudu. Işıkları kapatın ve masanın üzerinde bir mum yakın. Bu romantizm için değil, yalnızca gün boyu yorulan sinirlerinizi ve gözlerinizi dinlendirmek için.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'Yapay zekâ, gerçek yardım 🤖', 'Çocuğunuzun her şeye karşı çıkmasının altında hangi psikolojik nedenler yatıyor? İnternette korkutucu yazılar aramayın. Anacan AI''dan 33 aylık çocukların yaşadığı krizler hakkında bilimsel ve kısa bir açıklama isteyin.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'Uyku düzeninde kayma ⏱️', 'Akşamları uykuya dalması 1 saatten uzun mu sürüyor? Uyku zamanlayıcısındaki grafiğe bakın. Belki de gündüz uykusunu iyice kısaltmanın ve gece yatış saatini erkene çekmenin zamanı çoktan gelmiştir.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'Saç tarama kıyameti 🪮', 'Saçını taramak veya saçına dokunmak dünyanın en büyük işkencesiymiş gibi mi bağırıyor? Mücadeleye ara verin. Önce tarağı ona verin ve saçınızı taramasına izin verin, ardından sıra size gelsin.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'Demir deposu 🥩', 'Rengi soluk veya iştahı mı az? Beslenme takip aracından demir alımını kontrol edin. Etin yanında mutlaka limonlu salata vererek demir emilimini artırın.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'Oyuncak paylaşma dersi 🧸', 'Parka gitmeden önce “Bugün oyuncaklarımızı sırayla paylaşacağız” konuşmasını yapın. Evet, yine paylaşmayabilir ama bu soyut kuralı tekrar tekrar duyması gerekir.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'Babanın uyku taktiği 👨‍🍼', 'Geceleri pijamasını giymek istemiyor ve kaçıyor mu? Görevi babaya devredin. Baba giyinme sürecini güreşe veya eğlenceli bir oyuna dönüştürdüğünde çocuğunuz farkına bile varmadan pijamasını giymiş olur.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'Doğa bilmecesi 🍁', 'Parkta yalnızca yürümek yerine bunu bir oyuna dönüştürün: Haydi, en büyük sarı yaprağı bulalım! Doğa, onun için en büyük ve en etkileşimli okuldur.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'Çamaşır makinesi merakı 🧺', 'Çamaşır makinesinin karşısına oturup dönen çamaşırlara mı odaklandı? Bu, tamamen ücretsiz ve zihni sakinleştiren bir eğlencedir. Ona engel olmayın; siz de bu fırsattan yararlanıp dinlenin.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'Duygu günlüğünde itiraf 📝', 'Telefonunuzu elinize alın. Sosyal medyada gezinmek yerine Duygu günlüğünü açın ve bugün sizi çileden çıkaran her şeyi içinizi boşaltana kadar yazın. Dijital terapi işe yarar.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'Melatonin zamanı 🌙', 'Uyku hormonunun devreye girmesi için yatmadan en az 1 saat önce televizyon ve tablet gibi mavi ışık kaynaklarını tamamen kapatın. Karanlık ve sessizlik en iyi uyku ilacıdır.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'Ben anneyim! oyunu 🎭', 'Oyuncak bebeğini parmağıyla tehdit edip sizin ses tonunuzla mı kızıyor? Odada küçük bir siz dolaşıyor. Kendinizi dışarıdan izlemek hem komik hem de davranışlarınıza dikkat etmeniz için bir işarettir.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'Gündüz uykusunu reddetme 🥱', 'Yatağa gitmek istemiyor ama gözlerinden uyku mu akıyor? 3 yaşa yaklaşırken bu direnç çok yaygındır. Zorlamayın; odadaki ışıkları azaltıp Sessizce kitap inceleme saati ilan edin.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'Sabah inadının rengi 🔴', 'Yemeğini yeşil tabakta istemişti ama siz getirince “Ben kırmızı demiştim” diyerek ağlıyor. Mantık aramayı bırakın. Yemeği kırmızı tabağa koyun ve sinir hücrelerinizi koruyun.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'Gece fırtınası 😭', 'Gecenin bir yarısı sebepsiz yere ağlayarak mı uyandı? Gaz mı, yoksa uyku terörü mü? Tahmin etmeyi bırakın; Ağlama analizi ile nedenini bulun ve ona sakince sarılarak rahatlatın.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'Lazımlık kazaları 🚽', 'Lazımlık eğitimi sırasında yine halıya mı çişini yaptı? Derin bir nefes alın. Öfkelenmeniz gerilemesine neden olabilir. Temizlenebilecek bir şey için kendinizi yıpratmayın; bu yalnızca öğrenme sürecinin bir parçası.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'Parktaki avukat 🗣️', 'Biraz daha oynayayım, sadece 5 dakika! diyerek süreyi uzatıyor. Zaman kavramı yok ama pazarlık yeteneği harika. Bir zamanlayıcı kurarak kuralları onu incitmeden ve oyunla hatırlatın.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'Boy atma dönemi 📏', 'Pantolonları kısa mı gelmeye başladı? Hızla büyüyor! Güncel ölçülerini Gelişim Takipçisine girin ve uykusuz gecelerinizin meyvesine gururla bakın.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'Çift molası 🥂', 'Çocuk uyudu. Şimdi telefonları ve ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuk ve ödemeler dışında, bambaşka bir konu hakkında konuşun.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'Masalların büyülü dünyası 🪄', 'Bu akşam Akıllı masallarda bambaşka bir şey deneyin: Gökyüzünü keşfeden küçük bulutun hikâyesi. Ses tonunuzu masalın ritmine uydurarak onu uykuya hazırlayın.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', 'Bana bak! hamlesi 👀', 'Siz telefona bakarken gelip elinize vuruyor veya cihazı elinizden alıyor. Aslında son derece haklı. O anda tüm dikkatinizi, bölünmeden ona vermenizi istiyor. Göz teması kurarak onu dinlediğinizi hissettirin.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'İnatçı lekeler, özgür keşifler 🎨', 'Pijaması yemek, üstü başı boya lekesi içinde mi? Çocuklar tertemiz büyümek zorunda değil; keşfederken kirlenirler. Dağınıklık, yaratıcılığının imzasıdır; strese girmeyin.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'Gizli sebze operasyonu 🥦', 'Çorbadaki sebzeleri mikroskopla arıyormuş gibi ayırıp kenara mı koyuyor? Sağlıklı tariflerde sebzeleri görünmez hâle getirecek sos tariflerini keşfedin. Yaratıcılık, annenin en büyük silahıdır.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'Aşağı bakın, ne keşfediyor? 👣', 'Çıplak ayakla yürümekten ve farklı yüzeylere dokunmaktan özellikle keyif alıyor. Ayak tabanındaki sinirlerin uyarılması dengesi için önemlidir; güvenli ortamlarda çorapsız yürümesine izin verin.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'Gecenin koruyucuları 🧸', 'Karanlıktan mı korkuyor? En sevdiği ayıcıkları ve oyuncakları yatağının dört bir yanına dizip Onlar seni sabaha kadar koruyacak deyin. Bu görsel güvence harika işe yarar.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'Sessizliğin onayı 🤫', 'Gürültülü bir günün ardından çocuk uyuduğunda, Ses ölçer ile odanın sessizliğini ölçün. Sıfıra yaklaşan o rakamları görmek bile annenin beyninde terapi etkisi yaratır.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'Sabah Hayır!ı 🛑', 'Daha gözlerini bile açmadan ona bir şey önerdiğinizde Hayır! diyor. 3 yaşın eşiğindeyken soru sormayın, doğrudan harekete geçin. Gel, elimizi yüzümüzü yıkayalım yerine Elimizi yüzümüzü yıkama zamanı! deyin.'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'Kendinize de zaman ayırın 🥑', 'Koşturmaca sizi tüketti. Ayaküstü atıştırmak yerine, Sağlıklı tariflerden doyurucu ve vitamin dolu özel bir tabak hazırlayıp keyifle yiyin. Enerjiye mutlaka ihtiyacınız var.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'Fısıltıyla sohbet 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak bir sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlayan en iyi yöntemlerden biridir.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'Deneyim paylaşımı 💬', 'Çocuğunuzun her şeye karşı çıkması sizi korkuttu mu? İnternette korkutucu yazılar aramayın. Anacan Topluluğundaki deneyimli annelerin gerçek yaşam deneyimlerinden yararlanın ve gülümseyin.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'Profesyonel dansçı 🎶', 'Duyduğu ilk ritimle, ister reklam müziği ister araba kornası olsun, dans etmeye başlar. Hayata onun gibi neşeyle bakın! Odada ona katılıp birkaç dakikalık çılgın bir dans yapın.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'Babanın gizli taktiği 👨‍🍼', 'Günün yorgunluğu size yeter. Akşamüstü çocuğu uykuya hazırlama ve dişlerini fırçalatma sürecini babanın eğlenceli oyunlarına bırakın, siz de bir köşede sessizce dinlenin.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'Katlanan ve dağılan kıyafetler 👗', 'Siz büyük bir emekle kıyafetleri katlıyorsunuz, o ise gelip hepsini anında dağıtıyor. Sinirlenmek yerine işi oyuna çevirin: Bakalım bu tişörtü kim daha uzağa atacak?'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'Kendi başına yeme ısrarı 🥄', 'Kaşığı eline alıp her yeri mi batırıyor? Beslenme zamanlayıcısını başlatın. Dökülen yiyeceklere değil, kazandığı bağımsızlığa bakıp sevinin.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'Yalın ayak kâşif 👣', 'Çorap giymek istemiyor, kaçıp saklanıyor mu? Bırakın bir süre çıplak ayakla zemini, halıyı ve soğuk fayansı hissetsin. Ayak tabanındaki sinir uçlarının uyarılması, denge gelişimini destekler.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını kolaylaştırmak için odadaki tüm gereksiz ışıkları ve tablet ekranlarını kapatın. Melatonin salgısı karanlık ve ekransız bir ortamda daha iyi desteklenir.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'Doğa keşfi 🍁', 'Hava durumuna uygun giyinip dışarı çıkın. Parkta farklı taşlar ve renkli yapraklar bulma oyunu oynayın. Doğa, bu yaşta onun için en büyük ve en etkileşimli oyuncaktır.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'Markette unutkanlık 🛒', 'Hafızanıza güvenip markete gittiniz ve en önemli şeyi unutarak mı döndünüz? Tüm ihtiyaçlarınızı hemen Alışveriş listesine yazmayı alışkanlık hâline getirin; bırakın uygulama sizin yerinize hatırlasın.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'Sabah yardımcısı 🧑‍🍳', 'Kahvaltıyı hazırlamanıza yardım etmek istiyor. Unu dökecek, suyu etrafa saçacak, mutfak batacak... Ama bu küçük motor beceri denemeleriyle gelişiyor. Sabırlı olun.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'Sihirbaz babanın gösterisi 🤡', 'Sizin yaptıklarınız artık işe yaramadığında, babanın çıkardığı tuhaf sesler durumu hemen kurtarır. Akşam krizlerinde topu ona atın ve neşeli kahkahaları kenardan izleyin.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'Ilık banyo terapisi 🛀', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık banyo sırasında arka planda rahatlatıcı doğa sesleri açın. Suyun huzuru, en inatçı çocuğu bile uykuya hazırlamaya yardımcı olur.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'Kendi dökmek istiyor 💧', 'Suyu bardağa mutlaka kendisi dökmek istiyor. Bezleri hazırlayın, bağımsızlık hevesini kırmayın. Etrafa dökecek ama birkaç denemeden sonra o bardağı ne kadar dikkatli doldurduğuna hayran kalacaksınız.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'Tükenmişlik hissi 🔋', 'Kendinizi yetersiz mi hissediyorsunuz? Her şeyin üstesinden gelemediğinizi mi düşünüyorsunuz? Topluluktaki paylaşımlara göz atın; yalnız değilsiniz ve yetersiz de değilsiniz. Siz bu çocuğun dünyasısınız.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'Tuhaf dil bilgisi 🗣️', '“Ben acıktımdım”, “O gidiyordu geldi” gibi tamamen yeni ve kendine özgü dil bilgisi yapıları keşfediyor. Onu sert bir şekilde düzeltmeyin; yalnızca cümlenin doğru hâlini tekrarlayarak yanıt verin.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Anacan AI tavsiyesi 🤖', 'Çocuğunuzun parkta diğer çocuklarla sosyalleşmesi hakkında bir sorunuz mu var? İnternette saatlerce kaybolmayın; Anacan AI''a sorun ve gelişimine uygun, çocuk doktoru onaylı tavsiyeyi anında alın.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'Gece terörü uyarısı 😭', 'Aniden ağlar veya gözleri kapalı hâlde çığlık atarsa Ağlama analizi ile kontrol edin. Gece terörü yaşıyorsa onu uyandırmaya çalışmadan sadece yanında olun ve sessizce güven verin.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'Takım zaferi 🥂', 'Zorlu bir günü daha geride bıraktınız. Eşinizle karşılıklı oturup çay bardaklarınızı tokuşturun: Biz gerçekten efsanevi bir takımız ve bu işi harika başarıyoruz!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'Paylaşma derdi 🧸', 'Oyuncağını hiç kimseye vermiyor mu? Bu bencillik değil, gelişimin bir parçası. 3 yaşa yaklaşırken paylaşmayı değil, sırayla oynamayı öğretmenin yollarını Anacan AI''dan öğrenin.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'Üç tekerlekli bisiklet 🚴‍♂️', 'Pedallara basıp bisiklet sürmeye mi çalışıyor? Bacak kasları ve koordinasyonu yeni bir aşamada! Onu güvenli yerlerde teşvik edin.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'Anne için vitamin 🥑', 'Onu doyurmak için her şeyi yapıyorsunuz. Peki ya siz? Sağlıklı tarifler bölümünden demir ve kalsiyum açısından zengin, hafif bir öğle yemeği seçin.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'Babanın gece nöbeti 👨‍🍼', 'Gece uyanmalarının yükünü tamamen tek başınıza üstlenmeyin. Eşinizi de uyandırın; takım olmak, sorumluluğu eşit şekilde paylaşmaktır.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'Cepler dolusu hazine 🍁', 'Parktan döndünüz ve cebinden 3 taş, 1 kurumuş yaprak ve bir çöp mü çıktı? Onun için bunlar değerli birer hazine. Siz sadece bunları eve saçılmadan ortadan kaldırmaya çalışın.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'Mantık aramayın 👑', 'Kahvaltıda dondurma veya dünden kalan mercimek çorbasını mı istiyor? Evde yeni bir diktatör var. Ona seçenek sunarak (Örneğin: Elma mı istersin, yoksa muz mu?) dikkatini hemen başka yöne çekin.'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'Yataktan kaçma bahaneleri 🏃‍♂️', 'Su istiyor, tuvalete gitmek istiyor, odadaki perdeyi öpmek istiyor... Uykuya dalmamak için zihni yeni bahaneler üretiyor. Sınır koyun: Sadece 1 bardak su ve bitti. Kararlı olun.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'Vücut dövmeleri 🖍️', 'Birkaç saniyelik sessizlik bazen tehlikeli olabilir. Odaya girip kollarına keçeli kalemle dövme yaptığını mı gördünüz? Derin bir nefes alın. İnce motor becerileri gelişiyor, cildi ise nasıl olsa yıkanır.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'Takım arkadaşı baba 👨‍👧', 'Akşamüstü enerjiniz mi tükendi? “Ben bu senaryodan çıkıyorum” deyin ve çocuğu babasına devredin. Birlikte dağıttıkları odayı toplamak, çocukla tek başınıza mücadele etmekten daha kolaydır.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'Lif ihtiyacı 💩', 'Çok koşuyor ama su içmeyi unutuyor. Lazımlıktaki dışkısını takip edin. Kabızlık riski varsa menüsüne yulaf ve erik ekleyin.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'Gölge korkusu 👻', 'Sokakta veya odada birdenbire ağlamaya mı başladı? Bunun nedeni, gölgesinin onu takip etmesi olabilir! 3 yaşa yaklaşırken hayal gücü ilginç bir hâl alır. Ona sarılın ve gölgesiyle gülümseyerek tanıştırın.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'Yemek cerrahı 🥦', 'Yemeğini yemiyor, sadece içindeki küçük pirinç tanelerini veya yeşil baharatları cerrah titizliğiyle mi ayıklıyor? Beslenme planına girip sebzeleri püre hâline getirmenin yollarını keşfedin.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'Her şeyle vedalaşmak 🧸', 'Uyumadan önce odadaki arabaya, sandalyeye, hatta kapı koluna bile iyi geceler demek istiyor. Bu, benimsediği yeni uykuya geçiş ritüellerinden biridir; onu acele ettirmeyin.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'Hayalî iş görüşmeleri 🍌', 'Eline bir muz veya kumanda alıp uydurma bir dilde ciddi ciddi telefonla mı konuşuyor? Beden dilinizi tamamen taklit ediyor. Onu videoya çekip gelecek için arşivleyin, çok güleceksiniz.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'Uyku düzeni kayıyor mu? ⏱️', 'Akşam uykuya dalması 1 saatten uzun mu sürüyor? Uyku zamanlayıcısındaki programa bakın. Belki de gündüz uykusunu tamamen bırakmanın ve akşam yatış saatini erkene çekmenin zamanı gelmiştir.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'Zaman uçup gidiyor!', 'Geriye dönüp ne kadar çok şey öğrendiğinizi görün. Bu küçük avukat artık sizinle her konuda pazarlık yapabiliyor. Hem onunla hem de kendinizle gurur duyun.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'Masalın kahramanı 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masallarda onu astronot yapıp yıldızlara uçurun veya denizlerin derinliklerine indirin. Uyumadan önce hayal gücünü özgür bırakın.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'Sakinlik saati şart ☕', 'Gündüz uykusunu kesinlikle reddediyorsa zorlamayın. Ancak 30 dakikalık bir Sakinlik saati (quiet time) belirleyin. O, yatağında kitaplarıyla yalnız kalsın; siz de odada biraz soluklanın.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'Ruh hali günlüğü 📝', 'Telefonunuzu elinize alın. Sosyal medyada gezinmek yerine Ruh hali günlüğünü açın ve bugün yaptığı en komik, sizi en çok güldüren anı gelecek için kaydedin.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'Gizli sebzeler operasyonu 🥦', 'Çorbadaki sebzeleri ayıklayıp atıyor mu? Mücadele etmeyin. Beslenme planında sebzeleri püre haline getirip sosların içine gizlemenin en farklı ve yaratıcı yollarını keşfedin.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', '“Anne, bana bak!” ısrarı 👀', 'Siz telefona bakarken veya bir işle uğraşırken gelip elinize vuruyor mu? Aslında çok haklı; bölünmemiş ilginizi istiyor. Göz teması kurarak geçireceğiniz 5 dakikalık kaliteli zaman onu sakinleştirecektir.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'Odadan kaçma oyunu 🏃‍♂️', 'Siz pijamasını veya tişörtünü giydirmek istediğinizde gülerek odadan kaçıyor. Sinirlenmek yerine işi oyuna dönüştürerek çözün. Yakalamaca oynarken giydirmek daha kolaydır.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'Hava durumu uyarısı ⛅', 'Gezintiye çıkarken pencereden bakıp yanılmayın. Hava ve giyim yardımcısıyla dışarıdaki gerçek rüzgâr ve sıcaklığa en uygun kombini belirleyip evden çıkın.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'Sessiz moda geçiş 🤫', 'Uykuya daldığı anlarda hassasiyeti artar. Sessizliğe özen gösterin.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'Babayla uyku düeti 📖', 'Bu akşam odada farklı bir atmosfer yaratalım. Kitap okumak yerine babasıyla birlikte alçak sesle, ritmik bir şarkı söyleyerek uykuya dalmasını sağlayın.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'Anne, kendinizi de besleyin 🥑', 'Günlük koşuşturma içinde öğle yemeğini ayaküstü geçiştirmeyin. Oturup keyifle yiyebileceğiniz, demir ve kalsiyum açısından zengin, farklı bir salata hazırlayın. Sizin enerjiniz bu evin motorudur.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'Arkadaşlığa ilk adımlar 👫', 'Parkta ilk kez kendi isteğiyle oyuncağını başka bir çocukla paylaştı mı? Bu, büyük bir gelişim adımıdır! Benmerkezcilik azalıyor, empati gelişiyor. Onu büyük bir sevinçle alkışlayın.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', 'Mum ışığında 10 dakika 🕯️', 'Çocuk uyudu, evdeki kaos sona erdi. Işıkları kapatın; yalnızca karanlığa veya bir mumun ışığına bakarak 10 dakika boyunca zihninizi ve düşüncelerinizi tamamen sıfırlayın.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'Toplulukta teselli 💬', '“Bir daha asla eski ben olamayacağım” düşüncesi sizi bunaltıyor mu? Bu geçici ama çok ağır duyguyu Anacan Topluluğundaki annelerle paylaşın ve onlardan destek alın.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'İnatçı örgüler 🪮', 'Saçını toplamanıza veya taramanıza kesinlikle izin vermiyor mu? Mücadeleye ara verin. Aynanın karşısına geçip önce kendi saçınızı onun istediği gibi tarayın, ardından sırayı ona verin.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'Gündüz uykusu mücadelesi 🥱', 'Reddediyorsa zorlamayın. Onu defalarca uyutmaya çalışıp sinirlerinizi yıpratmak yerine, odasında oyuncaklarıyla sessizce oynayacağı bir düzen oluşturun.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'Diş fırçası savaşı 🪥', 'Diş fırçasını görünce ağzını sımsıkı kapatıyor mu? Hijyeni bir savaşa dönüştürmeyin. Önerilen Ürünler bölümündeki müzikli fırçalara göz atarak bu zorlu rutini eğlenceli bir oyuna çevirin.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', '“Bacaklarım çalışmıyor” inadı 🛑', 'Parktan dönerken birden yere oturup “Bacaklarım çalışmıyor” diyerek kucağınıza mı gelmek istiyor? Bu yorgunluk değil, manipülasyondur. “Bakalım eve kadar tavşan gibi zıplayabilecek misin?” diyerek bunu oyuna çevirin.'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'Lazımlık saklambacı 🚽', 'Tuvalet ihtiyacı geldiğinde perdenin arkasına veya kanepenin yanına mı saklanıyor? Bloglar bölümüne gidip lazımlık eğitimine nasıl başlayacağınıza dair bilimsel adımları okumanın tam zamanı.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'Günlüğe içini dökmek 📝', 'Biri size “Evdesin, neye yoruluyorsun?” mu dedi? Hemen Duygu Durumu Günlüğü''nü açın ve tüm öfkenizi parmaklarınızla ekrana dökün. Sahte bir gülümseme takınmaktansa gerçek duygularınızı yazmak daha iyidir.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'Babanın masal gösterisi 📖', 'Bu akşam odada sizin değil, babanın sesi duyulacak. Masalı o okusun, kahramanların sesini kalınlaştırıp incelterek eğlence katsın. Siz de kenarda durup kahkahaları dinleyin.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'Annenin gizli çikolatası 🍫', 'Çocuğu arkasını döner dönmez ağzına bir parça çikolata atıp hızla çiğneyen anne, o glikoz sizin en doğal hakkınız. Bütün gün o enerjiye dayanabilmek için şarj olmalısınız.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'Sıra dışı en iyi arkadaş 🥄', 'O kadar pahalı oyuncak varken mutfaktan silikon bir spatula bulup bütün gün onunla mı dolaşıyor, onu uyutuyor mu? Çocuk beyni inanılmazdır. Engel olmayın, bırakın spatulayı sevsin.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'Doğa keşfi ⛅', 'Dört duvar arasında kalmak zihninizi uyuşturdu. Hava durumuna ve kıyafetlere bakarak en uygun kombini seçin. Dışarı çıkıp yalnızca sarı yaprakları bulma göreviyle hem onun enerjisini atmasını sağlayın hem de biraz nefes alın.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'Tehlikeli kelimeler 🤐', 'Bir yerden duyduğu o kötü sözü gülerek size tekrarlıyor ve tepkinizi mi bekliyor? En büyük silahınız tepki vermemektir. Gülmeyin, sinirlenmeyin; sadece görmezden gelin. Unutacaktır.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'Altın sessizliğin ölçüsü 🤫', 'Sonunda uyudu! Ses ölçüm aracını etkinleştirin ve odanın mutlak ses seviyesini (0-10 desibel) ekrandan takip edin. Bu rakamları görmek, yorgun bir annenin zihni için en iyi masajdır.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'İnatçı pijama 👗', 'Sabahtan akşama kadar kirlenip lekelenen pijamasını çıkarmak istemiyor mu? 3 yaşında estetik önemli değildir. Üşümüyorsa birkaç saat daha böyle kalmasına izin verin.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'Akıllı masalda ben 🪄', 'Klasik kitapları ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak tasarlayıp sıra dışı bir uyku seansı oluşturun.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'Çizgi film eleştirmeni 📺', 'İzlediği çizgi filmi kendi dil bilgisiyle size anlatıyor, kimin nereye gittiğini ciddi ciddi açıklıyor. Onu dikkatle ve şaşırmış gibi dinleyin. Kendisini dünyanın en akıllı insanı gibi hissetsin.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'Güneşten önce uyananlar 🌅', 'O, saat 6''da ayakta ama siz tükenmiş durumdasınız, öyle mi? Bu düzeni nasıl ayarlayabileceğinizi Anacan AI''a sorun. Unutmayın, uykusuzluk sonsuza kadar sürmez; her şey geçecek.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'Çiftlerin kutlama kadehi 🥂', 'Çocuk uyudu. Şampanya olmasa da bardaklara sıcak çay doldurun ve eşinizle “Bu zor günü de sağ salim atlattık” diyerek bardaklarınızı tokuşturun. Siz harika bir partnersiniz.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'Listedeki sürpriz 🛒', 'Markete gitmeden önce Alışveriş Listesi''ni açtınız ve arkanızdan gelip telefonun ekranına dokunarak listeye çikolata eklediğini gördünüz. Evet, teknolojiyi sizden daha iyi biliyorlar!'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'Doğa sesleriyle uyku 🪄', 'Klasik müzik işe yaramıyor mu? Akıllı masallarda masalı kapatıp yalnızca yağmur veya orman seslerinin olduğu arka plana geçin. Tekdüze doğa sesleri çocuğunuzu adeta büyülenmiş gibi uyutur.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'Büyükler gibi iç çekmek 😔', 'Kanepede otururken birden büyükler gibi derin bir nefes alıp iç çekiyor. Sizi o kadar iyi taklit ediyor ki! Bu dramatik mimiklerini sadece gülümseyerek uzaktan izleyin.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'Mutfak faciaları 🧑‍🍳', 'Yemek yaparken mutlaka ocağın yanında size yardım edip tuzu dökmek istiyor. İzin verirseniz yemek mahvolacak, vermezseniz ağlayacak. Ona boş bir kap ve su verip “Sen de kendi çorbanı pişir” deyin.'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'Liste kontrolü 🛒', 'Yıldönümü için gereken her şeyi Alışveriş listesine eklediniz mi? Balonların ve küçük sürprizlerin de listede olduğundan emin olun. Eşinize uygulamadan son bir hatırlatma gönderin.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'Işık takipçisi 🤫', 'Uykuya daldığı ilk yarım saat, beynin en aktif olduğu zamandır. Ses ölçerle odadaki ortamı ayarlayın. Pencereden gelen sesleri etkisiz hâle getirip tamamen sessiz ve karanlık bir ortam oluşturun.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'Hikâyenin yönetmeni 🪄', 'Akıllı masalları açın ve bu akşam hikâyeyi onun yönlendirmesine izin verin. “Şimdi kahraman nereye gitsin?” diye sorun; bırakın, uydurduğu absürt sonla kendisi de uykuya dalsın.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'Mantıksız gözyaşları 🐶', 'Sokakta gördüğünüz köpek ona bakmadı diye 15 dakika hıçkıra hıçkıra ağladı mı? Mantık aramayın. Bu, onun için gerçekten derin bir üzüntüdür. “Biliyorum, onun sana bakmasını istiyordun” diyerek duygusunu onaylayın.'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'Evdeki kaosla barışmak 🌪️', 'Odanın her yanı oyuncaklarla mı dolu? Önemli olan temizlik değil, onunla geçirdiğiniz bu yaramazlık dolu anlardır. Oyuncaklar yarın da orada olacak, kendinizi yormayın. Bazen dağınıklığa teslim olmak en iyi dinlenme şeklidir.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'Tuvalet eğitiminde gerileme mi? 🚽', 'Lazımlığa gitmeyi öğrenmişti ama şimdi yine kaçırıyor mu? Bu, son derece normal bir gerilemedir. Baskı yapmayın; Anacan AI''a bu psikolojik engeli kriz yaşamadan aşmanın yollarını sorun.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'Bloglardan ilham almak 📱', '35 aya yaklaşan bir çocuğun gelişim sıçramaları nelerdir? Neleri yapabilmelidir? Uygulamadaki gelişim bloglarına göz atın ve çocuğunuzun ne kadar ileride olduğunu görüp sevinin.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'Büyük güne hazırlık 💆‍♂️', 'Çocuğunuz uyuduktan sonra eşinizle yarınki büyük dönüm noktası için birbirinizi kutlayıp kısa bir omuz masajı yapın. Yıldönümü gününün enerjisi için ikinizin de dinlenmesi şart.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'Yatak odasında koşturmaca 🏃‍♂️', 'Uyumak yerine kanepede mi zıplıyor? Biraz daha su isteme bahaneleri de bitmiyor mu? Uyku zamanlayıcısını başlatın, sınırlarınızı koruyun.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'Oyun sırası babada 👨‍👧', 'Annelik, hiç bitmeyen bir maraton değildir. Bugün çocuğunuz enerjisini babasıyla parkta atsın, siz de kanepede yalnızlığın tadını çıkarın.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'Yazın kışlık şapka 🧢', 'Havaya hiç uygun olmayan kıyafetler mi giymek istiyor? Bağımsızlık mücadelesinde ona küçük seçenekler sunun.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'Bitmeyen soru makinesi 🤔', '“Neden?”, “Nasıl?” soruları zihninizi yoruyor mu? Onun keşfetme merakına sıkılmadan nasıl mantıklı yanıtlar verebileceğinizi Anacan AI''dan öğrenin. Sabrınız, onun gelişimidir.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'Sessizlik günlüğü 📝', 'Evdeki kasırga sonunda uyudu. Şimdi telefonunuzu elinize alın ve Duygu durumu günlüğüne, bugünü atlattığınız için kendinize bir teşekkür mektubu yazın. Siz bunu başarabilirsiniz.'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'Banyoda buruşan parmaklar 🛀', 'Suyla oynamak o kadar keyifli ki parmakları buruşsa bile küvetten çıkmak istemiyor. Ona 5 dakika önceden haber verip zamanlayıcı kurun. Zil çaldığında çıkıyoruz kuralı çoğu zaman işe yarar.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'Saç şekillendirme mücadelesi 🪮', 'Sabah uyandı ve saçları elektrik çarpmış gibi havaya kalktı. Tarağı görür görmez de kaçmaya başlıyor. Taramak yerine saçlarını ellerinizle hafifçe ıslatıp yatıştırarak mücadeleyi sonlandırın.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'Yapay zekânın fikri 🤖', 'Çocuğunuz garip bir alışkanlık edindi (örneğin tırnak yemek) ve internetteki yazılar sizi korkuttu mu? Durun. Anacan AI''a bunun çocuk doktorları tarafından doğrulanmış gerçek nedenini sorun ve içinizi rahatlatın.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'Doktorunuz yanınızda 🩺', 'Oyuncak stetoskopunu alıp göğsünüze koyuyor ve nefes almanızı söylüyor. Siz hastasınız, o ise başhekim. Bu oyuna katılın, uzanın ve 5 dakikalığına da olsa muayene sırasında gözlerinizi kapatıp dinlenin.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'Enerji patlaması 🏃‍♂️', 'Evin içinde duvarlara tırmanıyor. Hava durumunu kontrol edip uygun kıyafetleri seçerek mutlaka dışarı çıkın. Bol oksijenli bir ortamda 30 dakika koşmak, akşam rahat uyumasının en büyük garantisidir.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'Fısıltının büyüsü 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle, fısıldayarak anlatın. Fısıltı, beyni uykuya hazırlayan en doğal ve sakinleştirici yöntemlerden biridir.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'Karanlığa alışmak 🌙', 'Uykuya dalmasını kolaylaştırmak için odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin hormonunun salgılanması yalnızca sakin ve karanlık bir ortamda hızlanır.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'Annenin şarj zamanı 🔋', 'Kendi başına yapboz yapıyor ve 10 dakikadır sessiz. Siz ise bu anı evi toplamaya ayırmak istiyorsunuz. Hayır! Gidip kanepeye uzanın. Akşama kadar dayanabilmeniz için sizin de pilinizi doldurmanız gerekiyor.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'Uydurma dil bilgisi 🗣️', 'Ben gittiydim, O geliyormuştu gibi tuhaf ve komik zaman kalıpları keşfetti. Kelime hazinesi gelişiyor! Gülerek yanlışını düzeltmeyin; sadece doğru cümleyi tekrarlayarak onu onaylayın.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'Duygu günlüğüne sığınmak 📝', 'Kimse ne kadar yorulduğunuzu görmüyor mu? Uygulamadaki Duygu günlüğü sizi dinlemek için orada. Bugün sizi çileden çıkaran tüm küçük ayrıntıları oraya yazın ve zihninizi boşaltın.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'Yemek denemeleri 🥣', 'Düne kadar yediği her şeyi bugün tükürüyor. Dişleriyle ilgili bir sorun yoksa bu yalnızca bir irade testidir. Sağlıklı tarifler arasından sebzeleri gizleyen, lezzetli ve renkli köfte tariflerini deneyin.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', '5 dakika yanılsaması ⏱️', 'Sadece 5 dakika daha izleyeyim diyor ama zihninde 5 dakika kavramı henüz yok. Telefonun zamanlayıcısını kurun ve sesi duyduğunda sürenin bittiğini anlatın. Suçlu teknoloji olsun, siz değil.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'Babanın sırtında ata binmek 🐴', 'Enerjisini tam olarak atamadı ve yatağa gitmiyor mu? Babanın sırtında evin içinde ata binmek ve kahkaha krizlerine girmek, bu enerjiyi sıfırlamanın en kısa ve eğlenceli yoludur. Top babada.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'Annenin sessizliğe ihtiyacı 🩸', 'Her ses sizi rahatsız mı ediyor? Regl Takipçisi''ne bakın. Bedeninizin dinlenmeye ihtiyacı var. Sağlıklı tariflerden magnezyum içeren bir atıştırmalık hazırlayıp kendinize zaman ayırın.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'Nedensiz çığlıklar 😭', 'Gözünü açar açmaz nedensizce ağlıyor mu? Bu şımarıklık değil, duygusal yüklenmedir. Kriz anında nasıl davranmanız gerektiğini Anacan AI uzmanımızla dertleşerek keşfedin.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'Babanın mutfak sırası 👨‍🍳', 'Bugün öğle yemeğini hazırlamak ve çocuğu doyurmak babanın görevi! Siz ise bu zamanı yalnızca uzanıp dinlenerek kendinize ayırın.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', 'Kendim yapacağım inadı 🛑', 'Ayakkabısının bağcıklarını kendi bağlamak istiyor ve bu 10 dakikanızı mı alıyor? Acele etmeyin, ona zaman tanıyın. Deneyip yanılması, gelecekteki problem çözme becerisinin temelidir.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'Kahve ve meditasyon ☕', 'Odayı birbirine mi kattı? Temizliği boş verin. Çocuk kendi kendine oyalanırken kanepeye oturun, sıcak kahvenizi için ve sadece duvara bakarak 10 dakika zihninizi boşaltın.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'Meslekleri taklit ediyor 🩺', 'Oyuncak ayısını tedavi ediyor veya arabaları tamir mi ediyor? Sembolik oyunlar (rol yapma oyunları) iyice gelişiyor.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'Gölge oyunları 🐰', 'Uyumak istemiyor mu? Odayı tamamen karartın ve ellerinizle duvarda bir gölge tiyatrosu oluşturun. Bu, karanlık korkusunu yenmenin en eğlenceli yoludur.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'Ağlama sen 🫂', 'Parkta ağlayan başka bir çocuk gördüğünde yanına gidip onu okşuyor mu? Empati duygusu resmen devrede! Onun bu muhteşem şefkatini gururla izleyin.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'Büyük yatağa geçiş? 🛏️', 'Beşiğinden tırmanarak çıkmaya mı çalışıyor? Belki de artık geçiş konusunda kararsızsınız. Anacan AI''a büyük çocuk yatağına geçişin güvenlik kurallarını ve en doğru zamanını sorun.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'Babanın kitap saati 📖', 'Bu akşam ses tellerinizi dinlendirin. Çocuğun en sevdiği kitapları farklı ses tonlarıyla okuma görevini babaya bırakın.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'Kişisel sınırlar koyuyor ✋', 'Biri onu öpmek istediğinde uzaklaşıyor veya hayır mı diyor? Bedensel sınırlarına saygı gösterin ve başkalarının da buna saygı duymasını sağlayın. Özgüven tam da burada başlar.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'Akıllı masalın büyüsü 🪄', 'Klasik masallardan sıkıldınız mı? Akıllı masallara özel bir konu verin: Sebze yemeyi seven sihirli dinozorun maceraları.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'Sessizliğin değeri 🤫', 'Sonunda uyudu. Şimdi evdeki en küçük ses bile sizi geriyor. Ses ölçer ile odanın ses sınırını ayarlarken arka planda kesintisiz bir beyaz gürültü açın.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'Saymaya başlıyoruz 🔢', 'Merdivenleri çıkarken veya oyuncaklarını dizerken bir, iki, üç demeye mi çalışıyor? Matematiksel düşünmenin temelleri atılıyor. Onunla birlikte odadaki eşyaları yüksek sesle sayın.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'Tükenmişlik sendromu 🔋', 'Her şeye bağırmak mı istiyorsunuz? Tükenmişlik yaşıyorsunuz. Anacan Topluluğuna girin ve Çok yoruldum yazın. Binlerce kadının aynı anda sizinle dayanışma içinde olduğunu göreceksiniz.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'Gündüz uykusunu reddediyor 🥱', 'Öğle uykusuna kesinlikle yatmak istemiyor ve direniyor mu? Bazı çocuklar 3 yaşına doğru gündüz uykusunu bırakır. Uyku düzenini Sessizlik saati (uykusuz sakin zaman) ile değiştirmeyi deneyin.'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'Anılar canlanıyor 🧠', 'Dün anneanneye gittik gibi geçmişe yönelik cümleler mi kuruyor? Zaman algısı ve uzun süreli hafıza gelişiyor. Bu anılarını ilgiyle dinleyin ve sorular sorun.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'Gece yarısı gözleri kapalıyken bağırıp ağlıyor mu?', 'Onu uyandırmaya çalışmayın. Sesini Ağlama analizine dinleterek bunun yalnızca gece terörü olduğundan emin olun ve sakince yanında kalın.'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'Özgürlük şelalesi 🥛', 'Suyu veya sütü bardağa mutlaka kendisi dökmek istiyor ve sonuç ne mi? Her yer göle dönüyor. Derin bir nefes alın. Bu karmaşa, onun el-göz koordinasyonu ve özgüven gelişiminin bedelidir. Bezi ona da verin ve söylenmeden birlikte temizleyin.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'Gürültü detoksu 🎧', 'Anne, anne, anne! sesleri zihninizde yankılanıyor mu? Kendinize kısa bir mola ilan edin. Onu 15 dakika boyunca güvenli bir etkinlikle baş başa bırakıp kahvenizi sessizlik içinde için. Sizin de enerjinizi yenilemeniz gerekiyor.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'Banyo inadını aşmak 🛁', 'Banyoya girmek istemiyor, yerde yuvarlanarak itiraz mı ediyor? Gel, seni yıkayayım demek yerine, Hadi en sevdiğin arabaları (veya bebeklerini) yıkayalım deyin. Oyuna dönüşen her zorunluluk, çocukların en kolay ikna olduğu noktadır.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'Evdeki ayakkabı krizi 👟', 'Dışarıda giydiği ayakkabıları evin içinde giymek ve asla çıkarmamak için ağlıyor mu? Savaşmaya değmez. Tabanlarını nemli bir bezle silin ve birkaç saat odada gururla dolaşmasına izin verin. Bazı mücadeleleri bilerek kaybetmek aslında bir annenin en büyük zaferidir.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'Sıra babada 👨‍🍼', 'Bütün gün hayır demekten ve kurallar koymaktan yoruldunuz. Pijama giyme ve diş fırçalama mücadelesini bu akşam babaya devredin. Odanın kapısını kapatın, Duygu günlüğüne yalnızca bugünkü hislerinizi yazın ve tamamen kendinize zaman ayırın.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'Toplulukta tebessüm 💬', 'Bugünkü inatlaşmaları sizi gerçekten tüketti mi? Hemen Anacan Topluluğunu açın ve diğer annelerin evlerinde yaşanan benzer, hatta daha komik kriz hikâyelerini okuyun. Aynı yollardan geçtiğinizi ve yalnız olmadığınızı bilmek en iyi psikolojik destektir.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'Yeni arkadaş arayışı 👫', 'Parkta yaşıtlarıyla koşmaya ve onların oyunlarına katılmaya mı çalışıyor? Sosyalleşme resmen başlıyor! Onu cesaretlendirin ve çocuklarla nasıl selamlaşacağını öğretin.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'Anne için doğa terapisi 🌳', 'Evin duvarları üzerinize mi geliyor? Çocuğunuzu da yanınıza alıp en yakın parka gidin. Temiz hava yalnızca çocuğunuzun değil, sizin de yorgun sinirlerinize iyi gelen en güzel terapidir.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'Babanın sorumluluğu 👨‍🍼', 'Her şeyi siz yapmak zorunda değilsiniz. Bu akşam diş fırçalama ve pijama giydirme sürecini tamamen babaya devredip dışarıdan izleyin.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'Anne sesinin gücü 🎶', 'Bu akşam hiçbir araç kullanmayın. Sadece onu göğsünüze yaslayın ve en sevdiği ninniyi kulağına fısıldayın. Sizin sesiniz onun en güvenli limanıdır.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'Hızlı pediatri desteği 🤖', '3 yaşına yaklaşan çocuğunuzun boy-kilo grafiği sizi endişelendiriyor mu? İnternette saatlerce arama yapmayın; doğru ve pediatristler tarafından onaylanmış normal değerleri Anacan AI''dan hemen öğrenin.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'Adını ve yaşını biliyor 🎂', 'Kaç yaşındasın? diye sorduğunuzda parmaklarıyla göstermeye mi çalışıyor? Benlik farkındalığı harika ilerliyor. Gelişim takibine bu zihinsel sıçramayı kaydedin.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'Ayna karşısında yönetmen 🎭', 'Aynanın karşısında durup farklı mimikler yapıyor, kendi kendine mi konuşuyor? Farklı rolleri deniyor. Onu gizlice izleyin ve bu komik anların tadını çıkarın.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'Enerji takviyesi gerekiyor 🍲', 'Koşturmaca sizi hâlsiz bıraktı. Sağlıklı tarifler bölümünden hem sizin hem de çocuğunuzun seveceği, demir ve protein açısından zengin, farklı bir öğle yemeği seçin.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'Günün değerlendirmesi 📝', 'Çocuğunuz uyur uyumaz eşinizle birlikte Duygu günlüğünü açın. Bugün yaptığı en komik şeyi yazın ve birlikte gülümseyerek stres atın.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'Müzikle uykuya geçiş 🛀', 'Akşam rutini zorlaşmaya mı başladı? Ilık bir banyo sırasında arka planda sakinleştirici klasik müzik çalın. Su ve müziğin uyumu, en inatçı çocuğu bile sakinleştirir.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'Diğer annelerle tanışın 👯‍♀️', 'Hem çocuğunuz oynasın hem de siz sohbet edin! Anne Dostu Mekânlar haritasından oyun grupları bulunan bir merkez bulup dışarı çıkın.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'Dişler fırçalanıyor mu? 🪥', 'Diş fırçasını görür görmez ağzını sımsıkı kapatıyor mu? Bu hijyen rutinini nasıl eğlenceli bir oyuna dönüştürebileceğinizi öğrenmek için Anacan AI''dan pratik öneriler alın.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'Doğal sakinleştirici 🍃', 'Çok gürültülü bir gün mü geçirdiniz? Zamanlayıcı durdu. Ev işlerini unutun, Sağlıklı tariflerden melisa çayı demleyip yalnızca sessizliğin tadını çıkarın.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'Seni buldum heyecanı 🙈', 'Saklambaç artık en sevdiği oyun. Perdenin arkasına saklanıp sizin onu bulmanızı bekliyor. Nesne sürekliliği kavramı bu yaşta oyunlarla daha da pekişir.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'Krizleri yönetmek 🛑', 'Mağazada veya parkta yaşanan öfke nöbetleri sizi utandırıyor mu? Unutmayın, önemli olan çevrenizdekilerin ne düşündüğü değil, çocuğunuzun o anki duygusudur. Ona sakince sarılın.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'Eşinizden yardım isteyin 🛒', 'Alışverişe vaktiniz yok mu? Alışveriş listesini açın, evde eksik olan her şeyi ekleyip tek tıkla eşinize gönderin. İş bölümü şarttır.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'Sessiz kitap okuma 📖', 'Bu akşam odada yalnızca kitap sayfalarının sesi duyulsun. İkiniz de yatağa uzanın; o kendi resimli kitabına baksın, siz de sessizliğin içinde dinlenin.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'Tehlikeli atlayışlar 🧗‍♂️', 'Kanepenin tepesinden yere atlamaya mı çalışıyor? Motor becerilerine fazlasıyla güveniyor. Yasaklamak yerine yere yumuşak yastıklar koyarak güvenli bir atlama alanı oluşturun.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'Kuralları ihlal etme testi ⚠️', 'Yapmamasını söylediğiniz hâlde gözlerinizin içine bakarak aynı davranışı mı sergiliyor? Amacı sizi kızdırmak değil, sınırlarınızın ne kadar tutarlı olduğunu sınamak. Kurallarınızda tutarlı olun.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'Ev dağınık kalsın 🌪️', 'Her gün aynı oyuncakları toplamaktan yoruldunuz mu? Bugün toplamayın! Evin dağınık olması dünyanın sonu değil, ancak annenin psikolojik olarak tükenmesi ciddi bir durumdur.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'Bugünün akıllı masalı 🪄', 'Akıllı masallara özel bir konu verin: Oyuncaklarını toplamayı seven sihirli ayıcık. Belki bu hikâye yarınki temizlikte size yardımcı olur!'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'Babanın rutinleri 👨‍🍼', 'Çocukların babalarıyla kendilerine özgü rutinleri olur. Bu akşamki uyutma sürecini babanın eğlenceli kurallarına bırakın ve odanın dışında sessizce çayınızı için.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'Renkleri keşfetmek 🎨', '“Bu kırmızı, bu mavi” diyerek renkleri doğru şekilde gruplandırıyor mu? Bilişsel gelişimde büyük bir ilerleme! Gelişim takipçisinde bu ayrıntıyı gururla işaretleyin.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'Mutfakta birlikte 🧑‍🍳', 'Sizinle birlikte bir şeyler yapmak mı istiyor? Sağlıklı tariflerden kolay bir kek seçin; unu veya suyu eklerken size yardım etmesine izin verin. Ortalık kirlense de eğlence garantili.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'Gecenin desibeli 🤫', 'Sokaktan gelen sesler derin uykuya dalmasını engelliyor mu? Ses ölçer ile odayı analiz edin.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'Sanatçı iş başında 🖍️', 'Duvarlar ve kapılar bazen onun tuvaline dönüşebilir. Kızmak yerine büyük bir karton bulup yere serin ve “Burası senin” deyin. İsteğini doğru yöne yönlendirin.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'Soru yağmuru 🤖', '3 yaşına yaklaşan çocuğunuzun davranışlarıyla ilgili sorularınız bitmiyor mu? Anacan AI, sizin için 7/24 uyanık olan dijital çocuk doktoru ve psikologdur. Yazın ve anında yanıt alın.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'Duygularınızı serbest bırakın 📝', 'Kendinizi çok yalnız ve anlaşılmamış mı hissediyorsunuz? Bu son derece doğal bir duygudur. Duygu günlüğüne hislerinizi içtenlikle yazın.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'Kendi benliğini keşfediyor 👑', '“Ben!”, “Benim!” sözleri dilinden düşmüyor. Benmerkezcilik döneminin en belirgin zamanıdır. Onun bu bireyselliğini saygıyla karşılayın; bu, gelişimin doğal bir aşamasıdır.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'Sağlıklı tatlı arayışı 🍎', 'Market bisküvilerine son! Bebek tariflerinde evde 10 dakikada hazırlanan hurmalı ve elmalı sağlıklı bisküvileri keşfedin, bebeğinizin iştahını artırın.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'Ayrılık korkusu geri mi dönüyor? 🌌', 'Odadan çıkar çıkmaz arkanızdan ağlıyor mu? Beyaz Sesler''den kalp atışı sesini açarak ona güven hissi verin ve uykuya geçmesine yardımcı olun.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'Hava değişken ⛅', 'Gezintiye çıkmak istiyorsunuz ama dışarıdaki hava yanıltıcı mı? Hava ve giyim aracına girerek onu terletmeden koruyacak en doğru kombini belirleyin.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'Takım gururu 🥂', 'Zorlu bir haftayı geride bıraktınız. Eşinizle karşılıklı oturup “Biz bu çocuğu gerçekten iyi yetiştiriyoruz.” diyerek birbirinizi motive edin.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'Cümlelerle masal anlatıyor 🗣️', 'Resimli kitaba bakıp kendi cümlelerini kurarak masal mı uyduruyor? Hayal gücü ve konuşma becerisi aynı anda şahlanıyor! Onu dikkatle dinleyip alkışlayın.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'Annelerin dayanışması 💬', 'Tuvalet eğitimi sizi bunalttı mı? Hemen Anacan Topluluğuna katılın. Oradaki diğer annelerin başarı ve başarısızlık hikâyeleri size güç verecek.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'Karanlık korkusu 🌙', 'Odasının karanlığından mı korkuyor? Yatağının yanına küçük bir gece lambası koyun, ancak odanın melatonin salgılanmasına yetecek kadar karanlık olduğundan emin olun.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'Kıyafetini kendi seçmek istiyor 👗', 'Dolabı açıp birbiriyle uyumsuz renkleri ve mevsimlik kıyafetleri kombinlemek mi istiyor? Bağımsızlığını destekleyin, ancak kontrolü elinizde tutmak için ona yalnızca 2 seçenek sunun.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'Kahve takviyesi ☕', 'Gündüz uykuları artık yok ve siz gün boyu dinlenemiyor musunuz? Onu 15 dakikalığına güvenli bir etkinlikle baş başa bırakın ve mutlaka kahve molanızı verin.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'Ağır yük, inatçı yürek 🛒', 'Gezintiden dönerken en ağır eşyayı veya poşeti mutlaka kendisi mi taşımak istiyor? Yerinden kıpırdatamasa bile yardımınızı kesin bir dille reddediyor. Bırakın biraz uğraşsın ve gücünü denesin.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'Küçük filozof 🤔', 'Gözleri tam kapanırken birden başını kaldırıp “Anne, güneş uyumaya nereye gidiyor?” gibi felsefi bir soru mu sordu? Beyni, uykuya geçiş anında bile dünyayı anlamlandırmaya devam ediyor. Fazla ayrıntıya girmeden kısa ve masalsı bir cevap verin.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'Mucizevi talepler 🪄', 'Bu sabah uyanır uyanmaz bağırarak dilimlenmiş elmayı yeniden bütün hâle getirmenizi mi istedi? Evet, 3 yaşa yaklaşırken çocukların mantığı fizik kurallarına meydan okuyor.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'Hayvanları taklit ediyor 🐶', 'Yalnızca seslerini çıkarmakla kalmayıp köpek gibi emekliyor, kedi gibi kıvrılıyor mu? Beden dili ve hayal gücü birleşiyor. Siz de onunla birlikte halının üzerinde bu oyuna katılın.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'Yemek seçiciliği 2.0 🥣', 'Düne kadar sevdiği çorbayı bugün reddediyor mu? Zorlamayın. Sağlıklı tarifler bölümünde sebzeleri gizleyebileceğiniz farklı alternatif tarifler bulun.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'Sihirli uyku hikâyesi 🪄', 'Akıllı Masallarda “Üç yaşına hazırlanan cesur kahraman”ın hikâyesini oluşturarak ona büyüdüğünü ve güçlendiğini hissettirin.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'Seni arıyorum! 👀', 'Odadan çıktığınız anda yine ağlamaya mı başlıyor? Ayrılık kaygısı bazen yeniden ortaya çıkabilir. Sesinizle uzaktan ona güven verin; ancak her an gözünün önünde olmak zorunda değilsiniz.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'Masalın sonunu o söylesin 📖', 'Bu akşam masal okurken cümleleri yarım bırakın, gerisini o tamamlasın! Bu harika hayal gücü gelişimini destekleyen diyalog yöntemlerini Anacan AI''a sorun.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'Liste şart 🛒', 'Doğum günü için gerekenler unutulmasın! Zihninizi yormayın; her şeyi hemen Alışveriş listesine yazın ve eşinizle senkronize edin.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'Pantolonlar yine kısaldı! 📏', 'Gömleklerin kolları dar mı geliyor? Bebeğiniz fiziksel bir büyüme atağı geçiriyor. Güncel ölçümleri Kilo Takibi''ne girin ve büyüme grafiğine gururla bakın.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'Komik telaffuzlar 🗣️', 'Bazı kelimeleri o kadar sevimli ve yanlış söylüyor ki! Bu altın değerindeki anları kaçırmayın. Bebek Albümü''ne sesli video olarak yükleyin ve gelecekte birlikte gülün.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'Çorap dikişi faciası 🧦', 'Bu sabah büyük bir krizle uyandınız: Çorabın içindeki dikiş parmağına değiyor! 3 yaşına doğru duygusal hassasiyet zirveye ulaşır. Mantık aramayın; çorabı ters giydirin ve bu anlamsız krizin 10 saniyede nasıl sona erdiğini izleyin.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'Su birikintisi avcısı 🌧️', 'Yağmurdan sonra dışarı çıktınız ve o, doğruca çamurlu su birikintisine mi atladı? Üstü başı kirlendi ama gözlerindeki o keşif ışığına bakın. Hava durumunu ve kıyafetlerini önceden düşünerek ona yağmur çizmesi giydirin; bırakın çocukluğunu yaşasın.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'Oyuncaklara İyi Geceler 🧸', 'Yatma vakti geldi ama o, odadaki her arabaya ve oyuncak ayıya tek tek veda ediyor. Bu, uykuyu erteleme sanatının başyapıtıdır. Zamanlayıcıyı kurun ve 3 dakika içinde hepsine aynı anda veda etme kuralını uygulayın.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'En tuhaf nesne 🥄', 'Bir sürü pahalı oyuncağı var ama o, mutfakta bir kepçe bulmuş; bütün akşam onunla dolaşıyor, hatta onu uyutuyor. Çocuk beyninin takıntılarını açıklamak mümkün değildir. Engel olmayın, bırakın o kepçeye sevgisini versin.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'Çorbanın içindeki cerrah 🥣', 'Yemeğini yemiyor, yalnızca içindeki küçük soğan veya pirinç tanelerini cerrah titizliğiyle ayırıyor. Sebzeleri püre hâline getirip görünmez yapmanın zamanı geldi. Sağlıklı tarifler bölümünde annelerin en yaratıcı, sebzeleri gizleyen tariflerine göz atın.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'Dolabı ben açacağım! 🚪', 'Sabah dolabın kapağını siz açtınız diye ağlayıp onu yeniden kapattırdı ve kendisi mi açtı? Evet, kontrol tamamen onda olmalı. Bu masum “Ben yapacağım” çabalarına gülümseyin; iradesini sınamaya çalışıyor.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'Sessizliğin dijital ölçümü 🤫', 'Sonunda uyudu! Eve çöken sessizliğe inanamıyorsunuz. Ses ölçüm aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarken zihninizin yavaş yavaş dinlendiğini ve yeniden şarj olduğunu hissedin.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', '“Sen kötü bir annesin!” darbesi 💔', 'İstediği şekeri vermediniz diye size “Sen kötüsün” mü dedi? Kalbiniz kırılmasın. O, duygularını henüz doğru kelimelerle ifade edemiyor; aslında “Çok öfkeliyim” demek istiyor. Göz teması kurun ve duygusunu kabul edin.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'Görünmez karıncayla sohbet 🐜', 'Balkonda veya parkta yerdeki bir karıncaya eğilip büyük bir ciddiyetle bir şeyler mi anlatıyor? Hayal gücü ve şefkat duygusu aynı anda çalışıyor. Bu harika anı hemen Bebek fotoğraf çekimi ile kaydedip arşivinizin en tatlı köşesine ekleyin.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'Babanın uçuş modu ✈️', 'Evde enerjisini atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Babası onu havaya kaldırıp uçak gibi gezdirdiğinde kahkahalar odayı doldurur ve biriken tüm fiziksel gerginlik saniyeler içinde yok olur.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'Yerde yuvarlanma özgürlüğü 🌪️', 'Marketin ortasında kendini yere mi attı? Onu kaldırmaya veya çevrenizdekilere açıklama yapmaya çalışmayın. Derin bir nefes alın. Anacan Topluluğuna katıldığınızda binlerce annenin aynı utandırıcı ama doğal anı yaşadığını göreceksiniz.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', '“Bana bakma!” inadı 🙈', 'Ona bakıp gülümsediğiniz için “Bana bakma!” diyerek ağlıyor. Anlamsız mantığın zirvesi! Yüzünüzü yana çevirip bu komik kaprisin geçmesini bekleyin; bazen onlar da ne istediklerini bilmiyor.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'Işıkların büyüsü 🌙', 'Karanlıktan korkmaya mı başladı? Odayı tamamen karartın ve küçük bir el feneriyle tavanda ışık oyunları oynayın. Korktuğu karanlığı eğlenceye, uyku öncesi küçük bir keşif macerasına dönüştürün.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'Pijama aşkı 👗', 'Sabah uyandı ve üzerindeki lekeli pijamayı çıkarmayı kesinlikle reddediyor. Evden çıkmayacaksanız mücadele etmeyi bırakın. Bazen annenin psikolojik rahatlığı, çocuğun derli toplu görünmesinden çok daha önemlidir.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'Cepten çıkan hazineler 🍁', 'Parktan döndünüz; cebinden 3 taş, 1 kurumuş yaprak ve bir çöp çıktı. Sizin için çöp, onun içinse bir hazine. Bunları eve saçmak yerine bir koleksiyon kutusu hazırlayın ve orada biriktirmesine izin verin.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'Duygusal yükü boşaltmak 📝', 'Evinizde kimse ne kadar yorulduğunuzu görmüyor mu? Duygu günlüğü en sessiz sırdaşınızdır. Bugün sizi çileden çıkaran tüm ayrıntıları oraya yazın ve zihninizin nasıl hafiflediğini görün.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'Protein alımı nasıl? 🍗', 'Hareketli kaslar için protein şarttır. Beslenme takip aracıyla günlük besin dengesini ölçün ve menüsünü zenginleştirin.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'Kendim yürüyeceğim! 🚶‍♂️', 'Sokakta elinizi tutmayı kesinlikle reddedip özgürlüğünü ilan ediyor. Güvenli yerlerde ona bu özgürlüğü tanıyın. Gözünüz üzerinde olsun, bırakın dünyayı kendi adımlarıyla keşfetsin.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'Mutfağın küçük aşçısı 🧑‍🍳', 'Siz hamur açarken mutlaka yanınıza bir sandalye çekip işe karışıyor mu? Eline küçük bir parça hamur verin. Her yer un olacak ama onun o ciddi, işine odaklanmış yüz ifadesi tüm bu temizliğe değer.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'Ekransız mola zorluğu 📺', 'Bugün işleriniz nedeniyle daha fazla çizgi film izlemesine izin verdiniz ve vicdan azabı mı çekiyorsunuz? Kendinizi suçlamayın. Her gün mükemmel bir anne olamazsınız. Bazen dijital bir dadı sizi psikolojik olarak tükenmekten kurtarır.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'Canlı ses kayıt cihazı 🎙️', 'Dün eşinizle konuşurken kullandığınız rastgele bir sözü bu sabah oyuncağına mı söylüyor? Kelime dağarcığı inanılmaz bir hızla genişliyor ve sizi tamamen taklit ediyor. Ona örnek olduğunuzu unutmayın.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'Fısıltı taktiği 🤫', 'Yatakta o kadar hareketli ki bir türlü uyumuyor. Sesinizi yükseltmek yerine aniden alçaltıp fısıldayarak konuşun. Çocuğunuz sizi duymak için dikkatini topladığında beyni otomatik olarak uyku moduna geçer.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'Oksijen ihtiyacı ⛅', 'Dört duvar arasında kalmak zihninizi uyuşturdu ve evde krizler yaşanıyor. Hava durumuna bakıp uygun kıyafetleri seçin. Dışarı çıkıp sadece koşmak hem onun enerjisini atmasını sağlayacak hem de size yeni bir soluk getirecek.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'Masalın kontrolü onda 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masalları açın; başkahramanı çocuğunuz, kurtarılacak yeri ise onun odası yaparak sıra dışı, sakin ve özgür bir uyku seansı oluşturun.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'Avangart yaratıcılık 🖍️', 'Birkaç saniyelik sessizliğin sonu tehlikeli bitti. Odaya girdiğinizde kollarına veya karnına keçeli kalemle dövme yaptığını gördünüz. Derin bir nefes alın. İnce motor becerileri gelişiyor, cildi ise nasıl olsa yıkanır.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'Su, her yerde su! 💧', 'Suyu bardağa mutlaka kendisi doldurmak istedi. Döktü, her yer ıslandı. Ama siz bezi alıp orayı temizlemeye çalışan o küçük ellerine bakın. Hata yaparak sorumluluk almayı öğreniyor, sinirlenmeyin.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'Sıra babada 👨‍👧', 'Annelik hiç bitmeyen bir maraton değildir. Bırakın bugünkü park koşusunu baba yönetsin, siz de kanepede yalnızlığın tadını çıkarın.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'Takım masajı 💆‍♂️', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birbirinize omuz masajı yapın. Siz yalnızca ebeveyn değilsiniz; bu evin ve birbirinizin en büyük destekçisisiniz.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'Ben yoruldum... 🔋', 'Herkes sizden enerji bekliyor ama piliniz bitti. Bugün hiçbir şey pişirmeyin; dışarıdan sipariş verin veya en kolay makarnayı haşlayın. Süper Kahraman olmak, her şeyi tek başınıza yapmak zorunda olduğunuz anlamına gelmez.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'Küvette huzur 🛀', 'Bütün gün “istemiyorum”larla geçti. Ilık bir banyo yalnızca hijyen için değil, onun gerilmiş sinir sistemini sıfırlamak içindir. Suyun sesini dinleyin, odanın havası anında değişecek.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'Merdivenleri tek başına çıkmak 🧗', 'Merdivenleri desteksiz çıkmaya mı çalışıyor? Motor becerileri zirvede! Kenardan izleyin, müdahale etmeyin. Bu bağımsız anı Bebek fotoğraf çekimiyle ölümsüzleştirin.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'Kutunun büyülü cazibesi 📦', 'Ona pahalı ve sesli bir oyuncak aldınız ama gidip 1 saattir oyuncağın kutusuyla oynuyor. Çocuk beyni hazır yapılar yerine hayal kurabileceği basit nesneleri sever. İzleyin ve öğrenin.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'Doğal beyaz sesler 🤫', 'Uykuya daldığı anlarda hassasiyeti artar. Sokaktan gelen sesleri etkisiz hâle getirmek için odada Ses ölçerin arka plan sesini etkinleştirin ve ortama kalıcı bir huzur katın.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'Bunu ben yapacağım! 👕', 'Sabahları giyinmek büyük bir krize mi dönüşüyor? İnatçılıkla başa çıkmanın ve ona seçim hakkı tanımanın püf noktalarını hemen Anacan AI''dan öğrenin.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'Kitabı yırtmak değil, okumak 📖', 'Akşam masalı sırasında sayfaları yırtıyor mu? Okuma alışkanlığına zarar vermeden bu sorunu nasıl çözebileceğinizi Bloglar bölümünde hemen okuyun.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'Uyku düzenini analiz edelim ⏱️', 'Akşam uyanık kalma süresi çok mu uzadı? Uyku zamanlayıcısını başlatın ve düzeni takip edin. Belki de gündüz uykusunu 15 dakika kısaltmanın tam zamanıdır.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'Kum ve çamur terapisi 🏖️', 'Kirlenmekten korkmayın! Kinetik kum veya duyusal oyunlar için en iyi ürünleri hemen Önerilen Ürünler bölümünde keşfedin.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'Bu sizin emeğiniz 🌟', 'Her gün öğrendiği yeni beceri, attığı her kendinden emin adım sizin emeğinizin eseri. Duygu Günlüğünü açın ve bugün kendinizle gurur duymanızı sağlayacak bir not yazın!'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'Numaradan ağlama 🎭', 'İstediğini elde etmek için gözyaşı dökmeden, sesini titreterek numaradan ağlıyor mu? Sizi manipüle etmeyi öğreniyor. Gülmemek için kendinizi tutun ama taviz de vermeyin. Sınırlarınız net olsun.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'Ansızın gelen Seni seviyorum 💖', 'Odanın ortasında oyun oynarken ansızın size bakıp Seni çooook seviyorum dedi mi? Tüm uykusuz gecelere ve yorgunluğa değer! Bu anın getirdiği o derin, eşsiz huzurun tadını çıkarın.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'Babanın çılgın dansı 🕺', 'Akşamüstü patlak veren huysuzluğun üstesinden yalnızca baba gelebilir. Müziğin sesini sonuna kadar açıp çocukla birlikte odada zıplayarak dans etsinler. Siz de bu neşeli enerjiyi uzaktan gururla izleyin.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', 'Yalnızca kendinize ait 10 dakika ☕', 'O çizgi filme dalmışken bulaşık makinesini doldurmaya koşmayın! Kanepeye uzanın. O kahveyi sonunda sıcacık için ve 10 dakika boyunca annelik rolünden çıkıp sadece kendiniz olun.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'Marketteki çikolata sürprizi 🛒', 'Markete gitmeden önce Alışveriş Listesini açtınız ve arkanızdan gelip telefonun ekranına dokunarak oraya bir şeyler karaladığını gördünüz. Evet, dijital hayatınızı da taklit ediyor!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'Uydurma dil bilgisinin tadı 🗣️', 'Ben gittiydim, O geliyormuştu gibi tuhaf ama çok tatlı zaman kalıpları keşfetti. Kelime dağarcığı fırtına gibi gelişiyor! Gelişim takipçisine kendine özgü bu özel dilini arşivlemek için kaydedin.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'Yatağın altında ne var? 👻', 'Karanlıkta canavarlar olduğuna mı inanıyor? İçine yalnızca su doldurulmuş bir şişe alın ve Korku kovucu sprey diyerek odaya püskürtüp onu ikna edin. Hayal gücünü hayal gücüyle alt edin.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'Sabah 5''te parti başladı! ⏰', 'Güneş henüz doğmadı ama o, yatakta zıplayarak güne başladı. Siz hâlâ uykulu olsanız da o dünyayı fethetmeye hazır. Ona katılın, bu çılgın enerjinin sizi de uyandırmasına izin verin.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'Kreş mi arıyorsunuz? 🏫', '3 yaşa yaklaşırken kreş düşüncesi aklınızda dönüp duruyor ama karar veremiyor musunuz? Tek başınıza düşünmekten yorulduysanız Anacan Topluluğuna katılın ve diğer annelerin gerçek kreş deneyimlerini okuyun.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'Duyguları kaydetme zamanı 📝', 'Biri size evdesin, neye yoruluyorsun mu dedi? Hemen Ruh Hâli Günlüğünü açın ve tüm öfkenizi parmaklarınızla ekrana dökün. Yapmacık bir şekilde gülümsemek yerine gerçek duygularınızı yazmak terapi gibidir.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'Sebze düşmanlığı devam ediyor 🥦', 'Çorbadaki o küçücük havuç parçasını yine görüp yemeği reddetti mi? Beslenme planından yararlanarak sebzeleri püre hâline getirip köftenin içine gizlemek, annelerin en eski ve faydalı yöntemlerinden biridir. Deneyin!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'Küçük doktor sizi muayene ediyor 🩺', 'Oyuncak stetoskopunu alıp göğsünüze koyuyor ve nefes alın diyor. Siz hastasınız, o ise başhekim. Bu oyuna katılın; uzanın ve 5 dakikalığına da olsa tedavi sırasında gözlerinizi kapatıp dinlenin.'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'Seslerin sınırı 🌙', 'Sonunda uykuya daldı. Artık evdeki en küçük ses bile sizi tedirgin ediyor. Işıkları kısın, televizyonu kapatın ve karanlığın ortasındaki o nadir sessizliğin tadını doyasıya çıkarın.'),
  ('19419b9a-b627-43ae-9610-e43b875264b1', 'Kararlı emekleme ve kaçış 🐢', 'Artık yürümekle yetinmiyor; hızla koşup sizden saklanıyor, kapıların arkasından bakıyor. Odadaki engelleri kaldırın ve siz de kocaman bir çocuk enerjisiyle bu kovalamaca oyununa katılın.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını kolaylaştırmak için odadaki tüm gereksiz ışıkları ve mavi ışık yayan ekranları kapatın. Uyku hormonu (melatonin), karanlık ve teknolojiden uzak bir ortamda daha kolay salgılanır.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'Yapay zekâ, gerçek cevap 🤖', 'Çocuğunuzda tuhaf bir alışkanlık ortaya çıktı (örneğin, tırnak yemek) ve internetteki forumlar sizi korkuttu mu? Durun. Anacan AI''a bunun çocuk doktorlarınca doğrulanan gerçek nedenini sorun ve içinizi rahatlatın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656'::uuid, 'Kendinizi unutmak yasak! 🥗', 'Onu doyurmak için 3 farklı menü düşündünüz, peki siz yine aç mı kaldınız? Sağlıklı tarifler arasından 10 dakikada hazırlanan, demir ve kalsiyum açısından zengin bir öğle yemeği seçin ve kendinize değer verdiğinizi hissedin.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'Ani öfke patlaması 💥', 'Oynarken birden öfkelenip oyuncaklarını mı fırlattı? O henüz duygularını yönetemiyor. Bağırmak yerine, Öfkelendiğini görüyorum, gel birlikte derin bir nefes alalım diyerek empati kurun.'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'Çiftlerin şampanyası 🥂', 'Çocuk uyudu. Şampanya olmasa da bardaklara sıcak çay doldurun ve eşinizle Bu zorlu günü de sağ salim atlattık diyerek bardaklarınızı tokuşturun. Siz bu evin en güçlü komutanlarısınız.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', '3 yaşına son 5 gün! 🚀', 'İnanılmaz! O kocaman 3 yaşına yalnızca 5 gün kaldı. Evin içinde kendi kurallarını koyan bu küçük bireyi siz büyüttünüz. Anacan''dan pasta siparişini hemen verin ve hazırlıklara başlayın.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'Babanın uçuş modu ✈️', 'Evde enerjisini atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Babası onu havaya kaldırıp uçak yaptığında kahkahalar odayı kaplar ve fiziksel gerginlik saniyeler içinde kaybolur.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'Annenin molası ☕', 'Çocuk dilinde konuşmaktan yoruldunuz. Anne Dostu Mekânlar arasından çocuk köşesi olan bir kafe bulun, kahvenizi için ve diğer annelerle dertleşip biraz nefes alın.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'Parktaki özgürlük 🌳', 'Dört duvar arasında kalmak onu hırçınlaştırıyor. Onu parka çıkarın; bırakın kuma bulansın, koşarken düşsün, taş toplasın. Doğadaki bu özgürlük, beynine en iyi gelen gelişim ilacıdır.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'Melatonin fabrikası 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm gereksiz ışıkları ve tablet ekranlarını kapatın. Melatonin yalnızca sakin, loş ve ekransız bir ortamda hızla salgılanır.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'Hayalî misafirler geldi ☕', 'Odada tek başına görünmez arkadaşlarıyla konuşup onlara çay mı dolduruyor? Bu, hayal gücü gelişiminin zirvesidir! Bu muhteşem senaristi uzaktan gururla izleyin; o artık kendi evrenini yaratıyor.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'Size açıklayayım! ☝️', 'Sizin zaten bildiğiniz bir şeyi, son derece ciddi ve bilmiş bir yüz ifadesiyle gelip size anlatıyor. O, bilgisini test ediyor. Gülmemek için kendinizi zor tutsanız da onu büyük bir ciddiyetle dinleyin.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'Duygu günlüğünde itiraf 📝', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının hayatlarını kaydırmak yerine Duygu günlüğünü açın ve bugün yaptığı en komik şeyi geleceğe bir anı olarak kaydedin. Dijital terapi işe yarıyor.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'Gündüz uykusu isyanı 🥱', 'Yatağa gitmeyi kesinlikle istemiyor mu? 3 yaşına yaklaşırken bu direnç çok yaygındır. Zorlamayın, ağlatmayın. Odadaki ışıkları azaltıp Sessizce kitaplara bakma saati ilan ederek rutini değiştirin.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'Ayrılık kaygısı yeniden mi? 🥺', 'Odadan bir saniyeliğine çıktığınızda bile arkanızdan ağlıyor. Ayrılık kaygısı 3 yaş civarında bazen geri dönebilir. Her seferinde ona seslenip burada olduğunuzu, Mutfaktayım, geliyorum diyerek uzaktan güven verin.'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'Sessizliğin kanıtı 🤫', 'Gürültülü bir günün ardından çocuk uyuduğunda Ses ölçer ile odanın sessizliğini ölçün. Sıfıra yaklaşan o rakamları görmek bile annenin beyninde en iyi görsel masaj etkisini yaratır.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'Mükemmellik baskısı 🛑', 'Başka çocuklar artık renkleri sayıyor ama sizin çocuğunuz istemiyor mu? Karşılaştırmayı hemen bırakın! Her çocuğun gelişim saati farklıdır. Çocuğunuz kendi hızında ilerliyor ve bu tamamen normal.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'Zafer hazırlığı 💆‍♂️', 'Çocuk uyuduktan sonra günün stresini atmak için eşinizle birbirinize omuz masajı yapın. Yarınki 3 yaş kutlaması ve koşuşturma için ikinizin de mutlaka enerjik olması gerekiyor!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'Bugün kaç kez Hayır dediniz? 💆‍♀️', 'Çok yoruldunuz, değil mi? Derin bir nefes alın. Tüm duygularınızı Duygu Günlüğü''ne dökün, vicdan azabını bir kenara bırakın ve sadece dinlenin.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'Bezi kuru mu uyandı? 🩲', 'Sabah bezini değiştirirken kuru olduğunu fark ettiniz mi? Tuvalet eğitimine başlamak için en doğru zamanı ve psikolojik yöntemleri hemen Anacan AI''a sorun.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'Kek sevgisi 🧁', 'Canınız tatlı mı istiyor? Markete koşmayın. Bebek tariflerindeki şekersiz, muzlu ve yulaflı 10 dakikalık ev kekiyle Beslenme takibi aracındaki sağlık puanınızı koruyun.'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'Annelerin destek grubu 💬', 'Zor bir gün geçiriyor ve her şey gözünüzde büyüyor mu? Anacan Topluluğundaki deneyimli annelerin tavsiyeleri, hiçbir kitapta yazmayan, hayatın içinden en gerçek çözüm yollarıdır. Onlardan ilham alın.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', '3 yaş arifesi! 🎂', 'Yarın büyük gün! Karnınızda ilk tekme attığı günden bu yana ne kadar uzun bir yol katettiniz. Bugün onu uzun uzun seyredin, kıyafetlerini seçin ve yarınki bebek fotoğraf çekimi için telefonunuzda yer açın.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'Partnerinizle kutlayın 🥂', '3 yılın yorgunluğunu, gözyaşlarını ve sevincini bu akşam eşinizle birlikte kutlayın. Masaya bir mum koyun; sarsılmaz bir ekip olarak kazandığınız zaferi büyük bir sevinçle, gülümseyerek alkışlayın!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'Muhteşem 3 yaş! 👑🎉', 'Tebrikler! Artık 3 yaşında! Tam 1095 gündür bu fırtınalı, yorucu ama dünyanın en keyifli yolunda yürüyorsunuz! Bu özel günü hemen bir şölene dönüştürün ve sevincinizi herkesle paylaşın!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'Siz mükemmelsiniz! 📈', 'Çocuğunuz ne kadar uzun bir yol katetti! İlk günlerin o hassas korkusu, yerini artık büyük bir güvene ve deneyime bıraktı. Bu 3 yılı büyük bir gururla geride bıraktınız! Siz gerçekten harika bir annesiniz!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'Kutlama sonrası gerçekler 🚀', 'Dünkü büyük kutlamanın ardından bu sabah yine etrafa saçılmış oyuncaklara ve Ben giyinmek istemiyorum! itirazlarına uyandınız. Hayat kendi ritmine döndü. Derin bir nefes alın; siz bu kaosun en iyi yöneticisisiniz.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'Masalın kontrolü onda 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masalları açın; başkahramanı çocuğunuz, kurtarılacak yeri de onun odası yaparak sıra dışı, sakin ve özgür bir uyku seansı oluşturun.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', 'Kendim yapacağım ısrarı 🛑', 'Ayakkabısının bağcıklarını kendi bağlamak istiyor ve bu 10 dakikanızı mı alıyor? Acele etmeyin, ona zaman tanıyın. Denemesi ve yanılması, gelecekteki problem çözme becerisinin temelidir.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'Evin kaosuyla barışmak 🌪️', 'Odanın her yeri oyuncakla mı dolu? Önemli olan temizlik değil, onunla geçirdiğiniz bu yaramazlık dolu anlardır. Oyuncaklar yarın da orada olacak, kendinizi yormayın. Bazen dağınıklığa teslim olmak en iyi dinlenme biçimidir.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'Babanın gizli taktiği 👨‍🍼', 'Günün yorgunluğu size fazlasıyla yetti. Akşam çocuğu uykuya hazırlama ve dişlerini fırçalatma sürecini babanın eğlenceli oyunlarına bırakın; siz de bir köşede sessizce dinlenin.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'Tuhaf en iyi dost 🥄', 'Bunca pahalı oyuncak varken mutfaktan bir silikon spatula bulup bütün gün onunla geziyor, hatta onu uyutuyor mu? Çocuk beyni inanılmazdır. Engel olmayın, bırakın spatulayı sevsin.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'Fısıltıyla uyku 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlayan ve gürültüyü unutturan en doğal ve güçlü yöntemlerden biridir.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'Listedeki sürpriz 🛒', 'Markete gitmeden önce Alışveriş listesini açtınız ve arkanızdan gelip telefonun ekranına dokunarak listeye çikolata eklediğini gördünüz. Evet, teknolojiyi sizden daha iyi biliyorlar!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'Amaçlı yıkım 🧱', 'Büyük bir emekle kule yapıyor, ardından gülerek tek hamlede yıkıyor. Fizik kurallarını ve neden-sonuç ilişkisini öğreniyor. Sinirlenmeyin; yıkılan kuleler, beyninde kurulan yeni nöral bağlantılardır.'),
  ('aa798243-c44e-4178-957c-647030916048', 'Hava durumu uyarısı ⛅', 'Gezintiye çıkarken pencereden bakıp yanılmayın. Hava durumu ve giyim yardımcısıyla dışarıdaki gerçek rüzgâr ve sıcaklığa en uygun kombini belirleyin; evden rahat ve hazırlıklı çıkın.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'Çizgi film eleştirmeni 📺', 'İzlediği çizgi filmi kendine özgü dil bilgisiyle size anlatıyor, kimin nereye gittiğini ciddi ciddi açıklıyor. Onu dikkatle ve şaşırmış gibi dinleyin. Kendisini dünyanın en akıllı insanı gibi hissetsin.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'Karanlığın gücü 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin, yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'Seçici gurmeler 🥦', 'Dün sevdiği yemeğe bugün hayır mı diyor? 3 yaşındaki yemek seçme davranışları normaldir. Sağlıklı tarifler arasından onu eğlendirecek renkli ve farklı sunumlar bulun.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'Hayal gücü uçuşta 🚀', 'Artık sadece oynamıyor, senaryolar kuruyor! Karton kutu bir anda uzay gemisine dönüşüyor. Bu bilişsel sıçramayı gelişim takipçisine gururla kaydedin ve oyununa katılın.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'Günün özeti 🌙', 'Uyumadan önce ışıkları azaltın ve bugün en çok neye güldüğünüzü konuşun. Bu küçük uyku öncesi sohbetleri, kendini ifade etme becerisini geliştirir.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'Görünmez takipçi 👻', 'Duvardaki gölgesinden korkup ağlamaya mı başladı? Gölgelerle mücadele, 3 yaşın en komik klasiklerinden biridir. Işıkları kapatın, el fenerini açın ve gölgeleri dans ettirerek bu korkuyu eğlenceli bir uyku ritüeline dönüştürün.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'Çamaşır dağından çadır ⛺', 'Yeni katladığınız temiz çamaşır yığınını dağıtıp kendine çadır mı kurdu? Sinirlenmeden önce o çadırın içine bir göz atın. Oradaki hayal dünyası ve çocuğunuzun sevinci, çamaşırları katlarken verdiğiniz emekten daha değerlidir.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'Etiket krizi 🏷️', 'Boynumu kaşındırıyor! Tişörtün arkasındaki o küçük etiket, bu sabahın en büyük düşmanı. 3 yaşında duyusal hassasiyet zirveye ulaşır. Tartışmayın, yalnızca o etiketi kesin ve güne huzur içinde başlama şansı verin.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'Banyoda batan gemiler 🛀', 'Suyla oynamak için banyoya girdiniz ve o, batmayan oyuncakları suya batırmaya çalışıyor. Fiziği keşfediyor! Bırakın sular etrafa sıçrasın; suyun enerjisi, gün boyu içinde biriken gerginliği de alıp götürecektir.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'Hayalî evcil hayvan 🐕', 'Odada olmayan bir köpeği veya kediyi okşayıp ona isim mi veriyor? Hayal gücü artık fiziksel sınırları aştı. Odanın bir köşesine görünmez bir su kabı koyun ve siz de bu tatlı hayale katılın.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'Buz kalıbında ziyafet 🧊', 'Ne yaparsanız yapın o sebzeleri yemiyor mu? Sunumu tamamen değiştirin. Sağlıklı atıştırmalıkları buz kalıbının (ice cube tray) küçük bölmelerine paylaştırın. Sıra dışı bir sunum her zaman iştah açar.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'Babanın uçuş modu ✈️', 'Evin içinde koşuyor ve yatağa girmeyi reddediyor. Babayı yardıma çağırın. Baba onu havaya kaldırıp uçak gibi uçurduğunda kahkahalar odayı doldurur ve biriken tüm fiziksel gerginlik, saniyeler içinde terle birlikte yok olur.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'Sabah 6''da yönetmenlik 🎬', 'Siz hâlâ uykudasınız, ama o başucunuzda durmuş: Sen ayı ol, ben tavşan! Yarı uykulu hâlde hırç hırç sesleri çıkararak bu sıra dışı tiyatroda rolünüzü oynayın. Annelik bazen en iyi oyunculuğunuzu sergilemenizi gerektirir.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'Topluluğun sırdaşlığı 💬', 'Çok yoruldunuz ve kimseye hiçbir şey anlatmak istemiyorsunuz. Anacan Topluluğuna girip yalnızca okuyucu olun. Diğer annelerin de benzer yorgunluklar yaşadığını görmek, yalnız değilim hissi vererek en iyi terapiye dönüşür.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'Sessizliğin dijital hazzı 🤫', 'Sonunda uykuya daldı! Eve çöken sessizlik o kadar derin ki kulaklarınız çınlıyor. Ses ölçer aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarak beyninizin yavaş yavaş nasıl toparlandığını görsel olarak hissedin.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', 'Markette Ben süreceğim! 🛒', 'Market arabasını mutlaka kendisi sürmek istiyor ve sonunda raflara çarpıyorsunuz. İradesini kırmamak için arabayı birlikte sürün. Bir şeyleri unutmamak için de uygulamadaki Alışveriş listesini açık tutun.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'Yarım kalan cümleleri tamamlayın 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaret edip sizin bulmanızı mı bekliyor? Evet, topu mu diyorsun? dediğiniz andaki rahatlamasını izleyin. Kelime dağarcığı büyüyor; yalnızca beyni, dilinden daha hızlı çalışıyor.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'Doğa detoksu şart 🌳', 'Dört duvar arasında enerjisi agresifliğe dönüşür. Hava ve kıyafet koşulları ne olursa olsun, uygun şekilde hazırlanıp onu mutlaka dışarı çıkarın. Toprağa dokunmak, yaprak toplamak sinir sistemini hemen sakinleştirir.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'Fısıltının mistik gücü 🌙', 'Masal okumaktan ses telleriniz yoruldu. Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlamanın en sakinleştirici yollarından biridir.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'Hayranlık uyandıran varlık 🎈', 'Bu uzun yolculukta hayran kalacak çok şey var. Örneğin, dün öğrendiği bir kelimeyi bugün felsefi bir cümlede kullanması! Bu günler bir daha yaşanmayacak.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'Gizli çikolata molası 🍫', 'Mutfak dolabının arkasında ondan gizlice çikolata yiyen anne, o glikoz sizin hakkınız. Kendinizi suçlamayın! O çılgın enerjiye dayanabilmek için sizin de şarj olmanız şart. Nefes alın ve çiğnemeye devam edin.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'Akıllı masalın kahramanı o 🪄', 'Bu akşam Akıllı masallardaki kahramana doğrudan çocuğunuzun adını verin. Masaldaki karakterin de dişlerini fırçalamayıp sonradan pişman olduğunu anlatarak değerleri dolaylı yoldan aşılayın.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'Tuvalet kâğıdı mühendisi 🧻', 'Birkaç dakikalık sessizlik... Sonra odaya girdiğinizde tuvalet kâğıdının tamamen açılıp eve yayıldığını görüyorsunuz! Sinirlenmek yerine kâğıtları toplayıp birlikte kardan adam yapın. Kaosu yaratıcılıkla yenin.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'Sen çocuk ol, ben anne 👩‍👧', 'Rol değiştirme oyunu başladı! Size “Buraya gel, yemeğini ye” diye talimatlar veriyor. Onun bu liderlik deneyimini keyifle kabul edin ve sesinizi çıkarmadan çocuğu rolünü oynayın.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'Yapay zekâ, gerçek çözüm 🤖', '3 yaşındaki bir çocuk neden birdenbire tırnak yemeye başlar? İnternetteki korkutucu, travmatik yazıları unutun. Anacan AI''a bunun yalnızca geçici bir stres tepkisi olup olmadığını sorarak bilimsel bir yanıt alın.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'Çift molası 🥂', 'Çocuk uyudu. Şimdi telefonları ve ev işlerini bir kenara bırakın. Eşinizle yüz yüze oturup yalnızca 20 dakika boyunca ödemeler ve çocuk dışında farklı bir konu hakkında konuşun. Siz aynı zamanda bir çiftsiniz!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'Cepten çıkanlar 🪨', 'Pantolonunu yıkarken cebinden 3 farklı boyda taş ve bir kestane kabuğu mu çıktı? Onun için bunlar dünyanın en değerli koleksiyonudur. Onları atmak yerine küçük bir kutuda biriktirip hazine sandığı oluşturun.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin (uyku hormonu) yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'Tükenmişlik hissi 🔋', 'Her şeye bağırmak mı istiyorsunuz? Gürültü beyninizi mi deliyor? Bu tam anlamıyla tükenmişliktir. Onu hemen güvenli bir yere bırakın (veya babasına verin), başka bir odaya geçin ve Duygu günlüğüne tüm stresinizi filtresizce yazın.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'Müzikle uyanış 🎶', 'Güneş henüz tam doğmadı ama o yatakta zıplayarak ritmik sesler çıkarıyor. Dünyanın en gürültülü ama en sevimli alarmı! Güne, onun bu bitmek bilmeyen enerjisine gülümseyerek başlayın.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'Duyguları kaydetme 📝', 'Çocuk uyuduktan sonra Duygu günlüğünü açın. Bugün yaptığı en komik, sizi en çok güldüren o absürt anı gelecek için kaydedin. Yıllar sonra okuduğunuzda gözleriniz dolacak.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'Sessizlik saati deneyi 🥱', 'Öğle uykusuna yatmak istemiyor ama gözlerinden uyku mu akıyor? 3 yaş direnci klasiktir. Zorlamayın; odanın ışıklarını azaltıp Sessizce kitaplara göz atma saati ilan ederek yeni bir rutin oluşturun.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'Babanın gizli silahı 🤡', 'Sizin yaptıklarınız artık işe yaramadığında babanın çıkardığı garip sesler ve komik yüz ifadeleri durumu hemen kurtarır. Akşam krizlerinde topu doğrudan ona atın, siz de kenardan dinlenerek izleyin.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'Bedeninizi dinleyin 🩸', 'Nedensiz yorgunluk ve ağlama isteği mi? Regl Takibini açın. Bedeniniz size sinyal veriyor. Sağlıklı tariflerdeki magnezyum açısından zengin atıştırmalıklarla kendinize şefkat gösterin.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'Seçici iştah 🍝', 'Yalnızca sevdiği 2-3 yemeği mi yiyor? Endişelenmeyin. Beslenme takip aracıyla haftalık dengeyi kontrol edin ve sofrada baskı kurmaktan kaçının.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'Masalın sonunu o bulacak 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masalları açın ve bu akşam hikâyeyi onun yönlendirmesine izin verin. Şimdi bu araba nereye gitsin? diye sorun; bırakın, uydurduğu tuhaf sonla uykuya dalsın.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'Mükemmel anne efsaneleri 🛑', 'Sosyal medyadaki çocuklar şimdiden şiir okuyor ama sizin çocuğunuz hâlâ kelimeleri mi karıştırıyor? Kıyaslamayı hemen bırakın! Her çocuğun gelişim süreci kendine özgü ve farklıdır. O, kendi hızında mükemmeldir.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'Ayakkabı giyme olimpiyatları 👟', 'Sağ ayakkabısını sol ayağına giydi ve kesinlikle çıkarmak istemiyor mu? Bırakın öyle kalsın. Özgürlük hissi ve ben yaptım gururu, doğru giymekten daha önemlidir. Bu, gelecekteki problem çözme becerisinin de temelidir.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'Görünmez çöp faciası 🗑️', 'Kendisinin bir kenara attığı, sizin de çöpe attığınız o gereksiz kâğıt parçasını arayıp ağlıyor! 3 yaş mantığı tam olarak budur. Onu geri getiremeyeceğiniz için dikkatini hemen daha ilgi çekici bir şeye yöneltin.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'Annenin şarj zamanı 🔋', 'Kendi başına yapboz yapıyor ve 10 dakikadır sessiz. Siz ise o anı evi toplamaya ayırmak istiyorsunuz. Hayır! Kanepeye uzanın. Akşama kadar bu tempoya dayanabilmeniz için sizin de pilinizin dolması gerekiyor.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'Karanlığa alışmak 🌙', 'Yatak odasında ışıklar söndüğünde huzursuz mu oluyor? Odanın bir köşesine küçük, sıcak renkli (sarı veya turuncu) bir gece lambası koyun. Odanın geri kalanı ise derin bir uyku için tamamen karanlık kalmalıdır.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'Sabah diktatörü iş başında 👑', 'Oraya siz oturmayın, ayıcığım oturacak! Kahvaltıda tüm masayı o yönetiyor. İradesini sertçe kırmadan, Tamam, ayıcığın orada otursun, ben de burada oturayım diyerek dengeyi koruyun.'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'Doğaya kaçış ⛅', 'Dört duvar hem onu hem de sizi gerginleştirdi. Hava durumu ve kıyafet aracını kontrol edip hemen parka koşun. Açık havada koşmak ve özgürce hareket etmek, en şiddetli küçük çocuk krizlerini bile bıçak gibi keser.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'Gecenin huzur anları 🛀', 'Bütün gün ben istemiyorumlarla geçti. Ilık bir banyo yalnızca hijyen için değil, onun gerilmiş sinir sistemini sıfırlamak içindir. Suyun sesi ve sıcaklığı tüm inatçılığı alıp götürecek.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'Marketteki unutkanlık 🛒', 'Hafızanıza güvenip markete gittiniz ve bebek bezini unutarak mı döndünüz? Böyle şeyler olur. Tüm ihtiyaçlarınızı hemen Alışveriş listesine yazmayı alışkanlık hâline getirin; bırakın uygulama sizin dijital hafızanız olsun.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'Anne, bana bak! 👀', 'Siz telefona bakarken veya bir işle uğraşırken gelip elinize vuruyor ya da önünüze geçiyor. O tamamen haklı; sizden bölünmemiş bir ilgi bekliyor. Yalnızca 5 dakika boyunca kesintisiz göz teması kurarak oynamanız onu sakinleştirecek.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'Sessizliğin kanıtı 🤫', 'Gürültülü bir günün ardından, çocuğunuz uyuduğunda Ses ölçer ile odanın sessizliğini ölçün. Sıfıra yaklaşan o rakamları görmek, o görsel sakinlik, annenin beyninde en güzel masaj etkisini yaratır.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'Zaman ne kadar hızlı akıyor!', 'O artık tamamen kendi kararları olan bir birey. Bu güçlü karakteri gelecekte sizi çok gururlandıracak. Bu günler bir daha yaşanmayacak; ona sevgiyle sarılın.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'Sebze cerrahı 🥦', 'Çorbadaki sebzeleri mikroskopla arıyormuş gibi kenara mı ayırıyor? Mücadele etmeyin. Sağlıklı tariflerde sebzeleri püre hâline getirip sosların içine gizlemenin en farklı ve lezzetli yollarını keşfedin.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'Babadan masaj seansı 💆‍♂️', 'Bugün çok uzun süre ayakta kaldınız, onun peşinden koşmaktan beliniz ağrıyor. Çocuğunuz uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin direğisiniz, direklerin de mutlaka güç toplaması gerekir.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'Karanlığa davet 🌙', 'Uykuya dalmasını hızlandırmak için odadaki tüm gereksiz ışıkları ve tablet ekranlarını kapatın. Melatonin, yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanarak uykuya geçişi kolaylaştırır.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'Kreş düşünceleri 🏫', 'Artık sosyalleşmeye daha fazla ihtiyaç duyduğunu mu hissediyorsunuz? Kreş için doğru zaman mı? Anacan Topluluğuna katılıp diğer annelerin gerçek uyum deneyimlerini okuyarak karar vermenizi kolaylaştırın.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'Size yardım edeyim! 🧽', 'Siz bulaşıkları yıkarken yanınıza mutlaka bir sandalye çekip suyla oynamak mı istiyor? Aslında yardım etmekten çok sürecin merkezinde olmak istiyor. Ona küçük, plastik bir kap verin; o da sabunlasın.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'Fısıltılı masallar 🪄', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp Akıllı Masallardan kısa bir hikâyeyi çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlayan en doğal ve sakinleştirici yöntemlerden biridir.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'Canlı ses kayıt cihazı 🎙️', 'Dün telefonda arkadaşınıza söylediğiniz o duygusal veya tuhaf cümleyi bugün oyuncağına söylüyor! Kelime dağarcığı inanılmaz bir hızla genişliyor ve sizi taklit ediyor. Artık sözlerinize iki kat daha fazla dikkat etmelisiniz.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'Kendinize değer verin 🥗', 'Onu doyurmak için yumurtayı 4 farklı şekilde pişirdiniz, peki siz ne yediniz? Sağlıklı tariflerden 5 dakikada hazırlanan, demir ve kalsiyum açısından zengin özel bir tabak hazırlayıp kendinizi ödüllendirin.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'Beyaz ses desteği 🤫', 'Uykuya daldığı anlarda hassasiyeti artar. Pencereden gelen sesleri nötrlemek için odada Ses Ölçerin arka plan sesini etkinleştirerek huzurlu bir ortam oluşturun.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'Giysiler leke içinde 🎨', 'Pijaması yemek, üstü başı boya lekesi içinde mi? Çocuklar tertemiz büyümek zorunda değildir; keşfederken kirlenmeleri doğaldır. Silikon önlükler kullanın, gerisini çamaşır makinesine bırakın.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'Mobilyalara tırmanmak 🧗‍♂️', 'Kanepeye veya koltuğa tutunup yukarı tırmanmaya mı çalışıyor? Dengesi gelişiyor, kas gücü artıyor. Onu koruyun ancak bu küçük dağcılık girişimlerine ve fiziği keşfetmesine kesinlikle engel olmayın.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'Annelerin dertleşmesi 💬', '“Bu çocuk hiç sakinleşmeyecek” düşüncesi sizi yoruyor mu? Anacan Topluluğuna katılın; her çocuğun 3 yaşa yaklaşırken bu fırtınalı krizlerden geçtiğini görecek ve derin bir nefes alacaksınız.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'Bir, iki, üç... on! 🔢', 'Parmaklarını veya oyuncaklarını saymaya mı çalışıyor? Matematiksel zekâsı uyanıyor. İnanılmaz bir hızla gelişen bu küçük çabaları kaçırmayın.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'Babanın gece nöbeti 👨‍🍼', 'Gece uyanmalarını ve uyutma sürecini tamamen tek başınıza üstlenmeyin. Eşinizi de uyandırın; ekip olmak, sorumluluğu eşit paylaşmaktır. Bu gece uykuya geçiş tamamen onun sorumluluğunda.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'Sakinlik saati deneyi 🥱', 'Öğle uykusuna yatmak istemiyor ve ağlıyor mu? Onu zorlamayın. Odanın ışıklarını azaltıp sessizce kitaplara göz atma saati ilan ederek ikinizi de rahatlatacak yeni bir rutin oluşturun.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'Karanlıktaki hayaller 🌌', 'Işıklar söndüğünde odadaki eşyalar canavara mı dönüşüyor? Beyaz Seslerden anne karnı sesini açarak ona o eski ve kusursuz güven duygusunu yeniden yaşatın.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'Mantık arayışı 🧩', 'Artık basit oyuncaklar ilgisini çekmiyor, daha karmaşık oyunlar kuruyor. Zihnini daha fazla zorlayacak ve mantıksal düşünme becerisini geliştirecek oyunları Önerilen Ürünler bölümünde arayın.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'Sıcak suyun sihri 🛀', 'Bütün gün “istemiyorum”larla geçti. Ilık bir banyo sadece hijyen için değil, gerilmiş sinir sistemini sıfırlamak için de harikadır. Suyun sesi ve sıcaklığı tüm inatçılığını alıp götürecek.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'Doğa bilmecesi 🍁', 'Evin sıkıcı havası ikinizi de bunaltıyor. Parka gidip en ilginç şekilli taşı bulma görevine çıkın. Doğa, onun için en büyük laboratuvardır ve tüm gerginliğini alıp götürecektir.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'Hayvan taklitleri 🐶', 'Sadece ses çıkarmakla kalmıyor; köpek gibi emekliyor, kedi gibi sürtünüyor mu? Beden dili ve hayal gücü şaşırtıcı biçimde birleşiyor. Siz de onunla birlikte halının üzerinde bu oyuna katılın ve stres atın.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'Anne için çevrim dışı saat ☕', 'Çocuğunuz kendi dünyasına dalıp oynarken hemen evi toplamaya koşmayın. Kendinize sıcak bir çay doldurun, telefonu bir kenara bırakın ve 15 dakika boyunca hiçbir şey düşünmeden sadece oturun.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'Çift molası 🥂', 'Çocuğunuz uyudu. Şimdi ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuk ve masraflar dışında herhangi bir konuda sohbet edin. Siz aynı zamanda bir çiftsiniz!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', '“Bu ne?” makinesi ☝️', 'Her şeyi parmağıyla gösterip adını mı soruyor? Sizden dünyayı onun için adlandırmanızı istiyor. Bu, iletişimde büyük bir sıçrama! Yorulsanız bile nesnelerin adlarını sabırla tekrarlamaya devam edin.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'Buzdolabındaki kumanda 📺', 'Televizyon kumandasını bulamıyor musunuz? Buzdolabına veya ayakkabı dolabına bakın. Eşyaları kendi kurduğu mantığa göre yerleştirerek dünyayı keşfediyor. Sinirlenmek yerine bu absürt dedektiflik oyununa gülerek yaklaşın.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'Hayali yara arayışı 🩹', 'Uyanır uyanmaz vücudunda görünmez bir yara bulup telaşla yara bandı yapıştırmanızı istiyor. Bu fiziksel bir acı değil, yalnızca ilgi ve şefkat ihtiyacıdır. Tartışmayın; o küçük bandı yapıştırıp öpün ve gününüz kurtulsun.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'Ani açlık sendromu 🥱', 'Tam yatağa girdiğinde “Anne, acıktım” deyip mutfağa koşmak istiyor. Uykuyu geciktirmek için tam bir şaheser! Beslenme planında akşam için uykuya geçişi destekleyen küçük bir atıştırmalık (örneğin muz) seçerek bu bahaneyi baştan ortadan kaldırın.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'Sessizliğin telaşı 🤫', 'Odasında tek başına resimlere bakıyor ve evde derin bir sessizlik var. Siz ise bu sessizlikten şüphelenip her an bir felaket çıkmasını bekliyorsunuz. Rahat olun. Bazen onlar da yalnız kalmak ister. Arkanıza yaslanın ve bu nadir çevrim dışı anın tadını çıkarın.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'Sesli düşünceler 💭', 'Yatağında uzanmış, gün içinde yaşananları kendi kendine ama yüksek sesle anlatıyor. Bilgileri ve anıları bu şekilde işliyor. Gelişim takipçisini açın ve hikâyeleri özgürce kurgulama becerisinin nasıl hızla geliştiğini gururla kaydedin.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'Halının çizgileri 📏', 'Halıdaki çizgilere basmadan yürümeye çalışıyor ve sizden de aynısını istiyor. Kaba motor becerileri ile dikkat koordinasyonu mükemmel biçimde birleşiyor. Oyunu bozmayın; siz de onunla birlikte birkaç adım boyunca aynı çizginin üzerinden atlayarak ilerleyin.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'Anne için bir nefes 🌬️', 'Evdeki kaos kulaklarınızı çınlatıyor. Hava durumunu kontrol edin, gerekirse kalın giyinip sadece 15 dakikalığına dışarı çıkın. O yerdeki taşları toplarken siz de yüzünüze vuran soğuk ve temiz havayı derin derin içinize çekin.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'Dinozor dili 🦖', 'Bu sabah o bir insan değil, dinozor ve tüm sorularınıza yalnızca kükreyerek cevap veriyor. Rol yapma oyunları kişilik gelişimi için harika bir araçtır. Siz de bir anlığına anne değil, başka bir dinozor olun ve onunla kendi dilinde konuşun.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'Yorgunluk itirafı 📝', 'Kimsenin sizi anlamadığını, emeğinizin görülmediğini mi düşünüyorsunuz? Zoraki gülümsemeleri bir kenara bırakın. Duygu günlüğüne bugün aslında ne kadar tükendiğinizi yazın. Ekrana dökülen her kelime omuzlarınızdaki ağır yükü biraz daha hafifletecek.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'Yapay zekâ ve kaygılar 🤖', 'Çocuğunuzun bazı harfleri telaffuz edememesi sizi birden endişelendirdi mi? İnternetteki uzman olmayan kişilerin yazdığı korkutucu forumları kapatın. Anacan AI''a 3 yaş civarındaki konuşma gelişimi normlarını sorun ve bilimsel, içinizi rahatlatan bir yanıt alın.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'Yataktaki sirk 🎪', 'Uyku vakti geldiğinde yatak bir anda sirk arenasına dönüşür. Zıplar, sürünür, bağırır. Sesinizi yükseltmeden ışıkları kısın. Enerjisinin son kırıntılarını atıyor. Akıllı Masallar''da çok yavaş tempolu bir hikâyeyle bu fırtınayı yavaş yavaş dindirin.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'Paylaşılamayan kapı kolu 🚪', 'Kapıyı ben açacağım! diyerek sizden önce koşar. Eğer siz açtıysanız ağlayarak kapıyı yeniden kapattırır ve kendisi açar. Bu yaşta kontrol hissi her şeydir. Bırakın o açsın; bu küçük zaferler onun hassas özgüvenini besler.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'Dayanışma topluluğu 💬', 'Bugün o kadar çok direndi ki kendinizi kötü bir anne gibi hissediyorsunuz. Hemen Anacan Topluluğuna girin. Diğer annelerin çocuklarının bugünkü isyanlarını okuduğunuzda yalnız olmadığınızı ve aslında harika bir iş çıkardığınızı anlayacaksınız.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'Gizli kararsızlık 🤔', 'Yanınıza gelip Bana su ver ama verme gibi tamamen çelişkili cümleler kurar. Zihninde birbirine zıt iki istek aynı anda vardır. Fazla mantık aramadan suyu masaya bırakın ve kararı onun iç dünyasındaki mücadeleye bırakın.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'Çekiç ve vida denemeleri 🛠️', 'Eline geçen her sert oyuncakla mobilyalara vurup onları tamir eder. Sesler beyninizi delip geçse de bu, onun neden-sonuç ilişkisini keşfetme biçimidir. Ona boş bir karton kutu ve tahta kaşık verin; gürültülü tamirine orada devam etsin.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'Çöp değil, sanat 🎨', 'Odanın ortasında küçük kâğıt parçaları ve kesilmiş iplerden oluşan büyük bir sanat eseri yarattı ve onu atmanıza izin vermiyor. Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya saygı gösterin; temizlik yarına da kalabilir.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'Ses ölçer terapisi 🤫', 'Evdeki bitmek bilmeyen gürültü sonunda sona erdi. O uyuyor. Ses ölçeri açın ve ekrandaki sayıların 0 desibele kadar düşüşünü izleyin. Odadaki mutlak sessizliğin zihninize görsel olarak nasıl masaj yaptığını hissedin.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'Ayna karşısında tiyatro 🎭', 'Sabahın erken saatlerinde aynanın karşısına geçip farklı ağlama, gülme ve şaşırma ifadeleri çalışıyor. Duygularını nasıl ifade edeceğini ve yüzünün nasıl şekillendiğini öğreniyor! Bu dâhiyane oyunculuk performansını uzaktan gururla izleyin.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'Babanın sihirli kolları 🫂', 'Bütün gün taşımaktan kollarınız koptu ama o hâlâ kucak istiyor. Babayı çağırın. Babanın kollarında uçmak hem çocuğun ilgi ihtiyacını karşılayacak hem de kollarınıza ve belinize çok ihtiyaç duyduğu dinlenme fırsatını verecek.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'Sorgulanan mantık 🧐', 'Balıklar neden yürümüyor? Sabahın erken saatlerinde zihni felsefeyle uyanır. Soruları sizi çıkmaza soksa da yorulmadan açıklamaya çalışın. Sizin sesiniz, onun için evreni anlamanın en güvenli ve en güzel yoludur.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'Alışveriş listesi karmaşası 🛒', 'Markette kasanın önündesiniz ve en önemli şeyi yine unuttuğunuzu fark ettiniz. Zihniniz zaten bin parçaya bölünüyor. Bundan sonra bir şeye ihtiyaç duyduğunuz anda onu uygulamadaki Alışveriş Listesine yazmayı alışkanlık hâline getirin; kendinize yardımcı olun.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'Ters giyinme gururu 🧦', 'Çorabın topuk kısmı ayağının üstünde ama kendi giydiği için gururla dolaşıyor. Sakın müdahale etmeyin. Onun bu ben başardım hissi, estetik görünmekten veya doğru giyinmekten milyon kat daha değerli bir psikolojik temeldir.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'Fısıltılı hikâyeler 🌙', 'Bugün sesinizi çok kullandınız, ciğerleriniz yoruldu. Işıkları kapatın, yanına uzanın ve gün boyunca yaşananları kulağına yalnızca fısıldayarak anlatın. Fısıltı onun dikkatini toplar ve zihnini hipnotik bir şekilde derin uykuya hazırlar.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'Mutfakta konser 🥄', 'Tencereleri ve tahta kaşıkları çıkarıp mutfağın ortasında gürültülü bir konser veriyor. Başınız ağrısa da bu, onun ritim duygusunun ve motor becerilerinin geliştiğini gösterir. Ona bir bravo deyin ve bu sürecin daha çabuk bitmesini umun.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'Altın sessizliğin ölçüsü 🤫', 'Evdeki karmaşa sonunda bitti ve o uykuya daldı. Bulaşıkları yıkamaya koşmayın! Ses ölçeri açın ve odadaki o mutlak sessizliğe (0-10 desibel) bakarak 15 dakika boyunca zihninizin nasıl dinlendiğini görsel olarak hissedin.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'Muz soyma faciası 🍌', 'Muzu onun yerine siz soydunuz diye sabah saat 8''de odada devrim mi koptu? Bu yaşın altın kuralı: Her şeye o karar vermelidir. Muzu yeniden kabuğuna yapıştıramazsınız; dikkatini hemen başka bir absürtlüğe yönlendirerek krizi yatıştırın.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'Gecenin huzuru 🛁', 'Bütün gün koşturmaktan hem o hem de siz tükendiniz. Ilık bir banyo sırasında arka planda sakinleştirici doğa sesleri açın. Suyun uyumu, en inatçı çocuğu bile derin bir uykuya hazırlayacaktır.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'Dokunulma yorgunluğu 🔋', 'Bütün gün üzerinize tırmanıyor, kucak istiyor ve saçınızla oynuyor. Siz ise sadece biraz fiziksel alan istiyorsunuz. Dokunulma yorgunluğu (touched out) gerçektir. En azından 15 dakika boyunca tek başınıza bir odaya çekilmeye hakkınız var.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'Küvet gideri korkusu 🛀', 'Eskiden sudan çıkmak istemeyen çocuğunuz birden küvetteki su giderinden korkup ağlamaya mı başladı? Hayal gücü geliştikçe yersiz korkular ortaya çıkabilir. Giderin üzerini plastik bir oyuncakla kapatıp ona güven verin.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'Çift molası 🥂', 'Çocuğunuz uyudu. Şimdi ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuk, sorunlar ve masraflar dışında herhangi bir konuda sohbet edin. Siz ebeveyn olmadan önce bir çiftsiniz!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'Cansız nesnelerle sohbet 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, hatta onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı anlamlandırıyor. Gelişim takipçisinde onun bu özel senaryolarını mutlaka işaretleyin.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'Babadan masaj seansı 💆‍♂️', 'Bugün uzun süre ayakta kaldınız, onun peşinden koşmaktan beliniz koptu. Çocuğunuz uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin direğisiniz; direklerin de mutlaka güç toplaması gerekir.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'Uyku erteleme taktiği ⏱️', 'Uyku vakti geldiğinde birden susuyor, tuvalete gitmek istiyor ya da duvarla vedalaşıyor mu? Zamanlayıcı kurun. Alarm çalınca herkes uyur kuralını uygulayarak bu bitmek bilmeyen vedalaşmalara sabırla son verin.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'Annenin besin deposu 🥗', 'Onu doyurmak için farklı menüler düşündünüz, peki siz yine aç mı kaldınız? Sağlıklı tarifler arasından 10 dakikada hazırlanan, demir ve kalsiyum açısından zengin bir öğle yemeği seçerek kendinize değer verdiğinizi gösterin.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'Çamaşır Yardımcısı 🧺', 'Siz büyük bir emekle çamaşırları katlıyorsunuz, o ise yardım ettiğini söyleyip hepsini yeniden odaya dağıtıyor. Sinirlenmek yerine işi oyuna dönüştürün: Bakalım bu çorapları sepete kim daha hızlı atacak?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'Avangart moda anlayışı 👗', 'Kışlık kazağının üzerine yazlık şortunu giydi ve çıkarmak istemiyor mu? Zararı yok. İnsanların arasına uyumsuz kıyafetlerle çıkan bir çocuk, aslında kendi kararını cesurca savunan bir çocuktur. İradesini kırmayın.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'Gece terörünün şifresi 😭', 'Gecenin bir yarısı gözleri kapalı şekilde ağlayarak uyandı ve kimseyi duymuyor. Ağlama analiziyle doğrulayın; eğer bu bir uyku terörüyse onu uyandırmaya çalışmayın. Sadece yanında olun ve sessizce güven verin.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'Hava durumu uyarısı ⛅', 'Gezmeye çıkarken pencereden bakıp yanılmayın. Hava ve giyim yardımcısıyla dışarıdaki gerçek rüzgâr ve sıcaklığa en uygun kombini belirleyerek evden rahatça ve hazırlıklı çıkın.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'Topluluğun sırdaşlığı 💬', 'Çok yoruldunuz ve kimseye hiçbir şey açıklamak istemiyorsunuz. Anacan Topluluğuna girip sadece okuyucu olun. Diğer annelerin benzer yorgunluklarını görmek, yalnız olmadığınızı hissettirerek en iyi terapiye dönüşür.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'Canlı konser ve komşular 🎤', 'Eline bir kaşık alıp odanın ortasında duruyor ve avazı çıktığı kadar bağırarak şarkı söylüyor. Komşuların ne düşüneceğini umursamayın. Evinizde bir yıldız büyüyor, siz sadece alkışlayın.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'Müzikle uykuya geçiş 🎶', 'Akşamüstü kopan sebepsiz fırtınaları hafif klasik müzikle dindirmeyi deneyin. Çoğu zaman bu basit ama etkili yöntem evde mucizeler yaratır ve odaya huzur getirir.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'Ekran süresi suçluluğu 📺', 'Bugün işleriniz nedeniyle ona daha fazla çizgi film izlettiniz ve vicdan azabı mı çekiyorsunuz? Kendinizi suçlamayın. Bazen dijital bakıcı, sizi psikolojik çöküşten kurtaran tek yoldur.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'Seçici işitme sendromu 🙉', 'Oyuncaklarını toplamasını söylediğinizde duymuyor ama yan odadan gelen çikolata ambalajının hışırtısını anında fark ediyor, öyle mi? İşitmesinde bir sorun yok, yalnızca işine geleni duyuyor. Kuralları fısıldayarak söylemeyi deneyin; ilgisi uyanacaktır.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'Cepten çıkan hazineler 🪨', 'Pantolonunu yıkarken cebinden 2 taş, kurumuş bir yaprak ve yarım bir çubuk mu çıktı? Sizin için çöp olan bu nesneler, onun evreni keşfederken oluşturduğu değerli koleksiyonudur. Onları atmak yerine küçük bir hazine kutusunda biriktirin.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'Brokoli kamuflajı 🥦', 'Çorbadaki yeşil sebzeleri cerrah titizliğiyle ayırıyor mu? Yemek seçiciliği zirvede. Beslenme planındaki sebzeleri görünmez kılan ve rengârenk köftelere dönüştüren özel, yaratıcı tarifleri keşfetmenin tam zamanı.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'Masalın yönetmeni o 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız. Akıllı masalları açın ve bu akşam hikâyeyi onun yönlendirmesine izin verin. “Şimdi bu uçan araba nereye gitsin?” diye sorun; bırakın, uydurduğu absürt sonla uykuya dalsın.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'Babanın uçuş modu ✈️', 'Evde enerjisini atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Babası onu havaya kaldırıp uçak yaptığında kahkahalar odayı doldurur, biriken tüm fiziksel gerginlik saniyeler içinde yok olur.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'Toplulukta nefes almak 💬', 'Çok yoruldunuz ve kendinizi dünyanın en sabırsız annesi gibi mi hissediyorsunuz? Hemen Anacan Topluluğunu açın. Başka annelerin de tamamen aynı absürt krizleri yaşadığını okumak en büyük psikolojik desteklerden biridir.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'Sonsuz Neden? döngüsü 🌪️', 'Kuşlar neden uçar?, Su neden ıslatır?, Neden neden?... Soru treni hızla üzerinize geliyor. Yorulsanız da ona mantıklı ve kısa cevaplar verin. O, evrenin sırlarını sizin ses tonunuzdan öğreniyor.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'Doğaya kaçış ⛅', 'Dört duvar hem onu hem de sizi huzursuz etti. Evin karmaşasından yoruldunuz. Hava ve giyim aracını kontrol edip hemen parka koşun. Açık havada özgürce koşmak, en şiddetli küçük çocuk krizlerini bile bıçak gibi keser.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'Yanlış renk felaketi 🔴', 'Suyu mavi değil de kırmızı bardakta verdiğiniz için kıyamet mi koptu? Bu şımarıklık değil; yalnızca sınırlarınızı ve dünyayı kontrol edip edemediğini test ediyor. İnatlaşmadan bardağı değiştirin ve enerjinizi koruyun.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'Duygularınızı serbest bırakın 📝', 'Evde ne kadar yorulduğunuzu kimsenin görmediğini mi düşünüyorsunuz? Duygu günlüğü, en sessiz sırdaşınızdır. Bugün sizi çileden çıkaran tüm ayrıntıları oraya yazın ve zihninizin nasıl hafiflediğini görün.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'Yapay zekâ, gerçek çözüm 🤖', 'Çocuğunuzda tuhaf bir alışkanlık mı ortaya çıktı (örneğin saçını parmağına dolamak) ve internetteki yazılar sizi korkuttu mu? Durun. Anacan AI''a bunun çocuk doktorlarınca doğrulanmış gerçek nedenini sorun ve gereksiz panikten kurtulun.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'Saklambaç mantığı 🙈', 'Odanın ortasında gözlerini elleriyle kapatmış, sizin onu bulmanızı bekliyor! 3 yaş mantığı: Ben seni görmüyorsam sen de beni göremezsin. Onun bu masum yanılgısına inanmış gibi yapıp odada gürültülü bir şekilde onu arayın.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin (uyku hormonu), yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'Dijital hafıza 🛒', 'Markete gittiğinizde mutlaka bir şeyi unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı hemen oraya yazın; eşiniz işten dönerken eksiksiz alsın, siz de zihninizi yormayın.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', 'Kendim yapacağım! kuralı 👟', 'Ayakkabısının bağcıklarını kendi bağlamak istiyor ve evden çıkmak için şimdiden 10 dakika geciktiniz. Acele etmeyin. Onun gelişimi için aksayan bir zaman planındansa incinmemiş bir özgüven daha önemlidir.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'Fısıltının mistik gücü 🤫', 'Yatakta o kadar hareketli ki uykuya dalamıyor. Sesinizi yükseltmek yerine aniden alçaltın ve fısıldayarak konuşun. Çocuk sizi duyabilmek için dikkatini topladığında beyni otomatik olarak uyku moduna geçer.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'Telefon saklama operasyonu 📱', 'Telefonunuzu nereye koyduğunuzu bulamıyorsunuz ve bir süre sonra oyuncak kutusundan çıkıyor. O, ilginizi telefonla paylaşmak istemiyor. Cihazı bir kenara bırakıp ona 15 dakika boyunca kesintisiz ilgi gösterin.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'Sessizliğin dijital ölçüsü 🤫', 'Sonunda uykuya daldı! Eve çöken sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarak zihninizin yavaş yavaş dinlendiğini görsel olarak hissedin.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'Oyuncağımı vermem! 🧸', 'Parkta kaydırakta veya kumda kimseye yer vermek istemiyor, oyuncaklarını sıkıca tutuyor. Bu bencillik değil, sınırlarını koruma davranışıdır. Paylaşmaya zorlamak yerine, sıra beklemeyi oyun yoluyla öğretin.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'Karanlığa davet 🌙', 'Yatak odasında ışıklar söndüğünde huzursuz mu oluyor? Odanın bir köşesine küçük, sıcak renkli bir gece lambası koyun. Odanın geri kalanı ise derin bir uyku için tamamen karanlık kalmalıdır.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'Anne yorulduğunda 🛑', 'Siz robot değilsiniz. Bugün yemek yapacak gücünüz yoksa dışarıdan sipariş verin veya sadece makarna haşlayın. Mükemmel anne olmak, her şeyi tek başınıza yapmak demek değildir. Kendinize izin verin.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'Listedeki Sürpriz 🛒', 'Markete gitmeden önce Alışveriş listesini açtınız ve arkanızdan gelip telefonun ekranına dokunarak listeye bir şeyler karaladığını gördünüz. Evet, dijital hayatınızı da taklit ediyor!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'Duygu günlüğünde itiraf 📝', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının hayatlarını kaydırmak yerine Duygu günlüğünü açın ve bugün onun yaptığı en komik şeyi geleceğe bir hatıra olarak kaydedin. Dijital terapi işe yarıyor.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'Avukat gibi pazarlık 🗣️', '“Sadece 5 dakika daha oynayayım, sonra giyinirim” mi diyor? Artık sizinle profesyonelce anlaşma yapmaya çalışıyor. Dil gelişimi harika, ancak sınırlarınızı ve kurallarınızı sevgiyle korumayı unutmayın.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'Sakinlik saati 🥱', 'Öğle uykusuna yatmak istemiyor ve ağlıyor mu? Zorlamayın. Odadaki ışıkları azaltıp Sessiz kitap karıştırma saati ilan ederek hem yeni hem de ikinizi dinlendirecek bir rutin oluşturun.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'Bugün bunu yemiyorum 🥣', 'Dün afiyetle yediği çorbayı bugün ağzına bile sürmüyor. Dişleriyle ilgili bir sorun yoksa bu yalnızca bir irade testidir. Beslenme planında aynı vitaminleri sağlayacak farklı alternatif tariflere göz atın.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'Babanın tuhaf sesleri 🤡', 'Sizin yaptıklarınız artık işe yaramadığında babanın çıkardığı tuhaf sesler ve yaptığı komik yüzler durumu hemen kurtarıyor. Akşam krizlerinde görevi hemen ona devredin, siz de kenardan dinlenerek izleyin.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'Doğa bilmecesi 🍁', 'Evin sıkıcı havası ikinizi de bunaltıyor. Parka gidip en tuhaf şekilli taşı bulma görevine çıkın. Doğa onun için en büyük laboratuvardır ve tüm stresini alacaktır.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'Hayali misafirler masada ☕', 'Boş fincanı size uzatıp “Çay iç” diyor ve odada olmayan arkadaşıyla mı konuşuyor? Bu, hayal gücü gelişiminin başyapıtıdır. Odanın bir köşesinde sahnelenen bu oyunu bozmayın, siz de o çayı için.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'Akıllı masalda ben 🪄', 'Klasik kitapları artık ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak tasarlayıp sıra dışı bir uyku seansı oluşturun.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'Banyoda barış 🛀', 'Suyla oynamak o kadar keyifli ki parmakları buruşsa bile küvetten çıkmak istemiyor. Ona 5 dakika önceden haber verip zamanlayıcı kurun. “Zil çalınca çıkıyoruz” kuralı çoğu zaman işe yarar.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', '“Elimi tutma!” özgürlüğü 🚶‍♂️', 'Sokakta elinizi tutmayı kesinlikle reddediyor, özgürce koşmak istiyor. Güvenli yerlerde ona bu özgürlüğü tanıyın. Gözünüz üzerinde olsun; bırakın, dünyayı kendi adımlarıyla fethetsin.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'Gelişimin izleri 📈', '3 yaş döneminde motor becerileri, kelime dağarcığı ve duygusal zekâsı hızla değişir. Yaptığı küçük keşifleri unutmamak için Gelişim takipçisine düzenli olarak not alın ve arşivleyin.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'Özür dileyip aynısını yapmak 🧸', 'Vurduğu biri veya kırdığı bir şey için içtenlikle özür diliyor, ancak 5 dakika sonra aynı davranışı tekrarlıyor mu? Henüz dürtülerini kontrol edemiyor. Kuralı sabırla tekrar tekrar açıklayın.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'Dertleşme ihtiyacı 💬', 'Zor bir karar mı vermeniz gerekiyor? (Kreş, tuvalet eğitimi, uyku). Anacan Topluluğundaki deneyimli annelerin tavsiyeleri, hiçbir kitapta yazmayan, hayatın içinden en gerçekçi çözüm yollarıdır.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'Masalın sonunu o yazsın 🪄', 'Klasik kitaplardan ikiniz de yoruldunuz. Akıllı masallarda bu kez hikâyenin sonunu çocuğunuza seçtirin. Sizce o kahramana kim yardım etti? diye sorarak uyku öncesinde hayal gücünü özgür bırakın.'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'Sağlıklı anne, sağlıklı çocuk 🥑', 'Günlük koşuşturma içinde öğle yemeğini ayaküstü geçiştirmeyin. Oturarak ve keyifle yiyebileceğiniz, demir ve kalsiyum açısından zengin, farklı bir salata hazırlayın. Sizin enerjiniz bu evin motorudur, onu koruyun.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'Sessizliğin kanıtı 🤫', 'Gürültülü bir günün ardından, çocuğunuz uyuduğunda Ses ölçer ile odanın sessizliğini ölçün. Sıfıra yaklaşan o rakamları görmek bile annenin beyninde en iyi görsel masaj etkisini yaratır.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'Yemek hazırlığına el atması 🧑‍🍳', 'Siz hamur açarken mutlaka yanınıza bir sandalye çekip sürece dâhil olmak ister. Ona ait plastik bir kaba un koymasına izin verin. Mutfak batacak ama onun o ciddi ve işine odaklanmış yüz ifadesi, ardından yapacağınız tüm temizliğe değecek.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'Birbirinize teşekkür edin 🥂', 'Zor bir günü geride bıraktınız. Çocuğunuz uyuduktan sonra partnerinizle birer çay doldurun ve Bu fırtınalı günde bana çok yardımcı oldun diyerek teşekkür edin. Takım ruhu böyle kurulur.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'Yapay zekâ, gerçek yanıt 🤖', '3 yaş krizlerinin bilimsel ve çocuk doktorlarınca doğrulanmış nedenleri nelerdir? İnternetteki korkutucu yorumları okumak yerine hemen Anacan AI''dan çocuğunuzun psikolojisi hakkında doğru ve profesyonel bir analiz isteyin.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'Duyusal aşırı yüklenme 🔋', 'Bütün gün üzerinize tırmandı, saçınızı çekti ve gürültü yaptı. Sinir sisteminiz kırmızı alarm veriyor. Dokunulma yorgunluğu tamamen gerçektir. Çocuğu partnerinize bırakıp bir süreliğine odanıza çekilin.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'Tuhaf telaffuzlar 🗣️', 'Kelimeleri o kadar tuhaf ve kendine özgü vurgularla söylüyor ki gülmemek elde değil. Gülerek düzeltmek yerine onu dikkatle dinleyin ve yalnızca cümlenin doğru hâlini tekrarlayarak yanıt verin.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'Markette unutkanlık belası 🛒', 'Hafızanıza güvenerek markete gittiniz ve bebek bezini almayı unutarak mı döndünüz? Böyle şeyler olur. Tüm ihtiyaçlarınızı hemen Alışveriş listesine yazmayı alışkanlık hâline getirin; bırakın dijital hafızanız sizi kurtarsın.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'Duygularınızı kâğıda dökün 📝', 'Kimse ne kadar yorulduğunuzu görmüyor mu? Duygu durumu günlüğü sizi dinlemek için orada. Bugün sizi çileden çıkaran tüm küçük ayrıntıları oraya yazın ve zihninizi boşaltın.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'Uyku hormonu için uygun ortam 🌙', 'Uykuya dalmasını kolaylaştırmak için yatmadan 1 saat önce odadaki tüm gereksiz ışıkları kapatın ve tablet ekranlarını devre dışı bırakın. Karanlık ve teknolojiden uzak bir ortam, uyku hormonu salgılanmasını destekler.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'Parkta özgürlük 🌳', 'Dört duvar arasında kalmak onu hırçınlaştırır. Hava ve kıyafet yardımcısıyla dışarıdaki rüzgâra en uygun kombini belirleyip parka çıkın. Bırakın kuma bulansın, koşarken düşsün. Özgürlük, onun gelişimi için en iyi ilaçtır.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'Beklenmedik bir sarılma 💖', 'Odanın ortasında oyun oynarken aniden size bakıp koşarak gelir ve boynunuza sarılır. Tüm uykusuz gecelere ve yorgunluklara değer! Bu anın getirdiği o derin ve eşsiz huzurun tadını çıkarın.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'Zaman kavramı gelişiyor ⏱️', 'Yarın, dün, sonra kelimelerini sık sık ama bazen yanlış yerlerde mi kullanıyor? Zaman algısı gelişiyor! Bu çabalarını gülümseyerek dinleyin.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'Anne için mola ☕', 'Çocuğunuz kendi kendine oynarken hemen ev işlerine koşmayın. Odadaki dağınıklık bir yere kaçmaz ama sizin enerjiniz tükenebilir. Oturun ve sıcak kahvenizi için.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'Yataktan kaçış planı 🛌', 'Beşiğinden tırmanarak çıkmaya mı çalışıyor? Güvenliği sağlamak için odayı yeniden gözden geçirin. Artık çocuk yatağına geçme zamanı yaklaşıyor.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'Hayali senaryolar 🧸', 'Oyuncaklarına yemek yediriyor, onları tedavi mi ediyor? Sembolik oyunlar empatinin temelidir. Bu bilişsel sıçramayı gelişim takipçisine gururla kaydedin.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'Sihirli gece atmosferi 🪄', 'Uykuya dalmakta zorlanıyor mu? Akıllı masallarda dişlerini fırçalayan kahraman ayıcığın hikâyesini oluşturarak yeni alışkanlıkları masallaştırın.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'Parkta sosyalleşme 🌳', 'Diğer çocuklarla oynamak yerine onların yanında kendi oyununu mu oynuyor? Paralel oyun bu yaş için tamamen doğaldır. Üzerinde baskı kurmadan sosyalleşmesini destekleyin.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'Brokoli dedektifi 🥦', 'Çorbanın içindeki o tek yeşil sebzeyi bulup yemeği mi reddediyor? Beslenme planında sebzeleri renkli makarnalarla karıştırarak dikkatini dağıtmanın ve yararlı besinleri gizlemenin en lezzetli yollarını keşfedin.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'Duygularla yüzleşme 📝', 'Bütün gün her şeye hayır dediğiniz için kendinizi kötü mü hissediyorsunuz? Duygu durum günlüğünü açın. Bugün içinizde beliren o en karanlık keşke yalnız olsaydım düşüncesini filtresizce yazın. Kendinizi suçlamayın; her anne bazen yorulur ve kaçıp gitmek ister.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'Bu benim hatam değil! 🤷‍♂️', 'Suyu bilerek yere döktü ama suçu masaya atıp Masa kaydı mı dedi? Bu bir yalan değil, çocuk beyninin sorumluluktan kaçınma ve kendini savunma içgüdüsüdür. İnatlaşmayın; Gel, masaya yardım edip birlikte silelim diyerek onu incitmeden sorumluluk duygusu kazandırın.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'Dört duvar psikolojisi ⛅', 'Ev sizi bunaltıyor, çocuğunuz ise agresifleşiyor. Hava durumunu kontrol edin, en uygun kıyafetleri seçip kapıyı çekerek parka koşun. Oksijen ve hareket özgürlüğü hem onun beyni hem de sizin yorgun sinirleriniz için en iyi detoks olacaktır.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'Çamaşır katlama operasyonu 🧺', 'Siz büyük bir emekle temiz çamaşırları katlıyorsunuz, o ise 2 saniye içinde aralarına dalıp hepsini dağıtıyor. Odaya derin bir sessizlik çöküyor... Sinirleriniz gerildi mi? Derin bir nefes alın. Kendinizi dağılmış çamaşır yığınının üzerine bırakıp bu kaosa gülerek teslim olun.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'Akıllı masalın yönetmeni 🪄', 'Klasik kitaplardaki kahramanlardan ikiniz de sıkıldınız. Akıllı masalları açın ve bu akşam hikâyeyi onun oluşturmasına izin verin. Şimdi bu uçan dinozor nereye gitsin? diye sorun ve kurduğu hayal dünyasında uykuya dalmasına izin verin.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'Babanın uçuş modu ✈️', 'Evde enerjisini atamadı ve yatağa gitmemek için binbir bahane uyduruyor. Babayı çağırın. Babası onu havaya kaldırıp uçak oyunu oynadığında kahkahalar odayı doldurur ve biriken tüm fiziksel gerginlik terle birlikte kaybolur.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', 'Sen kötü bir annesin! darbesi 💔', 'İstediği oyuncağı almadığınız için yüzünüze bakıp sen kötüsün mü dedi? Kalbiniz kırılmasın. Henüz duygularını doğru kelimelerle ifade edemiyor; aslında çok öfkeliyim ve hayal kırıklığına uğradım demek istiyor. Göz teması kurup yalnızca duygusunu anladığınızı belirtin.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', 'Markette Ben süreceğim inadı 🛒', 'Market arabasını kendisi sürmek istiyor ve raflara çarparak herkesin dikkatini çekiyor. Müdahale ettikçe ağlıyor. Arabayı birlikte sürün. Unutkanlığa karşı uygulamadaki Alışveriş listesini aktif tutun ki zihniniz daha az yorulsun.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'Ses ölçerin sessizliği 🤫', 'Sonunda uykuya daldı! Eve çöken sessizlik o kadar derin ki kulaklarınız çınlıyor. Ses ölçme aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarak zihninizin yavaş yavaş nasıl iyileştiğini görsel olarak hissedin.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'Kirlenmeye tam izin 🏖️', 'Çamurla, kumla oynamak mı istiyor? Bırakın kirlensin! Duyusal gelişimi destekleyen bu etkinlikler için en kolay temizlenen malzemeleri Önerilen Ürünler''de bulup onu özgür bırakın.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'Gölgeyle mücadele 👻', 'Duvardaki gölgesinden korkup arkanıza mı saklanıyor? Hayal gücü sınır tanımaz. Odayı karartın ve el feneriyle duvarda ellerinizi kullanarak gölge oyunları oluşturun.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'Müzikle uykuya geçiş 🎶', 'Akşamüstü kopan sebepsiz fırtınaları hafif klasik müzikle dindirmeyi deneyin. Bu basit ama etkili yöntem çoğu zaman evde mucizeler yaratır ve odaya huzurlu, dinlendirici bir atmosfer getirir.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'Bedeninizin çağrısı 🩸', 'Nedensiz gerginliğe ve yorgunluğa teslim olmayın. Regl Takipçisi''ne bakın; bedeniniz size sinyal veriyor. Kendinizi suçlamak yerine magnezyum içeren bir atıştırmalıkla dinlenin.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'Kelimeleri bilerek değiştirmek 🗣️', 'Araba yerine ısrarla Baraba diyor ve sizin buna gülmenizi mi bekliyor? Artık mizahı keşfediyor. Gülün ama beyninin doğru biçimi de kodlaması için her seferinde doğru telaffuzu nazikçe vurgulamayı unutmayın.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'Anne, kendinizi de doyurun 🥗', 'Onu yedirmek için yumurtayı 4 farklı şekilde pişirdiniz, peki siz ne yediniz? Sağlıklı tariflerden 5 dakikada hazırlanan, demir ve kalsiyum açısından zengin özel bir tabak hazırlayarak kendinizi ödüllendirin ve enerjinizi koruyun.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'Uykuyu erteleme taktiği ⏱️', 'Uyku vakti gelince birden susuyor, tuvalete gitmek istiyor veya duvarla vedalaşıyor mu? Zamanlayıcı kurun. Alarm çalınca herkes uyur kuralını uygulayarak bu bitmek bilmeyen vedalaşmalara sabırla ve sakince son verin.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'Oyuncaklarla toplantı 🧸', 'Tüm ayılarını ve arabalarını sıraya dizip parmağını sallayarak onlara son derece ciddi bir şekilde bir şeyler mi anlatıyor? Liderlik ve odaklanma becerileri gelişiyor. Odanın bir köşesinde durup bu hayali toplantıyı onu rahatsız etmeden sessizce izleyin.'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'Babanın tuhaf sesleri 🤡', 'Sizin yaptıklarınız artık işe yaramadığında babanın çıkardığı tuhaf hayvan sesleri ve komik yüz ifadeleri durumu hemen kurtarır. Akşam krizlerinde topu ona atın ve neşeli kahkahaları kenardan izleyin.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'Gündüz uykusu isyanı 🥱', 'Yatağa gitmek istemiyor ve ağlıyor mu? Zorlamayın. Odadaki ışıkları azaltıp Sessiz kitap inceleme saati ilan edin; ikinizi de dinlendirecek yeni bir rutin oluşturun. Böylece hem siz hem de o dinlenir.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'Kreş düşünceleri 🏫', 'Artık sosyalleşmeye daha fazla ihtiyaç duyduğunu mu hissediyorsunuz? Kreş için doğru zaman mı? Anacan Topluluğu''na katılıp diğer annelerin gerçek uyum deneyimlerini okuyarak karar vermenizi kolaylaştırın.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'Ani öfke patlaması 💥', 'Oynarken birden sinirlenip oyuncaklarını mı fırlattı? Henüz duygularını yönetemiyor. Bağırmak yerine, Sinirlendiğini görüyorum, gel birlikte derin bir nefes alalım diyerek empati kurun ve onunla temas hâlinde kalın.'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'Yatak odasında ışıklar sönünce huzursuz mu oluyor? 🌙', 'Odanın bir köşesine küçük, sıcak renkli bir gece lambası koyun. Odanın geri kalanı ise derin bir uyku için tamamen karanlık kalmalıdır.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'Cansız nesnelerle sohbet 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı anlamlandırıyor. Bu özel senaryolarını Gelişim Takipçisi''nde mutlaka işaretleyin.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'Ilık suyun mucizesi 🛀', 'Bazen hiçbir şey işe yaramaz, o sadece her şeye ağlar. Onu ılık suyla dolu küvete oturtun ve içine biraz köpük ekleyin. Suyun o büyülü, gerginliği azaltan gücü hem tüm odaya hem de sinir sistemine anında huzur getirecektir.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'Hava durumu uyarısı ⛅', 'Gezintiye çıkarken pencereden bakıp yanılmayın. Hava ve kıyafet yardımcısıyla dışarıdaki gerçek rüzgâr ve sıcaklığa en uygun kombini belirleyin; evden rahatça ve hazırlıklı çıkıp çocuğunuzun enerjisini açık havada atmasına imkân tanıyın.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'Topluluğun sırdaşlığı 💬', 'Çok yoruldunuz ve kimseye hiçbir şey açıklamak istemiyorsunuz. Anacan Topluluğuna girip yalnızca okuyucu olun. Diğer annelerin benzer yorgunluklarını ve komik çocuk krizlerini görmek, yalnız değilim hissini uyandırarak en iyi sakinleştirici olur.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'Mutfağın küçük aşçısı 🧑‍🍳', 'Siz hamur açarken mutlaka yanınıza bir sandalye çekip işe karışır. Ona ait plastik bir kaba biraz un koyup karıştırmasına izin verin. Mutfak dağılacak ama yüzündeki o ciddi, çalışkan ifade ve ben de yapabiliyorum hissi tüm bu temizliğe değer.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'Ters giyinmenin gururu 🧦', 'Çorabın topuk kısmı ayağının üstünde ama kendi giydiği için gururla dolaşıyor. Hiç müdahale etmeyin. Onun bu ben başardım hissi, estetik veya doğru giyinmekten milyon kat daha değerli bir psikolojik temeldir; bırakın gününü böyle geçirsin.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'Anne için çevrimdışı dakikalar ☕', 'Kendi kendine yapboz yapıyor ve 10 dakikadır sessiz. Siz ise o anı evi toplamaya ayırmak istiyorsunuz. Hayır! Gidip kanepeye uzanın. Akşama kadar bu tempoya dayanabilmeniz için sizin de pilinizi doldurmanız gerekiyor.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'Karanlıkla barışmak 🐰', 'Uyumak istemiyor ve odadaki gölgelerden korktuğunu mu söylüyor? Odayı tamamen karartın ve ellerinizle duvarda kuş, köpek gölgeleri oluşturun. Korkuyu eğlenceye dönüştürerek karanlıkla arkadaş olmasına ve hayal gücünü yönetmesine yardımcı olun.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'Yapay zekâ ve kaygılar 🤖', 'Çocuğunuzun bazı harfleri hâlâ doğru telaffuz edememesi sizi endişelendirdi mi? İnternetteki korkutucu forumları kapatın. Anacan AI''a 38 ay civarındaki konuşma gelişimi ölçütlerini sorarak bilimsel ve gerçekçi bir yanıt alın.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'Siz çocuk olun, ben anne 👩‍👧', 'Rol değiştirme oyunu başladı! Size buraya gel, yemeğini ye, ağlama diye talimatlar veriyor. Bu liderlik deneyimini büyük bir keyifle kabul edin ve itiraz etmeden onun çocuğu rolünü oynayın; bu, empati gelişiminin en temel yollarından biridir.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'Ayna karşısında tiyatro 🎭', 'Sabahın erken saatlerinde aynanın karşısına geçip farklı ağlama, gülme ve şaşırma mimikleri yapıyor. Duygularını nasıl ifade edeceğini ve yüzünün nasıl şekillendiğini keşfediyor. Bu dahiyane oyunculuk performansını uzaktan gülümseyerek izleyin.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'Babanın sihirli kolları 🫂', 'Bütün gün taşımaktan kollarınız koptu ama o yine de kucak istiyor. Babayı çağırın. Babanın kollarında uçmak hem çocuğun ilgi ihtiyacını karşılayacak hem de sizin kollarınıza çok ihtiyaç duyduğu dinlenme fırsatını verecek.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'Çöp değil, sanat 🎨', 'Odanın ortasında küçük kâğıt parçaları ve kesilmiş iplerden oluşan büyük bir sanat eseri yarattı ve onu atmanıza izin vermiyor. Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya saygı gösterin; temizlik yarına da kalabilir.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', 'Ben kendim yapacağım! direnişi 🛑', 'Ayakkabısının bağcığını kendi bağlamak istiyor ve evden çıkmak için şimdiden 10 dakika geciktiniz. Acele etmeyin. Onun gelişimi için bozulmamış bir özgüven, aksayan bir programdan daha önemlidir. Denemesine izin verin.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'Fısıltılı hikâyeler 🌙', 'Bugün sesinizi çok kullandınız, nefesiniz tükendi. Işıkları kapatın, yanına uzanın ve gün içinde yaşananları kulağına yalnızca fısıldayarak anlatın. Fısıltı, dikkatini toplar ve beynini hipnotik bir şekilde derin uykuya hazırlar.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'Mükemmel anne efsaneleri 🛑', 'Sosyal medyadaki çocuklar renkleri ve sayıları artık İngilizce söylüyor ama sizin çocuğunuz istemiyor mu? Karşılaştırmayı hemen bırakın! Her çocuğun gelişim takvimi benzersiz ve farklıdır. O, kendi hızında mükemmeldir.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'Gündüz uykusu bitti mi? ⏱️', 'Akşam uykuya dalması 1 saatten uzun mu sürüyor? Uyku zamanlama çizelgesine bakın. 3 yaş fırtınasında gündüz uykusunu tamamen kaldırmanın ve akşam yatış saatini öne çekmenin zamanı gelmiş olabilir.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'Bitmeyen Neden? soruları 🌪️', 'Balıklar neden yürümüyor?, Güneş nereye gitti? Sabahın erken saatlerinde zihni, saatte 100 soru hızıyla felsefi cevaplar arıyor. Yorulsanız da ona mantıklı ve kısa cevaplar verin. Evrenin sırlarını sizin ses tonunuzdan öğreniyor.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'Çizgi film eleştirmeni 📺', 'İzlediği çizgi filmi kendine özgü dil bilgisiyle size anlatıyor, kimin nereye gittiğini ciddi ciddi açıklıyor. Onu dikkatle ve şaşırmış gibi dinleyin. Kendisini dünyanın en akıllı insanı gibi hissetmesine izin verin.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'Mükemmellik diye bir şey yok 🛑', 'Bugün hiçbir şey planladığınız gibi gitmedi mi? Kendinizi suçlamayın. Siz gerçek bir annesiniz, sosyal medyadaki filtrelenmiş bir illüzyon değilsiniz. Çocuğunuzun yalnızca gülümsemenize ve kucağınıza ihtiyacı var.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'Gece terörünün şifresi 😭', 'Gecenin bir yarısı gözleri kapalı hâlde ağlayarak uyandı ve kimseyi duymuyor. Ağlama Analizi ile kontrol edin; eğer bu bir gece terörüyse onu uyandırmaya çalışmayın. Sadece yanında olun ve sessizce güven verin.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'Sadece sarılın 🫂', 'Hiçbir oyuna, kitaba veya masala gerek yok. Bu akşam sadece onu göğsünüze bastırın, o güzel kokusunu içinize çekin ve karanlıkta ona ne kadar değerli olduğunu fısıldayın.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'Tehlikeli kelimeler 🤐', 'Bir yerden duyduğu o kötü sözü gülerek size tekrarlıyor ve tepkinizi mi bekliyor? En güçlü silahınız tepkisiz kalmaktır. Gülmeyin, sinirlenmeyin, sadece görmezden gelin. O sözü kısa sürede unutacaktır.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'Dağınık ev izni 🌪️', 'Her gün aynı oyuncakları toplamaktan yoruldunuz mu? Bugün toplamayın! Ev bir müze değil, içinde hayatın kaynadığı bir yerdir. Dağınıklığa değil, çocuğunuzun özgürce öğrenme sevincine odaklanıp dinlenin.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'Aşağıya bakın, ne keşfediyor? 👣', 'Yalın ayak yürümekten, halıya veya odadaki taşlara dokunmaktan keyif alıyor. Ayak tabanındaki sinirlerin uyarılması, dengesi ve motor becerileri için çok önemlidir. Çorapsız yürümesine izin verin.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661'::uuid, 'Çift molası 🥂', 'Çocuk uyudu. Şimdi ev işlerini bir kenara bırakın. Eşinizle en az 20 dakika boyunca çocuk ve masraflar dışında herhangi bir konu hakkında sohbet edin. Siz aynı zamanda bir çiftsiniz!'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'Market alışverişinin kurtarıcısı 🛒', 'Markete gittiğinizde mutlaka en önemli şeyi unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya kaydedin, eşiniz de işten dönerken eksiksiz şekilde alsın; siz zihninizi yormayın.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'Günlüğe içini dökmek 📝', 'Biri size evde olduğunuz hâlde neden yorulduğunuzu mu sordu? Hemen Ruh Hali Günlüğü''nü açın ve tüm öfkenizi parmaklarınızla ekrana dökün. Yapmacık bir şekilde gülümsemek yerine gerçek duygularınızı yazmak terapidir.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'Sana anlatayım! ☝️', 'Zaten bildiğiniz bir şeyi gelip son derece ciddi ve bilmiş bir yüz ifadesiyle size anlatıyor. Bilgisini test ediyor. Gülmemek için kendinizi zor tutsanız da onu büyük bir ciddiyetle dinleyin ve söylediklerini onaylayın.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'Sessizliğin dijital ölçümü 🤫', 'Sonunda uykuya daldı! Evin üzerine çöken sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarak zihninizin yavaş yavaş dinlendiğini hissedin.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'Hava keşfi ⛅', 'Dışarıdaki hava tam olarak belli değil mi? Hava durumu ve kıyafet aracı, pencereden anlayamayacağınız rüzgâr hızını ve doğru kombini size anında söylesin.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'Ayakkabılarını kendi çıkarıyor 👟', 'Giydirmek artık bir güreş müsabakasına mı dönüştü? Çoraplarını ve ayakkabılarını çekip kendi çıkarıyor. Motor becerisine hayran kalın!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'Babadan gelen destek 🫂', 'Gece uyanmalarında bir sefer siz, bir sefer eşiniz kalkın. Yükü bir ekip olarak tam ortadan ikiye bölün.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'Uykuyu engelleyen tuvalet 🚽', 'Tam uykuya dalacakken birden tuvaletinin geldiğini söylüyor. Götürüyorsunuz ama hiçbir şey yok. Bu, uykuyu geciktirme sanatının en ince taktiklerinden biridir. Bağırmayın; Son kez gidiyoruz ve doğrudan yatağa dönüyoruz sınırını net bir şekilde çizin.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'Yatak gezgini 🛏️', 'Geceye kendi yatağında başlayıp sabah sizin yatağınızda, üstelik enlemesine uzanmış ve ayakları yüzünüzde hâlde uyanır. Onun bu alan işgalini gülümseyerek karşılayın. Sizin sıcak kokunuz, onun en büyük güven alanıdır.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'Kutunun büyüsü 📦', 'Ona aldığınız pahalı ve sesli oyuncağı bir kenara atıp 1 saattir oyuncağın kutusuyla mı oynuyor? Çocuk beyni hazır senaryoları değil, hayal gücüyle doldurabileceği boş nesneleri sever. Karton kutu onun için bir uzay gemisidir, dokunmayın.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'Kışın yaz isyanı ❄️', 'Dışarıda rüzgâr esiyor ama o ısrarla yazlık şortunu giymek istiyor. Açıklamaya çalışmak zaman kaybıdır. Hava ve kıyafet aracını açıp ekrandaki kalın giyinmiş çocuk simgesini ona gösterin. “Bak, telefon da bugün pantolon giymemiz gerektiğini söylüyor” hilesi harika işe yarar.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'Hayalî ısırık 🍏', 'Elinde hiçbir şey yokken size yaklaşıp “Al, ısır” diyerek hayalî bir elma uzatır. Rol oyunları, kişiliğin şekillendiği en önemli alanlardan biridir. O boşluğu büyük bir iştahla “kırt” diye ısırın ve bunun dünyanın en lezzetli elması olduğunu onaylayın.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'Penceredeki Canavar 👻', 'Dışarıda sallanan ağacın gölgesi odaya vurur ve o korkup arkanıza saklanır. Odanın ışığını açmayın. Elinize bir fener alın, gölgeye doğru tutun ve “Bak, bu sadece ağacın dansı” diyerek korkuyu sihre dönüştürün.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', 'Bana bak! maratonu 👀', 'Sabah uyanır uyanmaz tam 40 kez “Anne, bana bak” mı dedi? Zıplıyor, dönüyor ve sizin onayınızı bekliyor. Gözlerinizi telefondan ayırın; yalnızca 3 dakika boyunca tüm dikkatinizle ona bakıp “Harikasın” deyin. Bu kesintisiz ilgi, onun doyması için yeterli olacaktır.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'Annenin tembellik hakkı 🍕', 'Bugün her şeye bağırmak mı istiyorsunuz? Ev darmadağın mı? Temizliği boş verin, mutfağa girmeyin. Dışarıdan pizza veya kolay bir şey sipariş edin. Mükemmel anne yanılsamasını yıkın; ruh sağlığınız ev yemeğinden çok daha değerlidir.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'Çift koması 📺', 'Çocuk uyudu! Sonunda eşinizle film izlemek için kanepeye oturdunuz ama 10 dakika sonra ikiniz de uyuyakaldınız. Sizin gerçeğiniz bu. Birbirinize yaslanıp uyuduğunuz o yorgun ama tatlı manzara, sevginin ta kendisidir.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'Yemek seçiciliğinde mantık yoktur. 🥦', 'Düne kadar severek yediği o çorbayı bugün ağzına bile sürmüyor mu? Sağlıklı tarifler bölümüne geçerek sebzeleri püre hâline getirip renkli makarna soslarının içine nasıl gizleyebileceğinizi keşfedin. Kamuflaj sanatını öğrenin.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'Su altı krallığı 🛀', 'Küvette banyo yapmak artık temizlik değil, bir denizaltı görevidir. Bırakın sular etrafa sıçrasın. Suyun o mıknatıs etkisi, gün boyunca içinde biriken inatçı ve olumsuz enerjiyi yıkayıp gidere taşıyacaktır.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'Dâhi mucit 👟', 'Ayakkabısını kulağına tutup ciddi ciddi “Alo” diyerek bir şeyler anlatıyor. Nesnelere yeni işlevler buluyor! Bu sıra dışı ve dâhice anı kaçırmayın. Bebek fotoğraf çekimiyle bu komik mucidi kaydedip arşivinizin en gözde köşesine yerleştirin.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'Dijital sessizlik terapisi 🤫', 'Odaya sonunda mutlak bir sessizlik çöktü. Bulaşık makinesini doldurmak için acele etmeyin. Ses ölçüm aracını etkinleştirin ve ekrandaki 0 desibele kadar düşen sayıları izlerken yorgun zihninizin nasıl arındığını hissedin.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'Çöp çoğaltan sanatçı ✂️', 'Eline geçen temiz kâğıdı binlerce küçük parçaya ayırıp odaya mı saçıyor? İnce motor becerileri çalışıyor! Sinirlenip süpürgeye koşmayın. O parçaları bir kutuda toplayıp kar yağdırma oyunu oynayın.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'Aynadaki rakip 🪞', 'Aynanın karşısında durup kendi kendine kaşlarını çatıyor, öfkeli ve tuhaf mimikler yapıyor. Duyguların yüzünde nasıl göründüğünü test ediyor. Bu minyatür tiyatro oyuncusunun provasını kenardan, ses çıkarmadan ve merakla izleyin.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'Yalnızlık özlemi 🚪', 'Bütün gün üzerinize tırmanan ve size yapışan çocuktan yoruldunuz. Tuvalete girip kapıyı kapattınız ve 5 dakika yalnız kaldınız. Hemen Ruh Hâli Günlüğü''nü açın, içinizdeki o bunalmışlık hissini ekrana dökerek rahatlayın.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'Hikâyenin yönetmeni 🪄', 'Bu akşam sesiniz yoruldu. Akıllı masalları açın. Çocuğunuza “Bugün kahraman sensin, arka planda da yağmur yağıyor” diyerek özel, sakinleştirici ve kişiselleştirilmiş bir ses ortamı oluşturun ve huzurla uykuya dalmasını sağlayın.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'Kendinizle gurur duyun 🚀', 'Geriye dönüp baktığınızda onun ne kadar güçlü bir karaktere dönüştüğünü görüyorsunuz. Bugün ona uzun uzun bakın ve böylesine güzel bir insan yetiştirdiğiniz için kendinizle gurur duyun.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'Takıma teşekkür 🥂', 'Zorlu ve fırtınalı bir günü daha geride bıraktınız. Çocuğunuz uyuduktan sonra partnerinizle birer çay doldurup “Bugün bana çok yardımcı oldun, teşekkür ederim.” deyin. Ebeveynlik tek başına değil, uyumlu bir ekiple güzelleşir.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'Empati belirtileri 🧸', 'Oyuncağı düştüğünde onu okşayıp “Ağlama.” mı diyor? Demek ki empati duygusu gelişiyor! Bu tatlı dönüm noktasını Gelişim takipçisine mutlaka kaydedin.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'Ters kıyafetler 👗', 'Elindeki tişörtü ille de arkasını öne çevirerek mi giymek istiyor? Mücadele etmeyin. Bırakın bir gün de evde böyle dolaşsın; iradesini kırmayın.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'Biz bir takımız! 💖', 'Zorlu bir günün ardından eşinizle karşılıklı oturup dertleşin. Birbirinize destek olmak yükü gerçekten yarıya indirir.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'Battaniye mühendisliği 🛏️', 'Tam uykuya dalacakken birden ağlamaya başlıyor: Battaniyenin ucu kıvrıldı! Battaniyenin milimetrik düzgünlüğü onun için hayati önem taşıyor. Derin bir nefes alın, o battaniyeyi ütülenmiş gibi düzeltin ve bu komik titizliğe gülümseyip geçin.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'Şüpheli sessizlik 🤫', 'Evde birden derin bir sessizlik oldu. Ses ölçer 0 desibeli gösteriyor. Çocuk sessizse bir yerlerde büyük bir keşif yapılıyor demektir. Duvara çizilmiş resimler veya kesilmiş kâğıtlarla karşılaşmaya kendinizi hazırlayarak odaya girin.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'Tartışmaya girmeyin. 💼', '“Ben o lapayı yemem, çünkü o sarı!” Öylesine kusursuz ve ikna edici, absürt bir mantık yürütüyor ki neredeyse kendinizi suçlu hissedeceksiniz. Tartışmaya girmeyin. “Haklısın, sarı. Peki içine kırmızı orman meyveleri eklesek nasıl olur?” diyerek küçük avukatı ikna edin.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'Babanın su savaşı 🛁', 'Bu akşam banyo ritüeli tamamen babanın sorumluluğunda. Bırakın onlar suyu etrafa sıçratsın, siz de kapının arkasında sessizliğin tadını çıkarın.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'Gardırop isyanı 🥽', 'Evin içinde yüzücü gözlüğü ve kışlık bereyle dolaşmak istiyor. Israr ediyor, çıkarmıyor. Toplum kurallarını unutun. Yaratıcılığını ve karar verme özgürlüğünü kısıtlamamak için bırakın gününü o sıra dışı, komik kombinle geçirsin.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'Market arabası sürprizi 🛒', 'Kasaya yaklaştığınızda market arabasından sizin seçmediğiniz 3 farklı çikolata ve 1 adet tuhaf şekilli sabun çıktı. Hızlı bir manevrayla onları yerlerine bırakın. Bir şeyleri unutmamak ve hedefinizden sapmamak için gözünüz daima Alışveriş listesinde olsun.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'İşitme cihazı kapandı 🙉', '“Oyuncaklarını topla, gel elini yıka.” diyorsunuz ama tepki sıfır. Duymamazlıktan gelmek 3 yaşın en sevilen hobisidir. Bağırmak yerine yanına gidin ve kulağına çok hafif bir sesle fısıldayın. Ses tonunuzdaki ani değişiklik hemen dikkatini çekecektir.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'Banyo şantajı 🛀', 'Banyoya girerken ağlıyordu, şimdi ise sudan çıkmamak için feryat ediyor. Suyun çekim gücü onu büyüledi. 3 dakika önceden haber verip zamanlayıcı kurun. “Zil çalınca oyun biter.” ritüelleri her zaman işe yarar.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'Yemek tasarımcısı 🥦', 'Tabağındaki yiyecekleri renklerine ve şekillerine göre ayırıyor, yeşil olanları ise masanın kenarına itiyor. Beslenme planına göz atın. O sebzeleri nasıl görünmez bir püreye dönüştürüp köftelere ve soslara saklayabileceğinizi keşfederek bu oyunu kazanın.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'Evin başhekimi 🩺', 'Oyuncak stetoskopunu alıp göğsünüze koyuyor, kaşlarını çatarak “Nefes alın.” diyor. Siz de söz dinleyen hastasınız. Bu rol oyununu fırsata çevirin; gözlerinizi kapatıp 3 dakikalık muayene boyunca yerde uzanarak belinizi dinlendirin.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'Babanın ses telleri 📖', 'Bugün sesiniz yoruldu, boğazınız kurudu. Akşam masalını babaya devredin. O, kitaptaki resimden tamamen farklı, komik ve hayal ürünü bir hikâye anlatarak çocuğu kahkahaya boğacak. Siz de bu güzel manzarayı bir köşeden sıcak çayınızı yudumlayarak izleyin.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'Ansızın gelen sevgi 🥰', 'Oynarken oyuncağını bırakıp koşarak yanınıza gelir, kollarını boynunuza dolayıp “Seni seviyorum” der. İşte bu an, tüm o yorgunluğu ve uykusuzluğu silip süpüren bir sihirdir. Ona sımsıkı sarılın ve kokusunu içinize çekin.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'Babanın tuhaf masalı 📖', 'Bu akşam sesiniz yorgun. Masal okuma görevini babaya devredin. O, kitaptaki resimden tamamen farklı, hayal ürünü ve komik bir hikâye anlatarak çocuğu kahkahalara boğacak. Siz de bir kenarda, bir bardak çay eşliğinde bu manzarayı keyifle izleyin.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'Market arabası fırtınası 🛒', 'Kendisinden büyük olmasına rağmen kocaman market arabasını mutlaka kendisi sürmek istiyor. Herkesin içinde ağlamasındansa bırakın elleri arabanın kenarında kalsın, siz de fark ettirmeden yön verin.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'Ters giyilmiş özgürlük 👗', 'Pantolonunu ters giymiş ve son derece kararlı bir şekilde “Ben giydim” diyor. Görünüşü boş verin. Giderek artan öz güveni ve bağımsızlık hissi, kıyafetinin doğru giyilmesinden çok daha önemlidir. Bu küçük asiyle gurur duyun.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'Kaosun ortasında kahve ☕', 'Odanın ortasına bütün oyuncaklarını dağıtıp kendine bir kale kuruyor. Siz o dağınıklığı toplar toplamaz yeniden dağıtacak. Bu yüzden mücadeleyi bırakın, odanın bir köşesine geçip kahvenizi sıcakken için ve kaosu uzaktan izleyerek dinlenin.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'Odadaki gölgeler 🐰', 'Karanlıktan korkmaya mı başladı? Odayı tamamen karartın ve küçük bir el feneriyle tavanda ışık oyunları, hayvan gölgeleri oluşturun. Korktuğu karanlığı eğlenceye, uyku öncesinde birlikte gülüp keyif alacağınız küçük bir keşfe dönüştürün.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'Kesintisiz uyku umudu 🤞', 'O uyudu ve eve derin bir sessizlik çöktü. En büyük dileğiniz, bu gece uyanmaması. Ses ölçerin arka plan seslerinden biri olan hafif orman hışırtısını kısık sesle açarak derin uyku evresinde kalmasına yardımcı olun.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'Doğa laboratuvarı 🍂', 'Ev sizi bunaltıyor, çocuk ise huzursuz. Hava durumunu kontrol edip uygun şekilde giydirerek onu mutlaka dışarı çıkarın. Yalnızca kuru dalları ve yaprakları toplama göreviyle hem enerjisini atmasını sağlayın hem de siz dört duvar arasından çıkıp nefes alın.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'Oyuncakların annesi 🧸', 'Odadan ses geliyor. Dikkatle dinlediğinizde ayıcığını tamamen sizin ses tonunuzla ve sizin cümlelerinizle azarladığını fark ediyorsunuz! O sizin en iyi kopyanız. Bu, davranışlarınıza dışarıdan bakmanız için harika bir fırsat.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'Paylaşılamayan kahvaltı 🍳', 'Kendi tabağındakini size kesinlikle vermiyor ama gelip ısrarla sizin tabağınızdaki yumurtadan yemek istiyor. Çocuklar ebeveynlerinin seçimine her zaman daha çok güvenir. Mücadele etmeyin, lokmanızı bu küçük bencile sevgiyle uzatın.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'Listesiz felaket 🛒', 'Hafızanıza güvenip eve geldiniz ve çocuk için en önemli şeyi, sütü almadığınızı fark ettiniz. Zihniniz zaten fazlasıyla dolu. Bundan sonra bir ihtiyaç ortaya çıktığı anda onu uygulamadaki Alışveriş listesine yazmayı alışkanlık hâline getirerek stresten korunun.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'Küvetteki okyanus 🌊', 'Küvette banyo yapmak artık temizlik değil, dalga yaratma oyunu. Bırakın sular etrafa sıçrasın. Suyun o büyülü etkisi, gün boyunca içinde biriken inatçı ve olumsuz enerjiyi alıp gidere taşıyacak, uykusunun derinleşmesine yardımcı olacak.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'Siz mükemmelsiniz 🛑', 'Sosyal medyada her gün çocuğuyla sanat eserleri yapan, evi pırıl pırıl anneleri görüp kendinizi mi suçluyorsunuz? O filtrelere inanmayın. Sizin dağınık, gürültülü ve gerçek eviniz, çocuğunuz için en sıcak ve en mükemmel sevgi yuvasıdır.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'Küçük avukatın savunması 🗣️', '“Çikolata yiyebilirim, çünkü ben büyüdüm.” Artık neden-sonuç ilişkisi kurarak sizi ikna etmeye, sizinle pazarlık yapmaya çalışıyor! Dil gelişimi harika. Onu takdir edin, ancak sınırlarınızı ve kurallarınızı da sevgiyle koruyun.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'Sessizlik terapisi 🤫', 'Sonunda uykuya daldı! Ses ölçeri etkinleştirin ve ekrandaki sayıların 0 desibele kadar düşüşünü izlerken yorgun zihninizin nasıl arındığını, bu görsel sessizliğin size nasıl masaj yaptığını hissedin.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'Mutfak kazası 🧑‍🍳', 'Siz hamur açarken gelip elini una daldırıyor ve her yeri bembeyaz yapıyor. Evet, mutfak battı ve işiniz arttı. Ama o ciddi, çalışkan yüz ifadesini Bebek fotoğraf çekimi ile hemen kaydedin. Kir geçecek, o anı kalacak.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'İlk anlamsız şaka 🤡', '“Köpek arabaya bindi, patladı!” deyip kendi kendine kahkahalarla gülüyor. Ortada bir anlam yok ama o, mizah anlayışını yeni keşfediyor. Mantık aramayın; siz de onun bu saf ve neşeli kahkahasına yüksek sesle katılın.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'Kaydırak siyaseti 🛝', 'Parkta kaydırağın tepesinde durup diğer çocukların kaymasına izin vermiyor. Utanıp onu sertçe aşağı çekmeyin. Etraftakilere aldırmadan, sıra kuralını ona yumuşak bir sesle hatırlatın. O, sahiplenme duygusunu böyle koruyor.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'O artık bebek değil! 🌟', 'Kendi kararları, tuhaf soruları ve kocaman bir kalbi olan başlı başına bir insan. Onun bu güçlü karakterini kırmadan, yol göstererek büyüttüğünüz için kendinize kocaman bir teşekkür edin. Harika iş çıkarıyorsunuz.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'Şampanyasız zafer 🥂', 'Zor bir günün ardından bardaklara sıradan sıcak çay doldurun. Eşinizle kanepede karşılıklı oturup “Bugün o kaostan da sağ çıktık.” diyerek bardaklarınızı tokuşturun. Siz bu evin hem komutanları hem de takımsınız.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'Topluluğun gücü 💬', '“Benim çocuğum neden bu kadar inatçı?” düşüncesi zihninizi kemiriyor. Anacan Topluluğuna katılın. Diğer annelerin evlerinde yaşanan benzer tuhaf krizleri okuduğunuzda yalnız olmadığınızı ve tamamen normal bir süreçten geçtiğinizi göreceksiniz.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'Işıkların ritmi 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm gereksiz ışıkları ve tablet ekranlarını kapatın. Melatonin, karanlık ve teknolojiden uzak bir ortamda daha hızlı salgılanarak işinizi kolaylaştırır.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'Dinozorun kahvaltısı 🦖', 'Kahvaltıda ellerini kullanmadan, ağzını doğrudan tabağa götürerek bir dinozor gibi yemek istiyor. Görgü dersi vermeyin! Bırakın 5 dakika boyunca dinozor olsun; bu oyundan sıkılınca kaşığı zaten eline alacaktır.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', '“Kendim yapacağım” hızı 🐢', 'Evden çıkmanız gerekiyor ama ayakkabısını mutlaka kendisi giyecek ve bu, kaplumbağa hızıyla 15 dakika sürüyor. Müdahale ederseniz ağlama krizi 30 dakika sürecek. Kaybettiğiniz zamana değil, onun incinmeyen özgüvenine odaklanıp bekleyin.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'Kaybolan anahtarlar 🔑', 'Evin anahtarlarını bulamıyor musunuz? Buzdolabına veya ayakkabı dolabına bakın. O, eşyaları saklayarak nesne sürekliliğini test ediyor. Bu komik hazine avında sinirlenmek yerine gülmeyi seçin.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'Fısıltının hipnozu 🤫', 'Yatağa uzanıp bacaklarını havaya kaldırıyor ve uyumak istemiyor. Bağırmak yerine ses tonunuzu aniden alçaltın ve onunla yalnızca fısıldayarak konuşun. Çocuğunuz sizi duyabilmek için dikkat kesildiğinde beyni otomatik olarak sakinleşip uyku moduna geçecektir.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'Kolların dinlenme vakti 🫂', 'Bütün gün üzerinize tırmanmasından ve kucak istemesinden bedeniniz ağrıyor. Akşam görevi babaya devredin. Baba, çocuğu sırtına alıp atçılık oynadığında hem çocuğun ilgi ihtiyacı karşılanır hem de kollarınız ihtiyaç duyduğu dinlenmeye kavuşur.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'Sabah konseri 🎤', 'Güneş daha tam doğmamışken yatağın üzerinde zıplayıp anlamadığınız bir dilde yüksek sesle şarkı söylüyor. Evet, uykunuz var ama odada dolaşan bu yaşam enerjisi sizi de ayağa kaldıracak. Onun sesine yalnızca gülümseyin.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'Yapay zeka kurtarıcısı 🤖', '“Anne, güneş uyumak için nereye gidiyor?” sorusu karşısında donup kaldınız mı? Açıklamayı karmaşıklaştırmayın. Anacan AI''a çocuğunuzun yaşını belirterek bu soruyu sorun; 3 yaşındaki bir zihnin kolayca anlayabileceği, hikâye tadındaki o harika yanıtı alın ve ona anlatın.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'Sessiz gözyaşları 💖', 'Bütün gün sizi çileden çıkardı. Ama şimdi yatakta o kadar masum uyuyor ki ona bakıp duygulanıyorsunuz, değil mi? Anneliğin en büyük paradoksu tam da budur. Gözünüzden süzülen o bir damla yaş, onun varlığı için duyduğunuz şükrandır.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'Gizli besin operasyonu 🥣', 'Düne kadar sevdiği yumurtayı bugün ağzına bile sürdürtemiyorsunuz. İradesiyle savaşmayın. Sağlıklı tariflerde proteinleri farklı, renkli ve ilgi çekici biçimlere dönüştüren akıllıca atıştırmalık tariflerini uygulayın ve kazanan siz olun.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'Mantığın çöküşü 🛑', 'Suyunu kırmızı bardakta vermeniz için bağırıyor; kırmızı bardağa koyduğunuzda ise bu kez “Neden buna koydun?” diyerek ağlıyor. Burada mantık yok. O sadece yorgun ve bir kriz yaşamaya ihtiyaç duyuyor. Sakince bekleyin; fırtına kendiliğinden dinecek.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', 'Anne, bak! dönemi 👀', 'Kanepeden atlıyor ve her defasında aynı hareketi tam 50 kez yaparak Anne, bana bak! diyor. Gözlerinizi telefondan ayırın. O, hareketin kendisi için değil, gözlerinizdeki o onay ışıltısını görmek için atlıyor. Ona kesintisiz 5 dakika ayırın, ilgiyi doyasıya yaşasın.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'Müzikli hipnoz 🎶', 'Akşamüstü kopan sebepsiz fırtınalar, ağlama krizleri başladı. Televizyonu kapatın, ışıkları azaltın ve odada çok hafif bir klasik müzik çalın. Müziğin o derin frekansı atmosferi sihirli bir şekilde değiştirecek ve odaya huzur getirecek.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'Çizgi film senaristi 📺', 'İzlediği çizgi filmi size öylesine farklı bir kurguyla ve o kadar inandırıcı anlatıyor ki neredeyse inanacaksınız. Harika bir hayal gücü gelişiyor.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'Annenin sıfırlama düğmesi 🚪', 'Gürültü beyninizi deliyor, her şeye bağırmak istiyorsunuz. Duygu günlüğünü açın. Tüm tükenmişliğinizi oraya özgürce yazın. Bu kısa dijital terapi yeniden toparlanmanızı sağlayacak.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'Karanlıkla dans 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm gereksiz ışıkları ve tablet ekranlarını kapatın. Melatonin (uyku hormonu), karanlık ve teknolojiden uzak bir ortamda hızla salgılanarak uykuya geçişi kolaylaştırır.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'Sokaktaki hazine 🍁', 'Yerde bulduğu kirli bir şişe kapağını veya farklı renkteki bir taşı, altın bulmuşçasına sevinçle size gösteriyor. Onu at, kirli demek yerine, Ne kadar ilginç bir rengi var, gel evde yıkayalım diyerek keşfetme hevesini takdir edin.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'Felsefe saati geri döndü 🤔', 'Rüzgâr neden esiyor? Yapraklar neden dökülüyor? Derin felsefi sorular sabah sabah zihninizi zorluyor. Açıklamayı karmaşıklaştırmayın, doğayı onun anlayabileceği bir masal diliyle anlatın. Ses tonunuz, onun için evreni anlamanın en güvenli yoludur.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'Mutfakta konser 🥄', 'Tencereleri ve tahta kaşıkları çıkarıp mutfağın ortasında konser veriyor. Başınız ağrısa da bu, onun ritim duygusunun ve yaratıcılığının geliştiğini gösterir. Hemen müdahale etmeyin; birkaç dakika boyunca o çılgın enerjinin ses dalgalarıyla odaya yayılmasına izin verin.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'Toplulukta teselli 💬', 'Benim çocuğum neden bu kadar inatçı? düşüncesi içinizi kemiriyor. Anacan Topluluğuna katılın. Diğer annelerin evlerinde yaşanan benzer tuhaf krizleri okuduğunuzda yalnız olmadığınızı ve son derece normal, sağlıklı bir çocuk büyüttüğünüzü göreceksiniz.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'Nefesinin sıcaklığı 💖', 'Bütün gün sizi çileden çıkardı, her şeye ağladı. Ama şimdi yatakta göğsünüze sokulmuş ve oda onun ritmik, sıcak nefesiyle doluyor. Anneliğin en büyük ödülü işte budur. Onu bağrınıza basın ve tüm yorgunluğun bu nefesle uçup gittiğini hissedin.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'Ekip çalışmasının meyvesi 🥂', 'Zorlu ve fırtınalı bir günü daha geride bıraktınız. Çocuğunuz uyuduktan sonra partnerinizle birer çay doldurun ve Bugün bu kaostan da sağ çıktık, harika bir ekibiz diyerek birbirinize teşekkür edin. Ebeveynlik tek başına değil, destekle güzelleşir.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'Ters ayakkabı 👟', 'Ayakkabılarını ters giymiş ama dünyayı fethetmiş gibi gururla yürüyor. Müdahale edip düzeltmeye çalışırsanız her şey bozulacak. Özgüveni ve bağımsızlığı, estetikten daha önemlidir. Bırakın bu küçük asi gururla yürüsün.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'Mutfakta sabotaj 🧑‍🍳', 'Siz hamur açarken gelip elini una daldırıyor ve her yeri bembeyaz yapıyor. Evet, mutfak battı. Ama o ciddi, çalışkan yüz ifadesini Bebek fotoğraf çekimi ile hemen ölümsüzleştirin. Mutfak temizlenir, o komik kare ise sonsuza dek kalır.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'Canlı ayna 🦜', 'Sizin sinirlendiğinizde yaptığınız mimiği aynen taklit ederek oyuncağını azarlıyor. Hemen kendinize dışarıdan bakın! O, ne görürse onu kopyalıyor. Bu komik ama düşündürücü manzara, davranışlarınıza daha fazla dikkat etmeniz için harika bir aynadır.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'Akıllı masalda ben 🪄', 'Klasik kitapları ezberlediniz ve okumaktan yoruldunuz. Akıllı masalları açın. Başkahramanı çocuğunuz, arka planı ise rahatlatıcı orman sesleri olacak şekilde tasarlayıp sıra dışı ve hiç çaba gerektirmeyen bir uyku seansı oluşturun.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'Temiz hava ⛅', 'Hava durumunu kontrol edip uygun kıyafetleri seçerek onu mutlaka dışarı çıkarın. Yalnızca kuru dalları ve taşları toplama göreviyle hem onun enerjisini atmasını sağlayın hem de siz dört duvar arasından çıkıp derin bir nefes alın.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'Yatak göçü 🛏️', 'Gece doğru pozisyonda uyur, sabah ayakları yastıkta, başıysa yatağın tam karşı köşesinde uyanır. Uykusunda bile dünyayı keşfediyor! Onu uyandırmadan önce bu komik yatak göçünü kahkahalarla izleyin.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'Felsefi uyku ertelemesi 🦉', 'Tam yatağa girdiğinde Anne, yıldızlar neden düşmüyor? gibi derin sorular sorar. Amacı bilim öğrenmek değil, uykuyu ertelemektir. Sorularına kısa, hayal ürünü ve sevimli cevaplar verip hemen Akıllı masallarla odaya uyku sessizliğini getirin.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'Kostümlü kahraman 🦸‍♂️', 'Evin içinde ısrarla kışlık botlarıyla veya süper kahraman maskesiyle dolaşmak mı istiyor? Toplumsal kuralları ve estetik kaygıları boş verin. Bu, onun kimliğini keşfetme sürecidir. Bırakın odada botlarıyla kendini bir kahraman gibi hissetsin.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'Dinozorun dişleri 🦖', 'Dişlerini fırçalamayı kesinlikle reddediyor ve fırçayı fırlatıyor. Oyuna geçin! Eline yedek bir fırça verip Gel, önce oyuncak dinozorunun dişlerini fırçalayalım deyin. O dinozorun dişlerini fırçalarken siz de fark ettirmeden onun dişlerini fırçalayın.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'Bağımsızlık lekeleri 🥣', 'Yoğurdu mutlaka çatalla yemek istiyor ve her yeri batırıyor. Dışarıdan müdahale edip elinden almayın. Dökülen yiyecekler temizlenir ama onun ben kendim yaparım özgüvenini yeniden kazanması zordur. Silikon önlüğünü takıp bu manzarayı sabırla izleyin.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'Annenin 10 dakikası 🚪', 'Gürültü zihninizi uyuşturdu. Duygu günlüğünü açın, bugün sizi çileden çıkaran her şeyi özgürce ekrana dökerek içinizdeki sıfırlama düğmesine basın.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'Çöpün cazibesi 📦', 'Onca pahalı ve ışıklı oyuncak varken gidip boş bir plastik su şişesiyle veya karton kutuyla saatlerce oynuyor. Çocukların hayal gücü, hazır senaryolar yerine yaratıcılığa açık, sıradan nesneleri sever. İzleyin ve öğrenin.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'Rüya isyanı ☁️', 'Sabah uyanır uyanmaz kaşlarını çatıp size küsüyor. Sebebi mi? Rüyasında ona istediği oyuncağı vermemişsiniz! Çocuk beyni henüz rüyayla gerçeği tam olarak ayıramaz. Ciddi bir şekilde özür dileyin ve bu tuhaf duruma içinizden gülümseyin.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'Sessiz bakışma 🥂', 'Çocuk sonunda uyudu. Siz ve eşiniz kanepede yan yana oturuyorsunuz ve konuşacak hâliniz bile yok. Yalnızca sessizce birbirinize bakıp gülümsüyorsunuz. Evet, bu sessiz bakışma bu kaosun üstesinden geliyoruz demenin en güzel yoludur.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'Duvardaki tiyatro 🐰', 'Karanlıktan korktuğunu söyleyerek yataktan kaçıyor. Odadaki bütün ışıkları kapatın, el fenerini yakın ve ellerinizle duvarda kuş, köpek gölgeleri oluşturun. Korktuğu karanlık, saniyeler içinde onun için dünyanın en güvenli tiyatrosuna dönüşecek.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'Parktan ayrılma taktiği 🌳', 'Parktan dönme zamanı geldi ve ağlama krizleri başladı. Onu zorla sürükleyerek götürmeye çalışmayın. Bakalım arabaya kadar kim daha hızlı koşacak? diyerek bir yarış başlatın. Çocuklar yarışmaya ve kazanmaya asla hayır demez.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'Görünmez misafir 👻', 'Kahvaltıda hayalî arkadaşı için de masaya bir tabak koymanızı istiyor. Bu, psikolojik bir eksiklik değil, zihinsel gelişimde bir sıçramadır. O tabağı masaya koyun, misafirinize hayalî çay da doldurarak bu harika tiyatronun bir parçası olun.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'Yeni kelime keşifleri 🗣️', 'Eşyalara tamamen kendi uydurduğu, hiçbir dilde bulunmayan yeni adlar veriyor. Üstelik sizin de o kelimeleri kullanmanızı ısrarla istiyor! Gelişim takipçisini açın ve gelecekte okuyup gülmek için bu komik kelimeleri mutlaka kaydedin.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'Evin gizli hazineleri 🔑', 'Evin anahtarlarını veya kumandayı bulamıyor musunuz? Oyuncak fırının içine ya da yatağının altına bakın. Eşyaları saklayarak evrenin nasıl işlediğini test ediyor. Bu komik hazine avında sinirlenmek yerine gülmeyi ve derin bir nefes almayı seçin.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'Banyo paradoksu 🛀', 'Küvete girmek istemediği için ağlıyordu, şimdi de çıkmamak için feryat ediyor! Suyun büyülü ve sakinleştirici etkisi onu adeta hipnotize etti. Sudan çıkışı dramatik hâle getirmemek için havluya sıcak kucak adını verin, onu sarıp küvetten çıkarın.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'Benim! inadı 🧸', 'Evdeki herhangi bir eşyaya sarılıp Bu benim! diye bağırıyor ve onu kimseye vermiyor. Mülkiyet sınırlarını keşfediyor. Onu bencillikle suçlamayın; yalnızca o an için o eşyanın ona ait olmasına izin verin.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'Sesinin rengi 🌙', 'O, kitaptaki masalın konusunu değil, sizin ses tonunuzu dinliyor. Bu akşam konuyu unutun. Hikâyeyi uzata uzata, huzurlu bir müzik gibi alçak sesle okuyarak sinir sistemine doğrudan uyku sinyali gönderin.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'Sosyal medya illüzyonu 📱', 'İnternetteki mükemmel anneleri görüp evinizin dağınıklığı yüzünden kendinizi suçluyor musunuz? Durun. O 15 saniyelik filtreli videolara inanmayın.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'Sessizliğin desibeli 🤫', 'Sonunda uykuya daldı! Odayı toplamaya koşmayın. Ses ölçer aracını etkinleştirin ve ekrandaki o 0-10 desibel değerine bakın. Evdeki mutlak sessizliğin bu görsel kanıtı, yorgun beyninize en güzel masaj gibi gelecek.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'Felsefe profesörü 🧐', '“Anne, güneş neden orada?” değil, sadece “Güneş neden var?” diye soruyor. Soruları giderek soyutlaşıyor. Saatlerce bilimsel açıklamalar yapmaya çalışıp zihninizi yormayın. “Çünkü bizi ısıtmayı seviyor.” gibi kısa, masalsı ve sıcak bir cevap onu tamamen tatmin edecektir.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'Ayaklar tatilde 🚶‍♂️', 'Sokağın ortasında aniden yere oturup “Ayaklarım kırıldı, beni kucağına al.” diyor. Hayır, yorulmadı; yalnızca sizi test ediyor. Bu şantaja boyun eğmeyin. “Bakalım arabaya kadar penguen gibi nasıl gideceğiz?” diyerek onu oyuna dahil edin.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'Renkli beslenme 🥕', 'Bugün yalnızca turuncu renkli şeyler yemeye karar verdi ve diğer her şeyi reddediyor. Çocuk mantığı yine iş başında! Sağlıklı tariflerde sebzeleri nasıl kamufle edebileceğinizi keşfedin. Balkabağı ve havuç püresiyle hazırlanan farklı tariflerle bu inadın üstesinden gelin.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'Sabah solisti 🎤', 'Daha gün doğmadan, siz gözlerinizi güçlükle açarken o, elindeki oyuncakla odanın ortasında konser veriyor. Onu susturmaya çalışmayın. Çocukların bu çılgın ve bitmek bilmeyen yaşam enerjisi aslında eve bereket ve neşe getirir. Ona gülümseyerek bakın.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'Şifa veren dokunuş 💆‍♂️', 'Yatakta bir türlü sakinleşmiyor. Masalı ve müziği bir kenara bırakın. Küçük ayaklarına veya sırtına çok hafif, okşar gibi masaj yapın. Fiziksel temas hem onun hem de sizin vücudunuzdaki kortizolü (stres hormonunu) hızla azaltarak uykuyu getirecektir.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'Görünmez kırıntılar 🧹', 'Elindeki küçük süpürgeyle halının üzerindeki görünmez tozları son derece ciddi bir yüz ifadesiyle temizliyor. Yalnızca sizi taklit ediyor. Onun bu sorumluluk dolu anını Bebek fotoğraf çekiminde ölümsüzleştirin; evin en küçük ve en tatlı temizlik görevlisi iş başında.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'Ses Ölçer terapisi 🤫', 'Evdeki o çılgın kasırga sonunda yatağa teslim oldu. Odada bulaşık makinesinin sesinden başka hiçbir şey duyulmuyor. Ses ölçer aracını açın, ekrandaki o düşük desibel değerlerine bakarak gözlerinizi kapatın. Bu görsel sessizlik, beyniniz için en iyi masajdır.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'Kedi gibi uyanış 🐾', 'Bu sabah o bir insan değil. Dört ayak üzerinde yürüyor, bacağınıza sürtünüyor ve yalnızca miyavlayarak iletişim kuruyor. Bu, hayal gücünün en tatlı ve en yüksek noktası. Kural koymak yerine siz de ona hayalî bir süt kabı uzatıp bu oyunun tadını çıkarın.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'Toplulukta itiraf 💬', 'Bugün her şeye bağırdınız ve kendinizi dünyanın en sabırsız annesi gibi mi hissediyorsunuz? Lütfen yalnız olmadığınızı bilin. Anacan Topluluğuna katılın, diğer annelerin de bugün en az sizin kadar tükendiğini okuyarak vicdan azabınızı susturun.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'Babanın çılgın masalı 📖', 'Bu akşam odada duyulan ses sizinki olmasın. Masal kitabını babaya verin ve hikâyeyi bilerek ters, komik ve absürt bir şekilde anlatmasına izin verin. Çocuğunuzun onu düzeltmekten nasıl keyif aldığını ve babasına nasıl kahkahalarla güldüğünü uzaktan izleyin.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'Avangart mimar 🥞', 'Kahvaltıdaki krepleri üst üste dizip kule yapıyor, ortalarını delip parmağını içinden geçiriyor. Yiyeceklerle oynamak onun için yeni bir mühendislik projesi. Masanın kirlenmesini görmezden gelin; yiyeceklerin dokusunu da böyle keşfediyor.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'Hayalî mağaza 🍅', 'Odanın bir köşesine oyuncaklarını yığıp size hayalî parayla hayalî domates satıyor. Bu ticaret oyununu son derece ciddiye alın. O hayalî domatesi satın alıp iştahla yiyormuş gibi yapın. Rol oyunları, onun sosyal zekâsının ve matematiksel düşünme becerisinin en güçlü temelidir.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'Annenin gizli çikolatası 🍫', 'Mutfak dolabının arkasında ondan gizlice bir parça çikolata yiyen anne, o glikoz sizin en doğal hakkınız. Bütün gün o enerjiye ve bitmek bilmeyen “neden”lere dayanabilmek için sizin de şarj olmanız şart. Nefes alın ve keyifle çiğneyin.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'Gece terörü 😭', 'Gecenin bir yarısı gözleri kapalı hâlde ağlayarak uyanıyor ve kimseyi duymuyor. Ağlama analiziyle durumu doğrulayın; eğer bu bir gece terörüyse onu sarsmayın ve uyandırmaya çalışmayın. Yalnızca yanında sessizce durarak ona güven verin, geçecektir.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'Buz gibi mantık 🥶', 'Buzdolabını açıp buz kalıbını istiyor ve elleri üşümesine rağmen onu bırakmıyor. Sıcak ve soğuk kavramlarını bedeniyle test ediyor. Bir kaba ılık, diğerine buzlu su koyarak bu keşfi küçük bir bilimsel deneye dönüştürün; inadı anında kırılacaktır.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'Doğaya kaçış şart ⛅', 'Dört duvar arasında enerjisi agresifliğe dönüşüyor ve her cümlesi hayırla başlıyor. Hava ve kıyafet koşulları ne olursa olsun, uygun şekilde hazırlanıp onu mutlaka dışarı çıkarın. Toprağa dokunmak sinir sistemini hızla dengeleyecektir.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'Gece lambası 🌙', 'Yatak odasındaki ışıklar söndüğünde huzursuz mu oluyor? Odanın bir köşesine küçük, sıcak renkli (turuncu veya kırmızı) bir gece lambası koyun. Odanın geri kalanı ise melatonin salgılanması ve derin uyku için tamamen karanlık kalmalıdır.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'Dijital listenin kurtarıcılığı 🛒', 'Marketin ortasında durup buraya ne almaya gelmiştim diye mi düşünüyorsunuz? Annelik zihni zaten bin parçaya bölünüyor. Bir ihtiyaç doğduğu anda onu uygulamadaki Alışveriş listesine yazmayı alışkanlık hâline getirerek yükünüzü hafifletin.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', 'Size yardım edeyim! hamlesi 🧽', 'Siz bulaşıkları yıkarken yanınıza bir sandalye çekip suyla oynamak mı istiyor? Aslında yardım etmekten çok sürecin tam merkezinde olmak istiyor. Ona küçük, plastik bir kap ve sünger verin. Mutfak su içinde kalacak ama onun özgüveni büyüyecek.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'Müziğin sihirli frekansı 🎶', 'Akşama doğru kopan sebepsiz fırtınaları ve çığlıkları hafif bir klasik müzikle yatıştırmayı deneyin. Çoğu zaman bu basit ama etkili yöntem, odadaki gergin atmosferi sihirli biçimde değiştirir ve çocuğu huzura kavuşturur.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'Gardırop mühendisi 👗', 'Bugün dışarıya birbirinden farklı çoraplar ve ters giyilmiş bir tişörtle çıkmak istiyor. Toplumun uyum kurallarını boş verin. Kendi kararını verme ve bunu savunma özgürlüğü, renk uyumundan çok daha büyük bir hayat dersidir. İzin verin.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'Yapay zekâ ve huzur 🤖', '3 buçuk yaşına yaklaşan çocuğunuzun ani duygu değişimleri sizi endişelendirdi mi? İnternetteki korkutucu ve travmatik forumları kapatın. Anacan AI''dan bu yaş krizleri hakkında bilimsel ve psikolojik temellere dayanan, sakinleştirici bir yanıt alın.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'Senaryoyu o yazsın 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız ve odada bunaltıcı bir hava mı var? Akıllı masalları açın ve bu akşam hikâyeyi onun yönlendirmesine izin verin. Şimdi bu uçan araba nereye gitsin diye sorun; hayal dünyasını fethederek uykuya dalsın.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'Fısıltının hipnozu 🤫', 'Yatakta uzanıp ayaklarını havaya kaldırıyor ve kesinlikle uyumak istemiyor. Bağırmak yerine sesinizi bir anda alçaltın ve onunla yalnızca fısıldayarak konuşun. Çocuğunuz sizi duyabilmek için dikkat kesildiğinde beyni otomatik olarak sakinleşip uyku moduna geçecektir.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Anne için çevrimdışı bir an 🛋️', 'O çizgi film izlerken veya oyuncaklarıyla oyalanırken siz bulaşık makinesini boşaltmaya ya da çamaşır asmaya mı koşuyorsunuz? Durun! O 10 dakikayı yalnızca koltuğa uzanıp tavana bakarak ve hiçbir şey düşünmeyerek geçirin. Siz robot değilsiniz.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'Yarım kalan cümleleri tamamlayın 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaret edip kaşlarını çatıyor ve sizin bulmanızı mı bekliyor? Kelime dağarcığı büyüyor; yalnızca beyni, dilinden daha hızlı çalışıyor. Cümlesini sabırla tamamladığınızda yüzünde beliren evet, tam da bunu söylüyordum rahatlamasını izleyin.'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'Yemek tasarımcısı 🥦', 'Tabağındaki yiyecekleri renklerine ve şekillerine göre ayırıyor, yeşil olanları ise kenara mı itiyor? Sağlıklı tariflere göz atın. Sebzeleri görünmez bir püreye dönüştürüp lezzetli sosların içine nasıl saklayacağınızı keşfederek bu oyunu gizlice kazanın.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'Babanın sırtında ata binmece 🐴', 'Enerjisini tam olarak atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Baba, çocuğu sırtına alıp atçılık oynadığında kahkahalar odayı doldurur; biriken tüm fiziksel gerginlik ve o bitmek bilmeyen enerji, ter atarak saniyeler içinde yok olur.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'Tehlikeli kelimeler 🤐', 'Sokakta veya televizyonda duyduğu o kötü kelimeyi gülerek size tekrarlıyor ve büyük bir merakla tepkinizi mi bekliyor? En güçlü silahınız tepki vermemektir. Gülmeyin, sinirlenmeyin; yalnızca görmezden gelin. O kelimeyi kısa sürede unutacaktır.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'Küvetteki okyanus 🌊', 'Küvette yıkanmak artık temizlik değil, dalga yaratma oyunudur. Bırakın sular etrafa sıçrasın, banyonuz ıslansın. Suyun o büyülü etkisi, gün boyunca içinde biriken inatçı ve negatif enerjiyi yıkayıp gidere götürecek.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'Kapı ardındaki sırlar 🚪', 'Odasına girip kapıyı arkasından kapatmak, yalnız kalmak mı istiyor? Kişisel alan ve bireysellik anlayışı gelişiyor. Gerekli güvenlik önlemlerini alarak ona bu küçük mahremiyet hakkını tanıyın. O büyüyor.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'Ruh Hali Günlüğü''nde itiraf 📝', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının kusursuz hayatlarını kaydırmak yerine Ruh Hali Günlüğü''nü açın ve bugün yaptığı en komik, sizi en çok güldüren anı gelecek için kaydedin. Oraya yazmak en saf terapidir.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'Çiftlere özel kutlama 🥂', 'Çocuk uyudu. Şampanya olmasa da bardaklara sıcak çay doldurun ve eşinizle “Bu fırtınalı günü de sağ salim atlattık” diyerek bardaklarınızı tokuşturun. Siz bu evin hem komutanları hem de sarsılmaz ekibisiniz.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'Mantıksız gözyaşları 🐶', 'Sokakta gördüğünüz köpek ona bakmadı ya da yaprak yere düştü diye hıçkıra hıçkıra ağladı mı? Bu durumda mantık aramayın. Bu, onun için gerçekten derin bir üzüntüdür. “Biliyorum, onun sana bakmasını istiyordun” diyerek sadece duygusunu kabul edin.'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'Parkta diplomasi 🤝', 'Kaydırakta başka bir çocuğu itip kendisi kaymak mı istiyor? Paylaşmak, onun için henüz tam olarak yerleşmemiş karmaşık bir kavramdır. Onu utandırmak veya cezalandırmak yerine “Şimdi onun sırası” diyerek sadece kuralı hatırlatın.'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'Bedenin feryadı 🩸', 'Nedensiz gerginliğe ve yorgunluğa teslim olmayın. Regl Takipçisi''ne bakın, bedeniniz sinyal veriyor. Kendinizi suçlamak yerine magnezyum açısından zengin bir atıştırmalıkla dinlenin.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'Gölgeyle savaş 👻', 'Duvardaki gölgesinden korkup arkanıza mı saklanıyor? 3 yaşın ortalarına doğru hayal gücü sınır tanımaz. Odayı karartıp el feneriyle duvarda gölge oyunları yapın. Korktuğu karanlığı onun için en büyük eğlenceye dönüştürün.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'Masalların büyüsü 🪄', 'Klasik okuma tarzını bir kenara bırakın. Akıllı masalları açın. Masaldaki rüzgârın sesini, kapının gıcırtısını ve kahramanın ayak seslerini ağzınızla taklit ederek odada küçük bir ses tiyatrosu yaratın. Bu performansa hayran kalacak.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'Uykuyu erteleme taktiği ⏱️', 'Uyku vakti geldiğinde birden susuyor, tuvalete gitmek istiyor veya duvarla vedalaşıyor mu? Zamanlayıcı kurun. “Zil çalınca herkes uyur” kuralını uygulayarak bu sonsuz vedalaşmadan ve ustaca manipülasyondan sabırla kurtulun.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'Oyuncakların annesi 🧸', 'Odadan ses geliyor. Dikkatle dinliyorsunuz ve oyuncağı olan ayıyı tamamen sizin ses tonunuzla, size özgü cümlelerle azarlıyor! O sizin en kusursuz kopyanız. Bu, kendi davranışlarınıza dışarıdan bakmanız için mükemmel bir fırsattır.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'Hava keşfi ⛅', 'Dışarıdaki hava pek net değil; güneş var ama rüzgâr da esiyor mu? Hava ve kıyafet aracı, pencereden göremediğiniz rüzgâr hızını ve doğru kombini size anında söylesin; kapıda kararsız kalıp vakit kaybetmeden yürüyüşe çıkın.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'Babanın gizli taktiği 👨‍🍼', 'Günün yorgunluğu ve gürültüsü size fazlasıyla yetti. Akşamüstü çocuğu uykuya hazırlama ve dişlerini fırçalatma sürecini babanın eğlenceli oyunlarına bırakın; siz de başka bir odada mutlak sessizlik içinde dinlenin.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'Annenin enerji barı 🥑', 'Onu yedirmek için 4 farklı şekilde menü hazırladınız, peki siz ne yediniz? Sağlıklı tarifler arasından 5 dakikada hazırlanan, kalsiyum açısından zengin özel bir atıştırmalık seçin ve ayakta da olsa tadını çıkarın; siz bu evin motorusunuz.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'Paylaşılamayan kahvaltı 🍳', 'Kendi tabağındakileri size kesinlikle vermiyor ama ısrarla gelip sizin tabağınızdaki yumurtadan veya peynirden yemek istiyor. Çocuklar, ebeveynlerinin seçimlerine her zaman tamamen güvenir. Mücadele etmeyin, lokmanızı sevgiyle ona uzatın.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'Takım masajı 💆‍♂️', 'Çocuk uyuduktan sonra günün tüm fiziksel ve psikolojik stresini atmak için partnerinizle birbirinize omuz masajı yapın. Siz yalnızca aynı evi paylaşan ebeveynler değil, sarsılmaz bir destek ekibisiniz.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'Bu benim hatam değil! 🤷‍♂️', 'Suyu bilerek yere döktü, ancak suçu masaya atıp “Masa kaydı” dedi. Bu bir yalan değil, kendini savunma içgüdüsüdür. İnatlaşmayın; “Hadi masaya yardım edip birlikte silelim” diyerek onu incitmeden sorumluluk duygusu kazandırın.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'Topluluk desteği 💬', '“Bir daha asla eski, özgür halime dönemeyeceğim” düşüncesi bir anda içinizi daraltıyor mu? Geçici ama son derece ağır ve derin olan bu duyguyu Anacan Topluluğundaki annelerle paylaşın; onların da aynı yollardan geçtiğini görerek teselli ve destek alın.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'Sadece sarılın 🫂', 'Hiçbir oyuna, sesli kitaba veya masala gerek yok. Bu akşam sadece onu göğsünüze bastırın, o tertemiz kokusunu derin derin içinize çekin ve karanlıkta onun ne kadar değerli olduğunu, onu ne kadar sevdiğinizi fısıldayın.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', 'Markette “Ben süreceğim” inadı 🛒', 'Market arabasını kendi sürmek istiyor ve raflara çarparak ortalığı birbirine katıyor. Toplum içinde ağlamasına yol açmak yerine ellerinin arabanın kenarında kalmasına izin verin, siz de fark ettirmeden yönlendirin. Unuttuklarınızı ise Alışveriş listesinden kontrol edin.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'Oyuncak karmaşası 🌪️', 'Her gün aynı oyuncakları toplamaktan yoruldunuz mu? Bugün toplamayın! Ev bir müze değil; içinde hayatın kaynadığı ve küçük bir kaşifin büyüdüğü sıcacık bir yerdir. Dağınıklığa değil, çocuğunuzun özgürce keşfetme sevincine odaklanıp dinlenin.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'Aşağı bakın, neler keşfediyor? 👣', 'Çıplak ayakla yürümekten; halıya, odadaki taşlara veya soğuk fayansa dokunmaktan keyif alıyor. Ayak tabanındaki sinirlerin uyarılması, denge ve nörolojik gelişimi açısından çok önemlidir. Çorapsız yürümesine kesinlikle engel olmayın.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'Yapay zekâ, gerçek çözüm 🤖', 'Çocuğunuzun her şeye sert tepki vermesi sizi korkuttu mu? İnternetteki kaygı uyandıran yazıları unutun. Anacan AI''a bunun yalnızca geçici bir stres tepkisi olup olmadığını sorun; bilimsel ve çocuk doktorlarınca onaylanmış bir yanıt alarak rahatlayın.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'Sessizliğin dijital ölçüsü 🤫', 'Sonunda uykuya daldı! Eve çöken sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarken beyninizin yavaş yavaş nasıl toparlanıp dinlendiğini görsel olarak hissedin.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'Işıkları kapatın, uyku gelsin 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin (uyku hormonu), karanlık ve teknolojiden uzak bir ortamda daha hızlı salgılanarak uykuya geçişi kolaylaştırır.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'Bloglardan ilham alın 📱', '40. aya yaklaşırken çocuğun gelişim sıçramaları nelerdir? Neleri yapabilmelidir? Uygulamadaki gelişim bloglarına göz atın ve çocuğunuzun kavrama ve mantık alanlarında ne kadar ileride olduğunu görüp içinizden sevinin.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'Yarım kalan cümlelerin sonu 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaret ediyor, kaşlarını çatıyor ve sizin bulmanızı bekliyor. Cümlesini sabırla tamamladığınızda yüzünde beliren “Evet, tam da bunu söylüyordum” rahatlamasını izleyin. Onun tercümanı yalnızca sizsiniz.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'Ani Açlık Sendromu 🥱', 'Tam yatağa girdiğinde “Anne, acıktım” deyip mutfağa koşmak mı istiyor? Uykuyu ertelemek için harika bir yöntem! Beslenme planında akşam için uykuyu destekleyen küçük bir atıştırmalık seçerek bu bahaneyi en baştan ortadan kaldırın.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', '“Ayaklarım yoruldu” şantajı 🚶‍♂️', 'Sokakta yürürken aniden yere çöküp “Ayaklarım kırıldı, beni kucağına al” mı diyor? Bu fiziksel yorgunluk değil, yalnızca anneyi yönlendirme çabasıdır. Bunu oyuna çevirin: “Bakalım eve kadar tavşan gibi kim daha hızlı zıplayacak?”'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'Annenin Reset düğmesi 🚪', 'Gürültü beyninizi deliyor ve her şeye bağırmak istiyorsunuz. Duygu günlüğünü açın. Tüm tükenmişliğinizi oraya özgürce yazın. Bu kısa dijital terapi yeniden toparlanmanıza yardımcı olacak.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'Babanın masalı 📖', 'Bu akşam sesiniz yoruldu. Masal okuma görevini babaya devredin. O, kitaptaki resimden tamamen farklı, uydurma ve komik bir hikâye anlatarak çocuğu kahkahaya boğacak. Siz de kenarda, bir bardak çay eşliğinde bu manzarayı keyifle izleyin.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'Çamaşır yardımcısı 🧺', 'Siz büyük bir emekle çamaşırları katlıyorsunuz, o ise “Yardım ediyorum” diyerek hepsini yeniden odaya saçıyor. Sinirlenmek yerine işi oyuna çevirin: “Bakalım bu çorapları sepete en hızlı ve isabetli şekilde kim atacak?”'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'Doğaya mutlaka kaçış ⛅', 'Dört duvar arasında enerjisi agresifliğe dönüşür ve her cümlesi “hayır” ile başlar. Hava ve kıyafet koşulları ne olursa olsun, uygun şekilde hazırlayıp onu mutlaka dışarı çıkarın. Toprağa dokunmak sinir sistemini anında sıfırlayacaktır.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'Mantığın çöküşü 🔴', 'Suyunu kırmızı bardakta vermeniz için bağırır; kırmızı bardağa koyduğunuzda ise bu kez neden ona koyduğunuzu söyleyerek ağlar. Burada mantık aramayın. O sadece yorgun ve duygularını boşaltmaya ihtiyaç duyuyor. Sakince bekleyin, fırtına kendiliğinden dinecektir.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'Cepten çıkan hazineler 🪨', 'Pantolonunu yıkarken cebinden 2 taş, kurumuş bir yaprak ve yarım bir çubuk mu çıktı? Sizin için çöp olan bu nesneler, onun evreni keşfederken oluşturduğu değerli koleksiyonudur. Onları atmak yerine küçük bir hazine kutusunda biriktirin.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'Akıllı masalda ben 🪄', 'Klasik kitapları artık ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak tasarlayıp sıra dışı ve hiç çaba gerektirmeyen sesli bir uyku seansı oluşturun.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'Çöp değil, sanat 🎨', 'Odanın ortasında küçük kâğıt parçaları ve kesilmiş iplerden oluşan büyük bir sanat eseri yaratmış ve onu atmanıza izin vermiyor. Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya saygı gösterin; temizlik yarına da kalabilir.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'Ağlama analizinden destek😭', 'Gecenin bir yarısı gözleri kapalı şekilde ağlayarak uyandı ve hiç kimseyi duymuyor. Ağlama analiziyle kontrol edin; eğer bu bir gece terörü ise onu uyandırmaya çalışmayın. Sadece yanında sessizce durun, birkaç dakika içinde yeniden uykuya dönecektir.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'Cansız nesnelerle sohbet 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı ve kuralları anlamlandırıyor. Gelişim takibinde onun bu özel senaryolarını mutlaka işaretleyin.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'Küvette oyun 🌊', 'Küvette yıkanmak artık temizlik değil, dalgalar yaratma oyunudur. Bırakın sular etrafa sıçrasın, banyonuz ıslansın. Suyun o büyüleyici etkisi, gün boyunca içinde biriken inatçı ve negatif enerjiyi yıkayıp gidere taşıyacaktır.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'Amaçlı yıkım 🧱', 'Büyük bir emekle kule inşa ediyor, ardından gülerek onu tek hamlede yıkıyor. O, fiziği ve neden-sonuç ilişkisini öğreniyor. Sinirlenmeyin; yıkılan kuleler, beyninde kurulan yeni nöral bağlantılardır. Yeniden inşa etmesine yardım edin.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'Gündüz uykusu kıyameti 🥱', 'Yatağa gitmek istemiyor ve ağlıyor mu? Zorlamayın. Odadaki ışıkları azaltıp Sessiz kitap inceleme saati ilan ederek hem yeni hem de ikinizi dinlendirecek bir rutin oluşturun. Böylece hem siz hem de o, farklı biçimlerde dinlenebilirsiniz.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'Hayali market 🍅', 'Odanın bir köşesine oyuncaklarını toplayıp size hayali parayla hayali domates satıyor. Bu alışveriş oyununu çok ciddiye alın. Hayali domatesi satın alıp iştahla yiyormuş gibi yapın. Rol oyunları, onun sosyal zekâsının en güçlü temelidir.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'Müzikli hipnoz 🎶', 'Akşamüstü ortaya çıkan sebepsiz fırtınalar ve ağlama krizleri mi başladı? Televizyonu kapatın, ışıkları azaltın ve odada çok hafif bir klasik müzik çalın. Müziğin o derin frekansı, ortamı sihirli bir şekilde değiştirecektir.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'Mükemmellik yok 🛑', 'Bugün sabrınız mı tükendi? Kendinizi kötü hissetmeyin. İnternetteki o kusursuz anne yanılsamalarından uzaklaşın. Siz gerçek bir annesiniz; duygularınızı ve yorgunluğunuzu yaşamanız son derece doğal.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'Market kurtarıcısı 🛒', 'Markete gittiğinizde en önemli şeyi mutlaka unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya kaydedin, eşiniz de işten dönerken eksiksiz şekilde alsın; siz zihninizi yormayın.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', 'Anne, bana bak! dönemi 👀', 'Kanepeden atlıyor ve aynı hareketi tam 50 kez tekrarlayarak her defasında “Anne, bana bak!” diyor. Gözlerinizi telefondan ayırın. O, gözlerinizdeki onay ışıltısını görmek için atlıyor. Ona kesintisiz 5 dakika ayırın, ilginize doysun.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'Fısıltılı hikâyeler 🌙', 'Bugün sesinizi çok kullandınız, nefesiniz tükendi. Işıkları kapatın, yanına uzanın ve gün içinde yaşananları kulağına sadece fısıldayarak anlatın. Fısıltı, dikkatini toplar ve beynini hipnotik bir şekilde derin uykuya hazırlar.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'Dolabın içindeki sessizlik 🚪', 'Ev birden sessizliğe büründü ve onu dolabın içinde saklanıp kendi kendine oynarken buldunuz. Bu, kişisel alan arayışıdır. Onu hemen oradan çıkarmayın; o da gürültüden uzaklaşıp yalnız kalmak ve zihnini dinlendirmek istiyor.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'Sessiz öfke 😤', 'İstediği olmayınca ağlamak yerine kollarını kavuşturup duvara bakarak size küsüyor. Bu, duygu yönetiminin yeni ve çok önemli bir aşamasıdır. Üzerine gitmeyin; 3 dakika sonra hiçbir şey olmamış gibi gülerek geri dönecektir.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'Altın sessizliğin ölçüsü 🤫', 'Evdeki gürültü kulaklarınızı çınlatıyor. Sonunda uykuya daldığında Ses ölçer aracını etkinleştirin. Ekrandaki sıfıra yakın rakamları, o dijital sessizliği izlemek, yorgun bir annenin zihni için en güzel görsel masajdır.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'Yeni bir dilin keşfi 🗣️', 'Uçan-kaçan, Sıcak-soğuk gibi kendi uydurduğu karmaşık ve tuhaf sözcükler keşfetti. Kelime dağarcığı inanılmaz bir hızla genişliyor. Gelişim takipçisine onun uydurduğu bu komik sözcükleri unutulmaz bir arşiv olarak mutlaka kaydedin.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'Tuhaf yol arkadaşı 🥄', 'Parka giderken oyuncak arabalarını değil, mutfakta bulduğu bir kepçeyi yanında götürmekte ısrar ediyor. Engel olmayın! O kepçe bugün parkta kum kazmak için onun en sıra dışı ama en işlevsel oyuncağı olacak.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'Kediler sudan korkar 🐈', 'Küvete girmemek için Ben kediyim, kediler banyo yapmaz diyor. Rolünü kabul edip oyunu sürdürün: Peki, bu kedi sabun köpükleriyle oynamak ister mi? diyerek onu teşvik edin; engelleri hayal gücüyle aşın.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'Profesyonel pazarlık 🛒', 'Markette şeker için ağlamak yerine Bunu alırsak çorbamı yiyeceğim diye pazarlık ediyor. Tebrikler, küçük avukatınız büyüyor! Unutkanlığa karşı Alışveriş listesini açık tutun; onunla tartışırken dikkatiniz dağılmasın.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', 'Bana bak! dönemi 👀', 'Kanepeden atlıyor ve aynı hareketi tam 50 kez tekrarlayarak her seferinde onay bekliyor. Gözünüzü telefondan ayırın. O, hareket etmek için değil, yalnızca gözlerinizdeki sevgi dolu onay ışıltısını görmek için atlıyor.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'Sessiz sırdaş 📝', 'Kimse sizi anlamıyor ve evde bu kadar yoruluyor musunuz? Zoraki gülümsemeleri bir kenara bırakın. Duygu günlüğüne bugün aslında ne kadar tükendiğinizi yazın. Ekrana dökülen her sözcük omuzlarınızdan ağır bir yükü alacak.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'Yerde uyku 🥱', 'Gündüz uykusuna direnip uyumadı, ama oyuncaklarının ortasında, halının üzerinde kıvrılıp uykuya daldı. Onu yatağa taşırken uyandırmayın; bırakın odanın ortasında o masumluğun tadını çıkarsın, siz de 1 saat dinlenin.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'Hava keşfi ⛅', 'Güneş açtı ama o kışlık montunu giymek istiyor. Tartışmayın. Hava ve giyim aracını açıp ekrandaki ince giyinmiş çocuk simgesini ona gösterin. Bak, telefon bugün havanın sıcak olduğunu söylüyor numarası her zaman harika işler.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'Senaryo onun elinde 🪄', 'Klasik masallar artık ilgisini çekmiyor. Akıllı masalları açın ve ona sorun: Şimdi bu sihirli tren nereye gitsin? Bırakın, uydurduğu o tuhaf ve tamamen absürt sonla hayallere dalarak uykuya dalsın.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'Diş hekimi muayenesi 🦷', 'Fırçayı eline alıp dişlerinizi ciddi bir şekilde muayene etmek istiyor. Ağzınızı açın ve bu komik doktora uyun. Rol oyunları, kişilik gelişiminin ve korkuları yenmenin en etkili, en eğlenceli yollarından biridir.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'Çöp değil, hazine 🍬', 'Günlerdir sakladığı ve oynamadığı o eski çikolata ambalajını çöpe attığınız için kıyamet mi koptu? Sizin için çöp olan bir şey, onun değerli koleksiyonunun parçası olabilir. Ağlamasını durdurmak için dikkatini hemen daha ilgi çekici bir nesneye yönlendirin.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'Şampanyasız zafer 🥂', 'Çocuk uyudu. Şampanya olmasa da bardaklara sıcak çay doldurun ve eşinizle Bu fırtınalı kaosu bugün de yönetebildik diyerek bardak tokuşturun. Siz, bu evin sarsılmaz ve yorulmak bilmeyen ekibisiniz.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'Brokoli dedektifi 🥦', 'Çorbadaki o tek yeşil sebzeyi bulup yemek yemeyi mi reddediyor? Beslenme planında sebzeleri renkli makarnalarla karıştırarak dikkatini dağıtmanın ve püre hâline getirip gizlemenin en ustaca yollarını uygulayın.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'Sabah diktatörü iş başında 👑', 'Oraya sen oturma, ayıcığım oturacak! Kahvaltıda tüm masayı o yönetiyor. İradesini sertçe kırmadan, Tamam, ayıcığın orada otursun, ben de burada oturayım diyerek dengeyi ve odadaki huzuru koruyun.'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'Mum ışığında çay 🕯️', 'Çocuk uyudu. Işıkları kapatın, masanın üzerinde bir mum yakın. Bu romantizm için değil; yalnızca bütün gün gerilen sinirlerinizi ve ekranlardan, gürültüden yorulan gözlerinizi dinlendirmek için.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'Dokunulma yorgunluğu 🔋', 'Bütün gün üzerinize tırmanıyor, kucak istiyor ve saçınızla oynuyor. Dokunulma yorgunluğu (touched out) gerçektir. En azından 15 dakika tek başınıza bir odaya çekilmeye ve bedeninizin yalnızca size ait olduğunu hissetmeye hakkınız var.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'Babanın sırtında atçılık 🐴', 'Enerjisini tam olarak atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. O, çocuğu sırtına alıp atçılık oynarken kahkahalar odayı doldurur; biriken tüm fiziksel stres ve o bitmek bilmeyen enerji, ter dökülerek saniyeler içinde yok olur.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'Toplulukta itiraf 💬', 'Bugün her şeye bağırdınız ve kendinizi dünyanın en sabırsız annesi gibi mi hissediyorsunuz? Lütfen yalnız olmadığınızı bilin. Anacan Topluluğuna katılın ve diğer annelerin de bugün aynı ölçüde tükendiğini okuyarak rahatlayın.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'Aynadaki rakip 🪞', 'Aynanın karşısında durup kendi kendine kaşlarını çatıyor, öfkeli ve tuhaf mimikler yapıyor. Duyguların yüzünde nasıl göründüğünü test ediyor. Bu minyatür tiyatro oyuncusunun provasını, ses çıkarmadan ve merakla izleyin.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'Gizli gıda operasyonu 🥣', 'Düne kadar sevdiği yumurtayı bugün ağzına bile sürmüyor. İradesiyle savaşmayın. Sağlıklı tariflerde proteinleri farklı, renkli ve ilgi çekici biçimlere sokan kurnaz atıştırmalık tariflerini uygulayın ve kazanan siz olun.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'Sessizliğin kanıtı 🤫', 'Gürültülü bir günün ardından çocuk uyuduğunda, Ses ölçer ile odadaki sessizliği ölçün. Sıfıra yaklaşan o rakamları görmek, bu görsel sakinlik annenin beyninde en güzel masaj etkisini yaratır.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'Ansızın gelen Seni seviyorum 💖', 'Odanın ortasında oyun oynarken birden size bakıp koşarak gelir ve boynunuza sarılır. Tüm uykusuz gecelere ve yorgunluğa değer! Bu anın getirdiği o derin ve eşsiz huzurun tadını çıkarın.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'Işıkları kapatın, uyku zamanı 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin (uyku hormonu) yalnızca karanlık ve teknolojiden uzak bir ortamda hızla salgılanır.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'Lif ihtiyacı 💩', 'Çok koşuyor ama su içmeyi unutuyor. Lazımlıktaki dışkısını takip edin. Kabızlık riski varsa uygulamaya kaydedin ve hemen Beslenme takip aracıyla menüsüne yulaf ve erik ekleyin.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'Tehlikeli kelimeler 🤐', 'Sokaktan veya televizyondan duyduğu o kötü sözü gülerek size tekrarlıyor ve büyük bir merakla tepkinizi bekliyor. En güçlü silahınız tepkisiz kalmaktır. Gülmeyin, öfkelenmeyin; yalnızca görmezden gelin. O sözü kısa sürede unutacaktır.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'Masalın sonunu o yazsın 🪄', 'Klasik kitaplardan ikiniz de yoruldunuz. Akıllı masallarda bu kez hikâyenin sonunu çocuğunuzun seçmesine izin verin. Sence o kahramana kim yardım etti? diyerek yatmadan önce hayal gücünü özgür bırakın.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'Buz Gibi Mantık 🥶', 'Buzdolabını açıp buz kalıbını istiyor ve elleri üşümesine rağmen onu bırakmıyor. Sıcak ve soğuk kavramlarını bedeniyle test ediyor. Bir kaba ılık, diğerine buzlu su koyarak bu keşfi küçük bir bilimsel deneye dönüştürün.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'Babanın park koşusu 👨‍👧', 'Annelik 24/7 süren bir nöbet değildir. Partner işlevini devreye sokun! Bugün bırakın o bitmek bilmeyen enerjiyi babasıyla parkta atsın, siz de evde mutlak sessizliğin tadını çıkarın.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'Mutfakta konser 🥄', 'Tencereleri ve tahta kaşıkları çıkarıp mutfağın ortasında konser veriyor. Başınız ağrısa da bu, onun ritim duygusunun ve yaratıcılığının geliştiğini gösterir. Hemen müdahale etmeyin; birkaç dakika boyunca o çılgın enerjinin ses dalgalarıyla odaya yayılmasına izin verin.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'Hava keşfi ⛅', 'Dışarıda hava tam açık değil; güneş var ama rüzgâr da mı esiyor? Hava ve kıyafet aracı, pencereden anlayamayacağınız rüzgâr hızını ve doğru kıyafet kombinini size anında söylesin; kapıda kararsız kalıp vakit kaybetmeden yürüyüşe çıkın.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'Takım masajı 💆‍♂️', 'Çocuğunuz uyuduktan sonra günün stresini atmak için partnerinizle birbirinize omuz masajı yapın. Siz yalnızca aynı evi paylaşan ebeveynler değil, birbirine sarsılmaz destek veren bir takımsınız.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'Ani duygu değişimleri 🤖', '3 buçuk yaşına yaklaşırken çocuğunuzun ani duygu değişimleri sizi endişelendirdi mi? İnternetteki korkutucu ve travmatik forumları kapatın. Anacan AI''dan bu yaş krizleri hakkında bilimsel ve psikolojik temellere dayanan, içinizi rahatlatacak bir yanıt alın.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'Ilık suyun mucizesi 🛀', 'Bazen hiçbir şey işe yaramaz ve çocuğunuz her şeye ağlar. Onu ılık su dolu küvete koyun, suya biraz köpük ekleyin. Suyun o gizemli, gerginliği azaltan gücü hem tüm odaya hem de çocuğunuzun sinir sistemine anında huzur getirecek.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'Gardırop mühendisi 👗', 'Bugün dışarıya farklı çoraplar ve ters giyilmiş bir tişörtle çıkmak istiyor. Toplumun uyum kurallarını boş verin. Kendi kararını verme ve arkasında durma özgürlüğü, renk uyumundan çok daha büyük bir hayat dersidir. İzin verin.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'Canlı ses kayıt cihazı 🎙️', 'Dün partnerinizle konuşurken kullandığınız rastgele ve belki de gereksiz bir sözü bu sabah oyuncağına söylüyor! O sizin canlı aynanızdır. Yanında konuşurken yansıttığınız duygulara özellikle dikkat edin; hepsini birer birer kopyalıyor.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'Babanın eğlenceli masalı 📖', 'Bu akşam odada duyulan ses sizinki olmasın. Masal kitabını babaya verin ve hikâyeyi bilerek yanlış, komik ve absürt bir şekilde anlatmasını isteyin. Çocuğunuzun onu düzeltmekten nasıl keyif aldığını ve babasına nasıl kahkahalarla güldüğünü bir kenardan izleyin.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'Topluluğun gücü 💬', 'Çocuğum neden bu kadar inatçı? düşüncesi zihninizi mi kurcalıyor? Anacan Topluluğuna katılın. Diğer annelerin evlerinde yaşanan benzer, absürt krizleri okuduğunuzda yalnız olmadığınızı ve tamamen normal bir süreçten geçtiğinizi göreceksiniz.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'Küçük iş insanı 🍅', 'Odanın bir köşesinde oyuncaklarını toplamış, size hayalî parayla hayalî domates satıyor. Bu alışveriş oyununu son derece ciddiye alın. Hayalî domatesi satın alıp iştahla yiyormuş gibi yapın. Rol oyunları, çocuğunuzun sosyal zekâsı ve matematiksel düşünme becerisi için en güçlü temellerden biridir.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'Kalsiyum kalkanı 🦴', 'Hızla büyüyen kemikler için kalsiyum şarttır. Süt içmiyor mu? Beslenme takip aracıyla bugün tükettiği peynir, yoğurt veya brokoli miktarını mutlaka hesaplayın.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'Yataktan kaçış 🏃‍♂️', 'Su ver, oyuncağımı bul... 3 yaşındaki bir çocuğun uyumamak için öne sürdüğü bahaneler bitmez. Uyku zamanlayıcısını açın ve sınırları kararlılıkla koruyun.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'Dev yük 🎒', 'Ağır çantalarınızı veya büyük şemsiyeyi mutlaka kendisi taşımak istiyor; yerde sürüklese bile yardımınızı kesinlikle reddediyor. Gücünü sınamasına izin verin. Kendini evin en güçlü kahramanı gibi hissetmek istiyor; bağımsızlığına engel olmayın.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'Yeni kimlik 🕷️', 'Sabah uyanıyor ve size büyük bir ciddiyetle Ben çocuk değilim, örümceğim diyor. 40. aya doğru hayal gücü sınırları aşar. Tartışmayın; ona kahvaltısını yiyen örümcek rolünü vererek bu absürt tiyatroya katılın.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'Bitmeyen bahaneler 🦶', 'Tam uykuya dalacağı sırada Ayak parmağım kaşınıyor bahanesiyle yataktan kalkmak istiyor. Uykuyu erteleme sanatında ustalaşmış. Ciddi olun, ayağını kaşıyormuş gibi yapın ve ışıkları kararlılıkla kapatın; sınırları siz belirleyin.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'Babanın şapka şartı 🧢', 'Yatağa gitmek için babasının mutlaka kışlık bere takmasını istiyor. Babası o bereyi takıp komik sesler çıkarsın. Akşamın bu tuhaf ve absürt anı hem sizi güldürecek hem de çocuğunuzun inadını anında kıracak.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'Fiziğe meydan okuyan inat 💧', 'Suyu kuru istiyorum diyerek hıçkıra hıçkıra mı ağlıyor? Çocuk beyni, imkânsız şeyler talep ederek aslında iradenizi sınar. Bu durumda mantık aramayın; başka renkli bir nesneyle dikkatini hemen dağıtın.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'Bedendeki sanat 🖍️', 'Birdenbire ortalık sessizleşince şüphelendiniz ve onu kollarına keçeli kalemle sanat eseri çizerken buldunuz. Sinirlenmeyin. İnce motor becerilerini keşfediyor, üstelik cildi suyla yıkanabilir. Derin bir nefes alın ve bu komik anı kaydedin.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'Fısıltının hipnozu 🤫', 'Yatakta o kadar hareketli ki bir türlü uykuya dalamıyor. Sesinizi yükseltmek yerine birden alçaltın. Onunla yalnızca fısıldayarak konuşun. Çocuğunuz sizi duymak için dikkat kesildiğinde beyni otomatik olarak uyku moduna geçecektir.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'Anne topluluğunun gücü 💬', 'Bu çocuk hiç sakinleşmeyecek düşüncesi sizi yoruyor mu? Anacan Topluluğuna katılın. Oradaki annelerin benzer, hatta daha komik inatlaşma hikâyelerini okuduğunuzda yalnız olmadığınızı görüp derin bir nefes alacaksınız.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'Felsefe profesörü 🤔', 'Rüzgâr neden görünmüyor?, Yaprak neden düşüyor? Derin sorular sabahın erken saatlerinde zihninizi zorluyor. Saatlerce bilimsel açıklamalar yapmaya çalışmayın. Çünkü ağaçlar kıyafetlerini değiştiriyor gibi hayal ürünü ve sevimli cevaplar bu yaşta onu fazlasıyla tatmin edecektir.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'Gölgelerle dans 🐰', 'Karanlıktan korktuğunu söyleyerek yataktan kaçıyor. Odadaki tüm ışıkları kapatın, el fenerini açın ve ellerinizle duvara kuş, köpek gölgeleri yansıtın. Korktuğu karanlık, onun için saniyeler içinde bir tiyatroya dönüşecektir.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'Yapay zekâ kurtarıcısı 🤖', 'Çocuğunuzun sorularına veya garip davranışlarına açıklama bulamıyor musunuz? Anacan AI''a danışın. 3 yaşını geçmiş çocukların beyninin nasıl çalıştığını size çocuk doktoru diliyle, son derece rahatlatıcı ve kısa bir şekilde açıklayacaktır.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'Nefesinin sıcaklığı 💖', 'Bütün gün sizi çileden çıkardı, her şeye inat etti. Ama şimdi yatakta göğsünüze sokulmuş ve ritmik nefesi odayı dolduruyor. Anneliğin en büyük ödülü işte budur. Onu bağrınıza basın ve tüm yorgunluğunuzu unutun.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'Ters ayakkabı gururu 👟', 'Ayakkabılarını ters giymiş ama öyle gururlu yürüyor ki sanki dünyayı fethetmiş. Müdahale edip düzeltmeye çalışmayın. Çocuğunuzun öz güveni ve bağımsızlığı, kıyafetinin estetik görünmesinden milyon kat daha önemlidir.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'Empatinin zirvesi 🩹', 'Oyuncak ayısının kolu ağrıyor diye üzerine yara bandı yapıştırıp öpüyor mu? Onun kocaman, merhametli kalbine hayran kalın. Bu derin empati duygusunu, en güzel karakter özelliği olarak Gelişim takipçisine gururla kaydedin.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'Babanın oyun alanı 👨‍👧', 'Sabrınız mı tükeniyor? Odanın kapısını kapatın ve çocuğunuzu babasıyla yalnız bırakın. Bırakın bu akşam evdeki oyunların tek yöneticisi o olsun, siz de dinlenin.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'Bakın, ne yapıyorum! 🤸‍♂️', 'Tek ayak üzerinde durmaya veya zıplamaya çalışarak dikkatinizi mi çekiyor? Takdir edilmek istiyor. Bu fiziksel denge becerisini Gelişim takipçisine kaydedin ve onu alkışlayın.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'Sebze savaşları 🥦', 'Tabağındaki yeşil sebzeleri kenara mı itiyor? Mücadele etmeyin. Sağlıklı tariflerde sebzeleri kekin veya köftenin içine gizleyebileceğiniz yaratıcı yöntemler bulun.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'Karanlıktan mı korkuyor? 👻', '3.5 yaşa doğru karanlık korkusu sık sık ortaya çıkar. Odasına küçük bir gece lambası koyun ve Akıllı masallarda cesur kahramanların yer aldığı hikâyeler oluşturun.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'Annelerin sohbeti 💬', 'Benim çocuğum neden hâlâ lazımlığa tam olarak alışmadı? düşüncesi sizi yoruyor mu? Anacan Topluluğuna katılın, her çocuğun gelişim hızının farklı olduğunu göreceksiniz.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'Kelimeleri değiştiriyor mu? 🗣️', 'Bazı harfleri bilerek değiştirip komik sesler çıkarıyor ve buna gülüyor mu? Dilin esnekliğini keşfediyor. Siz de ona katılın ve kelime oyunları oynayın.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'Arkadaşlık duyguları 👫', 'Parkta artık diğer çocuklarla birlikte (paralel değil, etkileşimli) oynamaya mı çalışıyor? Sosyalleşme resmen başlıyor! Güvenliğini uzaktan gözeterek bu anı izleyin.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'Cebinizdeki liste 🛒', 'Günlük koşuşturma içinde şampuanın mı yoksa ıslak mendilin mi bittiğini hatırlamaya çalışmayın. Hemen Alışveriş listesine yazın ve eşinizle senkronize edin.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1'::uuid, 'Sessizlik ihtiyacı 🤫', 'Uykuya daldığı ilk yarım saat en hassas zamandır. Ses ölçerle ortamın desibelini kontrol edin ve yan odadaki televizyonun sesini sınırlayın.'),
  ('602f2986-8e86-421e-ab71-94038d048ccf', 'Avukat gibi konuşuyor 🗣️', 'Artık kelimeleri kullanarak sizinle pazarlık etmeye mi çalışıyor? Biraz daha oynayayım, sonra yatacağım mı diyor? Konuşması harika gelişiyor, ancak sınırlarınızı korumayı unutmayın.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'Yapboz ve mantık 🧩', '5-6 parçalı yapbozları birleştirmeye mi çalışıyor? Geometriyi ve mantığı öğreniyor. Tekrarlayıcı olsa da öğretici olan bu hareketlerine engel olmayın.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'Babanın desteği 🫂', 'Gece uyanmalarında mutlaka sırayla ilgilenin. Bazen karanlıkta yalnızca babasının ritmik okşayışı ve kokusu çocuğu anında sakinleştirir.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'Mavi elma talebi 🍏', 'Gözünü açar açmaz bağırarak sizden mavi elma istiyor. Doğada böyle bir şey olmadığını açıklayıp fizik/bioloji dersi vermeyin. Mavi elmalar hâlâ uyuyor, gel biz kırmızı olanı uyandıralım diyerek onun absürt mantığına aynı derecede absürt ama işe yarayan bir yanıt verin.'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'Battaniye takıntısı 🛏️', 'Tam uykuya dalacakken birden Battaniye sol ayağıma değiyor! diye ağlamaya başlıyor. 3 buçuk yaşındaki çocuğunuzun uykuyu geciktirmek için geliştirdiği bu yeni takıntıya içinizden gülümseyin. Hiçbir şey söylemeden battaniyeyi düzeltin ve kararlılıkla odanın ışıklarını tamamen kapatın.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'Şüpheli sessizliğin bedeli 💄', 'Evde birden oluşan 10 dakikalık sessizliğin sonu: Odaya giriyorsunuz ve en sevdiğiniz rujla hem yüzünü hem de aynayı boyamış. Artık sinirlenmek için çok geç.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'Babanın sihirli kolları ✈️', 'Bütün gün taşımaktan kollarınız koptu ama o hâlâ enerjik ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Babası onu havaya kaldırıp uçak yaptığında kahkahalar odayı doldurur ve biriken o bitmek bilmeyen enerji saniyeler içinde sıfırlanır.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'Kaldırım kenarında sınav 🧱', 'Parka giderken normal yoldan değil, ısrarla kaldırımın en dar ve yüksek kenarından ip cambazı gibi yürümek istiyor. Kaba motor becerileri ve dengesi gelişiyor! Kolundan tutarak güvenliğini sağlayın; bırakın küçük ama onun için çok önemli olan bu zirveyi fethetsin.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'Görünmez köpekle gezinti 🐕', 'Odanın ortasında elini aşağı uzatıp görünmez bir köpeği okşuyor ve onunla konuşuyor. Bu, hayal gücünün en masum evresidir. Köpeğin adı ne? diye sorun ve odanın bir köşesine hayalî bir su kabı koyarak bu muhteşem tiyatronun yardımcı oyuncusu olun.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'Gardırop isyanı 🕶️', 'Kahvaltıya güneş gözlüğü ve kışlık bereyle geliyor, bunları çıkarmayı kesinlikle reddediyor. Estetiği ve el âlem ne der kaygısını bir kenara bırakın. Kendi kararını verme ve bunu savunma özgürlüğü, kıyafetlerin uyumundan çok daha önemli bir psikolojik temeldir.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'Sessizliğin dijital ölçüsü 🤫', 'Evdeki gürültü kulaklarınızı çınlatıyor. Sonunda uykuya daldığında Ses ölçer aracını etkinleştirin. Ekranda 0-10 desibele düşen o dijital sessizliği izlemek, yorgun bir annenin zihni için en güzel ve görsel sakinleştirici masajdır.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'Karınca kurtarıcısı 🐜', 'Parkta yerdeki bir karıncanın ezilmesini önlemek için ağlayarak önüne mi geçti? Onun bu kocaman ve şefkat dolu empatisine hayran kalın.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'Akıllı masalda ben 🪄', 'Klasik kitapları okumaktan ses telleriniz yoruldu. Akıllı masalları açın. Başkahramanı çocuğunuz, arka planı ise sakinleştirici orman sesleri olacak şekilde tasarlayıp sıra dışı, hiç çaba gerektirmeyen hipnotik bir uyku seansı oluşturun.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'Topluluğun sessiz tesellisi 💬', 'Bir daha asla eski, özgür ve kaygısız hâlime dönemeyeceğim düşüncesi birden içinizi mi daraltıyor? Anacan Topluluğuna katılın. Diğer annelerin de bu ağır ama son derece doğal duygulardan geçtiğini ve bunun anneliğin bir evresi olduğunu okuyarak teselli bulun.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'Kelimelerin Remiksi 🗣️', 'Su ve süt kelimelerini birleştirip sütsu gibi tamamen uydurma kelimeler yaratıyor ve gülüyor. Kelime hazinesiyle remiks yapıyor! Bu dil oyunlarına kahkahalarınızla katılın; beyni, dilin sınırlarını tam da böyle denemelerle öğreniyor.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'Ani sevgi patlaması 🫂', 'Sabah size git diyen çocuk, yatağa girdiğinde kollarını boynunuza sıkıca dolayıp Seni dünyalar kadar seviyorum diyor. İşte anneliğin paradoksu budur! O sıcacık nefesi içinize çekin ve günün tüm yorgunluğunun uçup gitmesine izin verin.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'Anne, git buradan! 💔', 'Bir isteği yerine gelmediğinde size bakıp Seni istemiyorum, git buradan! diyor. Kalbiniz kırılmasın. O, henüz öfkesini nasıl yöneteceğini bilmiyor. Kişisel algılamayın; Ben buradayım, sakinleştiğinde konuşuruz deyip duygularını yaşaması için ona alan tanıyın.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'Market avukatı 🛒', 'Markette şeker için kendini yere atmak yerine Bunu alırsak evde çorbamı yiyeceğim diye pazarlık yapıyor. Tebrikler, küçük avukatınız büyüyor! Unutkanlığa karşı Alışveriş listenizi açık tutun ki onunla tartışırken asıl amacınızdan sapmayın.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'Küvetteki tsunami 🌊', 'Küvette banyo yapmak artık temizlik değil, küçük bir tsunami yaratma oyunu. Bırakın sular etrafa sıçrasın. Suyun o mistik, enerjiyi çeken mıknatıs etkisi, gün boyunca içinde biriken o inatçı, negatif enerjiyi yıkayıp gidere götürecektir.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'Annenin tembellik hakkı 🍕', 'Bugün her şeye bağırmak mı istiyorsunuz? Ev darmadağın mı? Temizliği boş verin, ocağı yakmayın. Dışarıdan pizza ya da en kolay ne varsa onu sipariş edin. Mükemmel anne olma yanılsamasını yıkın; ruh sağlığınız ev yemeğinden çok daha değerlidir.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'Kendisi dökme inadı 💧', 'Suyu büyük sürahiden küçük bardağa mutlaka kendisi dökecek. Su masaya, oradan da yere dökülüyor. Ama siz onun bezi alıp orayı temizlemeye çalışan o küçük ellerine bakın. O, hata yaparak sorumluluğu öğreniyor; o kaos, gelişimin ta kendisi.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'Küçük makaslarla tanışma ✂️', 'Çocuklar için güvenli plastik makasla kâğıt kesmeye mi çalışıyor? İnce motor becerileri için harika bir egzersiz! Gelişim takipçisine bunu mutlaka kaydedin.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', 'Bana bak! inadı 👀', 'Siz telefona veya başka bir işe bakarken gelip yüzünüzü kendisine doğru mu çeviriyor? Tüm dikkatinizi istiyor. Göz teması kurarak onu dinlediğinizi hissettirin.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'Babanın sırası 👨‍🍼', 'Gece uyanmalarının yükünü tamamen tek başınıza üstlenmeyin. Eşinizi de uyandırın; ekip olmak, sorumluluğu eşit paylaşmaktır.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'Ne pişirsem derdi 🍲', 'Ek gıda menüsü için fikirleriniz mi tükendi? İnternette kaybolmayın, Sağlıklı tarifler bölümünden yeni lezzetler bulun.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'Kişiye özel masal 🪄', 'Akıllı masallarda kahramanı kendi çocuğunuz olan özel bir hikâye oluşturun: Sihirli makasla dünyayı renklendiren cesur minik.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'Sana yardım edeyim! 🧹', 'Siz çamaşırları katlarken elinizden almaya mı çalışıyor? O artık kendisini büyümüş hissediyor. Ona küçük bir havlu verip yardım etmesine izin verin.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'Sana bir sır vereceğim 🤫', 'Yatağa girip gözleri kapanmak üzereyken birden Anne, sana bir sır vereceğim deyip uykuyu ertelemeye çalışıyor. Uyku geciktirme sanatında resmen doktora yapıyorlar. Gülümseyip Sırrını rüyanda anlatırsın diyerek ışıkları kararlılıkla kapatın.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'Bisküvinin sadece kreması 🍪', 'Yuvarlak bisküvilerin ortasındaki kremayı yalayıp kuru kısımlarını masanın kenarına mı dizdi? Tebrikler, resmen 3.5 yaşın yemek felsefesiyle tanıştınız. Sağlıklı tariflerde onun ilgisini çekecek daha mantıklı ama eğlenceli atıştırmalıklar keşfedin.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'Sen söyleme! yasağı 🛑', 'Arka planda çalan çocuk şarkısına mırıldanarak eşlik ettiniz ve o anında bağırdı: Sen söyleme! Odanın tek solisti o; sizin vokal denemeleriniz onun sahnesini daraltıyor. Gücenmeyin, sahneyi bu küçük egoiste bırakın.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'Babadan omuz masajı 💆‍♂️', 'Bugün uzun süre ayakta kaldınız; onun peşinden koşmaktan, yerden oyuncak toplamaktan beliniz kopacak gibi. Çocuğunuz uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin direğisiniz; direklerin de mutlaka dinlenmesi ve güç toplaması gerekir.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'Ben kendim yapacağım! 🛑', 'Ayakkabısının bağcığını mutlaka kendisi bağlamak istiyor; başaramıyor, sinirleniyor ama yardımınızı da öfkeyle reddediyor. Derin bir nefes alın. Geleceği için, aksayan bir programdan çok incinmemiş bir özgüven önemlidir. Bekleyin.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', 'Bana baktı! trajedisi 👀', 'Parkta başka bir çocuk sadece ona baktığı için hıçkıra hıçkıra ağlamaya mı başladı? Sosyal sınırlarını yeni keşfeden bir çocuk için başkasının bakışı bile müdahale olarak algılanabilir. Ona sarılın ve “O sadece senin güzel tişörtüne bakıyordu” diyerek dikkatini başka yöne çekin.'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'Akıllı masallarla sakinlik 🪄', 'Odanın içinde koşuyor ve yatağa girmeyi reddediyor. Işıkları kısın. Akıllı Masallar''da ilgi çekici bir hikâye oluşturup okuyun.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'Oyuncakları sıraya dizmek 🚗', 'Tüm arabalarını odanın bir ucundan diğerine milimetrik bir hassasiyetle sıraladı ve bir tanesinin bile yerinin değişmesine izin vermiyor. Bu, görsel düzen arayışıdır. Bu küçük mimarın çalışmasını uzaktan sessizce izleyin ve düzenini bozmayın.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'Toplulukta sessiz bir okur olmak 💬', 'Çok yorgunsunuz ve kimseye hiçbir şey açıklamak ya da içinizi dökmek istemiyorsunuz. Anacan Topluluğuna girip yalnızca okur olun. Diğer annelerin aynı akıl almaz krizlerle nasıl başa çıktığını görmek, en güçlü sessiz terapidir.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'Yanlış kaşık boyutu krizi 🥄', 'Çorbayı büyük kaşıkla verdiğiniz için neredeyse kıyamet koptu. “Ben küçük kaşık istiyordum!” Yemek aynı olsa da kaşığın fiziksel boyutu, onun mantığına göre yemeğin tadını değiştirir. Tartışmayın; yalnızca kaşığı değiştirin ve enerjinizi koruyun.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', 'Üstümü ört! takıntısı 🛏️', 'Tam uykuya dalacakken yorganın ucu açılıyor ve “Üstümü ört!” diye bağırıyor. Yorganın kenarlarının mutlaka düzgün olması onun için hayati önem taşıyor. Yorganı ütülenmiş gibi düzeltin ve bu komik uyku ritüellerine içinizden gülümseyin.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'Yara bandı sevgisi 🩹', 'Vücudunda görünmez bir yara buldu ve ısrarla oraya yara bandı yapıştırmanızı istiyor. Bu fiziksel bir ağrı değil, yalnızca annesinin ilgi ve şefkatine duyduğu ihtiyaçtır. O küçük yara bandını yapıştırıp öpün; inanın, gününüz kurtulacak.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'Sessizliğin görsel hazzı 🤫', 'Evdeki kaos sonunda bitti ve çocuğunuz uyudu. Bulaşıkları yıkamaya koşmayın! Ses ölçeri açın ve odadaki o mutlak sessizliği (0-10 desibel) izleyerek 15 dakika içinde zihninizin nasıl dinlendiğini, bu görsel sükûnetin sizi nasıl iyileştirdiğini hissedin.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'Kum mimarisi 🏰', 'Parktaki kum havuzunda sanki hazine arıyormuş gibi derin bir çukur kazıyor. Üstü başı çamur içinde. Ancak bu keşif anını bölmeyin. Hava koşullarına uygun ve kirlenmesini göze aldığınız kıyafetleri önceden seçmeniz, bu manzarayı strese girmeden izlemenizi sağlar.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'Akşam egzersizi - babanın üstünde zıplamak 🤸‍♂️', 'Enerjisini atamadı ve yatağa gitmek istemiyor. Babayı kanepeye uzatın ve çocuğun onun üzerinde zıplamasına izin verin. Babanın çıkardığı komik sesler odayı kahkahaya boğacak ve tüm o fazla enerji saniyeler içinde tükenecek.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'Annenin kendine özen göstermesi 🥗', 'Onu doyurmak için 3 farklı menü düşündünüz, peki siz yine aç mı kaldınız? Beslenme planı bölümünden yalnızca çocuklar için değil, anneler için de enerji veren, 10 dakikada hazırlanan, demir ve kalsiyum açısından zengin bir öğle yemeği seçin ve kendinizi değerli hissedin.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'Sen kimsin? oyunu 🎭', 'Sabah size çok ciddi bir ifadeyle bakıp “Sen kimsin? Benim annem nerede?” diyor. Hayal gücü gelişiminin zirvesi! Oyuna katılın: “Ben komşu teyzenim, annen birazdan gelecek” deyip ses tonunuzu değiştirerek bu muhteşem tiyatroyu sürdürün.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'Tuvalet kâğıdı sanatı 🧻', 'Birkaç dakikalık sessizlik... Sonra odaya girdiğinizde tuvalet kâğıdının tamamının açılıp eve yayıldığını görüyorsunuz! Sinirlenmek yerine kâğıtları toplayıp birlikte kardan adam ya da top yapın. Kaosu bağırarak değil, yaratıcılıkla alt edin.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'Kulağa fısıldanan sevgi sözleri 💖', 'Bütün gün sizi çileden çıkardı, her şeye inat etti. Ama şimdi yatakta öylesine masum uyuyor ki... Yanına uzanın; onu ne kadar sevdiğinizi ve bugün yaptığı güzel şeyleri kulağına fısıldayın. Çocuklar uykuda bile annelerinin sevgi dolu sesini hissederler.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'Annenin duvarla bakışması 🛋️', 'Odada gürültü var, o oyuncaklarını birbirine vuruyor, siz ise boş boş duvara bakıp dalmışsınız (zoned out). Bu, beyninizin korunma mekanizmasıdır. O 5 dakikalık donup kalma anını kendinize çok görmeyin; hayata yeniden dönebilmek için buna ihtiyacınız var.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'Toplum içinde şoke eden sorular 😳', 'Otobüste veya markette yüksek sesle Bu teyzenin burnu neden bu kadar büyük? diye mi sordu? Yerin yarılıp içine girmek istediğiniz o an! Onu susturup utandırmak yerine dikkatini hemen başka, renkli bir nesneye yöneltip durumdan diplomatik bir şekilde sıyrılın.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'Babanın mantıksız meydan okumaları 🎲', 'Gece pijamasını giymemek için evin içinde kaçıyor. Babası Bakalım bu pijamayı gözlerin kapalı giyebilecek misin? diyerek ortaya absürt bir oyun atıyor. Ve bum! Çocuk farkına varmadan pijamasını giyiyor. Babaların bu mantıksız ama işe yarayan oyunlarını dışarıdan yalnızca alkışlamak düşüyor.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', 'Ben bebeğim! nostaljisi 🍼', 'Birden bebek gibi emeklemeye, ağlamaya ve Ben bebeğim, bana sarıl demeye mi başladı? Büyümek bazen onları da korkutur ve eski, güvenli bebeklik günlerine sığınmak isterler. Ona birkaç dakikalığına o eski günlerdeki gibi sarılıp okşayın.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'Çamur çorbası 🍲', 'Parkta suyla toprağı karıştırıp anne, sana çorba yaptım diyerek o çamuru size uzatıyor. İğrenmek yok! O çorbayı hayalinizde dünyanın en lezzetli yemeğiymiş gibi için.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'Sessizliğin dijital hazzı 🤫', 'Evdeki kaos nihayet sona erdi ve o uyudu. Ses ölçeri açın, odanın sessizlik seviyesini (0-10 desibel) ekrandan izleyin. Sıfıra yakın o rakamları görmek, yorgun bir annenin beyninde dünyanın en pahalı spa seansı gibi etki yaratır.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'Muzun üzerindeki çizik 🍌', 'Muzun kabuğunu soyduğunuzda üzerinde milimetrik, küçük bir çizik gördü ve Bu bozulmuş! diye bağırıyor. Çocukların görsel mükemmellik arayışı çılgınlık seviyesindedir. O kısmı bıçakla kesip Kurtardım! diyerek bu mini dramı sonlandırın.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'Kapı kilitleme görevi 🚪', 'Evdeki tüm odaların kapılarını arkasından kilitleyip sizi dışarıda bırakmaktan büyük keyif alıyor. Kişisel alan anlayışı devrim geçiriyor. Parmakların sıkışmaması için önlem alın ama kendi bölgesini ilan ettiği bu oyuna ciddi şekilde müdahale etmeyin.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'Masalda farklı ses tonları 🪄', 'Bu akşam Akıllı masalları açın, ancak metni farklı seslerle okuyun. Ayının sesini kalın, kuşun sesini ince çıkararak odada küçük bir tiyatro kurun. Bu, monotonluğu bozar ve çocuğun dikkatini anında masalın içine, oradan da uykuya çeker.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'Karanlıkta fısıltılı keşifler 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları ya da karakterinde en sevdiğiniz özelliği çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlayan ve gürültüyü unutturan en mistik yöntemdir.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'Evin içinde şemsiye ☂️', 'Dışarıda güneş var ama o evin içinde açık şemsiyeyle dolaşmak istiyor. Hayal gücü fiziksel koşulları kabul etmiyor. Evde boş alan varsa bırakın o şemsiyenin altında kendine küçük bir kamp kursun. Çocukların mantığını toplum kurallarıyla boğmayın.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'Markette Hayır sınavı 🛒', 'Marketin tam ortasında şeker istedi, siz Hayır dediniz ve o ağlamaya başladı. Etraftaki yargılayıcı bakışlara rağmen kararınızdan dönmediniz. Siz mükemmel bir annesiniz! Bir şeyleri unutmamak için gözünüz Alışveriş listesinde olsun ki işinizi bitirip hızlıca çıkabilesiniz.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'Neden adımı söyledin? diye sebepsiz öfkelenmek 😤', 'Siz yalnızca Gel, yemek hazır dediniz, o ise öfkelenip Neden benim adımı söyledin? diye ağlamaya başladı. Bu yaşta duygular o kadar karmaşıktır ki bazen durduk yere bile küserler. Hiçbir şey açıklamayın, 2 dakika sonra kendisi yemeğe koşacaktır.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'Yapay zekâ ve tuhaf fobiler 🤖', 'Birdenbire her zaman oynadığı kırmızı arabadan korkmaya mı başladı? Açıklanamayan fobiler sizi endişelendiriyorsa internetteki travmatik forumları kapatın. Anacan AI''dan 3.5 yaşındaki bir çocuğun hayal dünyasındaki tuhaflıklar hakkında bilimsel ve sakinleştirici bir yanıt alın.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'Çift olarak film izlemek... 🎬', 'Çocuk uyudu! Sonunda eşinizle bir film izlemek için koltuğa oturdunuz ama 10. dakikada ikiniz de derin uykuya daldınız. Sizin gerçeğiniz bu. Birbirinize yaslanıp uyuduğunuz o yorgun manzara, gerçek ekip çalışmasının bir göstergesidir.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'Yataktaki kırıntılar 🍞', 'Sabah gözlerinizi açıyorsunuz ve yatağın içi kraker kırıntılarıyla dolu. Meğer sabahın erken saatlerinde kendine kahvaltı hazırlamış. Bağırmak yerine, onun bu bağımsız problem çözme becerisini Gelişim takipçisinde komik bir anı olarak kaydedin.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'Çamaşır makinesi keşfi 🧺', 'Çamaşır makinesinin karşısında oturmuş, dönen çamaşırlara çizgi film izler gibi odaklanıyor. Bu, tamamen ücretsiz ve zihni sakinleştiren bir eğlencedir. Ona engel olmayın; siz de fırsattan yararlanıp dinlenin.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'Masaldan kaçma girişimleri 🏃‍♂️', 'Masal okurken her fırsatta yataktan fırlayıp “Oyuncağımı getireyim” diyerek kaçıyor. Uykuya teslim olmak istemiyor. Sesinizi aniden iyice alçaltıp fısıldayarak okumaya başlayın. Sizi duyabilmek için yatağa dönmek ve dikkat kesilmek zorunda kalacak, ardından uykuya dalacaktır.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'Ben büyüğüm, kahve içeceğim! ☕', 'Fincanınıza uzanıp kararlılıkla “Ben büyüdüm, ben de kahve içeceğim” diyor. O yalnızca sizin dünyanıza katılmak istiyor. Küçük fincanına biraz süt ve kakao koyup “Bak, bu da senin çocuk kahven” diyerek onunla fincan tokuşturun.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'Hava durumu ve kat kat giyinme taktiği ⛅', 'Bahar yaklaşırken hava kararsızdır; sabahları soğuk, öğlenleri sıcaktır. Hava durumu ve giyim aracı, soğan yöntemiyle kat kat giydirmeyi hatırlatır. Parkta ısındıkça bir katını çıkararak hem onun terlemesini hem de kendi stresinizi önleyin.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'Burnunu çaldım oyunu 👃', '“Burnunu aldım!” deyip başparmağınızı gösteriyorsunuz, o da buna gerçekten inanıp ağlamaya başlıyor! 3.5 yaşındaki bir çocuğun hayal gücü bazen gerçekle yanılsamayı ayırt edemez. Hemen “İşte, geri taktım” deyip burnunu öperek bu küçük travmayı gülümsemeye dönüştürün.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'Eşinizle sessiz göz teması 🥂', 'Çocuk sonunda uyudu. Siz ve eşiniz kanepede yan yana oturuyorsunuz; konuşacak hâliniz bile yok. Yalnızca sessizce birbirinize bakıp gülümsüyorsunuz. Bu sessiz bakışma, “Bu kaosun üstesinden harika geliyoruz” demenin en güzel yoludur.'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'Yapay zekâ ve ani inatlaşmalar 🤖', 'Düne kadar sakin olan çocuk bugün her şeye agresif tepki mi veriyor? İnternette korkutucu nedenler aramayın. Anacan AI''a bu gelişim sıçramasının (mental leap) psikolojik nedenlerini sorun ve çocuk doktoru onaylı yanıtla endişenizi sıfırlayın.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', 'Bunu Ben Buldum - Sahiplenici Minik 🔑', 'Yerdeki televizyon kumandasını veya babasının anahtarını alıp “Bunu ben buldum, benim!” diye sahipleniyor. Ona göre bulmak, sahip olmak demektir. Elinden zorla almayın; “Benim için bulduğun için teşekkür ederim” deyip dikkatini başka bir oyuncağa yönelterek geri alın.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'Banyoda Mini Spa 🛀', 'Bu akşam yalnızca onu değil, kendinizi de banyoya sokun. Çocuk uyuduktan sonra sıcak su, biraz köpük ve banyoda yanan tek bir mum... Kapıyı kilitleyin ve yalnızca 15 dakikalığına anne rolünden çıkıp yeniden kendiniz olun.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'Kuaförlük denemesi ✂️', 'Odaya girdiğinizde elindeki makasla bebeğinin saçını kesmeye çalıştığını görüyorsunuz. Bu anı yaşamak her annenin kâbusudur. Sinirlenmeden makası alın ve bu kuaförlük denemesini Bebek fotoğraf çekiminde komik bir anı olarak saklayın.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'Şarkıyı Geri Getir! 🎶', 'Radyoda çalan ve biten şarkıyı yeniden dinlemek istiyor. Bunun canlı yayın olduğunu ve şarkının bittiğini açıklıyorsunuz. Ama o “Geri getir!” diye ağlıyor. Çocuk beyni canlı yayın mantığını anlayamaz. Dikkatini dağıtmak için şarkıyı farklı ve komik bir sesle kendiniz söylemeye başlayın.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'Alışveriş listesindeki gereksiz şeyler 🛒', 'Markete gitmeden önce Alışveriş listesini açtınız; o da arkanızdan gelip telefonun ekranına dokunarak listeye art arda anlamsız harfler ve çikolata ekledi. Evet, dijital dünyayı çok hızlı keşfediyorlar!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'Sessizlik içinde çay ☕', 'Odanın ortasında oyuncaklarını sıraya dizmiş, tek başına oynuyor. Ne olur, o anı evi süpürerek harcamayın! Kanepeye oturun, kahvenizi veya çayınızı sıcakken için ve 10 dakika boyunca hiçbir şey düşünmeden yalnızca bu sessizliğin tadını çıkarın.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'Uyku için zamanlayıcı taktiği ⏱️', 'Uyku vakti geldiğinde birden susuyor, tuvalete gitmek istiyor ya da duvarla vedalaşıyor mu? Zamanlayıcı kurun. “Zil çalınca herkes uyur” kuralını uygulayarak bu bitmek bilmeyen vedadan ve usta işi oyalama çabalarından tartışmadan kurtulun.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'Gerçek sanatçı duvarı seçer 🖍️', 'Birkaç saniyelik sessizliğin sonu pek iyi olmadı. Odaya girdiğinizde keçeli kalemle duvara bir sanat eseri çizdiğini gördünüz. Derin bir nefes alın. İnce motor becerileri gelişiyor, duvar ise nasıl olsa silinir. Gelecekte gülümseyerek hatırlamak için bu şaheserin mutlaka fotoğrafını çekin.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Anacan topluluğunun gücü 💬', '“Benim çocuğum neden bu kadar inatçı?” düşüncesi zihninizi kemiriyor. Anacan Topluluğuna katılın. Diğer annelerin evlerinde yaşanan benzer absürt krizleri okuduğunuzda yalnız olmadığınızı ve tamamen normal bir süreçten geçtiğinizi göreceksiniz.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'Sabah sabah saklambaç 🙈', 'Siz işe veya kreşe geç kalıyorsunuz, o ise perdenin arkasına saklanıp Beni bul! diyor. Sinirleriniz gerilse de bağırmak süreci daha da uzatacaktır. Acaba benim güzel bebeğim nerede? diyerek oyuna 2 dakikalığına katılın, onu bulup saklandığı yerden çıkarın.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'Yemekleri renklerine göre ayırmak 🍅', 'Tabağındaki yemekleri renklerine ve şekillerine göre ayırıyor, yeşil olanları ise kenara itiyor. Beslenme planına göz atın. O sebzeleri görünmez bir püreye dönüştürüp lezzetli sosların içine nasıl gizleyebileceğinizi keşfederek bu oyunu gizlice kazanın.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'Babanın uydurma hikâyeleri 📖', 'Bu akşam odada duyulan ses sizin değil. Masal kitabını babaya verin ve hikâyeyi bilerek yanlış, komik ve absürt bir şekilde anlatmasına izin verin. Çocuğunuzun onu düzeltmekten nasıl keyif aldığını ve babasına nasıl kahkahalarla güldüğünü kenardan izleyin.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'Öfkeyi duygu günlüğüne dökmek 📝', 'Evde ne kadar yorulduğunuzu kimse görmüyor mu? Duygu günlüğü en sessiz sırdaşınızdır. Bugün sizi çıldırtan tüm ayrıntıları oraya yazın; ekrana bakarken zihninizin nasıl hafiflediğini ve dertlerinizin nasıl uçup gittiğini görün.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'Evin içinde şapkayla dolaşmak 🧢', 'Kışlık şapkasını evin içinde takmak istiyor. Israr ediyor, çıkarmıyor. Toplum kurallarını unutun. Yaratıcılığını ve karar verme özgürlüğünü kırmamak için günü o farklı ve komik görünümle geçirmesine izin verin. Oda sıcaklığı normalse bırakın öyle dolaşsın.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', 'Sen beni dinlemiyorsun! çıkışı 😠', 'Siz telefona bakarken veya yemeği karıştırırken gelip yüzünüzü kendisine çeviriyor: Bana bak! Haklı. Fiziksel olarak yanında olmanızı değil, bölünmemiş dikkatinizi istiyor. Yaptığınız işi bırakın ve yalnızca 3 dakika boyunca göz teması kurarak onu tüm dikkatinizle dinleyin.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'Parkta tanışma girişimleri 🤝', 'Parkta tanımadığı bir çocuğun yanına gidip Benim adım... diyerek kendini tanıtıyor. Sosyal becerileri şaşırtıcı bir hızla gelişiyor. Gelişim takibinde bu cesur iletişim girişimlerini, kişilik gelişiminin gurur verici bir kaydı olarak saklayın.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'İnatçı Hayır dönemi 🛑', 'Su ister misin? - Hayır! Ama 5 saniye sonra su için ağlıyor. Bu, kararlarının sonuçlarını test ettiği bir dönemdir. Aslında istedikleri şeylere bile hayır derler. Suyu masaya koyun, onu zorlamayın; kendi içindeki mücadeleyi bitirince içecektir.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'Akıllı masallarla kolay uyku 🪄', 'Klasik kitapları ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak tasarlayıp sıra dışı ve hiç çaba gerektirmeyen sesli bir uyku seansı oluşturun. Siz de dinlenin.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'Karanlık odada gölge tiyatrosu 🐰', 'Karanlıktan korktuğunu bahane edip yataktan kaçıyor. Odadaki tüm ışıkları kapatın, el fenerini açın ve duvarda ellerinizle kuş, köpek gölgeleri oluşturun. Korktuğu karanlık, onun için saniyeler içinde bir tiyatroya dönüşecektir.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'Ses ölçerle sessizliği korumak 🤫', 'Evdeki gürültü kulaklarınızı çınlatıyor. O sonunda uykuya daldığında Ses ölçer aracını etkinleştirin. Ekrandaki sıfıra yakın rakamları, o dijital sessizliği izlemek yorgun bir annenin zihni için en güzel görsel masajdır.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', 'Sen oturma! diktatörlüğü 🪑', 'Siz kanepeye oturmak istiyorsunuz, o ise koşup Oraya ayıcığım oturacak, sen kalk! diyor. Evi yönetmeye çalışıyor. İradesini sertçe kırmadan, Ayıcığın burada, ben de onun yanına oturayım diyerek dengeyi ve odadaki huzuru koruyun.'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: Çocuklar neden yalan söyler? 🤥', 'Suyu ben dökmedim, oyuncak döktü dedi. Yalan mı söylüyor, yoksa hayal gücünü mü kullanıyor? İnternette korkutucu yanıtlar aramayın. Anacan AI''dan 3.5 yaşındaki bir çocuğun bu tür hayallerinin tamamen normal bir gelişim basamağı olduğunu öğrenip rahatlayın.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'Eşinizle kahkaha krizi 🥂', 'Çocuk sonunda uyudu. Gün içinde sizi çıldırtan o absürt olayı eşinize anlatırken birden ikiniz de kahkahalara boğuluyorsunuz. Evet, bu kahkahalar ebeveynliğin en keyifli ödülüdür.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'Oyuncakları banyoya götürmek 🛀', 'Banyo yapmak istemiyor, ancak tüm arabalarını ve plastik ayılarını küvete doldurduktan sonra suya girmeyi kabul ediyor. Engel olmayın. Küvetteki o oyuncaklar, onun suyun sakinleştirici etkisine kendini bırakmasını sağlayan en büyük yardımcılardır.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'Makarna sevgisi 🍝', 'Düne kadar sevdiği eti bugün reddediyor, ancak gün boyu makarna yemek istiyor. İradesiyle savaşmayın. Sağlıklı tariflerde proteinleri ve sebzeleri görünmez bir sos gibi makarnaya nasıl ekleyebileceğinizi öğrenerek kazanan siz olun.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'Aynadaki danslar 🪞', 'Aynanın karşısına geçip şarkı söylüyor ve farklı dans hareketleri deniyor. Kendi bedeninin ritmini ve nasıl göründüğünü keşfediyor! Gelişim takipçisinde onun bu beden farkındalığını ve ritim duygusunu sevinçle kaydedin.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'Fısıltılı uyku düeti 🌙', 'Yatakta o kadar hareketli ki bir türlü uykuya dalamıyor. Sesinizi yükseltmek yerine aniden alçaltın ve sevdiği şarkıyı fısıldayarak söylemeye başlayın. Bebeğiniz sizi duymak için dikkat kesildiğinde zihni sakinleşebilir ve uyku moduna geçebilir.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'Saç taramak düşmandır 🪮', 'Tarağı görür görmez çığlık atarak odadan kaçıyor. Mücadele etmeyi bırakın. Önce tarağı ona verin; sizin veya oyuncak bebeğinin saçını taramasına izin verin. Kontrolün kendisinde olduğunu hissettikten sonra sıranın size geçmesine izin verecektir.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'Anacan topluluğunda destek 💬', '“Bir daha asla eski, özgür ben olamayacağım” düşüncesi aniden içinizi mi daraltıyor? Anacan Topluluğundaki annelerle geçici olsa da çok ağır ve derin olan bu duyguyu paylaşın; aynı yollardan geçtiklerini bilmenin verdiği teselli ve desteği alın.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'Su terapisi 🌊', 'Bazen hiçbir şey işe yaramaz; o sadece her şeye ağlar. Onu ılık su dolu küvete koyun ve suya biraz köpük ekleyin. Suyun rahatlatıcı etkisi tüm odaya huzur katarken onun sinir sisteminin de kısa sürede sakinleşmesine yardımcı olabilir.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'Babanın masaj saati 💆‍♂️', 'Bugün uzun süre ayakta kaldınız; peşinden koşmaktan ve yerden oyuncak toplamaktan beliniz ağrıyor. Çocuğunuz uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin direğisiniz; direklerin de mutlaka dinlenmesi ve güç toplaması gerekir.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'Ters giyilen tişörtün gururu 👕', 'Tişörtünü ters giymiş ve bunu dünyayı fethetmiş gibi gururla sergiliyor. İnsanların arasına giysisini ters giyerek çıkan çocuk, kendi kararını savunan çocuktur. Hiç müdahale etmeyin; onun bu özgüvenine hayran olun.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'Marketteki sınavlar 🛒', 'Kasaya yaklaştığınızda market arabasından sizin seçmediğiniz 3 farklı çikolata çıktı. Sınırlarınızı test ediyor. Hızlı bir hamleyle bu ürünleri geri bırakın. Unutkanlığa karşı da gözünüz daima uygulamadaki Alışveriş listesinde olsun.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'Soğuk kahve gerçeği ☕', 'Kahveyi hazırlayıp 3 saat sonra buz gibi içmek anneliğin resmî kuralıdır. Ama bugün bir değişiklik yapın! Onu sevdiği çizgi filmle baş başa bırakın ve o kahveyi sıcakken için. Siz robot değilsiniz; dinlenmeye hakkınız var.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'Ses ölçerin dijital sessizliği 🤫', 'Sonunda uykuya daldı! Eve çöken sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki 0-10 desibel değerine bakarak zihninizin yavaş yavaş nasıl dinlendiğini görsel olarak hissedin.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'Ben senin annenim! 👩‍👧', 'Rol değiştirme oyunu başladı! Size “Buraya gel, yatağa gir, ağlama” diye talimatlar veriyor. Onun bu liderlik deneyimini keyifle kabul edin ve hiç sesinizi çıkarmadan çocuğu rolünü oynayın. Bu, empati gelişiminin bir parçasıdır.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'Gizli vitaminler operasyonu 🥣', 'Düne kadar sevdiği yemeği bugün ağzına bile sürmüyor. İradesiyle savaşmayın. Sağlıklı tariflerde protein içeren besinleri farklı, renkli ve ilgi çekici şekillere dönüştüren atıştırmalık tariflerini deneyerek kazanan siz olun.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'Oyuncağım hasta 🩺', 'Oyuncak stetoskopunu alıp ayıcığını ciddi ciddi muayene ediyor ve ona yara bandı yapıştırıyor. Sembolik oyunlar aracılığıyla şefkati öğreniyor ve dünyayı anlamlandırıyor. Siz de hastanedeki bir hasta rolüne girerek oyuna katılın.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'Akıllı masallarla hayaller 🪄', 'Klasik kitapları artık ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak tasarlayın ve sıra dışı, hiç çaba gerektirmeyen sesli bir uyku seansı oluşturun.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'Ruh hâli günlüğündeki itiraflar 📝', 'Evde ne kadar yorulduğunuzu kimse görmüyor mu? Ruh hâli günlüğü en sessiz sırdaşınızdır. Bugün sizi çileden çıkaran tüm ayrıntıları oraya yazın; ekrana bakarken zihninizin nasıl hafiflediğini ve dertlerinizin nasıl uçup gittiğini görün.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'Hava ve ani değişimler ⛅', 'Dışarıda hava tam olarak açık değil; güneş var ama rüzgâr da mı esiyor? Hava ve giyim aracı, pencereden anlayamayacağınız rüzgâr hızını ve uygun kombini size anında söylesin. Kapıda kararsız kalıp vakit kaybetmeden yürüyüşe çıkın.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'Mantıksız gözyaşları ☀️', '“Güneş gözüme bakıyor” deyip hüngür hüngür ağladı mı? Odada mantık aramayın. Bu, onun için gerçekten derin bir üzüntüdür; dünyayı kontrol edemediği için öfkelenir. “Perdeyi çekip güneşi sakladım” diyerek sadece duygusunu onaylayın.'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'Yalnızlık özlemi 🚪', 'Gürültü beyninizi deliyor, her şeye bağırmak istiyorsunuz. Onu güvenli bir yere bırakıp tuvalete girin ve kapıyı kapatın. Sadece 5 dakika duvara bakın, hiçbir şey yapmayın. Bu kısa mola, sizi yeniden annelik rolüne hazırlayacak.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'Çıplak ayak kuralı 👣', 'Çıplak ayakla yürümekten; halıya, odadaki taşlara veya soğuk fayanslara dokunmaktan keyif alır. Ayak tabanındaki sinirlerin uyarılması, dengesi ve nörolojik gelişimi için çok önemlidir. Üşümediği sürece çorapsız yürümesine kesinlikle engel olmayın.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'Babanın tuhaf sesleri 🤡', 'Sizin yaptıklarınız artık işe yaramadığında, babanın çıkardığı tuhaf hayvan sesleri ve komik yüz ifadeleri durumu hemen kurtarır. Akşam krizlerinde topu hemen ona atın ve kenarda dinlenerek izleyin.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'Bugün ben pişireceğim 🧑‍🍳', 'Siz hamur açarken mutlaka yanınıza bir sandalye çekip sürece müdahale ediyor mu? Aslında yardım etmek değil, sürecin tam merkezinde olmak istiyor. Ona küçük bir hamur parçası verin. Mutfak dağılacak ama egosu ve yaratıcılığı büyüyecek.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'Yeni kelimeleri kaydetme 📈', 'Nesnelere tamamen kendi uydurduğu, hiçbir dilde bulunmayan yeni adlar veriyor. Üstelik sizin de ısrarla o kelimeyi kullanmanızı istiyor! Gelişim takipçisini açın ve gelecekte okuyup gülmek için bu komik kelimeleri mutlaka arşivleyin.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'Karanlıkla barışmak 🌙', 'Uykuya dalmasını hızlandırmak için yatmadan 1 saat önce odadaki tüm ek ışıkları ve tablet ekranlarını kapatın. Melatonin, karanlık ve teknolojiden uzak bir ortamda daha hızlı salgılanarak uykuya geçişi kolaylaştırır.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'Işıkları kapat, sessizliği dinle 🤫', 'Sonunda uykuya daldı. Şimdi evdeki en küçük ses bile sizi rahatsız ediyor. Işıkları kısın, televizyonu kapatın ve karanlığın ortasında o nadir sessizliğin tadını doyasıya çıkarın. Bütün günün yorgunluğu böyle atılır.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'Sebepsiz küsmeler 😤', 'Siz sadece “Gel, yemek hazır” dediniz; o ise kollarını kavuşturup duvara bakarak size küstü. Bu yaşta duygular o kadar karmaşıktır ki bazen durup dururken bile küserler. Hiçbir şey açıklamayın; 2 dakika sonra kendiliğinden yemeğe koşacak.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: Çocukluk korkuları 🤖', 'Birdenbire her zaman oynadığı kırmızı arabadan korkmaya mı başladı? Açıklanamayan fobiler sizi endişelendiriyorsa internetteki travmatik forumları kapatın. Anacan AI''dan 3.5 yaşındaki bir çocuğun hayal dünyasının tuhaflıkları hakkında bilimsel ve sakinleştirici bir yanıt alın.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'Fısıltının hipnozu 🌙', 'Yatakta uzanıp bacaklarını havaya kaldırıyor, uykuya dalmayı kesinlikle istemiyor. Bağırmak yerine sesinizi birden alçaltın ve onunla yalnızca fısıldayarak konuşun. Çocuk sizi duyabilmek için dikkat kesildiğinde beyni otomatik olarak sakinleşip uyku moduna geçecek.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'Anacan topluluğunda rahatlama 💬', 'Çok yoruldunuz ve kimseye hiçbir şey açıklamak istemiyorsunuz. Anacan Topluluğuna girip sadece okuyucu olun. Diğer annelerin de benzer yorgunluklar yaşadığını görmek, “Yalnız değilim” hissi yaratarak en iyi terapiye dönüşür.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'Soru yağmuru - Neden? 🌪️', '“Balıklar neden yürümüyor?”, “Güneş nereye gitti?” Sabahın erken saatlerinde zihni, saatte 100 soru hızıyla felsefi yanıtlar arar. Yorulsanız da ona kısa yanıtlar verin. O, evrenin sırlarını sizin ses tonunuzdan öğreniyor.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'O Benim! - Her şeyi sahiplenmek 🧸', 'Evdeki herhangi bir eşyaya sarılıp “Bu benim!” diye bağırıyor ve onu kimseye vermiyor. Mülkiyet sınırlarını keşfediyor. Onu bencillikle suçlamayın; dikkatini başka bir oyuna yönlendirerek eşyayı geri alın.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'Annenin kendi payı 🥗', 'Onu doyurmak için 3 farklı menü düşündünüz, peki siz yine aç mı kaldınız? Beslenme planı bölümünden yalnızca çocuklar için değil, anneler için de uygun olan; enerji veren, 10 dakikada hazırlanan, demir ve kalsiyum açısından zengin bir öğle yemeği seçerek kendinize değer verdiğinizi hissedin.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'Çiftlerin şampanyası 🥂', 'Zor bir günün ardından bardaklara sıradan sıcak çay doldurun. Eşinizle kanepede karşılıklı oturup “Bugün o kaostan da sağ çıktık” diyerek bardaklarınızı tokuşturun. Siz hem bu evin komutanları hem de aynı takımın üyelerisiniz.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'Kendi dökme inadı 💧', 'Suyu büyük sürahiden küçük bardağa mutlaka kendisi dökecek. Su önce masaya, oradan da yere dökülüyor. Ama siz onun bezi alıp orayı temizlemeye çalışan o küçük ellerine bakın. O, hata yaparak sorumluluk almayı öğreniyor; kızmayın.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'Küvetteki okyanus 🌊', 'Küvette yıkanmak artık temizlik değil, dalga yaratma oyunu. Bırakın sular etrafa sıçrasın. Suyun o mıknatıs etkisi, gün boyunca içinde biriken inatçı ve negatif enerjiyi yıkayıp gidere götürecek.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'Alışveriş listesi - unutulanlar 🛒', 'Markete gittiğinizde mutlaka en önemli şeyi unutuyor musunuz? Alışveriş listesi uygulamada sizi bekliyor. İhtiyaçlarınızı oraya not edin, eşiniz de işten dönerken eksiksiz alsın; siz zihninizi gereksiz yere yormayın.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'Parktaki mimari 🏰', 'Parktaki kum havuzunda sanki hazine arıyormuş gibi derin bir çukur kazıyor. Üstü başı çamur içinde. Ama onun bu keşif anını bölmeyin. Hava durumuna göre önceden seçtiğiniz, kirlenmeye uygun kıyafetler sayesinde bu manzarayı stressizce izleyebilirsiniz.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'Cansız nesnelerle tuhaf dostluklar 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, hatta onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı anlamlandırıyor. Onun bu özel senaryolarını mutlaka Gelişim takipçisine kaydedin.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'Akıllı masalda Ben 🪄', 'Bu akşam Akıllı masallardaki kahramana doğrudan çocuğunuzun adını verin. Masaldaki karakterin de odasını toplayıp sonra huzurla uyuduğunu anlatarak kuralları ona bağırmak yerine dolaylı yoldan öğretin.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'Ruh hâli günlüğü - Rahatlama anı 📝', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının hayatlarını kaydırmak yerine Ruh hâli günlüğünü açın ve bugün onun yaptığı en komik şeyi geleceğe bir anı olarak kaydedin. Bu dijital terapi sizi de rahatlatacak.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'Babanın sırtında atçılık 🐴', 'Enerjisini tam olarak atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Baba, çocuğu sırtına alıp at gibi koşturduğunda kahkahalar odayı doldurur; biriken tüm fiziksel stres ve o bitmek bilmeyen enerji, saniyeler içinde terle birlikte yok olur.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', 'Bana bak! dönemi 👀', 'Kanepeden atlıyor ve aynı hareketi tam 50 kez tekrarlayarak Anne, bana bak! diyor. Gözlerinizi telefondan ayırın. O, hareketin kendisi için değil, gözlerinizdeki o onay ışıltısını görmek için atlıyor. Ona kesintisiz 5 dakika ayırın, ilginize doysun.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', 'Ses ölçerle 0 desibel 🤫', 'Sonunda uyudu! Evi kaplayan sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki o 0-10 desibel değerine bakarken zihninizin yavaş yavaş dinlendiğini, bu görsel sessizliğin size nasıl masaj yaptığını hissedin.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'Özgür dans 🎶', 'Duyduğu ilk ritimle, ister reklam sesi ister araba kornası olsun, dans etmeye başlıyor. Hayata onun gibi neşeyle bakın! Odada ona katılıp birkaç dakikalığına çılgınca dans edin; tüm stresiniz uçup gidecek.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'Takipçi - gelişim gururu 📈', 'O artık bir bebek değil! Kendi kararları, tuhaf soruları ve kocaman bir kalbi olan başlı başına bir insan. Harika bir iş çıkarıyorsunuz!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'Halıdaki sınır çizgileri 🗺️', 'Odadan mutfağa yalnızca halının kırmızı çizgilerine basarak gitme kuralı koydu. Kaba motor becerileri ve dikkat birlikte çalışıyor. Bu mantıksız kuralı bozmayın; siz de onunla çizgilerin üzerinde dans ederek sabah egzersizinizi yapın.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'Yastığın altında tiyatro 🎪', 'Yatağa girdi ama başını yastığın altına sokup kendi kendine konuşuyor. Odayı tamamen karartın. Bırakın o karanlık ve güvenli sığınağında kendi senaryolarını kurup yavaş yavaş uyku dünyasına geçsin; müdahale etmeyin.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'Cepten çıkan makarna sınavı 🍝', 'Çamaşır makinesine attığınız pantolonun cebinden kurumuş makarna mı çıktı? Sizin için çöp, onun için belki de yolda acıkırsam diye sakladığı bir erzak. Onu kınamayın; planlama becerisinin bu ilk işaretlerini Gelişim takipçisine komik bir anı olarak kaydedin.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', 'Suyu kurut! talebi 💧', 'Bardaktaki suyu içmek yerine Bu çok ıslak, bunu kurut diye bağırıyor. 3.5 yaşın absürtlüğüne hoş geldiniz. Açıklamaya çalışmak enerjinizi tüketecek. Peki, başka kuru su getiriyorum deyip aynı suyu farklı renkte bir bardakta verin.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'Babanın gizli rüşveti 🤫', 'Dişlerini fırçalamak istemiyor. Babası gizlice yanına yaklaşıp “Dişlerini fırçalarsan cebimdeki sihirli taşı sana göstereceğim” diyor. Annelik kuralları bazen babaların bu kurnaz ama hemen işe yarayan sıra dışı oyunlarıyla bozulmalı.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'Balkondan topluma bakış 👀', 'Balkona çıkıp yoldan geçen herkese bağırarak el sallıyor ve karşılık alamayınca üzülüyor. Sosyal bağ kurma ihtiyacı zirvede. Onu hemen içeri çekmeyin; “Çok uzaktalar, belki duymamışlardır” diyerek empati duygusunu incitmeden koruyun.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'Sessiz kitap okuma seansı 📖', 'Bu akşam kimse konuşmuyor. Akıllı masalları açın; metni sesli okumak yerine cihazdan gelen huzurlu doğa sesleri eşliğinde resimlere sessizce bakın. Görsel hafızasının çalışması onu yoracak ve kendiliğinden uykuya dalmasına yardımcı olacak.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'Yumurtanın yanlış tarafı 🍳', 'Haşlanmış yumurtayı ortadan kestiğiniz için büyük bir kriz yaşanıyor. “Ben bütün istemiştim!” Yiyeceklerin görünümü onların en hassas noktalarından biridir. Sağlıklı tariflere göz atarak yiyecekleri doğru biçimde ve eğlenceli kesimlerle nasıl sunacağınızı öğrenin.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'Doğadaki dedektif 🔍', 'Parkta yalnızca karınca yuvasını izlemek için 20 dakika boyunca kıpırdamadan oturdu. Onu acele ettirmeyin. Hava ve giyim yardımcısıyla hava durumunu önceden kontrol edip kalın tabanlı ayakkabılar ve uygun kıyafetler giydirdiyseniz bırakın bu küçük biyolog dünyayı keşfetsin.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'Küvetteki mini laboratuvar 🛀', 'Suya farklı renklerde sabunlar ekleyip iksir hazırlıyor. Banyo dağılıyor, evet. Ama o çözücüleri ve maddelerin birbirine karışmasını öğreniyor. Bu bilimsel keşif, akşamın yorgunluğunu atmasını ve sakin bir uykuya hazırlanmasını sağlayan en güzel araçlardan biridir.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'Dolapta sosyal izolasyon 🚪', 'Evin ortasındaki gürültü birden kesildi. Onu gardırobun içinde, karanlıkta tek başına oynarken buldunuz. Bu depresyon değil, yalnızca duygusal olarak yeniden başlama anıdır. Kapağı hafifçe kapatıp ona bu özel alanın keyfini yaşama fırsatı tanıyın.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'Dokunulma isyanı 🔋', 'Bütün gün üzerinize tırmanan ve saçınızı çeken çocuğunuz yüzünden fiziksel olarak tükendiniz. Onu hemen güvenli bir yere bırakıp başka bir odaya geçin. Duygu günlüğünüze “Bedenim bana ait değil” yazarak bu touched out sendromunun psikolojik yükünü hafifletin.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'Ses ölçerle iç huzur 🤫', 'Sonunda uyudu. Kulaklarınızdaki çınlama ise hâlâ geçmedi. Uygulamadaki Ses ölçeri açın. Ekrandaki 0 desibel yazısını izlerken odadaki sessizliğin zihninize nasıl işlediğini ve sizi nasıl iyileştirdiğini hissedin.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'Telefon hırsızı 📱', 'Kendinize çay doldururken telefonunuzun kaybolduğunu ve onun kanepenin arkasında sizin gibi “Alo” dediğini fark ettiniz. Dijital alışkanlıklarınızı gözlemliyor. Cihazı alırken “Telefonum da seninle konuşmak istiyormuş” diyerek oyunu bozmadan geri alın.'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'Kendin giyin! politikası 👖', 'Ayaklarını havaya kaldırıp “Ben bebeğim, sen giydir” diyor. Bağımsızlık ile bağımlılık arasında gidip geliyorlar. Onu zorla giydirmeyin. Kıyafeti yanına bırakıp “Bu süper kahraman pantolonu sahibini bekliyor” diyerek onu eğlenceli bir şekilde yönlendirin.'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'Fısıltının mistik gücü 🌙', 'Yatağa gitmemek için bahaneler uyduruyor. Sesinizi iyice alçaltın ve yalnızca fısıldayarak konuşun. Sizi anlayabilmek için fiziksel olarak dikkatini toplamak zorunda kalacak; bu odaklanma da zihnini sakinleştirerek uykuya dalmasını sağlayacak.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'Anacan topluluğunda teselli 💬', '“Asla mükemmel olamayacağım” düşüncesi sizi bunaltıyor mu? O Instagram anneleri yanılsamasını bir kenara bırakın. Anacan Topluluğuna girin; evleri darmadağın olan, çocuğu duvarları karalayan annelerin samimi itiraflarını okuyup “Ben tamamen normalim” deyin.'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'Dinozor mantığı 🦖', 'Sabah hiçbir soruya cevap vermiyor, yalnızca kükrüyor. O bugün bir T-Rex. “Peki T-Rex''ler lapa yer mi?” diyerek onun yarattığı bu kimliğe uyum sağlayın ve sabah rutinini gözyaşı dökülmeden tamamlayın.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'Babanın hayalî kahramanları 🦸‍♂️', 'Bu akşam kitaptaki masalları unutun. Baba, başkahramanı çocuğun kendisi olan hayal ürünü ve fantastik bir hikâye anlatsın. “Sonra kılıcını çekip... dişlerini fırçaladı!” gibi cümleler çocuğu kahkahalara boğarak uykuya hazırlayacak.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'Kendi resmini eleştirmek 🖍️', 'Çizdiği siyah karalamayı gösterip “Bu sendin ama kötü oldu” diyerek yırtıp atıyor. Kendini eleştirme becerisi gelişiyor! Duygularını küçümsemeyin; “Bir sonraki resimde belki kırmızı rengi de denersin?” diyerek gelişimini destekleyin.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', 'Markette Bunu ben buldum 🛒', 'Kasaya yaklaşırken alışveriş arabasında sizin koymadığınız bir paket bisküvi beliriyor. Meğer sessizce keşfe çıkmış. Alışveriş listesini açın ve Bak, listemizde bu yok, bir dahaki sefere yazarız diyerek kuralın sorumluluğunu dijital bir otoriteye yükleyin.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'Baş başa çay keyfi 🥂', 'Zorlu bir günün ardından bardaklara normal sıcak çay doldurun. Eşinizle kanepede karşılıklı oturup Bugünkü kaostan da sağ çıktık, harika bir takımız diyerek bardaklarınızı tokuşturun. Siz evin sarsılmaz temellerisiniz.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'Gizli sebzeler operasyonu 🥦', 'Çorbanın içindeki tek bir pirinç tanesini veya havucu bulup Ben bunu yemem diyor. Beslenme planına göz atın. Proteinleri ve sebzeleri nasıl renkli keklere dönüştürebileceğinizi öğrenerek bu inatçı aşçının zihnini şaşırtın.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'Mobilyalara tırmanma olimpiyatları 🧗‍♂️', 'Kanepenin kenarından pencereye doğru tırmanıyor. Ev sizin için tehlikelerle dolu, onun içinse bir spor salonu. Dikkat et, düşersin! diyerek panik yaratmak yerine, Elini şuraya koy diyerek bu hareket ihtiyacını doğru şekilde yönlendirin.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'Yapay zekâ ve huzur 🤖', 'Çocuğunuzda aniden başlayan kekemelik veya öfke nöbetleri, internette kötü hastalıklar aramanıza mı yol açtı? Durun! Anacan AI''a bunun 3 yaş gelişim sıçramasıyla ilgili olup olmadığını sorun ve çocuk doktorlarınca onaylanmış, içinizi rahatlatacak bir yanıt alın.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'Odadaki ses efektleri 🪄', 'Akıllı masalları açın. Hikâyeyi okurken yalnızca kapı gıcırtısı, rüzgâr sesi ve fısıltılar çıkararak odada bir ses tiyatrosu kurun. Bu sıra dışı ses dalgaları onun dikkatini anında masalın içine, oradan da derin bir uykuya çekecek.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'Gölgeden kaçış 👻', 'Sokakta yürürken birden kendi gölgesinden korkup arkanıza saklandı. Mantık aramayın, 3.5 yaşındaki bir çocuğun hayal gücü böyle çalışır. Gel, gölgenin üzerine atlayalım diyerek korktuğu şeyi anında fiziksel bir oyuna dönüştürün.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'Babadan omuz masajı 💆‍♂️', 'Bugün çok uzun süre ayakta kaldınız; onun peşinden koşmaktan ve yerden oyuncak toplamaktan beliniz kopacak gibi. Çocuk uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz evin motorusunuz; motorun da mutlaka dinlenmesi ve yenilenmesi gerekir.'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', 'Sen kötü bir annesin! mi dedi? 💔', 'İstediği arabayı almadığınız için o cümleyi kurdu. Yüreğiniz sızladı. Ancak şunu bilin: O henüz duygularını doğru şekilde ifade edemiyor; aslında Hayal kırıklığına uğradım demek istiyor. Yalnızca ona sarılın ve duygusunu kabul edin.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'Moda anlayışı 👗', 'Kışlık çoraplarının üzerine yazlık sandaletlerini giyip parka gitmek istiyor. Israr ediyor ve çıkarmıyor. Toplumun kurallarını unutun. Yaratıcılığını kırmamak için bırakın gününü o farklı ve komik görünümle geçirsin; özgür olmayı öğreniyor.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'Aynadaki rakip 🪞', 'Aynanın karşısında durup kendi kendine kaşlarını çatıyor, öfkeli ve tuhaf mimikler yapıyor. Duyguların yüzünde nasıl göründüğünü test ediyor. Bu minyatür tiyatro oyuncusunun provasını dışarıdan hiç ses çıkarmadan keyifle izleyin.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'Anne için yalnız kalma saati 🚪', 'Gürültü beyninizi deliyor, her şeye bağırmak istiyorsunuz. Onu güvenli bir yere bırakıp tuvalete girin ve kapıyı kapatın. Duygu günlüğünü açın. Tüm tükenmişliğinizi oraya özgürce yazın. Bu kısa terapi zihninizi sıfırlayacak.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'Karanlıkla barışmak 🐰', 'Karanlıktan korktuğunu bahane ederek yataktan kaçıyor. Odadaki tüm ışıkları kapatın, el fenerini yakın ve ellerinizle duvarda kuş, köpek gölgeleri oluşturun. Korktuğu karanlık, onun için saniyeler içinde bir tiyatroya dönüşecek.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'Hava keşfi taktiği ⛅', 'Dışarıda güneş var ama rüzgâr da esiyor. Pencereden bakıp yanılmayın. Hava ve kıyafet aracı, hissedilen sıcaklığı ve kat kat nasıl giyinmeniz gerektiğini size anında söylesin; böylece kapıda kararsız kalıp vakit kaybetmeden, sağlıklı bir şekilde yürüyüşe çıkın.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'Bu benim hatam değil! 🤷‍♂️', 'Suyu bilerek yere döktü ama suçu oyuncağına atıp O itti dedi. Bu bir yalan değil, çocuk beyninin savunma mekanizmasıdır. İnatlaşmayın; Gel, o oyuncağa da nasıl temizleneceğini öğretelim diyerek zihnini şaşırtın.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'Küvette okyanus fırtınası 🌊', 'Küvette yıkanmak artık temizlik değil, küçük bir tsunami yaratma oyunu. Bırakın sular etrafa sıçrasın. Suyun o mistik ve enerji çeken mıknatıs etkisi, gün boyunca içinde biriken o inatçı, olumsuz enerjiyi yıkayıp gidere götürecek.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', 'Sen söyleme! yasağı 🛑', 'Arka planda çalan çocuk şarkısına mırıldanarak eşlik ettiniz ve o anında bağırdı: Sen söyleme! Odanın tek solisti o; sizin vokal denemeleriniz sahnesini daraltıyor. Alınmayın, sahneyi bu küçük egoiste bırakın.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'Akıllı masalda Ben 🪄', 'Bu akşam Akıllı Masallardaki kahramana doğrudan çocuğunuzun adını verin. Masaldaki karakterin de odasını toplayıp sonra huzurla uyuduğunu anlatarak kuralları ona bağırmadan, dolaylı yoldan öğretin.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'Düzeni mi kayıyor? ⏱️', 'Akşamları uykuya dalması çok mu uzun sürüyor? Uyku zamanlayıcısının çizelgesine bakın. Belki de gündüz uykusunu tamamen bırakmanın ve akşam uykusunu erkene çekmenin zamanı gelmiştir.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'Çizgi film eleştirmeni 📺', 'İzlediği çizgi filmi kendi dil bilgisiyle size anlatıyor, kimin nereye gittiğini ciddi ciddi açıklıyor. Onu dikkatle ve şaşırmış gibi dinleyin. Bırakın hayal gücü coşsun ve kendisini dünyanın en akıllısı gibi hissetsin.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'Topluluğun sessiz desteği 💬', 'Çok yorgunsunuz ve kimseye hiçbir şey açıklamak ya da içinizi dökmek istemiyorsunuz. Anacan Topluluğuna girip yalnızca okuyucu olun. Diğer annelerin aynı mantık dışı krizlerle nasıl başa çıktığını görmek, en güçlü sessiz tesellidir.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'Yataktan kaçış 🏃‍♂️', 'Su ver, Oyuncağımı bul... Uyumamak için 3 yaş bahaneleri hiç bitmiyor. Uyku zamanlayıcısını açın, sınırları kararlılıkla koruyun ve Beyaz Seslerle odayı sakinleştirin.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'Destan yazan minik 🗣️', 'Artık kelimeleri birleştirip hayali hikâyeler ve fantastik senaryolar mı uyduruyor? Bu muhteşem dil gelişimini kaçırmadan hemen sesli anı olarak kaydedin ve Bebek Albümünde ölümsüzleştirin.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'Kalsiyum kalkanı 🦴', 'Hızla büyüyen kemikler için kalsiyum şarttır. Süt içmiyor mu? Beslenme takip aracıyla bugün tükettiği peynir, yoğurt veya brokoli miktarını mutlaka hesaplayın.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'Benim! dönemi 🧸', 'Oyuncağını kimseye vermiyor mu? Bu bencillik değil, gelişimin doğal bir parçasıdır. Paylaşmak yerine sırayla oynamayı öğretme yöntemlerini Bloglardan okuyup uygulayın.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'Sabah devrimi 🛑', 'Dün çok sevdiği yemeği bugün nefretle mi reddediyor? Bu iştahsızlık değil, yalnızca kontrolü ele alma çabasıdır. Krizlerde nasıl sakin kalacağınızı Anacan AI ile dertleşin, derin bir nefes alın ve sofrada asla savaşmayın.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'Babanın oyun alanı 👨‍👧', 'Annelik 24/7 süren bir nöbet değildir. Partner işlevini devreye sokun! Bırakın bugün o bitmek bilmeyen enerjiyi babasıyla parkta atsın, siz de evde mutlak sessizliğin tadını çıkarın.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'Annenin molası ☕', 'Çocukla durmadan konuşmak ve sorulara cevap vermek yorucudur. Anne Dostu Mekânlardan çocuk köşesi olan bir kafe bulun, sıcak kahvenizi için, diğer annelerle dertleşip biraz nefes alın.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'Babanın masal sırası 📚', 'Bu akşam uyku ritüeli tamamen babanın sorumluluğunda. Masalı o okusun, siz de kapının arkasında tam bir sessizliğin tadını çıkarın.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'Kendim yapacağım! 🛑', 'Her işe karışıyor ve giyinme sürecini 3 kat mı uzatıyor? Etrafa saçılanlara değil, gelişen öz güvenine bakın. Sabrınız taştığında krizleri oyunla çözmenin yollarını Bloglardan okuyup derin bir nefes alın.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'Sıcak çay ve sessizlik 🍵', 'Zamanlayıcı durdu, çocuk uyudu. Ev işlerini unutun, her şey bekleyebilir. Sağlıklı tariflerden ilginç bir içecek hazırlayıp kendinizle baş başa kalmanın tadını çıkarın.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'Sabah sabah saklambaç 🙈', 'Siz işe veya kreşe geç kalıyorsunuz, o ise perdenin arkasına saklanıp Beni bul! diyor. Sinirleriniz gerilse de bağırmak süreci daha da uzatacaktır. Acaba benim güzel bebeğim nerede? diyerek oyuna 2 dakikalığına katılın, onu bulup saklandığı yerden çıkarın.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'Bedeninizin feryadı 🩸', 'Nedensiz gerginliğe ve yorgunluğa teslim olmayın. Regl Takipçisine göz atın, bedeniniz size sinyal veriyor. Kendinizi suçlamak yerine Sağlıklı tariflerden magnezyum içeren bir atıştırmalık seçip dinlenin.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'Sabah sabah felsefe 🤔', 'Kuşlar neden düşmüyor?, Ağaç neden yeşil oldu? Sabahın erken saatlerinde bilim konferansı resmen başladı. Ayrıntılı açıklamalar yapmaktan yorulduysanız, Sizce neden? diyerek soruyu ona yöneltin ve o harika, hayal ürünü cevapları dinleyin.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'Uyku için zamanlayıcı anlaşması ⏱️', 'Uyku vakti geldiğinde birden susar, tuvalete gitmek ister ya da duvarla vedalaşmaya başlar. Bir zamanlayıcı kurun. Alarm çaldığında herkes ışıkları kapatır kuralını uygulayarak bu bitmek bilmeyen vedadan ve ustaca manevralardan sabırla sıyrılın.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'Markette İstiyorum krizi 🛒', 'Kasanın önünde şekerleme için bağırıyor mu? Çevredekilerin kötü çocuk der gibi bakan gözlerine hiç aldırmayın. Sakin bir şekilde göz teması kurup kuralı açıklayın ve kararlı duruşunuzu bozmayın. Listenizde yoksa alınmayacak.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'Sen kimsin? oyunu 🎭', 'Size bakıp son derece ciddi bir ifadeyle Sen kimsin? Benim annem nerede? diyor. Sizinle oyunculuk oyunu oynuyor! Ben komşu teyzenim, annen birazdan gelecek deyip ses tonunuzu değiştirerek bu muhteşem tiyatroyu sürdürün.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'Ansızın Seni seviyorum 💖', 'Odanın ortasında oyun oynarken birden size bakıp koşarak geliyor ve boynunuza sarılıyor. Tüm uykusuz gecelere ve yorgunluklara değer! Bu anın getirdiği o derin, eşsiz huzurun tadını çıkarın; tüm o karmaşayı anında unutacaksınız.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'Çöp değil, sanat 🎨', 'Odanın ortasında küçük kâğıt parçaları ve kesilmiş iplerden oluşan büyük bir sanat eseri yaratmış ve onu atmanıza izin vermiyor. Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya saygı gösterin, temizlik yarına da kalabilir.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'Sessizliğin huzuru 🤫', 'Sonunda uykuya daldı! Evi kaplayan sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki o 0-10 desibel değerine bakarak zihninizin yavaş yavaş dinlendiğini, bu görsel sessizliğin size nasıl masaj yaptığını hissedin.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'Yarım kalan cümleleri tamamlayın 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaretler yapıp kaşlarını çatıyor ve sizin bulmanızı bekliyor. Kelime dağarcığı büyüyor, yalnızca beyni dilinden daha hızlı çalışıyor. Cümlesini sabırla tamamladığınızda yüzünde beliren o evet, tam da bunu söylüyordum rahatlamasını izleyin.'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'Babanın sırtında oyun 🐴', 'Enerjisini tam olarak atamamış ve yatağa girmemek için direniyor. Babayı yardıma çağırın. Baba, çocuğu sırtına alıp atçılık oynadığında kahkahalar odayı doldurur; biriken tüm fiziksel stres ve o bitmek bilmeyen enerji, ter dökerek saniyeler içinde yok olur.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'Annenin enerji barı 🥑', 'Onu doyurmak için 4 farklı şekilde menü hazırladınız, peki siz ne yediniz? Sağlıklı tariflerden 5 dakikada hazırlanan, kalsiyum açısından zengin özel bir atıştırmalık seçip ayakta da olsa tadını çıkarın; siz bu evin motorusunuz, şarj olmalısınız.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'Kedi gibi uyanış 🐾', 'Bu sabah o bir insan değil. Dört ayak üzerinde yürüyor, bacağınıza sürtünüyor ve yalnızca miyav diyerek iletişim kuruyor. Hayal gücünün en tatlı hâli bu. Kural koymak yerine siz de ona hayalî bir süt kabı uzatıp bu oyunun tadını çıkarın.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'Müzikli hipnoz 🎶', 'Akşamüstü kopan sebepsiz fırtınalar ve ağlama krizleri başladı. Televizyonu kapatın, ışıkları kısın ve odada çok hafif bir klasik müzik çalın. Müziğin o derin frekansı ortamı sihirli bir şekilde değiştirecek ve odaya huzur getirecek.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'Paylaşılamayan kahvaltı 🍳', 'Kendi tabağındakileri size kesinlikle vermiyor ama gelip ısrarla sizin tabağınızdaki yumurtadan yemek istiyor. Çocuklar ebeveynlerinin seçimlerine her zaman tamamen güvenir. Mücadele etmeyin, lokmanızı sevgiyle ona verin ve gülümseyin.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'Cansız nesnelerle sohbet 🗣️', 'Parktaki bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, hatta onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı anlamlandırıyor. Gelişim takipçisinde onun bu özel senaryolarını mutlaka işaretleyin, bu yüksek yaratıcılığın göstergesidir!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'Ruh hâli günlüğünde itiraf 📝', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının kusursuz hayatlarını kaydırmak yerine Ruh hâli günlüğünü açın ve bugün onun yaptığı en komik, sizi en çok güldüren anı geleceğe bir hatıra olarak kaydedin. Oraya yazmak en saf terapidir.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'Yemekleri renklerine göre ayırmak 🍅', 'Tabağındaki yemekleri renklerine ve şekillerine göre ayırıyor, yeşil olanları ise kenara itiyor. Beslenme planına göz atın. O sebzeleri görünmez bir püreye dönüştürüp lezzetli sosların içine nasıl saklayacağınızı keşfederek bu oyunu gizlice kazanın.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'Sessizlik ihtiyacı 🤫', 'Sonunda uykuya daldı! Evin üzerine çöken sessizliğe inanamıyorsunuz. Ses ölçer aracını etkinleştirin ve ekrandaki o 0-10 desibel değerine bakarken beyninizin yavaş yavaş dinlendiğini, bu görsel sessizliğin size nasıl masaj yaptığını hissedin.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'Cepten çıkan hazineler 🪨', 'Pantolonunu yıkarken cebinden 2 taş, kurumuş bir yaprak ve yarım bir çöp mü çıktı? Sizin için çöp olan bu nesneler, onun evreni keşfederken oluşturduğu değerli koleksiyonudur. Onları atmak yerine küçük bir hazine kutusunda biriktirin.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'Kapı kilitleme görevi 🚪', 'Evdeki tüm odaların kapılarını içeriden kilitleyip sizi dışarıda bırakmaktan özel bir keyif alıyor. Kişisel alan anlayışı adeta devrim geçiriyor. Parmaklarının sıkışmasını önlemek için önlem alın, ancak kendi bölgesini ilan ettiği bu oyuna fazla müdahale etmeyin.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'Tuvalet kağıdı sanatı 🧻', 'Birkaç dakikalık sessizlik... Sonra odaya girdiğinizde tüm tuvalet kağıdının açılıp eve yayıldığını görüyorsunuz! Sinirlenmek yerine kağıtları toplayıp birlikte kardan adam veya top yapın. Kaosu bağırarak değil, yaratıcılıkla alt edin.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'Çamaşır makinesi keşfi 🧺', 'Çamaşır makinesinin karşısında oturmuş, dönen çamaşırlara sanki çizgi film izliyormuş gibi odaklanıyor. Bu, tamamen ücretsiz ve zihni sakinleştiren bir eğlencedir. Ona engel olmayın; siz de fırsattan yararlanıp dinlenin, kaos kısa bir mola verdi.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'Kulağa fısıldanan sevgi sözleri 💖', 'Bütün gün sizi çileden çıkardı, her şeye karşı çıktı. Ama şimdi yatağında öyle masum uyuyor ki... Yanına uzanın; onu ne kadar sevdiğinizi ve bugün yaptığı güzel şeyleri kulağına fısıldayın. Çocuklar uykudayken bile annelerinin sevgi dolu sesini hissederler.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', 'Beni dinlemiyorsun! çıkışı 😠', 'Siz telefona bakarken veya yemeği karıştırırken gelip yüzünüzü kendisine çeviriyor: Bana bak! Haklı. Fiziksel olarak yanında olmanızı değil, bölünmemiş ilginizi istiyor. Yaptığınız işi bırakıp yalnızca 3 dakika boyunca göz teması kurarak onu tüm dikkatinizle dinleyin.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'Masaldan kaçma girişimleri 🏃‍♂️', 'Masal okurken her fırsatta Oyuncağımı getireyim diyerek yataktan fırlayıp kaçıyor. Uykuya teslim olmak istemiyor. Ses tonunuzu aniden iyice alçaltıp fısıltıyla okumaya başlayın. Sizi duyabilmek için mecburen yatağa dönüp tüm dikkatini size verecektir.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'Hava durumu ve kat kat giyinme taktiği ⛅', 'Yaz ayları yaklaşırken hava kararsızdır; sabah soğuk, öğlen sıcaktır. Hava durumu ve giyim aracı size soğan gibi kat kat giydirme yöntemini hatırlatır. Parkta ısındıkça bir katını çıkararak hem onun terlemesini hem de kendi stresinizi önleyin.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'Yapay zeka ve ani inatlaşmalar 🤖', 'Düne kadar sakin olan çocuk bugün her şeye agresif tepki mi veriyor? İnternette korkutucu nedenler aramayın. Anacan AI''a bu gelişim sıçramasının (mental leap) psikolojik nedenlerini sorun ve çocuk doktoru onaylı yanıtla endişenizi sıfırlayın.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'Burnunu çaldım oyunu 👃', 'Burnunu aldım! deyip başparmağınızı gösteriyorsunuz ve o buna gerçekten inanıp ağlamaya başlıyor! 3.5 yaşındaki bir çocuğun hayal gücü bazen gerçekle yanılsamayı ayıramaz. Hemen Aha, geri taktım deyip burnunu öperek bu küçük travmayı gülümsemeye dönüştürün.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'Eşinizle sessizce göz göze gelmek 🥂', 'Çocuk sonunda uyudu. Siz ve eşiniz kanepede yan yana oturuyorsunuz, konuşacak haliniz bile yok. Sadece sessizce birbirinize bakıp gülümsüyorsunuz. Bu sessiz bakışma, Bu kaosun üstesinden harika geliyoruz demenin en güzel yoludur.'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', 'Bunu ben buldum - Sahiplenici küçük çocuk 🔑', 'Evdeki kumandayı veya babasının anahtarını yerden alıp Bunu ben buldum, benim! diye sahipleniyor. Onun için bulmak, sahip olmak demektir. Elinden zorla almayın; Benim için bulduğun için teşekkür ederim deyip dikkatini başka bir oyuncağa yönelterek geri alın.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'Mutfakta konser 🥄', 'Tencereleri ve tahta kaşıkları çıkarıp mutfağın ortasında konser veriyor. Başınız ağrısa da bu, onun ritim duygusunun ve yaratıcılığının geliştiğini gösterir. Hemen müdahale etmeyin; birkaç dakika boyunca o çılgın enerjinin ses dalgalarıyla odaya yayılmasına izin verin.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'Banyoda mini spa 🛀', 'Bu akşam banyoya yalnızca onu değil, kendinizi de sokun. Çocuk uyuduktan sonra sıcak su, biraz köpük ve banyoda yanan tek bir mum... Kapıyı kilitleyin ve yalnızca 15 dakika boyunca anne rolünden çıkıp yeniden kendiniz olun. Bunu hak ediyorsunuz.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'Duygu günlüğünde itiraf', 'Telefonunuzu elinize alın. Sosyal medyada başkalarının hayatlarını kaydırmak yerine Duygu günlüğünü açın ve bugün onun yaptığı en komik şeyi geleceğe bir anı olarak kaydedin. Bu dijital terapi sizi de rahatlatacak; dertlerinizin nasıl uçup gittiğini ekrana bakarak görün.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'Şarkıyı geri getir! 🎶', 'Radyoda çalan ve biten şarkıyı yeniden dinlemek istiyor. Bunun canlı yayın olduğunu ve şarkının bittiğini açıklıyorsunuz. Ama o Geri getir! diye ağlıyor. Çocuk beyni canlı yayın mantığını henüz anlayamaz. Dikkatini dağıtmak için şarkıyı farklı ve komik bir sesle kendiniz söylemeye başlayın.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'Sessizlik içinde çay ☕', 'Odanın ortasında oyuncaklarını sıraya dizmiş, kendi başına oynuyor. Ne olur, o anı evi süpürerek harcamayın! Kanepeye oturun, kahvenizi veya çayınızı sıcakken için ve 10 dakika boyunca hiçbir şey düşünmeden yalnızca bu sessizliğin tadını çıkarın.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'Uyku için zamanlayıcı taktiği ⏱️', 'Uyku vakti geldiğinde birden susuyor, tuvalete gitmek istiyor ya da duvarla vedalaşıyor mu? Bir zamanlayıcı kurun. Zil çalınca herkes uyur kuralını uygulayarak bu sonsuz vedalaşmadan ve ustaca oyalanma çabasından tartışmadan kurtulun.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Anacan Topluluğunun gücü 💬', 'Benim çocuğum neden bu kadar inatçı? düşüncesi zihninizi kemiriyor. Anacan Topluluğuna katılın. Diğer annelerin evlerinde yaşanan benzer tuhaf krizleri okuduğunuzda yalnız olmadığınızı ve tamamen normal bir süreçten geçtiğinizi göreceksiniz.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'Gerçek ressam duvarı seçer 🖍️', 'Birkaç saniyelik sessizlik, tehlikeli bir sonuç doğurdu. Odaya girdiğinizde keçeli kalemle duvara bir sanat eseri çizdiğini gördünüz. Derin bir nefes alın. İnce motor becerileri gelişiyor, duvar ise nasıl olsa silinir. Gelecekte gülümseyerek hatırlamak için bu şaheserin mutlaka fotoğrafını çekin.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'Karanlığa davet 🌙', 'Yatak odasının ışıkları söndüğünde huzursuz oluyor mu? Odanın bir köşesine sıcak renkli (turuncu veya kırmızı), küçük bir gece lambası yerleştirin. Odanın geri kalanı ise melatonin salgılanması ve derin uyku için tamamen karanlık kalmalıdır.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'Kuaförlük denemesi ✂️', 'Odaya girdiğinizde elindeki makasla bebeğinin saçını kesmeye çalıştığını görüyorsunuz. Bu anı yaşamak her annenin kâbusudur. Sakinliğinizi koruyarak makası elinden alın ve bu kuaförlük denemesini Bebek fotoğraf çekiminde komik bir anı olarak arşivleyin.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'Doğaya kaçış şart ⛅', 'Dört duvar arasında enerjisi öfkeye dönüşüyor ve her cümlesi hayırla başlıyor. Hava ve kıyafet koşulları ne olursa olsun, uygun şekilde hazırlanıp onu mutlaka dışarı çıkarın. Toprağa dokunmak sinir sistemini hemen yenileyecektir.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'O benim! - Her şeyi sahiplenmek 🧸', 'Evdeki herhangi bir eşyaya sarılıp Bu benim! diye bağırıyor ve onu kimseye vermiyor. Mülkiyet sınırlarını keşfediyor. Onu bencillikle suçlamayın; dikkatini başka bir oyuna yönlendirerek eşyayı geri alın.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'Çöp değil, sanat 🎨', 'Odanın ortasında küçük kâğıt parçaları ve kesilmiş iplerden oluşan büyük bir sanat eseri yaratmış, onu atmanıza da izin vermiyor. Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya saygı gösterin; temizlik yarına da kalabilir.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'Babanın sırtında ata binmek 🐴', 'Enerjisini tamamen atamadı ve yatağa gitmemek için direniyor. Babayı yardıma çağırın. Baba onu sırtına alıp atçılık oynadığında kahkahalar odayı doldurur; biriken tüm fiziksel stres ve o bitmek bilmeyen enerji, saniyeler içinde terle birlikte yok olur.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'Masallar dünyası 🪄', 'Klasik masalları bir kenara bırakın. Akıllı masalları açın. Özel bir masal oluşturun.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'Topluluk desteği 💬', 'Çok yoruldunuz ve kimseye hiçbir şey açıklamak ya da içinizi dökmek istemiyorsunuz. Anacan Topluluğuna katılıp yalnızca okuyucu olun. Diğer annelerin aynı tuhaf krizlerle nasıl başa çıktığını görmek, en güçlü sessiz tesellidir.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'Sabah diktatörü iş başında 👑', 'Oraya sen oturma, ayıcığım oturacak! Kahvaltıda tüm masayı o yönetiyor. İradesini sertçe bastırmadan, Tamam, ayıcığın orada otursun, ben de burada oturayım diyerek dengeyi ve odadaki huzuru koruyun.'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'Gündüz uykusu isyanı 🥱', 'Yatağa gitmek istemiyor ve ağlıyor mu? Zorlamayın. Odadaki ışıkları azaltıp Sessizce kitap inceleme saati ilan ederek ikinizi de dinlendirecek yeni bir rutin oluşturun. Böylece hem siz hem de o farklı şekillerde dinlenebilirsiniz.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'Senaryoyu o yazsın 🪄', 'Klasik kitaplardan ikiniz de sıkıldınız ve odada bunaltıcı bir hava var. Akıllı masalları açın ve bu akşam hikâyeyi onun yönlendirmesine izin verin. Şimdi o uçan araba nereye gitsin? diye sorun; hayal dünyasında yeni yerler keşfederek uykuya dalsın.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'Aynadaki rakip 🪞', 'Aynanın karşısında durup kendi kendine kaşlarını çatıyor, kızgın ve tuhaf mimikler mi yapıyor? Duyguların yüzünde nasıl göründüğünü test ediyor. Bu minik tiyatro oyuncusunun provasını, ses çıkarmadan keyifle izleyin.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'Duvarla fısıltılı sohbet 🤫', 'Yatağa girip yüzünü duvara dönerek biriyle fısıltıyla dertleşiyor mu? Çok tatlı! Işıkları kapatın, o fısıltıların uykuya karışmasını dinleyerek dinlenin.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'Yanlış bardak kavgası mı? 🥤', 'Suyu sarı bardakta verdiğiniz için kıyamet mi koptu? Üzerinde durmayın; bu sabah sadece sınırlarını test ediyor. Suyu hemen mavi bardağa doldurun, evde huzuru yeniden sağlayın ve enerjinizi günün geri kalanına saklayın.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'Elektrikli süpürgeyle düşmanlık 🌪️', 'Evi süpürürken Tozlarımı süpürme diye ağlayıp önünüzü mü kesiyor? Aidiyet duygusu iyice absürt bir noktaya ulaştı. Süpürgeyi kapatın ve 5 dakika boyunca tozlara bay bay deme töreni düzenleyin. İnanın, bu kaosu daha çabuk bitirecek.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'Kıyafetler yine uyuşmadı 🧥', 'Dışarı çıkacaksınız ama o, yağmur çizmesiyle kısa kollu bir üst giymek mi istiyor? Tartışmayın. Hava ve Kıyafet bölümünü açıp telefonun buna izin vermediğini gösterin. Kuralı dijital ekrana bırakıp aradan çekilin; gömleğini sessizce giyecektir.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'Bir bardak çay hayali ☕', 'O kadar yoruldunuz ki o oynarken gizlice mutfağa kaçıp kapıyı mı kapattınız? Haklısınız. Duygu günlüğünü açın ve yalnızca iki kelime yazın: Bugün hayatta kaldım. Bazen bir annenin ihtiyacı olan tek şey, o 5 dakikalık kaçıştır.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'Bulutu tut, gitmesin! ☁️', 'Pencereden bakıp bulutun gitmesine mi ağlıyor? Rüzgârı bilimsel olarak açıklamaya çalışıp zaman kaybetmeyin. O şimdi başka çocuklara selam vermeye gitti deyin. Bu tuhaf düşüncesini mizah ve küçük hikâyelerle başka yöne çekerek günü kurtarın.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'Babasıyla kanepe güreşi 🤼‍♂️', 'Yatağa gitmemek için kaçıp saklandı mı? Topu babaya atın. Bırakın kanepede güreşiyormuş gibi yapsınlar. O gürültülü, terleten baba-oğul/baba-kız oyunu, çocuğun kalan son inatçı enerjisini de tüketip onu uykuya teslim edecek.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'İnternet annelerinden yoruldunuz mu? 📵', 'Instagram''ı açar açmaz herkesin mükemmel çocuğunu görüp moralinizi bozmayın! O uygulamayı kapatın ve Anacan Topluluğuna girin. Herkesin evinin sizinki gibi darmadağın, çocuklarının da gürültülü olduğunu görünce derin bir nefes alın; yalnız değilsiniz!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'Bunu ben pişireceğim! 🍳', 'Yumurtayı mutlaka kendisi çırpmak istedi ve kabın yarısı masaya mı döküldü? Bırakın o gururlu aşçı bakışının tadını çıkarsın. Mutfak nasıl olsa temizlenecek; onun gelişen benlik duygusuna ve bağımsızlığına dokunmayın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c'::uuid, 'Gizli makarna stoğu 🍝', 'Pantolonunu yıkarken cebinden kurumuş makarna mı çıktı? Bu açgözlülük değil, çocukça bir planlama. Ciddi bir yüz ifadesiyle onu çöpe atın ama içinizden bu kâşif ve tedarikçi çocuğa gülümseyin. Büyüyorlar!'),
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc', 'Sessizliğin ekrandaki değeri 🤫', 'Sonunda uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız mı çınlıyor? Uygulamadaki Ses ölçeri açın. O 0 desibel yazısına bakmak, gürültüden şişmiş yorgun beyniniz için dünyanın en iyi görsel masajı olacak.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'Gömleğin etiketi batıyor! 🏷️', 'Arkadaki o küçük etiket ona iğne gibi battığı için giymeyecek mi? 3.5 yaşın duyusal hassasiyeti insanı çileden çıkarabiliyor. Hiç tartışmayın; makası alın, etiketi dibinden kesin ve bu küçük krizi saniyeler içinde sonlandırın.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'O taş benimdi! 🪨', 'Parktan getirdiği o kirli taşı attığınız için feryat mı ediyor? Meğer en yakın arkadaşıymış. Hemen başka parlak bir eşya bulun ve Bak, taş sana bunu hatıra olarak göndermiş deyin. Uydurduğunuz küçük bir hikâyeyle durumu ustalıkla kurtarın.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'Benim masalım, benim kuralım 📖', 'Masal okurken bir kelimeyi yanlış söylediniz ve o da sizi hemen düzeltti mi? Demek ki ezberlemiş! Kitabı kapatın ve O zaman bu akşam sen bana oku deyin. Bırakın hayal dünyası çalışsın; siz de uzanıp yalnızca onun sesini dinleyin.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'Çorba dedektifi iş başında 🥕', 'Kaşığı çorbaya daldırıp tek bir soğan parçasını buldu ve kenara mı koydu? Kuyumcu titizliği! Hemen Sağlıklı tariflere göz atın; yarından itibaren o sebzeleri blenderdan geçirip sosların içine nasıl gizleyeceğinizi öğrenin ve gizlice kazanın.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'Çift olarak sessizliğin tadını çıkarın 🥂', 'Çocuk uyudu, ev toplandı. Eşinizle kanepede yan yana oturun, televizyonu bile açmayın. Sadece birbirinize “Bunu da başardık, hayatta kaldık” bakışı atın. İnanın, ebeveynliğin en romantik ve gerçek anı tam da budur.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'Marketteki o korkunç “İstiyorum!” 🛒', 'Kasanın tam önünde çikolata için bağırıyor mu? Arkanızdakilerin bakışlarına rağmen pes etmeyin. Alışveriş listesini açıp “Burada yok, kasa bunu kabul etmeyecek” deyin. Dışarıdan bir otorite onlara her zaman daha inandırıcı gelir.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'Neden benimle konuştun? 😤', 'Sadece “Günaydın” dediniz diye öfkelendi mi? Sebepsiz küsmeler dönemi son sürat devam ediyor. Üzerine gitmeyin, çayınızı koyup için. Emin olun, 2 dakika sonra gelip dizinize sarılacak. Duyguları o kadar karışık ki!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'Dört ayak üzerindeki çocuk 🐾', 'Bu sabah yataktan çocuk gibi değil de köpek gibi emekleyerek mi çıktı? Kuralları sıralayıp gerilmeyin. “Aferin benim akıllı köpeğime” deyip kahvaltısını verin. Rol oyunlarına katılmak, inatlaşmaktan çok daha az enerji harcatır.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'Gece yarısı ansızın gelen çığlık 😭', 'Gece gözleri kapalı hâlde ağlayarak uyandı ve sizi duymuyor mu? Ağlama analizinden kontrol edin; bu bir gece terörüdür. Uyandırmaya çalışmayın, yalnızca yanında durun, elini tutup okşayın. Kendiliğinden sakinleşip yeniden derin uykuya dalacaktır.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'Bedenim bana ait değil 🔋', 'Bütün gün bacağınıza sarılıp kucağa mı gelmek istiyor? Fiziksel olarak tükenmişsiniz. Dokunulma yorgunluğu (touched out) yaşıyorsunuz. Onu oyuncaklarıyla odada bırakıp 5 dakikalığına banyoya geçin ve yalnızlığın tadını çıkarın. Bu sizin hakkınız.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'Kapıyı ben açacağım! 🚪', 'Evden çıkarken kapıyı siz açtınız diye ağlayıp kapıyı yeniden kapattırdı mı? Kontrol hissi, bu yaşın en büyük psikolojik ihtiyaçlarından biridir. Bırakın size 1 dakika kaybettirsin; böylece sokakta yaşanabilecek 30 dakikalık krizi önleyip öz güvenini destekleyebilirsiniz.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'Küvetteki su baskını 🌊', 'Banyo yapmak bahane; aslında küvette bir okyanus oluşturup dalgalarla mı oynuyor? Bırakın oynasın. Suyun sesi ve sıçraması, içindeki o bitmek bilmeyen inatçı enerjiyi alıp götürecektir. Akşam hiç direnmeden yatağa uzanacaktır.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'Tuhaf sorulara AI yanıtı 🤖', '“Anne, gölgem geceleri nereye gidiyor?” sorusu karşısında donup kaldınız mı? Bir şeyler uydurmayın. Anacan AI''ı açın ve 3.5 yaş için masalsı, sevimli ve bilimsel bir yanıt alıp ona okuyun. Kendinizi büyük bir filozof ve her şeyi bilen bir anne gibi hissedin.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'Ters giyinmenin gururu 👕', 'Tişörtünü ters giydi ve düzeltmenize kesinlikle izin vermiyor mu? Kendi tercihi! Gözlerindeki “Ben başardım” diyen öz güven, giysisini doğru giymesinden daha önemlidir. Bırakın bütün gün öyle gururla dolaşsın; bu onun seçimi.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'Fısıltıyla uykuya dalmak 🤫', 'Yataktan kalkıp odada koşuyor, uyumak istemiyor mu? Bağırmayın. Birden çok yavaş ve fısıltıyla konuşmaya başlayın. Sizi anlayabilmek için dikkatini o kadar yoğunlaştırmak zorunda kalacak ki beyni yorulup otomatik olarak uyku moduna geçecektir. Deneyin!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'Kusursuz sessizlik anı 🛋️', 'Yapbozlarıyla öyle dalmış oynuyor ki ev birden sessizliğe mi büründü? Şüphelenmeyin, hemen kendinize bir kahve koyun. O nadir ve altın değerindeki dakikaları temizliğe ya da çamaşırlara değil, ruhunuzu dinlendirmeye ayırın. Siz robot değilsiniz.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'Küvetteki mini laboratuvar 🛀', 'Suya farklı renklerde sabunlar katıp iksir hazırlıyor. Evet, banyo dağılıyor. Ama o, çözücüleri ve maddelerin nasıl karıştığını öğreniyor. Bu bilimsel keşif, akşamın yorgunluğunu alıp onu huzurlu bir uykuya hazırlayan en güzel araçtır.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'Dokunulma isyanı 🔋', 'Bütün gün bedeninize tırmanan, saçınızı çeken çocuk yüzünden fiziksel olarak tükenmişsiniz. Onu hemen güvenli bir yere bırakıp başka bir odaya geçin. Duygu günlüğüne “Bedenim bana ait değil” yazarak bu touched out sendromunun psikolojik yükünü üzerinizden atın.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'Dolabın içinde dünyadan uzaklaşmak 🚪', 'Evin ortasındaki gürültü birden kesildi. Onu giysi dolabının içinde, karanlıkta tek başına oynarken buldunuz. Bu depresyon değil, yalnızca duygusal olarak yeniden başlama anıdır. Kapağı hafifçe kapatıp ona bu özel alanın keyfini yaşama fırsatı tanıyın.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'Telefon hırsızı 📱', 'Kendinize çay doldururken telefonunuzun ortadan kaybolduğunu ve kanepenin arkasında sizin gibi Alo dediğini fark ettiniz. O, dijital alışkanlıklarınızı tarıyor.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', 'Sen kendin giyin! politikası 👖', 'Ayaklarını havaya kaldırıp Ben bebeğim, sen giydir diyor. Bağımsızlık ile bağımlılık arasında gidip geliyorlar. Zorla giydirmeyin. Kıyafeti yanına bırakıp Bu süper kahraman pantolonu sahibini bekliyor diyerek onu yönlendirin.'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'Ses ölçer ile iç huzur 🤫', 'Sonunda uyudu. Kulaklarınızdaki çınlama hâlâ geçmedi. Uygulamadaki Ses ölçeri açın. Ekrandaki 0 desibel yazısını izleyerek odadaki sessizliğin zihninize nasıl işlediğini ve sizi nasıl iyileştirdiğini görsel olarak doğrulayın.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'Anacan topluluğunda teselli 💬', 'Asla mükemmel olamayacağım hissi sizi bunaltıyor mu? O Instagram anneleri illüzyonunu bir kenara bırakın. Anacan Topluluğuna girin; evleri darmadağın olan, çocukları duvarları karalayan annelerin samimi itiraflarını okuyup Ben tamamen normalim deyin.'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'Fısıltının mistik gücü 🌙', 'Yatağa gitmemek için bahaneler uyduruyor. Sesinizi iyice alçaltın ve yalnızca fısıldayarak konuşun. Sizi anlayabilmek için tüm dikkatini vermek zorunda kalacak; bu odaklanma da beynini hipnotize ederek uykuya dalmasını sağlayacak.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'Dinozor mantığı 🦖', 'Sabah hiçbir soruya cevap vermiyor, sadece kükrüyor. O bugün bir T-Rex. Peki T-Rex''ler lapa yer mi? diyerek onun yarattığı bu kimliğe uyum sağlayın ve sabah rutinini gözyaşı dökülmeden tamamlayın.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'Babanın hayalî kahramanları 🦸‍♂️', 'Bu akşam kitaptaki masalları unutun. Baba, başkahramanı çocuğunuz olan hayalî ve fantastik bir hikâye anlatsın. Ve kılıcını çekip... dişlerini fırçaladı! gibi cümleler çocuğunuzu kahkahaya boğarak uykuya hazırlayacak.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'Kendi resmini eleştirmek 🖍️', 'Çizdiği siyah karalamayı gösterip Bu sendin ama kötü oldu diyor ve yırtıp atıyor. Kendini eleştirme becerisi gelişiyor! Duygularını küçümsemeyin; Bir sonraki resimde belki kırmızı rengi de denersin? diyerek gelişimini destekleyin.'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', 'Markette Bunu ben buldum 🛒', 'Kasaya yaklaşırken alışveriş arabasından sizin koymadığınız bir paket bisküvi çıkıyor. Sessizce keşfe çıkmış. Alışveriş listesini açın ve Bak, bu listemizde yok, bir dahaki sefere yazarız diyerek kuralı dijital bir otoriteye bağlayın.'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'Mobilyalara tırmanma olimpiyatları 🧗‍♂️', 'Kanepenin kenarından pencereye doğru tırmanıyor. Ev sizin için tehlikelerle dolu, onun içinse bir spor salonu. Dikkat et, düşersin! diyerek panik yaratmak yerine Elini oraya koy diyerek bu hareket ihtiyacını doğru biçimde yönlendirin.'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'Gizli sebzeler operasyonu 🥦', 'Çorbanın içindeki o tek pirinç tanesini veya havuç parçasını bulup Ben bunu yemem diyor. Beslenme planına girin. Proteinleri ve sebzeleri nasıl renkli keklere dönüştürebileceğinizi öğrenerek bu inatçı aşçının zihnini şaşırtın.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'Çift çayı 🥂', 'Zorlu bir günün ardından bardaklara sıradan sıcak çay doldurun. Eşinizle kanepede karşılıklı oturup Bugün o kaostan da sağ çıktık, harika bir ekibiz diyerek bardaklarınızı tokuşturun. Siz evin sarsılmaz temellerisiniz.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'Gölgeden korkmak 👻', 'Sokakta yürürken aniden kendi gölgesinden korkup arkanıza saklandı. Mantık aramayın; 3.5 yaşındaki bir çocuğun hayal gücü böyle çalışır. Gel, gölgenin üstüne atlayalım diyerek korktuğu şeyi anında fiziksel bir oyuna dönüştürün.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'Yapay zekâ ve sakinlik 🤖', 'Çocuğunuzda aniden başlayan kekemelik veya öfke nöbetleri, internette ciddi hastalıklar aramanıza mı neden oldu? Durun! Anacan AI''a bunun 3 yaş gelişim sıçraması olup olmadığını sorun ve çocuk doktorlarınca onaylanmış, içinizi rahatlatan bir yanıt alın.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'Odadaki ses efektleri 🪄', 'Akıllı masalları açın. Hikâyeyi okurken kapı gıcırtısı, rüzgâr sesi ve fısıltılar çıkararak odada bir ses tiyatrosu kurun. Bu sıra dışı ses dalgaları, dikkatini anında masalın içine, oradan da derin uykuya çekecek.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'Ekmeğin ortası benim! 🍞', 'Bir dilim ekmeğin yalnızca ortasını yiyip kabuklarını size mi uzatıyor? Kabuklar yüzünden tartışmayın. Yarından itibaren ekmekleri metal kurabiye kalıplarıyla (hayvan şeklinde) kesin. Tasarım, bu beslenme felsefesi sorununu anında çözer.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'Sadece kokusunu içinize çekin 🫂', 'Bugün sizi gerçekten çileden çıkardı, enerjinizi tüketti, değil mi? Ama yatakta o kadar masum uyuyor ki... Işıkları kapatın, masal okumayın. Yanına uzanıp o mis gibi çocuk kokusunu derin derin içinize çekin ve bugün için de şükredin.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'Evden çıkmak istemiyorum derdi ⛅', 'Dört duvar sizi bunaltıyor, o ise koltukta ağlayıp dışarı çıkmak istemiyor mu? Hava durumunu ve giysi bölümünü açıp doğru kombini seçin ve zor da olsa onu parka götürün. Temiz hava yüzüne değer değmez tüm o öfkesi uçup gidecek. Size güveniyoruz!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'Birbirine değmeyen yiyecekler kanunu 🚫', 'Kahvaltıda domates salatalığa değdi diye kıyamet mi koptu? 3.5 yaşın resmî yemek felsefesine hoş geldiniz. Mantık aramayın; Sağlıklı tariflerde tabakları nasıl eğlenceli ve birbirinden ayrı bölgelere ayıracağınızı öğrenerek bu anlamsız krizi barışçıl biçimde çözün.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'Diplomatik uyku pazarlığı 🤝', 'Yatağa girmemek için sizinle resmen pazarlık ediyor: İki yudum su içeyim, bir kez sarıl, sonra uyuyacağım. Bu ustaca manipülasyona gülümseyin. Şartını kabul edip ışıkları kararlılıkla kapatarak anlaşmayı hemen sonuçlandırın.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'Yerdeki lav oyunu 🌋', 'Yer lav, koltuğa çık! Hayal gücü evi bir ormana çevirdi. İşlerinizi bir kenara bırakın ve 2 dakikalığına da olsa siz de lavdan kaçarak onun dünyasına girin. Bazen çocuğun kurallarına uymak, stres atmanın en iyi yoludur.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'Çöp kutusundaki sırlar 🗑️', 'Marketten aldığınız oyuncakla değil de oyuncağın sarıldığı balonlu naylona sarılıp bütün gün onunla mı oynuyor? Çocuk beyni hazır senaryoları değil, özgürlüğü sever. Gelişim takipçisine onun bu sıra dışı yaratıcılık anlarını gururla kaydedin.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'Akşamın huzurlu anları 🛀', 'Bütün gün duyduğunuz nedenlerden başınız şişti. Onu ılık su dolu küvete koyup suya biraz köpük ekleyin. Siz de kenarda oturup yalnızca suyun sesine odaklanın. Suyun o sihirli etkisi hem çocuğun inadını alıp götürecek hem de sinirlerinizi yatıştıracak.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'Siz beni dinlemiyorsunuz! 😤', 'Beni dinle! diyerek yüzünüzü elleriyle kendine doğru çeviriyor. Fiziksel olarak yanında olmanızı değil, tüm dikkatinizin onda olmasını istiyor. Telefonu veya elinizdeki işi yalnızca 3 dakikalığına bırakıp onu gözlerinin içine bakarak dinleyin. Bu, saatlerce sürebilecek mızmızlanmanın önüne geçer.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'Gece yarısı felsefesi 🦉', 'Tam yatağa girdiğinde Anne, bulutlar neden aşağı düşmüyor? gibi derin sorular soruyor. Amacı bilim öğrenmek değil, sizinle konuşup uyku saatini geciktirmek. Çünkü yukarıda uyuyorlar gibi kısa ve uydurma bir cevap verin; Akıllı masallardaki hafif melodiyi açarak uyku sessizliğini kararlılıkla sağlayın.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'Marketteki o şoke eden soru 😳', 'Kasa sırasında beklerken yüksek sesle Bu teyzenin saçı neden böyle? diye mi sordu? Onu utandırıp susturmayın; dikkatini hemen uygulamadaki Alışveriş listesine yöneltin: Bakalım elmayı almış mıydık? diyerek bu durumdan diplomatik bir şekilde sıyrılın.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'O tişört neden yıkandı?! 👕', 'Çok sevdiği ve artık rengi solmuş o tişörtü çamaşır makinesine attınız diye evde yas mı ilan edildi? Çocukların eşyalara bağlılığı bazen mantığın ötesine geçer. Tartışmayın; hemen Bebek fotoğraf çekimini açın, bu öfkeli hâlinin fotoğrafını çekip durumu eğlenceye dönüştürün. Gel, ekranda ne kadar kızgın göründüğüne bakalım hilesi dikkatini anında dağıtır, deneyin!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'Işıkları kapatın, gölge tiyatrosu başlasın 🐰', 'Karanlıktan korkuyor ve koridora tek başına çıkmak istemiyor mu? Odanın ışıklarını tamamen kapatıp küçük bir el feneri yakın. Ellerinizle duvarda köpek ve kuş gölgeleri oluşturarak karanlığı onun için korkutucu bir yer olmaktan çıkarıp oyun alanına dönüştürün. Uykuya dalması an meselesi olacak.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'Sizin de offline olmanız gerekiyor ☕', 'Odasında oyuncaklarıyla öyle dalmış oynuyor ki eve birden sessizlik mi çöktü? Ne olur, o anı evi süpürerek veya çamaşır katlayarak harcamayın! Gidip koltuğa uzanın, Ruh hâli günlüğüne sadece 5 dakikalık huzur yazın ve kahvenizi sıcakken için. Siz de bu evde yaşayan bir insansınız.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'Ben dağıtmadım, ayıcığım yaptı! 🧸', 'Suyu bilerek yere döküp suçu oyuncağına mı atıyor? Yalan söylemiyor, yalnızca 3.5 yaşın savunma mekanizmasını keşfetti. İnatlaşmayın, O zaman gel, ayıcığına nasıl temizleneceğini öğretelim deyip bezi eline verin. Hem sorumluluk almayı öğrenecek hem de egosu incinmeyecek.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'Fiziğe meydan okuyan inat 💧', 'Suyu masaya döktü ve ağlayarak o suyu yeniden bardağa doldurmanızı mı istiyor? Evet, odada mantık yok; yalnızca geri döndürülemeyen bir hatanın yarattığı hayal kırıklığı var. Açıklamaya çalışmayın; eline bir bez verip Gel, bu suyu yok edelim diyerek bunu oyuna dönüştürün.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'Anne için Offline sığınak 🚪', 'Gürültüden kulaklarınız çınlıyor. Onu güvenli bir yere (veya babasına) bırakıp tuvalete girin ve kapıyı kapatın. Yalnızca 5 dakika duvara bakın, hiçbir şey yapmayın, telefonu bile açmayın. Bu kısa sessizlik, anne rolünüze geri dönmenizi sağlayacak en güçlü silahtır.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'Babanın uçuş modu ✈️', 'Evde enerjisini atamamış ve yatağa gitmek istemiyor. Babayı koltuğa çağırın. O, çocuğu havaya kaldırıp uçak gibi gezdirirken odayı dolduran kahkahalar, biriken tüm fiziksel stresi saniyeler içinde yok edecek. Sıra babada.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'Yeni bir dilin icadı 🗣️', 'Oyuncağım üzüldü, Gökyüzü ağladı gibi duyguları nesnelere yükleyerek tamamen hayal ürünü, şiirsel cümleler kuruyor. Kelime dağarcığı ve duygusal zekâsı hızla gelişiyor. Bebek fotoğraf çekiminin video moduyla onun bu tatlı felsefesini hemen arşivleyin.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'Mutfak lideri iş başında 🧑‍🍳', 'Siz kek yaparken mutlaka yanına bir sandalye koymanızı ve unu kendisinin dökmesini istiyor. İzin verirseniz mutfak savaş alanına dönecek. Ona boş bir kap, su ve biraz un verip Sen kendi kekinin hamurunu yoğur deyin. Ortalık karışacak ama egosu tamamen tatmin olacak.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', 'Sen Kendin Ye! İsyanı 🥣', 'Kendi başına yiyebildiği hâlde inatla sizin yedirmenizi istiyor, sonra da kaşığı itip ağlıyor. Bu, çelişkiler dönemidir. Ne yedirmeye çalışın ne de aç kalmasından korkun. Tabağı önüne koyup Acıkınca yersin diyerek masadan kalkın. Kendi yiyecek.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'Annenin besin deposu 🥗', 'Onu doyurmak için farklı menüler düşündünüz; peki siz yine ayaküstü kuru bir şeyler mi yediniz? Sağlıklı tariflerden yalnızca çocuklar için değil, anneler için de enerji veren, 10 dakikada hazırlanan, demir ve kalsiyum deposu bir öğle yemeği seçerek kendinize değer verin.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'Oyuncağım hasta oyunu 🩺', 'Oyuncak stetoskopunu alıp ayıcığını ciddi bir şekilde muayene ediyor ve ona yara bandı yapıştırıyor. Sembolik oyunlar aracılığıyla şefkat ve ilgi duygularını işliyor. Siz de hastanede bir hasta rolüne girip uzanın ve bırakın sizi 5 dakika sessizce muayene etsin.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'Akıllı Masallarla Kolay Uyku 🪄', 'Klasik kitapları ezberlediniz. Akıllı masalları açın; başkahramanı çocuğunuz, fethedilecek yeri ise onun odası olarak belirleyip sıra dışı ve hiç çaba gerektirmeyen bir uyku seansı oluşturun.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'Sadece sarılın 🫂', 'Hiçbir oyuna, kitaba veya masala gerek yok. Bu akşam sadece onu göğsünüze bastırın, o güzel kokusunu içinize çekin ve karanlıkta ona ne kadar değerli olduğunu, onu ne kadar çok sevdiğinizi fısıldayın.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'Cansız nesnelerle sohbet 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler anlatıyor, onları azarlıyor. Sembolik oyunlar aracılığıyla dünyayı anlamlandırıyor.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'Sabah sabah saklambaç 🙈', 'Siz işe veya kreşe geç kalıyorsunuz, o ise perdenin arkasına saklanıp Beni bul! diyor. Sinirleriniz gerilse de bağırmak süreci daha da uzatacak. Acaba benim güzel yavrum nerede? diyerek oyuna 2 dakikalığına katılın, onu bulup saklandığı yerden çıkarın.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'Parkta diplomasi 🤝', 'Kaydırakta başka bir çocuğu itip kendisi mi kaymak istiyor? Paylaşmak onun için henüz tam olarak oturmamış, karmaşık bir kavramdır. Onu utandırmak veya cezalandırmak yerine Şimdi sıra onda diyerek yalnızca düzenin kuralını hatırlatın.'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'Güneş neden bana bakıyor?! ☀️', 'Sabah gözünü açar açmaz Güneş neden gözümün içine bakıyor? deyip hıçkıra hıçkıra ağlıyor mu? Mantık aramaya ve doğa olaylarını açıklamaya çalışmayın; o sadece dünyayı kontrol edemediği için öfkeleniyor. Perdeyi çekip Güneşi senin için sakladım deyin ve bu absürt sorunu saniyesinde çözün.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'Arabam daha uyumadı! 🚗', 'Yatağa girmemek için Arabamın uykusu gelmedi diye direniyor mu? Çocuklar kendi uykusuzluklarını ve dirençlerini çoğu zaman oyuncaklarına yansıtırlar. Tartışmayın, Akıllı masalları açın ve arabalar hakkında bir masal oluşturun. Araba uykuya dalar dalmaz o da kendiliğinden gözlerini kapatacak. Deneyin ve görün!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'Ekmeğin kenarları kesilsin! 🍞', 'Tostun sadece yumuşak kısmını yiyip kenarlarını kesinlikle reddediyor mu? Bu yaşın kendine özgü bir görsel estetik anlayışı vardır. O ekmekleri sevimli hayvan şekillerinde kesmeyi öğrenin. Tasarım, bu kavgayı anında bitirecek.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'Sessizce bakışmanın keyfi 🥂', 'Çocuk uyudu, ev toplandı. Eşinizle koltukta yan yana oturun, televizyonu bile açmayın. Sadece birbirinize bugün de hayatta kaldık bakışı atın. İnanın, yorgun ebeveynliğin en romantik ve gerçek anı tam da budur.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'Görünmez leke faciası 👕', 'Üstünde yalnızca mikroskopla görülebilecek bir leke bulup gömleğini giymeyi reddetti mi? O lekeyi ıslak mendille silermiş gibi yapıp Sihirle yok ettim deyin. Çocuk zihni annesinin sihrine her zaman inanır, deneyin ve görün.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'Karanlık odada gölge tiyatrosu 🐰', 'Karanlıktan korkuyor ve yatağa gitmiyor mu? Odanın ışıklarını tamamen kapatıp küçük bir el feneri yakın. Duvarda ellerinizle köpek ve kuş gölgeleri oluşturun. Korkutucu karanlığı onun için bir oyun alanına dönüştürün; uykuya dalması an meselesi olacak.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'Dinozorlar lapa yemez! 🦖', 'Sabah hiçbir soruya cevap vermiyor, sadece kükrüyor mu? O bugün bir T-Rex. Peki T-Rex''ler kahvaltı yapar mı? diyerek onun yarattığı bu karaktere ayak uydurun ve masaya gözyaşı dökmeden oturmasını sağlayın.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'Bugün tükendim 🛑', 'Her şey üst üste geldi ve sesinizi yükselttiniz. Şimdi de vicdan azabı çekiyorsunuz. Siz robot değilsiniz. Duygu günlüğünüzü açın ve Bugün gerçekten çok yoruldum yazın. Bu itiraf, kendinizi sahte bir gülümsemeye zorlamaktan daha çok yardımcı olacak.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'Sen kimsin? oyunu 🎭', 'Sabah size yabancı biriymişsiniz gibi bakıp Sen kimsin? Annem nerede? mi dedi? Bu, yeni bir rol oyunudur. Ben komşu teyzenim, annen birazdan gelecek deyin. Bırakın oda sabahtan kahkahaya boğulsun; bu, inatlaşmaktan çok daha az enerji harcatır.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'Masal okumadan uyutmak 🪄', 'Bu akşam masal okuyacak hâliniz yok mu? Akıllı masalları açın. Arka planda yalnızca fısıldayan orman ve rüzgâr sesleri olsun. Karanlıkta bu doğa seslerini dinleyerek ikiniz de gürültüden uzaklaşıp dinlenin. Görsel yorgunluk bir anda sona erecek.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'Çamaşır makinesinde unutulan hazine 🍝', 'Pantolonunu yıkarken cebinden kurumuş makarna veya bir taş mı çıktı? Bu açgözlülük değil, çocukça bir keşif merakıdır. Ciddi bir ifadeyle onu çöpe atın ama içinizden bu küçük tedarikçiye gülümseyin. Gelişim takipçisine bunu komik bir an olarak kaydedin.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'Suyu farklı bardakta verin! 🥤', 'Suyu sarı bardakta verdiğiniz için odada kıyamet mi koptu? Üstelemeyin, o sadece sınırlarını deniyor. Suyu hemen istediği bardağa aktarın, odada barışı sağlayın ve enerjinizi günün geri kalanına saklayın.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'Parktan çıkışta yarış taktiği 🌳', 'Parktan dönme vakti geldi ve ağlama krizleri başladı. Onu sürükleyerek götürmek işe yaramayacak. Bakalım arabaya kadar kim daha hızlı penguen gibi yürüyecek? diyerek dikkatini hemen eğlenceli bir yarışa yöneltin. O mutlaka kazanmak isteyecek.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'Babasıyla koltuk güreşi 🤼‍♂️', 'Yatağa gitmemek için kaçıp saklandı mı? Topu babaya atın. Bırakın koltukta şaka yollu güreşsinler. Bu gürültülü ve terleten oyun, çocuğun kalan son inatçı enerjisini de tüketerek kolayca uykuya teslim olmasını sağlayacak.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'Müzikli hipnoz etkisi 🎶', 'Akşamüstü kopan sebepsiz fırtınaları hafif klasik müzikle dindirmeyi deneyin. Televizyonu kapatın. Çoğu zaman bu basit yöntem, o derin frekanslarla gürültüyü bastırır ve odaya bir şekilde mucizevi bir sessizlik getirir.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'Kendi uydurduğu kelimeler 🗣️', 'Gökyüzü ağladı, Araba küstü gibi tuhaf cümleler kuruyor. Kelime dağarcığı fırtına gibi büyüyor ve o, kelimelerle oynuyor. Gelişim takipçisini açın ve onun bu tatlı, şiirsel felsefesini arşive ekleyin; yıllar sonra okuyup çok güleceksiniz.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'Ekran molası ve vicdan azabı 📺', 'Bugün çok işiniz olduğu için televizyonun karşısında uzun süre mi kaldı? İçinizi vicdan azabı mı kemiriyor? Her gün mükemmel olamazsınız. Bazen ekranlar, bizi büyük kaoslardan kurtaran en masum bakıcıdır. Kendinize yüklenmeyin.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'Tuhaf korkuların başlaması 🤖', 'Birdenbire banyodaki gider deliğinden korkmaya mı başladı? İnternette hastalık aramayın. Anacan AI''a sorun; bunun bu yaştaki hayal gücünün yol açtığı tamamen normal ve geçici bir fobi olduğunu öğrenerek paniğinizi yatıştırın.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'Kendim yiyeceğim! 🥣', 'Kendi başına yiyebildiği hâlde ısrarla sizin yedirmenizi istiyor, kaşığı uzattığınızda ise itip ağlıyor. Ne istediğini kendisi de bilmiyor. Tabağı önüne koyup Acıkınca yersin deyin ve masadan kalkın. Acıktığında kendi başına yiyecek.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'Kendinize de biraz zaman ayırın 💆‍♂️', 'Çocuk uyuduktan sonra eşinizden 10 dakikalık bir omuz masajı isteyin. Bütün gün koşturmaktan boynunuz tutuldu. Siz yalnızca aynı evi paylaşan ebeveynler değilsiniz; birbirinizin en yakın psikolojik destekçisisiniz.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Instagram anneleri ve gerçekler 📱', 'Instagram''ı açar açmaz herkesin mükemmel çocuğunu görüp moralinizi bozmayın! O uygulamayı kapatın ve Anacan Topluluğu''na girin. Herkesin evinin sizinki gibi darmadağın, çocuklarının da gürültülü olduğunu görün ve Ben tamamen normalim deyin!'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'Alarm çalınca yatıyoruz ⏱️', 'Uyku saati sürekli uzuyor. Su, tuvalet, duvarla vedalaşma... Telefonunuzun zamanlayıcısını kurun. Alarm sesini duyunca herkes ışıkları kapatır diye bir kural koyun. O sesi duyduğunda hiç itiraz etmeden yatağa girecek.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'Dört ayak üstündeki çocuk 🐾', 'Bu sabah yataktan çocuk gibi değil de köpek gibi emekleyerek mi çıktı? Kuralları sıralayıp sinirlenmeyin. “Aferin benim akıllı köpeğime” deyip kahvaltısını verin. Rol oyunlarına katılmak, inatlaşmaktan çok daha az enerji harcatır.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'Bedenim bana ait değil 🔋', 'Bütün gün bacaklarınıza sarılıyor, kucak mı istiyor? Fiziksel olarak tükenmişsiniz. Dokunulma yorgunluğu yaşıyorsunuz. Onu oyuncaklarıyla odada bırakıp 5 dakikalığına banyoya kaçın ve kapıyı kapatın. Sadece o yalnızlığın tadını çıkarın.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'Gece yarısı aniden gelen çığlık 😭', 'Gece gözleri kapalı hâlde ağlayarak uyandı ve sizi duymuyor mu? Belirtileri değerlendirin; bu bir uyku terörüdür. Uyandırmamaya çalışın, sadece yanında durun, elini tutup okşayın. Kendi kendine sakinleşip yeniden derin uykuya dalacak.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'Mutfaktaki yardımcı felaketi 🧑‍🍳', 'Siz hamur açarken sandalyesini getirip unu mutlaka kendisi mi dökmek istedi? İzin vermezseniz ağlayacak. Ona küçük plastik bir kap ve biraz un verin. Mutfak dağılacak ama o ciddi aşçı ifadesi, sonrasında yapacağınız temizliğe değecek.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'Kapıyı ben açacağım! 🚪', 'Evden çıkarken kapıyı siz açtınız diye ağlayıp yeniden kapattırdı ve kendisi mi açtı? Kontrol hissi bu yaşta en büyük psikolojik ihtiyaçtır. Size 1 dakika kaybettirsin ama dışarıda yaşanacak 30 dakikalık krizi önlesin.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'Marketin ortasında donup kalmak 🛒', 'Marketin ortasında durup “Ben ne almaya gelmiştim?” diye düşüncelere mi daldınız? Annelik zihni gerçekten çok dolu. Uygulamadaki Alışveriş listesini açıp o dijital hafızaya güvenmek sizi bu karmaşadan her zaman kurtaracak.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'Banyodaki su baskını 🌊', 'Banyo yapmak bahane, aslında küvette bir okyanus yaratıp dalgalarla mı oynuyor? Bırakın oynasın. Suyun sesi ve sıçramaları, içindeki o bitmek bilmeyen inatçı enerjiyi alıp götürecek. Akşam hiç direnmeden yatağa uzanacak.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'Mükemmel sessizlik anı 🛋️', 'Yapbozlarıyla öylesine derin bir şekilde oynuyor ki ev bir anda sessizliğe mi büründü? Şüphelenmeyin, hemen kendinize bir kahve koyun. O nadir ve altın değerindeki dakikaları temizliğe veya çamaşırlara değil, ruhunuzu dinlendirmeye ve tavanı seyretmeye ayırın. Siz robot değilsiniz.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'Tişörtün etiketi batıyor! 🏷️', 'Arkasındaki o küçücük etiket iğne gibi battığı için giymeyecek mi? Bu yaştaki duyusal hassasiyet insanı çıldırtır. Hiç tartışmayın, makası alın, etiketi dibinden kesin ve bu küçük krizi saniyeler içinde bitirin.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'Fısıltıyla uykuya dalmak 🤫', 'Yataktan kalkıp odada koşuyor, uyumak istemiyor mu? Bağırmayın. Birden çok yavaş ve fısıltıyla konuşmaya başlayın. Sizi anlamak için dikkatini o kadar yoğunlaştırmak zorunda kalacak ki beyni yorulup otomatik olarak uyku moduna geçecek. Deneyin!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', 'Oyuncağım devirdi! yalanı 🤷‍♂️', 'Suyu bilerek yere döktü ama parmağıyla arabasını gösterip “O itti” mi dedi? Bu yalan söylemek değil, bir savunma mekanizmasıdır. “Gel, o arabaya da nasıl temizleneceğini öğretelim” diyerek zihnini ustalıkla yönlendirin.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'Sessizliğin ekrandaki değeri 🤫', 'Sonunda uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız mı çınlıyor? Uygulamadaki Ses ölçeri açın. O 0 desibel yazısına bakmak, gürültüden şişmiş yorgun beyninize dünyanın en iyi görsel masajı olacak.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'Görünmez sebzeler operasyonu 🥦', 'Çorbanın içindeki tek bir havuç parçasını bulup “Bunu yemiyorum” mu dedi? Tanıdık bir manzara! Sebzeleri püre hâline getirip soslara ekleyin, bakalım şimdi nasıl bulacak! O aşçılık zekâsını alt edin.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'Ters giyinmenin gururu 👕', 'Tişörtünü ters giymiş ve düzeltmenize kesinlikle izin vermiyor mu? Kendi tercihi! Gözlerindeki “Ben başardım” diyen özgüven, doğru giyinmesinden daha önemlidir. Bırakın bütün gün öyle gururla dolaşsın; bu onun özgür seçimi.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'Sözünüz işe yaramayınca baba devreye girer 🤡', 'Söylediklerinizi artık umursamıyor ve direniyor mu? Babası gelip tuhaf hayvan sesleri çıkarıp komik yüz ifadeleri yapınca anında gülmeye mi başladı? Bazen erkeklerin bu mantıksız mizahı evi gerçekten kurtarıyor. Siz kenardan izleyin.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'Garip sorulara AI yanıtı 🤖', '“Anne, gölgem geceleri nereye gidiyor?” sorusu karşısında donup kaldınız mı? Hiçbir şey uydurmayın. Anacan AI''ı açın, bu yaşa uygun en masalsı, tatlı ve bilimsel yanıtı alın, ona okuyun. Kendinizi büyük bir filozof gibi hissedeceksiniz.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'İçimdeki öfkeyi yazmak 📝', 'Evde ne kadar yorulduğunuzu kimsenin görmemesi sizi patlama noktasına mı getiriyor? Duygu günlüğünü açın. Bugün sizi çileden çıkaran ne varsa hepsini oraya yazın. Sahte bir gülümsemenin ardına saklanmak yerine duygunuzu kabul edip yazmak size çok daha iyi gelecektir.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'Cansız nesnelerle uzun sohbetler 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler mi anlatıyor? Oyun yoluyla kuralları ve dünyayı anlamlandırıyor.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'Bu akşam sadece sarılalım 🫂', 'Hiçbir oyuna veya sesli bir kitaba gerek yok. Bu akşam onu göğsünüze bastırın, o tertemiz çocuk kokusunu içinize derin derin çekin ve karanlıkta ona ne kadar değerli olduğunu fısıldayın. Bu, ikinize de yetecektir.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'Havayı pencereden tahmin etmeyin ⛅', 'Dışarıda güneş var ama rüzgâr da mı esiyor? Hava ve giyim aracı size kat kat giydirmenizi öneriyorsa ona güvenin. Kapının önünde kararsız kalıp söylenmek yerine doğru kombini seçerek rahatça dışarı çıkın.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'Kendi yemeğini size vermez 🍳', 'Kendi tabağındakileri size vermiyor ama ısrarla gelip sizin tabağınızdan mı yemek istiyor? Çocuklar ebeveynlerinin seçimlerine her zaman tamamen güvenir. Mücadele etmeyin, lokmayı sevgiyle ona uzatın ve bu komik bencilliğe sadece gülümseyin.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'Benim masalım, benim kuralım 📖', 'Masal okurken bir kelimeyi yanlış söylediniz ve o sizi hemen düzeltti mi? Demek ki ezberlemiş! Kitabı kapatın ve “O zaman bu akşam sen bana oku.” deyin. Bırakın hayal dünyası çalışsın; siz de uzanıp o tatlı sesini dinleyin.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'Kuleyi yapıp sonra yıkmak 🧱', 'Büyük bir emekle bloklardan kule yapıyor, ardından kahkaha atarak tek hamlede mi yıkıyor? Siz emeğine üzülseniz de o fizik kurallarını ve neden-sonuç ilişkisini öğreniyor. Bu yıkımlar, beyninde kurulan yeni bağlantılardır; sinirlenmeyin.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'Benim öğle yemeğim nerede? 🥗', 'Çocuğunuza sebzeli özel bir tabak hazırlarken kendiniz sadece ekmek mi atıştırıyorsunuz? Durun! Beslenme planındaki annelere özel, kolay ve 5 dakikalık salatayı hazırlayın. Bu evin asıl motorunu, yani kendinizi, şarj etmeyi artık unutmayın. Siz önemlisiniz.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'Işıkları kapatın, uyku gelsin 🌙', 'Uyku saatinden 1 saat önce odadaki tüm parlak ışıkları ve televizyonu kapatın. Oda karardıkça otomatik olarak esnemeye başlayacaktır. Melatonini (uyku hormonunu) böylece sessizce ve doğal yoldan devreye sokarak işinizi kolaylaştırın.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'Ben biliyorum, sana da öğreteyim ☝️', 'Sizin zaten bildiğiniz bir şeyi gelip son derece ciddi ve bilge bir yüz ifadesiyle size mi açıklıyor? Kendi zekâsını test ediyor. Gülmemek için dudağınızı ısırın ama onu büyük bir ciddiyetle dinleyip “Gerçekten mi? Çok sağ ol.” deyin.'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'Babasının hikâyeyi yanlış anlatması 📖', 'Bu akşam anlatma sırası sizde değil. Masal kitabını babasına verin. Babası hikâyeyi bilerek tersinden, komik ve absürt bir şekilde anlatsın. Çocuğunuzun onu düzeltmekten nasıl keyif aldığını ve kahkahalar attığını siz de kenardan keyifle izleyin.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'Temizliği boş verin, oyuncaklar kalsın 🎨', 'Odanın ortasında parçalardan büyük bir eser yarattı ve toplamanıza izin vermiyor mu? Temizlik takıntısını bir kenara bırakın. Yarattığı karmaşaya dokunmayın; temizlik yarına da kalabilir. Ev müze değil.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'Çizgi filmi size anlatıyor 📺', 'İzlediği çizgi filmi bambaşka bir mantıkla anlatıyor, kimin nereye gittiğini ciddi ciddi açıklıyor mu? Onu her şeye inanıyormuş gibi dikkatle dinleyin. Bırakın kendini dünyanın en akıllı ve en güçlü insanı gibi hissetsin.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'Marketteki o korkunç “istiyorum” 🛒', 'Kasanın hemen önünde çikolata için bağırıyor mu? Arkanızdakilerin bakışlarına rağmen teslim olmayın. Alışveriş listesini açıp “Burada yok, kasa bunu okumaz.” deyin. Dışarıdan bir otorite onlara her zaman daha inandırıcı gelir.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'Tüm yorgunluğu suyla yıkamak 🛀', 'Bazen hiçbir şey işe yaramaz; o sadece her şeye ağlar. Onu ılık su dolu küvete koyun. Suyun o gizemli, gerginliği gideren gücü tüm odaya ve sinir sistemine anında büyük bir huzur getirecektir. Deneyin ve görün.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'Yere dökülen yer çekimi 🍝', 'Yemeği bilerek yere atıp ardından bakıyor mu? Bağırmayın; aslında sizi kızdırmaya değil, yer çekimini test etmeye çalışıyor. Tabağı sakince önünden alın, dersinizi sonra verirsiniz.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'Bana Batman de! 🦇', 'Sabah uyanıp kendi adını reddederek başka bir isimle çağrılmayı mı istiyor? Uyum sağlayın! 5 dakika boyunca Buyurun Batman, lapanızı yiyin diyerek odadaki gerginliği komediye dönüştürün.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'Pijama lastiği derdi 👖', 'Pijaması onu sıkıyor diye feryat mı ediyor (oysa üzerinden düşecek kadar bol)? Duyusal hassasiyetleri devrede olabilir. Bekle, sihirli tekerlemeyi okuyayım da genişlesin deyin ve pijamayı genişletiyormuş gibi çekiştirin. Buna inanacak!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'Gözlerimi kapatırsam yok olacağım 👀', 'Gözlerini kırpmamaya çalışıp sulanana kadar direniyor mu? Çocuk zihni bazen açıklanması güç korkular üretebilir. Bak, ben kapattım ve hâlâ buradayım diyerek bu anlamsız korkuyu oyuna dönüştürün.'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'Bana dokunma, sıcak oluyor 🛑', 'Size sarılmayı birdenbire reddetti mi? Alınmayın! Kişisel sınırlarını ve bedeninin yalnızca kendisine ait olduğunu keşfediyor. Bu bir bağımsızlık belirtisidir; siz de gururla uzaktan izleyin.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'Koltuğun altında uyku 🛋️', 'Yatağını reddedip koltuğun altında kıvrılarak mı uyudu? Onu oradan zorla çıkarıp uyandırmayın. Farklı ve korunaklı bir yerde uyumanın keyfini çıkarsın, siz de dinlenin.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'Yastık düzgün değil! 🛏️', 'Yastığı milimetrik biçimde düzeltmek için ağlıyor mu? Mükemmeli arıyor. Kurallarına uyun, yastığı cetvelle ölçülmüş gibi düzeltin ve ışıkları kararlılıkla kapatın.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'Evdeki sessizlik paniği 🚪', 'Ev birdenbire fazlasıyla sessizleşti mi? Aramaya çıktığınızda onu kapının arkasında hayallere dalmış hâlde bulabilirsiniz. Endişelenmeyin; gürültüden uzaklaşıp kendini yeniden dengeliyor. Ona bu zamanı tanıyın.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'Kraker kırıldı derdi 🍪', 'Kraker ikiye bölündü diye kıyamet mi koptu? Onu yeniden yapıştıramazsınız. Bak, şimdi iki tane oldu; biri bana, biri sana diyerek matematiği ve paylaşmayı devreye sokun.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'Dondurma rüyada kaldı 🍦', 'Rüyasında dondurma yerken onu uyandırdığınız için size kızdı mı? Rüya ile gerçek birbirine karışmış olabilir. O kızgın yüzünü kucaklayıp gülümseyin; gerçekliğe dönmesi 2 dakika sürecek.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'Su şişesinin rengi 🚰', 'Gece su istiyor ama kırmızı bardakta olmasını istemiyor mu? Gecenin bir yarısı mantık arayıp ona ders vermeyin. Bardağı hemen değiştirin; enerjinizi sabaha, huzurunuzu da korumaya saklayın.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', 'Ayakkabımın içinde taş var takıntısı 👟', 'Ayakkabısını 10 kez çıkartıp kontrol ettiriyor ama taş yok! Bu senaryo tanıdık geldi mi? Elinize küçük siyah bir tanecik alıp Bak, buldum, kurtulduk deyin ve yürüyüşe devam edin.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'Lapa neden sıcak? 🥣', 'Sıcak olmazsa yemiyor ama şimdi de sıcak diye mi ağlıyor? Tam bir çıkmaz! İçine bilerek renkli bir buz parçası atın; saniyeler içinde ilgisini çekip sakinleşmesini sağlayacaktır.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'Kapının arkasında ağlamak 🚪', 'Kapıyı kapatıp odasında tek başına ağlıyor ve sizi istemiyor mu? Ona zorla sarılmaya çalışmayın. Bazen çocuklar da duygularını yalnız yaşamak ister; ona zaman ve alan tanıyın.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'Kitaptaki kurda öfke 🐺', 'Kitaptaki kurt resmini yumruklayıp azarlıyor mu? Hayal gücü harika! Gerçekliği bozmadan Sen beni korudun, çok cesursun diyerek özgüvenini destekleyin.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'Çorabımı sen giydirme! 🧦', 'Sizin yaptığınız her şeyi kararlılıkla reddediyor mu? Harika! Kıyafetini kanepeye bırakın ve Kim önce giyinecek? yarışını başlatın. Saniyeler içinde kendi başına giyinecek.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'Masanın altındaki felsefe 🤔', 'Masanın altına girip oradan size bir şeyler uydurarak anlatıyor mu? Bırakın o küçük filozof kendi hayal dünyasında kalsın, siz de bu fırsattan yararlanıp dinlenin.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'Yorganın sesi geliyor 🛌', 'Yorganın hışırtısından uyuyamıyormuş! Tuhaf bahaneler zirvede. Üzerini hafif bir battaniyeyle örtün; her şeye bir çare bulduğunuzu görünce pes edecektir.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'Banyo yapma isyanı 🛀', 'Suya girmek istemiyor mu? Küvete farklı renklerde kaplar, hatta plastik mutfak gereçleri atın. Su, bir anda korkutucu bir yer olmaktan çıkıp eğlence merkezine dönüşecektir.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'Ben babayım 👔', 'Sabah babasının büyük ayakkabılarını giyip işe gitmek mi istiyor? Acele etmeyin! Onu kapıya kadar uğurlayın; asansörü görür görmez gülerek geri dönecektir.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', '0 desibel aşkı 🤫', 'Sonunda uyudu! Uygulamadaki Ses Ölçer''i açın ve göstergenin en dibine inen o mutlak sessizliği izleyin. Bu görsel sessizlik, yorgun zihninize adeta spa masajı yapacak.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'Ağaç yaprağını düşürdü 🍂', 'Yerdeki yaprak yüzünden ağaca küsüp onu azarlıyor mu? Doğayla öylesine saf ve komik bir bağı var ki!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'Gölgem benden önce gidiyor 👻', 'Gölgesi önünden gidiyor diye sokakta ağlıyor mu? Onu kucağınıza alın ve “Bak, gölgeler birleşti” deyin. Fiziği açıklamak yerine ona sadece güven verin.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'Babanın tuhaf şakaları 🤡', 'Uyku vakti babası onu güldürüp uykusunu kaçırdı diye kızmayın. O neşeli kahkahalar, çocuğun gün boyunca biriken stresini tamamen sıfırlayacak; bırakın biraz gürültü yapsınlar.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'Yumurta ağlamasın 🍳', 'Yumurtayı kırınca ona acıdı ve yemiyor mu? Empatisi sınırsız. “O şimdi senin kaslarında yaşayacak” gibi sevimli hikâyeler uydurarak durumu kurtarın.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'Fısıltı oyunu 🤫', 'Uyumak istemiyor ve kaçıyor mu? Sesinizi aniden kısarak çok alçak sesle fısıldayın. Sizi duyabilmek için dikkat kesilecek, zihni yorulacak ve 5 dakika içinde uykuya teslim olacaktır.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'Bedeninizin feryadı 🩸', 'Nedensiz gerginliğe ve yorgunluğa teslim olmayın. Regl Takipçisi''ne bakın; bedeniniz size sinyal veriyor. Kendinizi suçlamak yerine Sağlıklı Tarifler''den magnezyum içeren bir atıştırmalık seçip dinlenin.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'Yalnızca kırmızı yiyecekler 🍅', 'Bugün takıntı günü! Yalnızca kırmızı şeyler mi istiyor? Beslenme planına bakın; ona bugün kırmızı domates ve çilek verin. Bırakın bu tuhaf isteği gerçekleşsin, onunla savaşmayın.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'Oyuncağım hastalandı 🩺', 'Oyuncak ayısını hastaneye mi yatırdı? Siz de hasta olun! Kanepeye uzanın, bırakın sizi de 10 dakika boyunca muayene ediyormuş gibi yapsın; bu bahaneyle beliniz biraz dinlensin.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'Benimle uyu ısrarı 🫂', 'Yanında uyumanız için ısrar mı ediyor? Bir günlüğüne kuralları bozun; kokusunu içinize çeke çeke siz de onunla uyuyun. Bu, ikiniz için de sevgi terapisidir.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'Yapay Zekâ, bana yardım et 🤖', 'Çocuğunuzun durmadan felsefi sorular sorması sizi tüketti mi? Anacan AI''a yazın; sizin yerinize 4 yaşındaki bir çocuğa uygun, bilimsel, sabırlı ve sevimli yanıtları hemen hazırlasın.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'Kendimi aynada tanıyamadım 🪞', 'Aynada kendine bakıp yüz ifadelerini değiştirerek kendi kendine kızıyor mu? Benlik algısı ve duyguları şekilleniyor. Onun bu oyunculuğunu sessizce kenardan izleyin.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'Masaldaki benim! 🪄', 'Akıllı masallarda kahramanın adını doğrudan çocuğunuzun adıyla değiştirin. Hikâye boyunca kahramanın nasıl çabucak ve uslu uslu uyuduğunu gördükçe o da motive olup aynısını yapacaktır.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'Marketin ortasında donup kalmayın 🛒', 'Markete girdiniz ve ne alacağınızı unuttunuz mu? Alışveriş listenizi dijital olarak tutmazsanız o kaosun içinde her şeyi unutursunuz. Dijital hafızanıza her zaman güvenin.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'Gece yıldız saymak 🌟', 'Yatak odasının tavanına bakıp hayalî yıldızları mı sayıyor? Bırakın saysın. O hayalî yıldızların sayısı 10''a ulaşana kadar zaten uykusu gelip derin bir uykuya dalacaktır.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'Ellerim ayak oldu 🤸‍♂️', 'Elleri üzerinde yürümeye çalışıp düşüyor mu? Yaratıcı motor gelişimi son sürat devam ediyor! Evin güvenli bir yerinde ona küçük bir parkur kurun, bırakın enerjisini atsın.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'Babanın sessiz gelişi 👨‍🍼', 'Siz masal okumaktan tükendiğiniz anda baba sessizce odaya girip onu okşuyor ve size gidip dinlenmenizi işaret ediyor. Ebeveynliğin tam bir ekip işi olduğunu gösteren anlardan biri.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'Muzu doğru soymadınız 🍌', 'Bahanelerin kralı! Muzu siz soyduğunuz için kıyamet koptu. Yeni bir muz verin; bırakın nasıl istiyorsa, gerekirse ortadan kırarak kendi soysun da bağımsızlık duygusu zedelenmesin.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'Hava çok sıcak isyanı 🧥', 'Montunu sokağın ortasında çıkarıp atıyor, siz de üşümesinden mi korkuyorsunuz? Mücadele etmeyin; gerçekten üşüdüğünde gelip kendisi isteyecektir. Bırakın sonucunu kendisi deneyimlesin.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'Ben bir sandalyeyim 🪑', 'Kendisini bir eşya gibi tanıtıp hareketsiz mi duruyor? Üzerine şaka yollu bir oyuncak koyun ve Ne güzel bir sandalye deyin. Bu tuhaf rolü çok sevecek ve sakin kalacaktır.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'Topluluk bana ne diyor? 💬', 'Her şeyi yanlış yaptığınızı mı düşünüyorsunuz? Anacan Topluluğuna girin, diğer annelerin ele avuca sığmayan çocuklarının hikâyelerini okuyun, derin bir nefes alın ve kendi çocuğunuza şükredin!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'Odayı tamamen karartın 🌙', 'Koridordan sızan ışık yüzünden uyuyamıyor mu? Kusursuzluk arıyor. Kapıyı sıkıca kapatın, odayı tamamen karartın ve melatoninin doğal işini yaparak onu uyutmasına izin verin.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'Görünmez leke derdi 👕', 'Pantolonunda leke arıyor ama hiçbir şey yok mu? Yine o görsel takıntılar. Islak mendille siliyormuş gibi yapıp Uçtu, gitti deyin. Çocuk beyni illüzyonlara çok çabuk inanır.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'Siz uzakta oturun 🛑', 'Yatağının yanında değil, uzakta, kapının önünde oturmanızı mı istiyor? Alınmayın! Bu, onun bağımsızlığa doğru attığı büyük bir adımdır; içinizden sevinmelisiniz.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'Penceredeki kuş benim 🐦', 'Bahçedeki kuşu eve getirmek istiyor ve ağlıyor mu? Doğa sevgisi taşıp taşıyor. Kuşun annesinin onu evde beklediğini söylemek, bu krizi anında huzura dönüştürecektir.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'Gece korkuları başlıyor 👻', 'Yatağın altındaki canavardan mı korkuyor? Boş bir sprey şişesine su doldurun ve sihirli canavar kovucuymuş gibi odaya püskürtün. O korku saniyeler içinde yok olacaktır.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'Dişimi parmağım fırçalasın 🪥', 'Diş fırçasını reddediyor, mutlaka parmağıyla fırçalamak mı istiyor? İtiraz etmeyin; üzerine az miktarda macun sürülmüş temiz bir parmakla da bu işlem yapılabilir. Meseleyi büyütmeyin.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'Gizli çikolata keyfi 🍫', 'Çocuğunuz televizyon izlerken mutfakta ondan gizlice çikolata mı yiyorsunuz? Afiyet olsun! Bunca krize dayanabilmeniz için bu sizin en doğal enerji barınız; kendinizi suçlamayın.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'Ters tişört özgürlüğü 👕', 'Tişörtünü önü arkasına gelecek şekilde giyip gururla dolaşıyor mu? Düzeltmeyin! Özgüveni o kadar yüksek ki, uzaktan izleyip bu özgür ruhlu geleceğin lideriyle gurur duyun.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'Sessizce bakışmak 🥂', 'Çocuk uyudu; siz ve eşiniz kanepede sessizce birbirinize bakıyorsunuz. Hiç konuşmuyorsunuz. Bu sessizlik aslında “Bunu da başardık” demenin en romantik yoludur.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'Rüzgâr beni itti 💨', 'Dışarıda esen rüzgâra sinirlenip ona vurmak mı istiyor? Hava durumu ve giyim aracına önceden baksaydınız belki de hiç dışarı çıkmazdınız. Şimdi bu komediye gülüp eve koşun.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'Yer sanatı 🎨', 'Odanın ortasında kuru makarnalarla resim yapmış ve size gururla mı bakıyor? Temizliği boş verin, ona gülümseyin.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'Babanın uyku getiren masalı 📖', 'Sesiniz yoruldu, masal okumak istemiyor musunuz? Topu babaya atın. Onun farklı, kalın ses tonu ve uydurduğu absürt ayrıntılar çocuğu daha çabuk hipnotize edecek.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'Saçım canımı acıtıyor 🪮', 'Saçını taramak ölümle eş değer mi? Su spreyiyle hafifçe ıslatın, dikkatini ise aynada yaptığınız komik yüz ifadelerine yöneltin. Dikkati dağıldığı anda tarayıp bitirin.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'Bedenim bana ait değil 🔋', 'Bütün gün üzerinize tırmanmasından bedeniniz uyuştu mu? Çocuğu 5 dakika odada tek başına bırakın; kapıyı kapatın, gözlerinizi yumun ve derin bir nefes alın. Yenilenmeniz gerekiyor.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'Bana çocuk deme! 😤', '“Ben büyüdüm” deyip odada size kurallar mı koyuyor? Artık büyüdüğünü kanıtlamaya çalışıyor. Ona “Peki, genç hanım/bey” diyerek bir yetişkin gibi hitap edin ve saygısını kazanın.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'Dijital terapim 🤫', 'Ev halkı uyudu ama zihniniz hâlâ gürültüyle mi dolu? Ses ölçeri açın. Odadaki 0 desibel yazısına bakmak sizi bir psikolog seansından daha çok rahatlatacak, deneyin.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'Oyuncaklarını uyutmak 🧸', 'Kendisi uyumuyor ama oyuncaklarını birer birer yatağa yatırıp üzerlerini mi örtüyor? Bu rol oyunu aslında onu yavaş yavaş, psikolojik olarak kendi uykusuna hazırlıyor; müdahale etmeyin.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'Kapıyı neden siz açtınız? 🚪', 'Kapıyı siz açtığınız için ağlayıp kendisi açabilsin diye yeniden kapatmanızı mı istiyor? Bırakın 1 dakikanızı alsın; böylece evde kopacak 20 dakikalık isyanı ve çığlıkları huzur içinde önleyin.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'Sadece yeşil renk! 🥦', 'Tabağında yalnızca yeşil şeyler mi arıyor? Beslenme planına bakın, yeşilliklerden sevimli şekillerde yeşil sebze topları yapmayı öğrenin ve bu tuhaf takıntısını doyurun.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'Gökyüzü nereye gitti? ☁️', 'Sisli havada sorduğu ani felsefi soru zihninizi mi dondurdu? “Üşümesin diye bulutlar üzerini örttü” deyin. Zihni henüz bilimsel açıklamaya hazır değil; sadece bir masal istiyor.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'Marketin ortasında koşmak 🛒', 'Kasanın önünde birden koşup rafların arkasına mı saklanıyor? Alışveriş listenizi dijital olarak tutun ki böyle panik anlarında almadıklarınızı unutup eve eli boş dönmeyin.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'Fısıltı oyunu 🤫', 'Bağırarak koşuyor ve uyumak istemiyor mu? Birden sesinizi tamamen kısın. Çok alçak sesle fısıldayarak konuşmaya başlayın. Sizi duyabilmek için dikkatini toplayacak ve uykusu gelecek.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'Mükemmel bir anne değilim 🛑', 'Bugün her şey altüst oldu ve bağırdınız mı? Kendinizi köşeye sıkıştırmayın. Duygu günlüğünüze sadece şunu yazın: Bugün kötü geçti ama ben iyi bir anneyim ve yarın yeniden deneyeceğim.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'Yağmur sesli masal 🌧️', 'Sesiniz çıkmıyor, masal okumaya hâliniz mi yok? Akıllı masallarda arka plan sesi olarak yalnızca yağmur ve orman sesini açın. Doğanın bu dinginliği bazen en güzel masaldan bile daha çabuk uykuya daldırır.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'Elimi tutma! 🚶‍♂️', 'Yolda elinizi bırakıp kendi başına yürümek mi istiyor? Güvenli bir alandaysanız bağımsızlığını denemesine izin verin; siz de yalnızca iki adım geriden onu gururla izleyin.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'Ekmeğin kenarları düşman 🍞', 'Ortasını yiyip kenarlarını kararlılıkla atıyor mu? Kabuklarla savaşmayın. Hayvan figürlü kalıplarla kesip kabuksuz şekiller hazırlayın; bırakın bu mutfak tasarımının tadını çıkarsın.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'Evden çıkmak istemiyor ⛅', 'Dört duvar sizi bunaltıyor ama o ağlayıp dışarı çıkmak istemiyor mu? Hava ve giyim aracına güvenip gerekirse biraz ısrar ederek dışarı çıkarın. Temiz havayı içine çektiği anda evde biriken tüm o öfke saniyeler içinde uçup gidecek.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'Babasıyla pijama güreşi 🤼‍♂️', 'Uyumak istemiyor mu? Babası oyun olsun diye onu duvara yaslayıp yenebilir. Terleyip kalan tüm enerjisini orada harcayacak ve koşarak yatağa girecek.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'Topluluktan güç almak 💬', 'Sabrınız tükendiğinde Anacan Topluluğuna girin. Oradaki annelerin de aynı kaosu yaşadığını görünce içinizi büyük bir rahatlama ve yalnız olmadığınız hissi kaplayacak.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'Bunu da başardık! 🚀', 'Ev uykuya daldı. Gelecek ayın yeni kaoslarına hazırsınız; siz bu işin ustasısınız. Işıkları kapatın ve bugün yarattığınız tüm o küçük mucizeler için kendinize teşekkür edin.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'O gölge benim 👻', 'Kendi gölgesini sahiplenip onunla konuşuyor ve ona talimatlar mı veriyor? Hayal gücü sınırsız.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'Asfalttaki çizgiler kanundur 🛣️', 'Sokakta yürürken taşların arasındaki çizgilere basmamak için tuhaf hareketler mi yapıyor? Kaba motor becerileri ve dikkati aynı anda çalışıyor. Acele ettirmeyin, elinden tutun ve siz de o çizgilerin üzerinden atlayın.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'Suyun aktığı delik korkusu 🛁', 'Küvetten çıkarken suyun aktığı delikten mi korkuyor? Hayal gücü bazen akıl almaz şekilde çalışır. Oraya plastik bir oyuncak gemi koyup Bak, bu bir koruyucu, hiçbir şeyi içine çekmeyecek deyin. Korkusu bir anda oyuna dönüşecek.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'Sabah saat 6''da başlayan konser 🎤', 'Gözünü açar açmaz avazı çıktığı kadar uydurma bir şarkı mı söylüyor? Sus, komşular uyanacak diyerek o çılgın enerjiyi kesmeyin. Siz de ona katılın. Sabaha şarkıyla başlayan çocuk gün boyunca daha az hırçın olur.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'Sessizliğin 0 desibellik dansı 🤫', 'Sonunda oda karanlık ve uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız uğulduyor. Uygulamada Ses ölçeri açın. Ekrandaki değerin 0 desibele düşmesini izlemek, gürültüden şişen beyniniz için gerçek bir dijital masajdır.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'Oyuncağım size küstü 🧸', 'Siz bağırdığınız için yanınıza gelip Ayıcığım size küstü mü dedi? Kendi duygularını nesnelere yükleyerek size anlatıyor. Ayıcıktan son derece ciddi bir şekilde özür dileyin ve ona sarılın. Çocuğunuzun nasıl rahatladığını göreceksiniz.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'Çay neden buharlaşıyor? ☕', 'Fincanınızdan çıkan buhara bakıp sizden açıklama mı istiyor ya da korkuyor mu? Bilimsel bir açıklama yapamıyor musunuz? Anacan AI''dan 4 yaşındaki bir çocuk için felsefi ve sevimli bir açıklama alın: Bulutlara katılmak için uçuyor.'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'Listeye gizli saldırı 🛒', 'Markete gitmeden önce uygulamadaki Alışveriş listesini açtınız ve listede 5 tane çikolata yazdığını mı gördünüz? Evet, telefonunuza sızmayı ve dijital dünyayı taklit etmeyi çoktan öğrendi.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'Bütün elma dramı 🍏', 'Elmayı dilimlediğiniz için odada kıyamet mi koptu? Ben onu bütün istiyordum! diyerek ağlıyor. Mantık aramayın. Dilimleri birbirine yapıştırıp Bak, yeniden düzelttim deyin ve bu anlamsız dramdan diplomatik bir şekilde sıyrılın.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'Babanın uydurduğu kahraman 🦸‍♂️', 'Sesiniz çıkmıyor, kitap okuyacak hâliniz yok mu? Görevi babaya devredin. Baba, başkahramanı çocuğunuzun olduğu, tamamen uydurma ve mantıksız bir hikâye anlatsın. Siz sadece kanepeye uzanın ve odadan gelen kahkahaları dinleyin.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'Ters giyilen çorap inadı 🧦', 'Çorabın topuk kısmını ayağının üstüne getirerek giydi ve düzeltmenize kesinlikle izin vermiyor mu? Öyle kalsın. Onun “Bunu ben başardım” diyen gururu, çorabı doğru giymesinden milyon kat daha değerlidir.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'Bir yudum daha su bahanesi 💧', 'Tam uykuya dalacakken “Çok susadım” diyerek yataktan fırlıyor mu? Amacı su içmek değil, sizinle biraz daha vakit geçirmektir. Yatağının yanına önceden dökülmeyen bir suluk koyarak bu meşhur oyunun önüne baştan geçin.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'Yoruldum ama söylemiyorum 📝', 'Bugün ne kadar gerildiğinizi kimse görmüyor ve herkese gülümsemek sizi bunaltıyor mu? Duygu günlüğünüzü açın. İçinizdeki tüm o zehri ve öfkeyi ekrana dökün. Dijital olarak içinizi boşaltmak, sizi psikologdan daha hızlı iyileştirecek.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'Mont savaşı 🧥', 'Dışarıda güneş var ama montunu giymek istemiyor. Pencereden bakıp aldanmayın; Hava ve kıyafet aracındaki gerçek sıcaklığı ve kat kat giyinmiş çocuk görselini ona gösterin. Kural koyma işini telefona bırakın.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'Kuş neden bana bakmadı? 🐦', 'Parkta bir güvercin uçup gitti diye hıçkıra hıçkıra ağladı mı? Bu durumda mantık aramayın. Bu, onun için gerçekten büyük bir hayal kırıklığıdır. “O da seni çok özleyecek” diyerek duygusunu sevgiyle kabul edin.'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'Masalda benim adım olsun 🪄', 'Klasik kitaplardaki kahramanlardan sıkıldı mı? Akıllı masallarda kahramanın adını çocuğunuzun adıyla değiştirin. Kendisinin nasıl cesurca uyuduğunu duyunca, odasında hiç itiraz etmeden uykuya teslim olacak.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'Ben bugün arabayım 🚗', 'Sabah size “Ben çocuk değilim, arabayım” mı diyor? Kural koymayın. “O zaman hızlı gidebilmen için benzinini (lapanı) dolduralım” deyin. Bu komik rol oyunları, bağırmaktan çok daha kolaydır.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'Kumdan yapılan pasta 🏖️', 'Parkta suyla toprağı karıştırıp üstünü başını çamur ederek size pasta mı hazırladı? Temizliği boş verin. Bu, ince motor becerisi ve yaratıcılıktır.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'Göz kırpmama yarışması 👀', 'Uyumak istemiyor ve gözlerini bilerek kocaman açıp size mi bakıyor? “Gözlerini ilk kapatan kaybeder” oyununu oynayın. Gözleri sulanıp zaten yorulacak ve 2 dakika içinde kendiliğinden kapanacak. Deneyin ve görün!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'Yataktaki gizli oyuncaklar 🧸', 'Yatağına girdiğinizde altından 3 tane sert oyuncak araba mı çıktı? Onları korumak için birlikte uyuyor. Endişelenmeyin; uykuya daldıktan 10 dakika sonra canını acıtabilecek o oyuncakları gizlice çıkarıp rahatça uyumasını sağlayabilirsiniz.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'Toplulukta sessiz teselli 💬', 'Çok yoruldunuz ve biriyle dertleşmek bile istemiyor musunuz? Anacan Topluluğuna girip sadece okuyucu olun. Diğer annelerin aynı absürt krizlerle nasıl başa çıktığını görmek, size en güçlü sessiz teselliyi verecek.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'Yanlış kaşık krizi 🥄', 'Çorbayı büyük kaşıkla verdiniz diye neredeyse kıyamet mi koptu? 4 yaş civarında yiyecek aynı olsa bile nesnenin fiziksel boyutu, çocuğunuzun zihninde yemeğin tadını değiştirir. Tartışmayın, kaşığı hemen değiştirin ve enerjinizi koruyun.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'Sessizce kanepeye çökme anı 🥂', 'Çocuk uyudu, ev toplandı. Eşinizle kanepede yan yana oturun, televizyonu bile açmayın. Sadece birbirinize “Bunu da başardık, hayatta kaldık” bakışı atın. İnanın, ebeveynliğin en romantik ve gerçek anı tam da budur.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'Yeşil renk sevgisi 🥦', 'Tabağında yalnızca yeşil şeyler arıyor ve diğer renkleri itiyor mu? Sağlıklı tariflere göz atın, yeşilliklerden sevimli şekillerde yeşil sebze topları yapmayı öğrenin.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'Kapıyı neden siz kapattınız? 🚪', 'Evden çıkarken kapıyı siz kapattınız diye feryadı bastı ve yeniden açtırdı mı? Kontrol hissi, onun en büyük ihtiyacıdır. Size 1 dakika kaybettirmesine izin verin ama sokakta yaşanacak 30 dakikalık ağlama krizini önleyin.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'Aynadaki o çocuk kim? 🪞', 'Aynanın karşısında durup kendi kendine kaşlarını çatıyor, öfkeli ve tuhaf mimikler mi yapıyor? Duyguların yüzünde nasıl göründüğünü keşfediyor. Bu minyatür tiyatro oyuncusunun provasını hiç ses çıkarmadan, keyifle izleyin.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'Işıkları söndür, gölgeyi bul 🔦', 'Karanlıktan korkuyor ve yatağa gitmiyor mu? Odanın ışıklarını tamamen söndürüp küçük bir el feneri yakın. Ellerinizle duvarda köpek ve kuş gölgeleri oluşturun. Korkutucu karanlığı onun için bir tiyatroya dönüştürün; böylece uykuya dalması kolaylaşır.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'Duvara çizilen şaheser 🖍️', 'Birkaç saniyelik sessizliğin ardından onu keçeli kalemle duvara bir sanat eseri çizerken mi buldunuz? Derin bir nefes alın. İnce motor becerileri gelişiyor, duvar ise nasıl olsa temizlenir. Bu şaheseri silmeden önce mutlaka fotoğrafını çekin.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'Babanın sırtında atçılık 🐴', 'Enerjisini tam olarak atamadı ve yatağa gitmemek için direniyor mu? Babayı yardıma çağırın. Babası onu sırtına alıp at gibi koşturduğunda kahkahalar odayı doldurur, biriken fiziksel gerginlik de saniyeler içinde terle birlikte yok olur.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'Tuvalete 5 dakikalık kaçış 🚪', 'Gürültü beyninizi deliyor ve her şeye bağırmak mı istiyorsunuz? Onu güvenli bir yere bırakıp tuvalete girin ve kapıyı kapatın. Sadece 5 dakika boyunca duvara bakın, hiçbir şey yapmayın. Bu kısa sessizlik yeniden kendiniz gibi hissetmenizi sağlayacak.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'Lapa çok yuvarlak 🥣', 'Yemeğin şekline kızıp yemeyi mi reddediyor? Mantık aramadan lapayı kaşıkla karıştırın ve “Bak, düzelttim” deyin. İllüzyon sanatı annelikte her zaman işinize yarayacak.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'Mantıksız gözyaşları 😭', 'Parktan dönerken yolda bir taşı tekmeleyemedi diye kıyamet mi koptu? Bunun mantıklı bir nedeni yok; sadece yorgun. Tartışmayın, onu kucağınıza alın, duygusunu kabul edin ve dikkatini başka bir yöne çekin.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'Fısıltılı masal sırları 🤫', 'Yataktan kaçmak için bahaneler mi uyduruyor? Sesinizi iyice alçaltın ve yalnızca fısıltıyla konuşmaya başlayın. Sizi anlayabilmek için dikkatini toplamak zorunda kalacak ve beyni kısa sürede uykuya geçecektir.'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'Sesimi neden kestin? 🎶', 'Arka planda çalan çocuk şarkısına mırıldanarak eşlik ettiniz ve o hemen “Sen söyleme!” diye mi bağırdı? Odanın tek solisti o; vokal denemeleriniz sahnesini daraltıyor. Alınmayın, sahneyi bu küçük egoiste bırakın.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'Kıyafetini kendi seçiyor 👗', 'Kırmızı pantolon, spor ayakkabı ve kışlık bere... Üstelik parka böyle gideceği konusunda ısrar ediyor. Başkalarının ne diyeceğini boş verin. Kendi seçimiyle dışarı çıkmasına izin verin; bu özgürlük onun için estetikten daha önemlidir.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'Zamanlayıcıyla uyku anlaşması ⏱️', 'Uyku vakti gelince aniden susuyor ya da duvarla vedalaşmaya mı başlıyor? Bir zamanlayıcı kurun. Alarm çaldığında herkesin uyuyacağı kuralını koyun. Dışarıdan gelen bir otoriteyi kabul etmek çocuklara her zaman daha kolay gelir.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'Ay neden hâlâ gitmedi? 🌙', 'Sabah gökyüzünde Ay''ı görüp “Ay neden uyumamış?” diye mi sordu? Bilimsel terimlerle zihnini yormayın. Anacan AI''ı açın; yaşına uygun o tatlı astronomi masalını bulup ona okuyun ve merakını giderin.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'Ekmeğin yalnızca kenarı yeniyor 🍞', 'Ekmeğin yalnızca kabuğunu yiyip içini mi bırakıyor? Tersine işleyen beslenme anlayışları size de tanıdık geliyor. Kabuklar için savaşmayın. Beslenme planında ekmeği kalıplarla keserek ona nasıl farklı kabuklar oluşturabileceğinizi öğrenin.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'Melatonin için karanlık 🌌', 'Uykuya dalmasını kolaylaştırmak için yatmadan 1 saat önce odadaki tüm televizyon ve telefon ekranlarını kapatın. Melatonin (uyku hormonu) karanlık ortamda daha kolay salgılanır; doğal sürece güvenin.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'Oyuncaklar neden uyumuyor? 🧸', 'Kendisi uyumuyor ama bütün oyuncaklarını tek tek yatağa yatırıp üzerlerini mi örtüyor? Bu rol oyunu aslında onu yavaş yavaş, psikolojik olarak kendi uykusuna hazırlıyor; kesinlikle müdahale etmeyin.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'Sadece kokusunu içinize çekin 🫂', 'Bugün sizi gerçekten çileden çıkardı, tüm enerjinizi tüketti mi? Ama yatağında öyle masum uyuyor ki... Işıkları söndürün. Yanına uzanıp o tertemiz çocuk kokusunu derin derin içinize çekin ve karanlıkta ona sevginizi fısıldayın.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'Marketin ortasında donakalmak 🛒', 'Markete girdiniz ve ne alacağınızı unuttunuz mu? Alışveriş listenizi dijital olarak tutmazsanız o karmaşada her şeyi unutursunuz. Eve eli boş dönmemek için uygulamadaki dijital hafızanıza her zaman güvenin.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'Sen benimle oynamıyorsun! 😤', 'Siz yemeği karıştırırken gelip yüzünüzü elleriyle kendine çeviriyor: Bana bak!? Haklı. Fiziksel olarak yanında olmanızı değil, tüm dikkatinizi istiyor. İşinizi bırakın ve sadece 2 dakika boyunca göz teması kurarak onu dinleyin.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'Yağmur sesli oda 🌧️', 'Sesiniz çıkmıyor, masal okumaya gücünüz mü yok? Akıllı masallarda arka plan sesi olarak yalnızca yağmur ve orman seslerini açın. Doğanın bu tekdüze sakinliği bazen en güzel hikâyeden bile daha hızlı uykuya dalmasını sağlar.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'Kendi uydurduğu isimle çağrılmak 🦇', 'Sabah uyanıp kendi adını reddederek Bana Batman de diye mi tutturdu? Uyum sağlayın! 5 dakika boyunca Buyur Batman, mamanı ye diyerek odadaki gerginliği anında komediye dönüştürün.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Instagram annelerinden yorulmak 📱', 'Instagram''ı açar açmaz herkesin mükemmel çocuğunu görüp moralinizi bozmayın! O uygulamayı kapatın ve Anacan Topluluğu''na girin. Herkesin evinin sizinki gibi darmadağın olduğunu görünce derin bir nefes alın; yalnız değilsiniz.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'Tüm stresi suyla yıkamak 🛀', 'Bazen hiçbir şey işe yaramaz, o sadece her şeye ağlar. Onu ılık su dolu küvete koyun. Suyun o gizemli, gerginliği çekip alan mıknatıs etkisi hem tüm odaya hem de sinir sistemine anında büyük bir huzur getirecektir.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'Git, seni istemiyorum 💔', 'İsteğini reddettiğiniz için size Kötü annesin, git! mi dedi? Kalbiniz sızladı. Ancak o henüz öfkesini kelimelere dökemiyor; aslında Hayal kırıklığına uğradım diyor. Üzerinize alınmayın, sadece sevgiyle sarılın.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'Görünmez arkadaşla çay saati 🫖', 'Odanın köşesindeki boşluğa çay doldurup gülüyor mu? Hayalî arkadaş dönemi başlıyor!'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'Babasının yanlış okuduğu masal 📖', 'Bu akşam masal kitabını babasına verin. Babası hikâyeyi bilerek ters, komik ve saçma bir şekilde anlatsın. Çocuğunuzun onu düzeltmekten nasıl keyif aldığını ve kahkahalar attığını siz de kenardan neşeyle izleyin.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'Sabah erkenden kovalamaca 🏃‍♂️', 'Sabah saat 7''de kanepelerin üzerinde mi koşuyor? Bağırmayın. İşlerinizi 2 dakikalığına bırakıp siz de zıplayarak ona katılın. Çocuğunuzun hayal dünyasına katılmak aslında sizin için de sıra dışı bir stres atma yöntemidir.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'Ani kekeleme paniği 🤖', 'Çocuğunuzun aniden kekelemeye başlaması internette hastalıkları araştırmanıza mı neden oldu? Durun! Anacan AI''dan bunun 4 yaş gelişim sıçraması olduğunu öğrenip paniğinizi yatıştırın.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'Sessizliğin ekrandaki rakamı 📉', 'Sonunda uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız mı çınlıyor? Uygulamadaki Ses ölçeri açın. O 0 desibel yazısına bakmak, yorgun ve gürültüden şişmiş beyniniz için dünyanın en iyi görsel masajı olacak.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'Muzu sen soydun kavgası 🍌', 'Muzu siz soydunuz diye odada kıyamet mi koptu? Bu yaşın altın kuralı: Her şeye o karar vermeli. Muzu tekrar kabuğuna yapıştıramazsınız; yeni bir muz verin, istediği gibi kendisi soysun ve bağımsızlık duygusu zedelenmesin.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'Kaldırım kenarında ip cambazlığı 🧱', 'Parka giderken düz yoldan değil de mutlaka kaldırımın en dar kenarından mı yürümek istiyor? Kolundan tutarak güvenliğini sağlayın ve bu küçük zirveyi fethetmesine izin verin. Dengesi ve özgüveni aynı anda harika bir şekilde gelişir.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'Kendinize zaman ayırmak suç değil 🥗', 'Onu doyurmak için farklı menüler hazırladınız, peki siz ne yediniz? Sağlıklı tariflerde anneler için yer alan o kolay 5 dakikalık salatayı yapın ve artık kendinizi de şarj etmeyi unutmayın.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'Birbirine sessizce bakmak 🥂', 'Çocuk uyudu. Siz ve eşiniz kanepede sessizce birbirinize bakıyorsunuz. Hiçbir şey söylemiyorsunuz. Bu sessizlik aslında Bunu da başardık, harika bir ekibiz demenin en romantik ve samimi yoludur.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'Montu reddetmek 🧥', 'Dışarıda güneş var diye kışlık montunu giymek istemiyor mu? Hava durumu ve kıyafet bölümünü açıp telefondaki kışlık giyinmiş çocuk simgesini gösterin. Kuralı dijital ekrana bırakıp aradan çekilin; sakince giyinecektir.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'Karanlıkta fısıltıyla dertleşmek 🌙', 'Odanın ışıklarını tamamen kapatın. Yanına uzanıp gün içinde yaşananları ya da onun karakterinde en sevdiğiniz özelliği çok alçak sesle kulağına fısıldayın. Fısıltı, beyni uykuya hazırlayan en gizemli yöntemlerden biridir.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', 'Bu benim hatam değil yalanı 🤥', 'Suyu bilerek yere döktüğü hâlde parmağıyla arabasını gösterip O itti mi dedi? Bu, yalan söylemek değil, bir savunma mekanizmasıdır. Gel, o arabaya da nasıl temizleneceğini öğretelim diyerek zihnini ustaca başka yöne çekin.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'Parkta kaydırak diplomasisi 🤝', 'Kaydırakta başka bir çocuğu itip kendisi kaymak mı istedi? Utandığınız için çocuğunuza vurmayın. Şimdi onun sırası, sonra sen diyerek kuralı yumuşak ama kararlı bir sesle hatırlatın. Sosyal kuralları böyle öğrenecektir.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'Yumurta ağlamasın 🍳', 'Yumurtayı kırınca ona acıdığı için yemiyor mu? Empatisi sınırsız. O şimdi kaslarında yaşayacak ve seni güçlendirecek gibi sevimli hikâyelerle durumu hemen kurtarın.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1'::uuid, 'Yastıkların diziliş kuralı 🛏️', 'Yastığı milimetrik şekilde düzeltmek için ağlıyor mu? Uyku takıntıları oluşmuş olabilir. Kurallarına uyun, yastığı cetvelle ölçülmüş gibi düzeltin ve ışıkları kararlılıkla kapatarak ona güven verin.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'Attığım çöpü geri ver! 🗑️', 'Sakladığı o eski çikolata ambalajını çöpe attınız diye kıyamet mi koptu? Sizin için çöp, onun için hazinedir. Dikkatini başka, parlak bir oyuncağa yönlendirin.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'Evin diktatörü sofrada 👑', 'Kahvaltıda Siz oraya değil, buraya oturun diyerek sofrayı mı yönetiyor? İradesini sertçe kırmadan, Peki, senin dediğin gibi olsun diyerek dengeyi ve evdeki huzuru küçük bir gülümsemeyle koruyun.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'Kimseye hiçbir şey açıklamamak 📝', 'Kimse evde ne kadar yorulduğunuzu görmüyor ve bu sizi çileden mi çıkarıyor? Duygu günlüğünüzü açın. Bugün sizi çıldırtan ne varsa hepsini oraya yazın. Duygularınızı kabul edip yazıya dökmek size daha fazla yardımcı olacaktır.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'Sessiz okuma saati 📖', 'Bu akşam okumak yok. Akıllı masallardan hafif bir fon müziği açın ve yalnızca resimlere sessizce bakın. Beyni görsel olarak yorulacak ve siz tek kelime etmeden uykuya teslim olacaktır.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'Market kasasındaki sınav 🛒', 'Kasanın hemen önünde çikolata için bağırıyor mu? Arkanızdakilerin bakışlarına rağmen pes etmeyin. Alışveriş listesini açıp Burada yok, kasa bunu okumaz deyin. Siz kararlı olursanız o da geri adım atacaktır.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'Elleriyle değil, ağzıyla yemek 🐶', 'Tabaktan ellerini kullanmadan kedi gibi yemek mi istiyor? Yasak koymayın. Mutfak zaten kirlenecek; bırakın 5 dakika boyunca kedi olsun. Bu komik rol oyunu, iştahsızlığı gidermenin en eğlenceli yoludur.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'Babadan omuz masajı 💆‍♂️', 'Bugün uzun süre ayakta kaldınız; onun peşinden koşmaktan ve yerden oyuncak toplamaktan beliniz kopacak gibi. Çocuk uyur uyumaz eşinizden 10 dakikalık omuz masajı isteyin. Siz evin motorusunuz, mutlaka dinlenip toparlanmalısınız.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'Odanın tamamen karanlık olması 🌌', 'Koridordan sızan ışık yüzünden uyuyamıyor mu? Kusursuzluk arıyor. Kapıyı sıkıca kapatın, odayı tamamen karartın ve melatoninin doğal görevini yaparak onu hızla uykuya geçirmesine izin verin.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'O benim krizi 🧸', 'Evdeki kumandaya sarılıp Bu benim! mi diyor? Mülkiyet sınırlarını test ediyor. Ona bencil demeyin; Benim için bulduğun için teşekkür ederim deyip dikkatini başka bir oyuna yönlendirerek kumandayı geri alın.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'Yarım kalan cümlelerin anlamı 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaret edip sizin bulmanızı mı bekliyor? Cümlesini sabırla tamamladığınızda yüzündeki rahatlamayı izleyin. Kelime dağarcığını ve öz güvenini tam da sizin desteğinizle böyle geliştirir.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'Mutfakta yardım felaketi 🧑‍🍳', 'Siz hamur açarken gelip sandalyesini koydu ve unu mutlaka kendisi dökmek mi istedi? İzin vermezseniz ağlayacak. Ona küçük plastik bir kap ve biraz un verin. Mutfak batacak ama egosu tatmin olacak.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'Ay önümüzden koşuyor 🌕', 'Akşamüstü arabayla dönerken pencereden bakıp Ay''ın bizi takip ettiğini mi söylüyor? Evrenin onun etrafında döndüğünü düşünüyor. Bu hayal gücünü bozmadan, “Acaba bizimle nereye geliyor?” diyerek oyuna katılın.'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'Kirli tişört aşkı 👕', '3 gündür aynı tişörtü giyiyor ve yıkamanıza izin vermiyor mu? Bu yaşlarda bazı eşyalar onlara güven verir. Tartışmayın; “Tişörtünü çamaşır makinesinde sihirli bir maceraya gönderdim, güçlenip geri dönecek” diyerek küçük bir masalla elinden alın. Bu hayale inanacak.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'Karınca için yas töreni 🐜', 'Parkta yerdeki karıncayı gördüğü için kıpırdamıyor, onun kaybolduğunu düşünüp ağlıyor mu? Empatisi sınır tanımıyor. “Annesi birazdan gelip onu götürecek” deyin.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'Bataklıktaki beyaz gürültü 🌊', 'Odasında uyumak yerine oradan oraya mı zıplıyor? Ses ölçerin arka planından güçlü bir deniz dalgası veya beyaz gürültü sesi açın. O monoton frekans, beynindeki o çılgın enerjiyi alıp götürecek; 10 dakika içinde gözleri kapanacak.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'Süpürgeyle felaket yardımı 🧹', 'Siz evi toplarken gelip “Ben yapacağım” diyerek çöpleri odanın her yanına mı yayıyor? İzin vermezseniz kıyamet kopacak. Eline nemli bir mendil verip “Sen sadece masanın bu köşesinden sorumlusun” deyin. Hem siz işinizi yapın hem de onun egosu doysun.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'Boş duvara bakma saati 🛋️', 'Odasında tek başına mı oynuyor? Ne olur, o anı gidip bulaşık yıkayarak harcamayın! Kanepeye geçin, çayınızı elinize alın ve sadece duvara bakın. Evet, hiçbir şey düşünmeden. Duygu günlüğünüze 5 dakikalık huzur yazın. Buna ihtiyacınız var.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', 'Saçım kırıldı! dramı 🪮', 'Tarağı görür görmez saçının acıdığını söyleyip kaçıyor mu? Duyusal hassasiyeti onu korkutuyor. Dikkatini dağıtın. Eline bir ayna verip “Bakalım aynada kim daha komik dil çıkaracak?” deyin; dikkati dağılmışken saçlarını saniyeler içinde tarayıp bitirin.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'Ani felsefe atağı 🤔', 'Birden “Denizin dibi neden karanlık?” diye bilimsel bir soru mu sordu? Terlemeyin! Anacan AI''ı açın; bu yaştaki bir çocuğun anlayabileceği en tatlı, pediatrist ve psikolog onaylı masalsı yanıtı alın ve ona okuyun. Siz her zaman her şeyi bilen annesiniz!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'Karanlık odada yakalamaca 🔦', 'Uyku vakti geldi ama enerjisi hâlâ bitmedi mi? Odadaki bütün ışıkları kapatın. Elinize küçük bir fener alın ve “Bakalım ışık duvarda kimi yakalayacak?” oyunu oynayın. Karanlıkta oynamak hem melatonin salgılanmasını hızlandıracak hem de onu yoracak.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'Görünmez yaranın acısı 🩹', 'Parmağında hiçbir şey yok ama kanadığını söyleyip ağlıyor ve yara bandı mı istiyor? Bu fiziksel bir acı değil; sizden gelecek şefkate ihtiyacı var. O bandı yapıştırın, öpün ve “Sihirli öpücükle iyileştirdim” deyin. Gününüz böylece kurtulacak.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'Kapıyı kapatmak ve kişisel alan 🚪', 'Odasına girip kapıyı arkasından kapattı ve “Gelme” mi dedi? Alınmayın. Sadece kendini gürültüden ve karmaşadan soyutlayıp dinlenmek istiyor. Güvenliği sağlanmışsa kişisel alanının tadını çıkarmasına izin verin. Büyüyor!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'Gecenin bitmek bilmeyen bahaneleri 🚰', 'Gözleri kapanıyor ama birden “Ayağım kaşındı”, “Su istiyorum” diyerek yerinden mi sıçrıyor? Uyku erteleme konusunda profesör olmuş. Zamanlayıcı kurun. “Telefon çalınca bütün bahaneler uyur” deyin. Otoriteyi telefona devredin, siz aradan çekilin.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'Benim adım sen değilsin 📛', '“Bana adımla seslenme, ben Örümcek Adam''ım” mı diyor? Bu bir kimlik arayışı. Uyum sağlayın! Kahvaltısını “Buyurun Bay Örümcek” diyerek verin. Odadaki gerginliği saniyeler içinde komediye dönüştürmek sizin elinizde.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'Markette liste şantajı 🛒', 'Kasanın önünde birden şeker mi istedi? Etraftakilerin “Nasıl anne?” der gibi bakışlarını kesinlikle umursamayın. Alışveriş listesini açıp “Listede yok, kasa bunu bize satmaz” deyin ve kararlı durun.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'Boyalar duvara taştı 🖍️', 'Odaya girdiniz ve duvarda yeni bir fresk mi gördünüz? Derin bir nefes alın. O, kâğıdın sınırlarını aşarak motor becerilerini büyük ölçekte deniyor. Silmeden önce bu şaheserin mutlaka fotoğrafını çekin; gelecekte ona gösterip birlikte gülersiniz.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'Suyu kurutma isteği 💧', 'Bardaktaki suyu içmek yerine Bu çok ıslak, bunu kurut diye bağırıyor mu? Mantık aramadan suyu başka renkte bir bardağa dökün ve Kuru su getirdim deyin. İllüzyon sanatı, annelikteki en güçlü silahınızdır.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'Doğaya kaçış şart ⛅', 'Dört duvar arasında enerjisi öfkeye dönüşüyor ve her cümlesi hayırla mı başlıyor? Havaya ve kıyafetlerinize güvenip onu mutlaka dışarı çıkarın. Toprağa dokunmak, sinir sistemini hemen sıfırlayacaktır.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'Zil sesiyle otomatik uyku ⏱️', 'Uyku vakti geldiğinde aniden tuvalete gitmek mi istiyor? Bir zamanlayıcı kurun. Zil çalınca herkes ışıkları kapatır kuralını uygulayarak bu sonsuz vedadan ve ustaca manipülasyondan tartışmadan kurtulun.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'Perde arkasında saklambaç 🙈', 'Kreşe geç kalıyorsunuz ama o perdenin arkasına saklanıp Beni bul! mu diyor? Bağırmak süreci uzatır. Acaba benim bebeğim nerede? deyip 2 dakikalığına oyuna katılın ve onu oradan gülerek çıkarın.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'Akıllı masalda farklı ses efektleri 🪄', 'Akıllı masalları açın. Hikâyeyi okurken kapı gıcırtısı, rüzgâr sesi ve fısıltılar çıkararak odada bir ses tiyatrosu kurun. Bu sıra dışı sesler, onun dikkatini anında masalın içine çekecektir.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'Ekran molasında vicdan azabı 📺', 'Bugün çok işiniz olduğu için televizyon karşısında fazla mı kaldı? İçinizi vicdan azabı mı kemiriyor? Her gün mükemmel olamazsınız. Bazen ekranlar, bizi büyük kaoslardan kurtaran en masum bakıcıdır; rahat olun.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'Kendi eserini yırtan ressam 🖍️', 'Çizdiği çizgiyi beğenmeyip Bu kötü oldu diyerek kâğıdı yırtıp atıyor mu? Öz eleştiri ve mükemmeliyetçilik duygusu gelişiyor! Bir dahaki sefere farklı bir renk deneyelim diyerek hayal kırıklığını keşfe dönüştürün.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'Kedi gibi sürtünmek 🐾', 'Bu sabah dört ayak üzerinde yürüyor, bacağınıza sürtünüyor ve sadece miyav mı diyor? Ona kuralları anlatmak yerine siz de hayalî bir süt kabı uzatın. Oyun oynamak, azarlamaktan her zaman daha kolay ve eğlencelidir.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'Küvetteki mini laboratuvar 🛀', 'Suya farklı renklerde sabunlar katıp iksir mi hazırlıyor? Banyo kirleniyor, evet. Ama o, çözücüleri öğreniyor. Bu bilimsel keşif, akşamın yorgunluğunu giderip onu huzurlu bir uykuya hazırlayan en güzel araçtır.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'Sen kimsin? oyunu 🎭', 'Size yabancı biriymişsiniz gibi bakıp Sen kimsin? Annem nerede? mi diyor? Bu yeni bir rol yapma oyunudur. Ben doktor teyzenim, kalbini dinlemeye geldim deyin ve onu gıdıklayın. Bırakın sabah oda kahkahalarla çınlasın.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'Tuvalet kâğıdı sanatı 🧻', 'Odaya girdiğinizde tüm tuvalet kâğıdının açılıp eve yayıldığını mı gördünüz? Sinirlenmek yerine kâğıtları toplayıp birlikte bir top yapın. Kaosu bağırarak değil, yaratıcılık ve kahkahayla alt edin.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'Sessizliğin verdiği haz 🤫', 'Sonunda uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız mı çınlıyor? Uygulamadaki Ses ölçeri açın. O 0 desibel yazısına bakmak, gürültüden yorulup şişen beyniniz için dünyanın en iyi görsel masajı olacaktır.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'Bardağın rengi yanlış 🥤', 'Suyu sarı bardakta verdiğiniz için kıyamet mi koptu? Üzerine gitmeyin; o sadece bu sabah sınırlarını test ediyor. Suyu hemen mavi bardağa dökün, odada barışı sağlayın ve enerjinizi koruyun.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'Sadece bağrınıza basmak 🫂', 'Bugün sizi gerçekten çıldırttı, enerjinizi tüketti, değil mi? Ama yatakta öyle masum uyuyor ki... Işıkları kapatın, masal okumayın. Yanına uzanıp o tertemiz çocuk kokusunu içinize derin derin çekin ve şükredin.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'Diğer annelerin hikâyeleri 💬', 'Instagram''ı açar açmaz herkesin mükemmel çocuğunu görüp moralinizi bozmayın! O uygulamayı kapatın ve Anacan Topluluğuna girin. Herkesin evinin sizinki gibi darmadağın olduğunu görünce derin bir nefes alın.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', 'Elimi tutma! bağımsızlığı 🚶‍♂️', 'Yolda elinizi bırakıp özgürce yürümek mi istiyor? Güvenli bir bölgedeyseniz bırakın bağımsızlığını test etsin. Siz de iki adım geriden bu küçük ve özgür ruhlu asiyi gururla izleyin.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'Sessizliğin ekrandaki kanıtı 📉', 'Sonunda uyudu. Kulaklarınızda hâlâ çığlık sesleri mi çınlıyor? Ses ölçeri açın. Odadaki o 0 desibele inen çizgiyi izlemek, yorgun ve şişmiş beyniniz için dünyanın en güzel görsel masajı olacak.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'Babanın uydurduğu masal 🦸‍♂️', 'Konuşacak hâliniz yok, kitabı okumak istemiyor musunuz? Masalı babaya bırakın. Baba, başkahramanı çocuğunuz olan uydurma ve absürt bir hikâye anlatsın. Siz de duvara yaslanıp dinlenirken çocuğunuzun babasına nasıl kahkahalarla güldüğünü izleyin.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'Bu yemeğin şekli kötü 🥒', 'Salatalığı yuvarlak değil de uzun kestiğiniz için tabağı mı itti? Yemek estetiği anlayışı tam da bu dönemde gelişiyor. Aynı sebzeyi eğlenceli şekillere sokarak nasıl gizleyebileceğinizi öğrenin. Bu tasarım oyununu siz kazanacaksınız.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'Yalnız kalmak için banyoya kaçış 🛀', 'Bütün gün bacağınıza sarılıyor, sürekli dokunulmaktan bedeniniz uyuşmuş gibi mi hissediyor? Touched out gerçektir. Onu odada bırakıp 5 dakikalığına banyoya girin, kapıyı kapatın ve sadece nefes alın. Yenilenmeye ihtiyacınız var.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'Kendi uydurduğu şarkılar 🎤', 'Güneş daha doğmadı ama o zıplayarak anlamsız sözlerle yüksek sesle şarkı mı söylüyor? Bağırıp onu susturmayın. Güne şarkıyla başlayan çocuk, içindeki gerginliği atar. Siz de o çılgın enerjiye 1 dakikalığına katılın; uykunuz hemen açılacak.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Instagram''daki kusursuz anneler 📱', 'Instagram''ı açar açmaz herkesin düzenli evini ve uslu çocuğunu görüp moraliniz mi bozuldu? O uygulamayı silin! Anacan Topluluğuna katılın. Evi sizinki gibi dağınık, çocuğu inatçı olan gerçek annelerin hikâyelerini okuyun ve rahatlayın.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'Fısıltıyla gelen uyku 🤫', 'Yataktan kaçıp oradan oraya mı zıplıyor? Sesinizi aniden iyice alçaltın. Çok kısık sesle fısıldayarak konuşmaya başlayın. Sizi anlayabilmek için fiziksel olarak dikkatini yoğunlaştıracak, beyni de 5 dakika içinde yorulup uyku moduna geçecek. Deneyin!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'Buzdolabında bulunan oyuncak 🧊', 'Buzdolabını açtınız ve içinden oyuncak bir araba mı çıktı? Bu, hafızayı ve nesneleri farklı ortamlarda deneme oyunudur. Öfkelenmeyin; bu absürtlük onun gelişiminin bir parçasıdır.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'Evden çıkmak istemiyor ⛅', 'Ev darmadağın, o da kanepede ağlayıp “Gitmeyeceğim” mi diyor? Hava durumunu açıp dışarıdaki gerçek sıcaklığı kontrol edin, ona uygun bir kombin giydirin ve gerekirse biraz ısrar ederek parka götürün. Temiz hava yüzüne değer değmez tüm gerginliği uçup gidecek.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'Masalın kahramanı o olduğunda 🪄', 'Akıllı masalları açın. Oradaki kahramanın adını doğrudan çocuğunuzun adıyla değiştirin. Hikâye boyunca o kahramanın nasıl cesurca ve söz dinleyerek uyuduğunu okuyun. Kendisini o hikâyenin içinde duyunca hiç itiraz etmeden gözlerini kapatacak.'),
  ('139226ae-9370-42b4-954a-012623528599', 'Gece yarısı anlaşılmaz ağlama 😭', 'Gecenin bir yarısı gözleri kapalı hâlde ağlayarak uyandı ve sizi duymuyor mu? Ağlama analiziyle kontrol edin; bu büyük olasılıkla gece terörüdür. Onu uyandırmamaya çalışın, yalnızca yanında durup elini tutun. Kendiliğinden sakinleşip yeniden uyuyacaktır.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'Annenin gizli çikolata saati 🍫', 'Dolabın arkasında ondan gizlice çikolata mı yiyorsunuz? Afiyet olsun! Bitmek bilmeyen “neden” sorularına ve çığlıklara dayanmak, enerjinizi yeniden toplamak için o glikoz en doğal hakkınız. Bunun için kendinizi asla suçlamayın.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'Gölgeyle kovalamaca 🏃‍♂️', 'Sokakta yürürken birden koşup kendi gölgesini yakalamaya mı çalışıyor? Hayal gücü mantığının önüne geçiyor. Onu durdurmayın; siz de kendi gölgenizi yakalamaya çalışarak sokağın ortasındaki bu çılgın ve neşeli oyuna katılın. Hayat, bu kadar ciddiye alınacak kadar uzun değil.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'Ters ayakkabı sendromu 👟', 'Sağ ayakkabıyı sol ayağına, sol ayakkabıyı sağ ayağına giymiş ve düzeltmenize izin vermiyor mu? Öyle kalsın! “Kendim giydim” derken hissettiği gurur ve özgürlük, ayakkabıların doğru giyilmesinden milyon kez daha değerlidir.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'İçimdeki öfkeyi dijitale dökmek 📝', 'Bugün ne kadar yorulduğunuzu kimse görmüyor ve gülümsemek sizi boğuyor mu? Duygu günlüğünü açın. İçinizdeki tüm o zehri ve yorgunluğu ekrana dökün. “Tükendim” diye yazmak, sizi sahte mükemmellikten çok daha hızlı iyileştirecek.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'Babadan omuz masajı 💆‍♂️', 'Bugün çok uzun süre ayakta kaldınız; onun peşinden koşmaktan ve yerden oyuncak toplamaktan beliniz kopacak gibi. Çocuk uyur uyumaz eşinizden 10 dakikalık bir omuz masajı isteyin. Siz bu evin motorusunuz; motorun da mutlaka dinlenmesi ve yenilenmesi gerekir.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'Muzu neden siz soydunuz?! 🍌', 'Muzu siz soydunuz diye odada kıyamet mi koptu? Bu yaşın altın kuralı: Her şeye o karar vermeli. Muzu tekrar kabuğuna yapıştıramazsınız; hemen yeni bir muz verin, istediği gibi kendisi soysun. İnatlaşmak yalnızca zaman kaybettirir.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'Çift olarak sessizliğin tadını çıkarın 🥂', 'Çocuk uyudu, ev toplandı. Eşinizle kanepede yan yana oturun, televizyonu bile açmayın. Yalnızca birbirinize “Bunu da başardık, hayatta kaldık.” bakışı atın. Ebeveynliğin en romantik ve en gerçek ekip anı işte budur.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'Masanın altındaki küçük ev ⛺', 'Yemek masasının altına girip kendine bir ev kurdu ve öğle yemeğini orada mı yemek istiyor? Kuralları biraz esnetin. Çorbayı o karanlık mekâna uzatın. Mekân değişikliği, en iştahsız çocuğun bile macera duygusuyla karnını doyurabilir.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'Benimle oynamıyorsunuz! 😠', 'Siz telefona bakarken gelip yüzünüzü elleriyle kendine doğru çevirdi: “Bana bak!?” Haklı. Sizin yalnızca fiziksel varlığınızı değil, bölünmemiş ilginizi istiyor. Telefonu bir kenara bırakın, 3 dakika boyunca kesintisiz göz teması kurun; hemen sakinleşecektir.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'Kaldırım kenarındaki ip cambazı 🧱', 'Parka giderken düz yoldan değil de mutlaka kaldırımın en dar kenarından mı yürümek istiyor? Kolundan destek olun ve bu küçük zirveyi fethetmesine izin verin. Dengesi ve özgüveni aynı anda harika bir şekilde gelişir; ona engel olmayın.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'Odadaki ses efektleri 🪄', 'Bu akşam okumaktan yoruldunuz mu? Akıllı masalları açın. Hikâye okunurken yalnızca kapı gıcırtısı, rüzgâr sesi ve fısıltılar çıkararak odada bir ses tiyatrosu kurun. Bu sıra dışı sesler, onun dikkatini anında masalın içine çekecektir.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'Parktan ayrılmanın rekabet taktiği 🌳', 'Parktan dönme zamanı geldi ve ağlama krizi başladı. Onu sürükleyerek götürmek işe yaramaz. “Bakalım arabaya kadar kim tavşan gibi daha hızlı zıplayacak?” diyerek dikkatini hemen eğlenceli bir yarışa yöneltin; mutlaka yarışacaktır.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'Sadece kokusunu içinize çekin 🫂', 'Bugün sizi gerçekten çileden çıkardı, enerjinizi tamamen tüketti mi? Ama yatağında öyle masum uyuyor ki... Işıkları kapatın. Yanına uzanıp o tertemiz çocuk kokusunu derin derin içinize çekin ve onun sizin için ne kadar değerli olduğunu fısıldayın.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'Suyu farklı bir bardakta verin! 🥤', 'Suyu sarı bardakta verdiğiniz için odada kıyamet mi koptu? “Ben maviyi istiyordum!” diyor. Üzerinde fazla durmayın; yalnızca sınırlarını deniyor. Suyu hemen mavi bardağa aktarın, odada huzuru sağlayın ve enerjinizi koruyun.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'Dinozorlar lapa yemez! 🦖', 'Sabah hiçbir soruya cevap vermiyor, yalnızca kükrüyor mu? O bugün bir T-Rex. “Peki T-Rex''ler kahvaltı yapar mı?” diyerek yarattığı bu karaktere uyum sağlayın ve masaya gözyaşı dökmeden, huzur içinde oturmasına yardımcı olun.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'Marketin ortasında donup kalmak 🛒', 'Markete girdiniz ve ne alacağınızı unuttunuz mu? Anne zihni gerçekten de çok dolu. Uygulamadaki Alışveriş listesini açıp bu dijital hafızaya güvenmek, eve eli boş dönmenizi her zaman önleyecektir.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'Işıkları kapatın, uyku gelsin 🌙', 'Daha çabuk uykuya dalmasını sağlamak için yatmadan 1 saat önce odadaki tüm televizyon ve telefon ekranlarını kapatın. Melatonin karanlık ortamda hızla salgılanır; bırakın doğal süreç sizin yerinize çalışsın.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'Çöp değil, sanat eseri 🎨', 'Odanın ortasında kuru makarna ve kâğıt parçalarından büyük bir sanat eseri mi yarattı? Temizlik takıntınızı bir kenara bırakın. Bu, Gelişim takipçisine kaydedilecek kadar güzel bir ince motor becerisi çalışmasıdır. Ev müze değil.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'Sessizliğin ekrandaki değeri 📉', 'Sonunda uyudu. Eve öyle bir sessizlik çöktü ki kulaklarınız mı çınlıyor? Uygulamadaki Ses ölçeri açın. O 0 desibel yazısına bakmak, gürültüden yorulup şişmiş beyniniz için dünyanın en iyi görsel masajı olacaktır.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'Yarım kalan cümleleri tamamlayın 🗣️', 'Bir kelimeyi unuttuğunda elleriyle işaretler yapıp sizin bulmanızı mı bekliyor? Kelime dağarcığı büyüyor ama zihni dilinden daha hızlı çalışıyor. Cümlesini sabırla tamamladığınızda yüzünde beliren “Evet, tam da bunu söylüyordum.” rahatlamasını izleyin.'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'Babasıyla kanepe güreşi 🤼‍♂️', 'Yatağa gitmemek için kaçıp saklandı mı? Topu babaya atın. Bırakın kanepede oyun olsun diye güreşsinler. Gürültülü ve terleten bu baba-çocuk oyunu, çocuğun kalan son inatçı enerjisini de tüketerek kolayca uykuya teslim olmasını sağlayacaktır.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'Sebzeleri gizleme sanatı 🥦', 'Çorbanın içindeki o tek havucu bulup Bunu yemem mi dedi? Sebzeleri püre hâline getirip soslara ekleyin, bakalım şimdi nasıl bulacak! O aşçılık zekâsını ustalıkla alt edin.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'Ben uçmak istiyorum! 🕊️', 'Kanepeden atlayıp kollarını çırpıyor ve uçamadığı için size kızıyor mu? Fizik kurallarını öğretmek için henüz erken. Sen uçamıyorsun, çünkü kanatların hâlâ büyüyor deyip dikkatini yumuşak bir yere atlamaya yönlendirin.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'Kendi resmini eleştirmek 🖍️', 'Çizdiği çizgiyi beğenmeyip Bu kötü oldu diyerek kâğıdı yırtıp atıyor mu? Öz eleştiri ve mükemmeliyetçilik duygusu gelişiyor! Gel, bir dahaki sefere farklı bir renk deneyelim diyerek hayal kırıklığını destekleyici bir keşfe dönüştürün.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'Toplulukta sessiz teselli 💬', 'Çok yoruldunuz ve biriyle dertleşmek bile istemiyor musunuz? Anacan Topluluğuna girip yalnızca okuyucu olun. Diğer annelerin aynı absürt krizlerle nasıl başa çıktığını görmek, size en güçlü sessiz teselliyi verecek.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'Küvette okyanus fırtınası 🌊', 'Banyo yapmak bahane, aslında küvette bir okyanus yaratıp dalgalarla mı oynuyor? Bırakın oynasın. Suyun sesi ve sıçramaları, içindeki o bitmek bilmeyen inatçı enerjiyi alıp götürecek. Akşam hiç direnmeden yatağa uzanacak.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'Sabah sabah beklenmedik felsefe 🤔', 'Rüzgâr neden görünmüyor? diye aniden bilimsel bir soru mu sordu? Paniklemeyin! Anacan AI''ı açın; bu yaştaki bir çocuğun anlayabileceği en tatlı, çocuk doktoru ve psikolog onaylı masalsı cevabı alın ve ona okuyun. Siz her zaman her şeyi bilen annesiniz!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'Sadece sessizce uzanmak 🛋️', 'Kendi kendine yapboz yapıyor ve ev bir anda sessizliğe mi büründü? Ne olur, o anı evi süpürerek harcamayın! Kanepeye uzanın. Akşama kadar bu tempoya dayanabilmeniz için sizin de pilinizin dolması gerekiyor. Mutlaka dinlenin.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'Cepten çıkan hazineler 🪨', 'Pantolonunu yıkarken cebinden kurumuş bir yaprak ya da taş mı çıktı? Bu açgözlülük değil, çocukça bir keşif merakıdır. Ciddi bir yüz ifadesiyle onu çöpe atın ama içinizden bu küçük koleksiyoncuya gülümseyin; dünyayı keşfediyor.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', 'O benim! kıyameti 🧸', 'Evdeki kumandayı kucaklayıp Bu benim! mi diyor? Mülkiyet sınırlarını test ediyor. Ona bencil demeyin; Benim için bulduğun için teşekkür ederim deyip dikkatini başka bir oyuna yönlendirerek kumandayı yavaşça geri alın.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'Alarm çalınca uyuyoruz ⏱️', 'Uyku saati uzadıkça uzuyor. Su, tuvalet, duvarla vedalaşma... Telefonun zamanlayıcısını kurun. Alarm sesini duyunca herkes ışıkları kapatır kuralını koyun. Dışarıdan gelen bir otoriteye uymak onlara her zaman daha kolay gelir.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'Kimseye hesap vermeyin 🛑', 'Bugün sabrınız tükendi ve sesiniz yükseldi mi? Kendinizi cezalandırmayın. Duygu günlüğünüze Ben iyi bir anneyim, sadece bugün çok yoruldum yazın. Kendinize şefkat gösterin; hiç kimse sizden kusursuz olmanızı beklemiyor.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'Annenin enerji barı 🥗', 'Onu beslemek için farklı menüler hazırladınız, peki siz ne yediniz? Sağlıklı tariflerde anneler için yer alan o kolay, 5 dakikalık salatayı hazırlayın.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'Sessizlik içinde sıcak çay ☕', 'Çocuk sonunda uyudu. Odanın ortasına saçılmış oyuncaklara bakıp derin bir nefes alın. Şimdi onları toplamayın! Kendinize sıcak bir çay koyun, kanepeye oturun ve sadece bu sessizliğin verdiği huzurun tadını çıkarın.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'Cansız nesnelerle uzun sohbetler 🗣️', 'Parkta bir taşa veya evdeki sandalyeye son derece ciddi bir şekilde bir şeyler mi anlatıyor? O, oyun aracılığıyla kuralları ve dünyayı öğreniyor.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'Montu reddetmek 🧥', 'Dışarıda güneş var diye kışlık montunu giymek istemiyor mu? Pencereden bakıp yanılmayın. Hava ve kıyafetler bölümünü açın, telefondaki kışlık giysiler giymiş çocuk simgesini gösterin. Kuralı dijital ekrana devredin, siz aradan çekilin.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'Yatağın altında saklambaç 🛏️', 'Yatağında değil de mutlaka yatağın altında mı uyumak istiyor? Bu kapalı ve küçük alanlar, onlara anne karnındaymış gibi güven verir. İzin verin; uykuya daldıktan sonra onu yavaşça yatağına alırsınız. Enerjinizi koruyun.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'Masal okumadan uyutmak 🪄', 'Bu akşam masal okuyacak hâliniz yok mu? Akıllı masalları açın. Arka planda yalnızca fısıldayan orman ve rüzgâr seslerini çalın. Karanlıkta o doğa seslerini dinleyerek ikiniz de gürültüden uzaklaşıp dinlenin. Görsel yorgunluğunuz anında geçecek.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'İçimdeki öfkeyi yazmak 📝', 'Evde ne kadar yorulduğunuzu kimse görmüyor ve bu sizi çileden mi çıkarıyor? Duygu günlüğünü açın. Bugün sizi ne çıldırttıysa hepsini oraya yazın. Yapmacık bir gülümsemenin ardına saklanmak yerine duygularınızı kabul edip yazmak size çok daha iyi gelecek.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'Ben biliyorum, size de öğreteyim ☝️', 'Bildiğiniz bir şeyi gelip size son derece ciddi ve bilmiş bir ifadeyle mi anlatıyor? Kendi zekâsını test ediyor. Gülmemek için dudağınızı ısırın ama onu büyük bir ciddiyetle dinleyip Gerçekten mi? Çok teşekkür ederim deyin. Egosunu okşayın.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'Küvette su baskını 🌊', 'Banyo yapmak bahanesi; aslında küvette bir okyanus yaratıp dalgalarla mı oynuyor? Bırakın oynasın. Suyun sesi ve sıçramaları, içindeki o bitmek bilmeyen inatçı enerjiyi alıp götürecek. Akşam hiç direnmeden yatağa uzanacak.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'Mutfakta size yardım ediyor 🧑‍🍳', 'Siz hamur açarken sandalyesini getirip unu mutlaka kendisi dökmek mi istedi? İzin vermezseniz ağlayacak. Ona küçük, plastik bir kap ve biraz un verin. Mutfak dağılacak ama o ciddi aşçı ifadesi, yapacağınız temizliğe değecek.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'Marketin ortasında donup kalmak 🛒', 'Marketin ortasında durup Ben ne almaya gelmiştim? diye düşüncelere mi daldınız? Anne zihni gerçekten de çok dolu. Uygulamadaki Alışveriş listesini açıp o dijital hafızaya güvenmek sizi her zaman bu karmaşadan kurtaracak.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'Tişörtün etiketi batıyor! 🏷️', 'Arkasındaki o küçük etiket ona iğne gibi battığı için giymeyecek mi? Bu yaşlardaki duyusal hassasiyet insanı çıldırtıyor. Hiç tartışmayın; makası alın, etiketi kökünden kesin ve bu mini krizi saniyeler içinde bitirin.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'Mükemmel sessizlik anı 🛋️', 'Yapbozlarıyla öylesine dalmış oynuyor ki ev bir anda sessizliğe mi büründü? Şüphelenmeyin, hemen kendinize bir kahve koyun. O nadir ve altın değerindeki dakikaları temizlik ya da çamaşır için değil, ruhunuzu dinlendirmek ve tavanı seyretmek için kullanın. Siz robot değilsiniz.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'Gece yarısı aniden gelen çığlık 😭', 'Gece gözleri kapalı hâlde ağlayarak uyandı ve sizi duymuyor mu? Ağlama analizinden kontrol edin; bu bir gece terörüdür. Uyandırmamaya çalışın, sadece yanında durun, elini tutup okşayın. Kendi kendine sakinleşip yeniden derin uykuya dalacak.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Anacan''dan size bir mektup var 💌', 'Sağlıklı tariflerle gizlenen sebzeler, Duygu günlüğüne dökülen gözyaşları ve tükenmişlik anları... Bu 4 yılda dünyanın en zor mesleğinde ustalaştınız. Artık hiçbir uygulamaya ihtiyaç duymadan, kendi sezgilerinizle karmaşayı yöneten bir kahramansınız. Biz yalnızca arka plandaki rehberdik; asıl işi yapan sizdiniz!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', '1460. gün: Başardık! 🚀', 'Sabah uyanıp ona bakıyorsunuz... Artık tam 4 yaşında! Tam 1460 gündür uykusuzlukla, krizlerle ve inatlaşmalarla mücadele ederek bu küçük insanı büyüttünüz. Bu yıllar boyunca yalnızca bir çocuk değil, içinizde güçlü ve yenilmez yeni bir anne de büyüttünüz. Bugün hiçbir kural yok; sadece ona sarılın ve kendi ellerinizle yarattığınız bu mucizeye gururla bakın.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'Son bildirim, son sessizlik 🌌', 'Uyudu. Işıkları kapatın. Bu, uygulamadan size gelen son bildirim. 1460 gün boyunca yorulduğunuzda, ağladığınızda ve köşeye sıkıştığınızda sizi anlamaya, sessizce yanınızda olmaya çalıştık. Şimdi telefonu bir kenara bırakın. Siz mükemmelsiniz, siz yeterlisiniz. Bundan sonraki muhteşem hikâyeyi kendi başınıza siz yazacaksınız. Sizinle bu yolda yürümek bir onurdu. Görüşmek üzere, Anacan! ❤️'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'Buz gibi mantıksızlık 🥶', 'Sıcak çayı üfleyerek içmek yerine içine mutlaka buz atmanızı mı istiyor? Sıcak ve soğuk arasındaki zıtlığı öğreniyor. Buzu verin, erime sürecini izlemesine izin verin. Kahvaltı gecikse de o, bilimsel keşfini yapmış olacak.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'Yağmur sesli masal odası 🌧️', 'Sesiniz çıkmıyor, masal okumaya gücünüz mü yok? Akıllı masallarda arka plan sesi olarak yalnızca yağmur ve orman sesini açın. Doğanın bu monoton dinginliği bazen en güzel, en heyecanlı hikâyeden bile daha hızlı hipnotize edip uykuya daldırır.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'Aynada kendine kızıyor 🪞', 'Aynanın karşısına geçip farklı sesler çıkarıyor ve mimikler mi yapıyor? Bu, benlik bilincinin güçlendiğini gösterir. Kendi bedenini ve duygularının dışarıdan nasıl göründüğünü test ediyor. Sessizce kenardan izleyin.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'Dokunulma isyanı 🔋', 'Bütün gün bacağınıza sarılıyor, kucak mı istiyor? Fiziksel olarak tükenmişsiniz. Dokunulma yorgunluğu yaşıyorsunuz. Onu oyuncaklarıyla odada bırakıp 5 dakikalığına banyoya kaçın ve kapıyı kapatın. Yalnızca o yalnızlığın tadını çıkarın.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'Parktan çıkış kavgası 🤝', 'Kaydırakta başka bir çocuğu itip kendisi mi kaymak istedi? Herkes size bakıyor. Utanıp çocuğunuza vurmayın. “Şimdi onun sırası, sonra biz kayacağız” diyerek kuralı nazik ama kararlı bir sesle hatırlatın. Sistem böyle işler.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'Sabah sabah kovalamaca 🏃‍♂️', 'Sabah saat 7''de koltukların üzerinde mi koşuyor? Bağırmayın. İşlerinizi 2 dakikalığına bırakıp siz de zıplayarak ona katılın. Çocuğun hayal dünyasına katılmak aslında sizin için de tuhaf ama çok işe yarayan bir stres atma yöntemidir.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'Gece korkusuna bilimsel çözüm 🔦', 'Yatak odasındaki gölgelerden mi korkuyor? Odayı tamamen karanlık yapmayın; sıcak renkli, küçük bir gece lambası kullanın. Bu, hem melatonin salgısını bozmaz hem de ona görsel güven vererek korkusunu giderir.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'Ansızın “Seni seviyorum” 💖', 'Odanın ortasında oyun oynarken aniden size bakıp koşarak gelir ve boynunuza sarılır. Bütün uykusuz gecelere ve yorgunluğa değer! Bu anın getirdiği o derin, eşsiz huzurun tadını çıkarın ve tüm o karmaşayı unutun.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'Fısıltının mistik gücü 🤫', 'Yataktan kaçıp oradan oraya mı zıplıyor? Sesinizi bir anda tamamen kısın. Çok alçak sesle fısıldayarak konuşmaya başlayın. Sizi anlayabilmek için fiziksel olarak dikkatini toplar ve beyni 5 dakika içinde yorularak uyku moduna geçer. Deneyin!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Instagram anneleri yanılsaması 📱', 'Instagram''ı açar açmaz herkesin düzenli evini, uslu çocuğunu görüp moraliniz mi bozuldu? O uygulamayı silin! Anacan Topluluğuna katılın. Evi sizinki gibi dağınık, çocuğu inatçı olan o gerçek annelerin hikâyelerini okuyun.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'Babanın uyku getiren masalı 📖', 'Sesiniz yoruldu, masal okumaya gücünüz mü yok? Sıra babada. Babanın farklı, kalın ses tonu ve uydurduğu absürt ayrıntılar, çocuğun beynini alışık olduğu sesinizden daha hızlı hipnotize edip uykuya daldırabilir.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', '“Sen kimsin?” oyunu 🎭', 'Sabah size yabancı biriymişsiniz gibi bakıp “Sen kimsin? Annem nerede?” mi dedi? Bu, yeni bir rol oyunudur. “Ben komşu teyzenim, annen birazdan gelecek” deyin. Bırakın oda sabah sabah kahkahalarla çınlasın; bu, inatlaşmaktan çok daha az enerji harcatır.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'Kendi yemeğini size vermez 🍳', 'Kendi tabağındakini size vermiyor ama ısrarla sizin tabağınızdan mı yemek istiyor? Çocuklar ebeveynlerinin seçimlerine her zaman sonuna kadar güvenir. Mücadele etmeyin; lokmayı sevgiyle ona uzatın ve bu komik bencilliğe yalnızca gülümseyin.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'Ben uçmak istiyorum! 🕊️', 'Kanepeden atlayıp kollarını çırpıyor ve uçamadığı için size mi kızıyor? Ona fizik kurallarını öğretmek için henüz erken. “Uçamıyorsun çünkü kanatların hâlâ büyüyor” deyip dikkatini yumuşak bir yere atlamaya yönlendirin.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'Telefon hırsızı 📱', 'Kendinize çay doldururken telefonunuzun kaybolduğunu ve onun kanepenin arkasında sizin gibi “Alo” dediğini mi gördünüz? Dijital alışkanlıklarınızı taklit ediyor. Cihazı geri alırken “Telefonum da seninle konuşmak istemiş” deyip gülümseyerek elinden alın.'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'Bir çift olarak sessizlik içinde 🥂', 'Çocuk uyudu, ev toplandı. Eşinizle kanepede yan yana oturun, televizyonu bile açmayın. Yalnızca birbirinize “Bunu da başardık, hayatta kaldık” bakışı atın. İnanın, yorgun ebeveynliğin en gerçek ekip anı işte budur.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'Giyim diplomasisi 👗', 'Kışın ortasında yazlık pantolon giymek mi istiyor? Hemen Hava ve giyim aracını açın ve ekrandaki görsellerden yararlanarak dışarıda havanın soğuk olduğunu ona mantıklı bir şekilde açıklayın.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (10 boş-mənbə sətri istisna)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_ru IS NULL) AS preg_ru_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_ru IS NULL) AS mommy_ru_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_tr IS NULL) AS mommy_tr_bos;
